window.UNITS=[{"id":"u01","title":"Egészségpszichológia","desc":"Fogalom, történet, modellek, feladatok","lessons":[{"id":"u01l1","title":"Mi az egészségpszichológia?","theory":[["Matarazzo (1982)","Az egészségpszichológia a pszichológia specifikus-edukációs, tudományos és gyakorlati hozzájárulása az <b>egészség elősegítéséhez és fenntartásához</b>, a betegség <b>megelőzéséhez és kezeléséhez</b>, az etiológiai és diagnosztikus korrelátumok azonosításához, valamint az egészségvédelem rendszeréhez."],["Jellemzői","Az <b>egészségre</b> orientált. Hangsúlyt helyez a <b>prevencióra</b> (mentális és testi betegségeknél), a lineáris okozati gondolkodás helyett <b>rendszerszemléletű</b>, gondolkodásmódja <b>bio-pszichoszociális</b>. Az egyén a szükséges információk birtokában tudatosan alakítja a megküzdést (Kállai és mtsai, 2007)."],["Klinikai pszichológia vs. egészségpszichológia","A klinikai pszichológia középpontjában a <b>betegség</b> áll, az egészségpszichológiáéban az <b>egészség</b>. A klinikai pszichológia a pszichiátriai problémákra fókuszált; a testi tünetek a hagyományos pszichoterápiákkal alig módosultak, a szomatikus betegségek és szomatoform zavarok új módszereket igényeltek."]],"qs":[{"t":"mc","q":"Ki határozta meg 1982-ben az egészségpszichológiát a pszichológia specifikus-edukációs, tudományos és gyakorlati hozzájárulásaként?","o":["Matarazzo","Schofield","Kállai","Selye"],"a":0,"e":"Ez Matarazzo (1982) definíciója."},{"t":"tf","q":"Az egészségpszichológia gondolkodásmódja lineáris okozati, medicinális szemléletre épül.","a":false,"e":"Lineáris okozati gondolkodás helyett rendszerszemlélet jellemzi, bio-pszichoszociális alapokon."},{"t":"mc","q":"Mire helyezi a hangsúlyt az egészségpszichológia?","o":["A prevencióra","Kizárólag a gyógyszeres kezelésre","A pszichiátriai diagnosztikára","A kórházi adminisztrációra"],"a":0,"e":"Az egészségpszichológia a mentális és testi betegségek megelőzésére koncentrál."},{"t":"match","q":"Mi áll a középpontban?","pairs":[["Klinikai pszichológia","A betegség"],["Egészségpszichológia","Az egészség"],["Biomedikális modell","Fiziológiai zavarok"]],"e":"A klinikai pszichológia a betegségre, az egészségpszichológia az egészségre fókuszál."},{"t":"fill","q":"Az egészségpszichológia gondolkodásmódja ___ tényezőkre épül.","a":["bio-pszichoszociális","biopszichoszociális","bio-pszicho-szociális"],"e":"Biológiai, pszichológiai és szociális tényezők együttesen."},{"t":"tf","q":"A klinikai pszichológia a kezdetekben főként pszichiátriai problémákra összpontosított.","a":true,"e":"Schofield (1969) éppen ezt kritizálta."},{"t":"mc","q":"Kinek a szerepét hangsúlyozza az egészségpszichológia a betegséggel való megküzdésben?","o":["Az egyénét, aki tájékozottan, tudatosan alakítja a folyamatot","Kizárólag az orvosét","A hozzátartozókét","A gyógyszergyártóét"],"a":0,"e":"Kállai és mtsai (2007) szerint az egyén a szükséges információk birtokában tudatosan alakítja a megküzdést."}]},{"id":"u01l2","title":"A történet és kialakulás","theory":[["Előzmények","A II. világháború után a pszichológiát az egészségügyben egyoldalúan a klinikai pszichológia képviselte. <b>Schofield (1969)</b> tanulmánya felhívta a figyelmet, hogy a klinikai pszichológia csak a pszichiátriai problémákra összpontosít."],["Az 1970-es évektől","Az egészségpszichológia az <b>1970-es években</b> alakult ki. <b>1974</b>: a University of California egyetemi kurzust vezet be. <b>1976</b>: az APA irányelve. <b>1978</b>: az APA egészségpszichológiai szekciója (első konferencia: 1983). <b>1982</b>: az első folyóirat (<i>Health Psychology</i>). <b>1988</b>: Európai Egészségpszichológiai Társaság és a <i>Psychology and Health</i> folyóirat."],["Miért született meg?","A <b>biomedikális modell kudarca</b>; az életminőség iránti érdeklődés; a hangsúly áttolódása a fertőző betegségekről a <b>krónikus betegségekre</b>; a viselkedéstudományok fejlődése (megküzdés- és stresszkutatás, tanuláselméletek); az egészséggondozás egyre költségesebb és krónikus betegségeknél kevésbé hatékony."]],"qs":[{"t":"mc","q":"Melyik tanulmány hívta fel a figyelmet, hogy a klinikai pszichológia csak a pszichiátriai problémákra összpontosít?","o":["Schofield (1969)","Matarazzo (1982)","Engel (1977)","Kasl és Cobb (1966)"],"a":0,"e":"Schofield 1969-es tanulmánya."},{"t":"fill","q":"Az első egészségpszichológiai folyóirat 1982-ben ___ címmel jelent meg.","a":["Health Psychology","Healt Psychology"],"e":"Az APA egészségpszichológiai szekciója 1978-ban alakult, az első folyóirat 1982-ben jelent meg."},{"t":"match","q":"Párosítsd az évszámot az eseménnyel!","pairs":[["1974","Egyetemi egészségpszichológia-kurzus"],["1978","APA egészségpszichológiai szekció"],["1988","Európai Egészségpszichológiai Társaság"]],"e":"Ezek a kialakulás mérföldkövei."},{"t":"mc","q":"Melyik NEM oka az egészségpszichológia megszületésének?","o":["A fertőző betegségek előretörése","A biomedikális modell kudarca","A krónikus betegségek előtérbe kerülése","Az életminőség iránti fokozott érdeklődés"],"a":0,"e":"A hangsúly éppen a fertőző betegségekről tolódott át a krónikusakra."},{"t":"tf","q":"Az egészségpszichológia kialakulása az 1970-es évekre tehető.","a":true,"e":"Az 1970-es években alakult ki."},{"t":"mc","q":"Ki vezette a magyarországi Klinikai Pszichofiziológiai és Egészségpszichológiai Társaságot a 90-es évek elején?","o":["Kopp Mária","Kállai János","Pikó Bettina","Oláh Attila"],"a":0,"e":"A társaság Kopp Mária vezetésével alakult."},{"t":"tf","q":"A krónikus betegségek ellátása a 20. század második felében egyre költségesebbé és kevésbé hatékonnyá vált.","a":true,"e":"Ezért kerestek alternatív megoldásokat a drága módszerek helyett."}]},{"id":"u01l3","title":"Modellek: biomedikális, BPS, pszichoszomatika","theory":[["Biomedikális modell","A 20. században terjedt el. A betegségeket <b>fiziológiai zavarokra</b>, mérhető biológiai változókra vezeti vissza (sérülés, biokémiai egyensúlyzavar, fertőzés). Betegségeket kezel, nem betegeket; nem veszi figyelembe a viselkedéses tényezőket; krónikus betegségekben kevésbé hatásos."],["Bio-pszichoszociális modell","A 70-es években írták le. Felismeri a pszichológiai, szociális és kulturális faktorok szerepét a kialakulásban és lefolyásban: <b>prediszponáló</b> (hajlamosító), <b>precipitáló</b> (kiváltó) és <b>fenntartó</b> tényezők. Az orvos–beteg viszony itt partneri, a biomedikálisban alá-fölérendelt."],["Pszichoszomatikus orvoslás (1930–50)","Az első tudományos megközelítés, amely a betegségek hátterében pszichológiai tényezőkkel számolt. Előzmény: <b>Hippokratész</b> (testnedvek és temperamentum), <b>Galénosz</b>. 1939: <i>Psychosomatic Medicine</i> folyóirat. <b>Freud</b>: tudattalan vágy + konfliktus, a tünet kerülőúton fejezi ki a vágyat."],["Alexander és Engel","<b>Franz Alexander</b>: nukleáris konfliktuselmélet, speciális tudattalan konfliktus és szervi diszfunkció között egyenes oksági kapcsolat. A „hétszentség”: hipertónia, asthma bronchiale, gyomorfekély, hipertireózis, reumatoid artritisz, colitis ulcerosa, neurodermatitis. Ma multikauzalitást vallunk. <b>George Engel</b>: tárgyvesztés és megbetegedés összefüggése."]],"qs":[{"t":"mc","q":"Melyik modell vezeti vissza a betegségeket fiziológiai zavarokra és hagyja figyelmen kívül a viselkedést?","o":["Biomedikális","Bio-pszichoszociális","Pszichoanalitikus","Konfliktuselméleti"],"a":0,"e":"A biomedikális modell kizárólag biológiai változókra épít."},{"t":"match","q":"Párosítsd a tényezőt a jelentésével!","pairs":[["Prediszponáló","Hajlamosító"],["Precipitáló","Kiváltó"],["Fenntartó","Állapotot tartósító"]],"e":"A bio-pszichoszociális modell három tényezőtípusa."},{"t":"mc","q":"Ki dolgozta ki a nukleáris konfliktuselméletet?","o":["Franz Alexander","George Engel","Freud","Dunbar"],"a":0,"e":"Alexander speciális tudattalan konfliktusokat feltételezett konkrét szervi diszfunkciók mögött."},{"t":"tf","q":"A „pszichoszomatikus hétszentség” része a hipertónia és a gyomorfekély.","a":true,"e":"Valamint az asthma bronchiale, hipertireózis, reumatoid artritisz, colitis ulcerosa és neurodermatitis."},{"t":"mc","q":"Mit vizsgált George Engel?","o":["A tárgyvesztés és a megbetegedés összefüggését","A testnedvek szerepét","Az A típusú viselkedést","A kapukontrollt"],"a":0,"e":"A szeretett személy elvesztésének évfordulóján romolhat az egészség."},{"t":"tf","q":"A bio-pszichoszociális modellben az orvos–beteg viszony alá-fölérendelt.","a":false,"e":"Ez a biomedikális modellre jellemző; a bio-pszichoszociálisban partneri."},{"t":"fill","q":"A pszichoszomatikus orvoslás előzménye Hippokratész és ___ testnedv-tana.","a":["Galénosz","Galenosz","Galén","Galen"],"e":"Hippokratész és Galénosz a testnedvek és az érzelmi állapotok összefüggését feltételezte."},{"t":"mc","q":"Mit mondott Freud a pszichoszomatikus tünetről?","o":["Tudattalan vágy és konfliktus kerülőúton fejeződik ki benne","Mindig fertőzés okozza","Speciális jelentése van minden szervnek","Csak a genetika határozza meg"],"a":0,"e":"A tudattalan vágy a valósággal konfliktusba kerül, és kerülőúton jut kifejezésre."}]},{"id":"u01l4","title":"Határterületek, területek és feladatok","theory":[["Magatartásorvoslás","Interdiszciplináris tudományág, amely integrálja a <b>viselkedéses és biomedikális</b> megközelítéseket, és alkalmazza a megelőzésben, diagnózisban, kezelésben és rehabilitációban. <b>Tágabb kategória</b>, az egészségpszichológia is része. Részei: viselkedéstudományok, biomedikális tudományok, egészségügyi szolgáltatások, orvostudomány."],["Irányzatok","<b>Klinikai</b>: egészségügyi intézményekben, a szomatikus kezelések hatékonyságát javítja. <b>Preventív/egészségfejlesztő</b>: iskola, munkahely, média; veszélyeztetett egészségesek. <b>Közösségi</b>: kisebb közösségek (család, lakóközösség), tájékoztatás. <b>Kritikai</b>: a társadalmi viszonyok (pl. gazdasági helyzet) hatását elemzi."],["Kutatási területek","Viselkedéses rizikófaktorok (<i>viselkedéses patogének</i>); intervenciók; egészség viselkedéses megőrzése (<i>viselkedéses immunogének</i>); egészség-betegség reprezentációk; kommunikáció, döntéshozatal, együttműködés; krónikus, rokkant és haldokló betegek problémái; a kezelés környezete (pl. kórházi tartózkodás előkészítése)."],["Az egészségpszichológus feladatai","Egészséges életvitel fejlesztése; problémamegoldás, attitűdváltoztatás, szokások korrekciója; fájdalomcsökkentő módszerek; kognitív módszerek <b>műtéti előkészítésben</b>; betegségspecifikus megelőzés és terápia; kutatás, oktatás; egészségpolitika; orvos–beteg kommunikáció; <b>compliance</b> kialakítása. Módszerek: műtéti előkészítés, fájdalomcsökkentés, biofeedback, hipnoterápia."]],"qs":[{"t":"mc","q":"Melyik a tágabb kategória?","o":["Magatartásorvoslás","Egészségpszichológia","Klinikai pszichológia","Kritikai egészségpszichológia"],"a":0,"e":"A magatartásorvoslásnak része az egészségpszichológia."},{"t":"match","q":"Párosítsd az irányzatot a jellemzőjével!","pairs":[["Klinikai","Kórházakban, szomatikus kezelések segítése"],["Preventív","Iskola, munkahely, média"],["Közösségi","Családok, lakóközösségek"],["Kritikai","Társadalmi viszonyok elemzése"]],"e":"Az egészségpszichológia négy irányzata."},{"t":"fill","q":"Az egészségre ártalmas magatartásmintákat viselkedéses ___ nevezzük.","a":["patogéneknek","patogén","patogének","patogeneknek"],"e":"A kedvező mintákat viselkedéses immunogéneknek hívják."},{"t":"tf","q":"A viselkedéses immunogének az egészség megőrzése szempontjából jótékony magatartásminták.","a":true,"e":"Pl. a viselkedéses patogének kerülése."},{"t":"mc","q":"Mit jelent a compliance?","o":["Az orvosi előírások betartása","A kórházi felvétel","A tünetek tagadása","A kezelés visszautasítása"],"a":0,"e":"Az egészségpszichológus feladata az előírások betartatása, az együttműködés kialakítása."},{"t":"mc","q":"Melyik NEM az egészségpszichológia gyakorlati módszere?","o":["Műszeres sebészeti beavatkozás","Biofeedback","Hipnoterápia","Fájdalomcsökkentő pszichológiai módszerek"],"a":0,"e":"A sebészet orvosi beavatkozás, nem pszichológiai módszer."},{"t":"mc","q":"Mi a példa a klinikai egészségpszichológia területére?","o":["Szívműtét utáni depresszió","Iskolai drogprevenciós kampány","Gazdasági helyzet és egészség elemzése","Lakóközösségi felvilágosítás"],"a":0,"e":"A betegségek, sérülések pszichológiai hatása a klinikai egészségpszichológia tárgya."},{"t":"tf","q":"A kritikai egészségpszichológia módszere a kritikai elemzés és vita.","a":true,"e":"A társadalmi, szakmai diskurzusok rendezése a célja."}]}],"color":"#58cc02"},{"id":"u02","title":"Egészség-/betegségmagatartás","desc":"Meghatározók, elméletek, reprezentáció","lessons":[{"id":"u02l1","title":"Egészség- és betegségmagatartás","theory":[["Kasl és Cobb (1966)","<b>Egészségmagatartás</b>: bármely viselkedés, amelyről az egyén úgy véli, hogy elősegíti egészségét, megelőzi a betegséget vagy elősegíti annak felismerését (prevenció). <b>Betegségmagatartás</b>: bármely viselkedés, amelyet az önmagát betegnek érző személy azért végez, hogy tisztázza állapotát és megtalálja a megfelelő gyógykezelést."],["Kapcsolódó fogalmak","<b>Egészségvédő viselkedés</b> (Harris és Guten, 1979): minden viselkedés, amellyel a személy védi, fenntartja egészségét, függetlenül az észlelt állapottól és attól, hogy objektíven hatékony-e. <b>Betegségviselkedés</b> (Pikó, 2006): a betegségre adott válasz – tünetek megítélése, orvoshoz fordulás, együttműködés."],["Betegszerep (Parsons, 1964)","Ha valaki nem tudja ellátni szociális feladatát, a társadalom felmenti. <b>4 alkomponens</b>: (1) nem felelős az állapotáért, (2) felmentés a szociális szerepek alól, (3) a betegszerep nemkívánatos, (4) együttműködés az orvossal. <b>Kritika</b>: kultúrafüggő, krónikus és gyógyíthatatlan betegségekre nem alkalmazható, paternalisztikus."]],"qs":[{"t":"mc","q":"Ki határozta meg az egészség- és betegségmagatartás fogalmát?","o":["Kasl és Cobb","Leventhal","Selye","Lazarus"],"a":0,"e":"Kasl és Cobb (1966) – jóval az egészségpszichológia megszületése előtt."},{"t":"mc","q":"Melyik az egészségmagatartás meghatározása?","o":["Amit az egyén azért tesz, mert hiszi, hogy megelőzi a betegséget","Amit a beteg a gyógyulás érdekében tesz az orvos utasítására","A betegség tüneteinek tagadása","A társadalmi szerepek alóli felmentés"],"a":0,"e":"A betegség elkerülésének célja vezérli."},{"t":"match","q":"Párosítsd a fogalmat a szerzővel!","pairs":[["Betegszerep","Parsons"],["Egészségvédő viselkedés","Harris és Guten"],["Betegségmagatartás","Kasl és Cobb"]],"e":"Három alapfogalom, három szerző."},{"t":"tf","q":"Parsons szerint a beteg felelős az állapotáért.","a":false,"e":"A betegszerep első komponense az állapotért való felelősség hiánya."},{"t":"fill","q":"A betegszerep egyik kritikája, hogy a ___ orvos-beteg kapcsolatból indul ki.","a":["paternalisztikus","paternalista"],"e":"Emellett kultúrafüggő és krónikus betegségekre nem alkalmazható."},{"t":"mc","q":"Melyik NEM a betegszerep alkomponense?","o":["Az orvossal való szembenállás","A szerepvitel alóli felmentés","Az állapotért való felelősség hiánya","A betegszerep nemkívánatossága"],"a":0,"e":"A negyedik komponens az orvossal való kooperáció."},{"t":"tf","q":"Az egészségvédő viselkedés fogalma szerint a viselkedésnek objektíven hatékonynak kell lennie.","a":false,"e":"Harris és Guten: függetlenül attól, hogy objektíven hatékony-e."}]},{"id":"u02l2","title":"Demográfiai meghatározók","theory":[["Életmód és szocio-kulturális faktorok","Az életmód az egyik legfontosabb tényező (kockázatok: dohányzás, alkohol, drogok, rossz táplálkozás, kevés mozgás, közlekedésbiztonság elhanyagolása). Alacsony <b>szocioökonómiai státusz</b>: rövidebb várható élettartam, több káros viselkedés, kisebb születési súly, több krónikus betegség; okai: rosszabb szokások, külső kontroll, kevesebb ismeret."],["Életkor","Az anya egészségviselkedése hatással van a magzatra; 3 kockázat: <b>elégtelen táplálkozás</b> (alacsony születési súly), <b>terhesség alatti fertőzések</b> (agyi fejlődési rendellenesség), <b>kémiai anyagok</b> (nikotin, alkohol, gyógyszerek). <b>Adoleszcencia</b>: kritikus, ekkor indulnak a kockázatos viselkedések. Felnőttkorban nő a tudatos egészségviselkedés aránya."],["Nemi különbségek","A nők tovább élnek (nemi hormonok, a férfiaknál több baleset, dohányzás, alkohol, veszélyesebb munkák), de <b>többet betegek</b>, több gyógyszert fogyasztanak, gyakrabban fordulnak orvoshoz. A hátterben a tünetészlelés és megküzdés sztereotípiái állnak: nők <b>érzelemközpontú</b>, férfiak <b>problémacentrikus</b> megküzdés. Az egészségvédő magatartás inkább női, a rizikóviselkedés férfi."],["Férfiak és egészség","A férfiak ritkábban járnak szűrésre és orvoshoz, később észlelik a tüneteket, kevesebbet tudnak az egészségről. A <b>hagyományos hegemón maszkulinitás</b> elutasítja a test iránti törődést. Rosszabbul viselik a válást, a szegénységet, az izolációt. Kevésbé érzik, hogy kontrollálnák egészségüket."]],"qs":[{"t":"mc","q":"Melyik NEM az alacsony szocioökonómiai státusz jellemzője?","o":["Nagyobb születési testsúly","Rövidebb várható élettartam","Több krónikus felnőttkori betegség","Nagyobb csecsemőhalandóság"],"a":0,"e":"Az alacsony SES kisebb születési testsúllyal jár."},{"t":"match","q":"Párosítsd a magzati kockázatot a következménnyel!","pairs":[["Elégtelen táplálkozás","Alacsony születési súly"],["Terhességi fertőzés","Agyi fejlődési rendellenesség"],["Nikotin, alkohol","Kémiai ártalom"]],"e":"Az anya egészségviselkedésének három kockázati tényezője."},{"t":"mc","q":"Melyik életszakasz kritikus a kockázatos viselkedések indulása szempontjából?","o":["Adoleszcencia","Csecsemőkor","Időskor","Óvodáskor"],"a":0,"e":"Ekkor kezdődik pl. dohányzás, alkohol, drog, kockázatos autóvezetés."},{"t":"tf","q":"A nők hosszabb élettartama mellett többet betegek, és gyakrabban fordulnak orvoshoz.","a":true,"e":"A nők több gyógyszert is fogyasztanak, a szomatizációs tünetek is rájuk jellemzők."},{"t":"mc","q":"Melyik megküzdési mód jellemző sztereotipikusan a férfiakra?","o":["Problémacentrikus","Érzelemközpontú","Társas támogatást kereső","Kibeszélő"],"a":0,"e":"A nőkre az érzelemközpontú megküzdés jellemző."},{"t":"fill","q":"A hagyományos hegemón ___ egyik fő komponense a testtel való törődés elutasítása.","a":["maszkulinitás","maszkulinitas"],"e":"Minél tradicionálisabb a férfi nemi identitás, annál nagyobb az egészséget fenyegető magatartás valószínűsége."},{"t":"tf","q":"A férfiak az egészségi állapotuk feletti kontrollt erősebbnek érzik, ezért aktívabban küzdenek.","a":false,"e":"Kevésbé érzik, hogy kontrollálni tudnák egészségüket, ez rontja az aktív megküzdést."},{"t":"mc","q":"Mi az evolúciós biológiai magyarázat a nők hosszabb élettartamára?","o":["Az utódgondozásra fordított nagyobb ráfordítás","A nagyobb izomtömeg","A kevesebb stressz","A magasabb jövedelem"],"a":0,"e":"A reprodukcióra való nagyobb ráfordítás rövidebb, az utódgondozásra fordított hosszabb életet jelent."}]},{"id":"u02l3","title":"Személyiség és egészség","theory":[["Típusok: A, B","<b>A típus</b> (Friedman és Rosenman, 1970-es évek): agresszív, nyughatatlan, teljesítményorientált, versengő, hosztilis, időprés-érzés, türelmetlen; több szív- és érrendszeri betegség (főleg infarktus). <b>B típus</b>: kiegyensúlyozott, nyugodt. Magyarázat: <b>hiperreaktivitás-modell</b> – erős stresszválasz, a vérnyomás, pulzus, katekolamin hirtelen nő, ez szívaritmiához és artériakárosodáshoz vezet."],["Típusok: C, D","<b>C típus</b> (cancer prone, 1980-as évek): szélsőséges alkalmazkodás, mindenkinek kedvezni akar, érzelmeit elfojtja, represszív megküzdés. <b>D típus</b> (distressz): negatív érzelmek átélése + elnyomása, társas kapcsolatok kerülése; kulcs: <b>negatív affektivitás + szociális gátlás</b> együtt (koszorúér-betegség)."],["Modellek","<b>Hiperreaktivitás-modell</b>; <b>alkati prediszpozíciók modellje</b> (Eysenck, 1967): a személyiség és betegség közös alkati háttérből ered, nem feltétlen ok-okozat; <b>rizikóviselkedés-modell</b>: bizonyos személyiségűek gyakrabban kerülnek erős stresszel járó helyzetekbe. Friedman: a személyiség szerepe főleg közvetett."],["Egészségvédő személyiség","<b>Szívós személyiség</b> (Kobasa): <b>3 C</b> – commitment (elkötelezettség), control (kontroll), challenge (kihívás). <b>Koherenciaérzés</b> (Antonovsky): stabil diszpozíció, fiatal felnőttkorra alakul ki; strukturálni, elővételezni, magyarázni tudja az ingereket, mozgósítja az erőforrásokat, kihívásként értelmez. Általános ellenállási erőforrások: társas támasz, önértékelés, kulturális stabilitás, presztízs."]],"qs":[{"t":"mc","q":"Melyik személyiségtípushoz kötődik a szív- és érrendszeri betegségek fokozott kockázata?","o":["A típus","B típus","C típus","Egyik sem"],"a":0,"e":"Friedman és Rosenman az A típust azonosította."},{"t":"match","q":"Párosítsd a típust a jellemzőjével!","pairs":[["A típus","Versengő, időprésben él"],["C típus","Érzelmek elfojtása, túlalkalmazkodás"],["D típus","Negatív affektivitás + szociális gátlás"],["B típus","Kiegyensúlyozott, nyugodt"]],"e":"A négy személyiségtípus."},{"t":"mc","q":"Mi a Kobasa-féle szívósság három eleme?","o":["Elkötelezettség, kontroll, kihívás","Kontroll, optimizmus, remény","Kiszámíthatóság, érthetőség, értelem","Hit, remény, szeretet"],"a":0,"e":"3 C: commitment, control, challenge."},{"t":"fill","q":"A rákra hajlamosító személyiség angol neve: cancer prone, azaz ___ típus.","a":["C","c"],"e":"Konfliktuskerülő, érzelmeit elfojtó, represszív megküzdés jellemzi."},{"t":"mc","q":"Ki alkotta meg a koherenciaérzés modellt?","o":["Antonovsky","Kobasa","Eysenck","Rosenbaum"],"a":0,"e":"A koherenciaérzés stabil személyiségdiszpozíció."},{"t":"tf","q":"A D típus diagnosztikus kritériuma a negatív affektivitás és a szociális gátlás együttes megléte.","a":true,"e":"Mindkettő szükséges."},{"t":"mc","q":"Mit állít az alkati prediszpozíciók modellje (Eysenck)?","o":["A személyiség és a betegség közös alkati háttérből eredhet","A személyiség közvetlenül okozza a betegséget","A betegség sosem függ össze a személyiséggel","Csak a környezet számít"],"a":0,"e":"A kapcsolat korreláció, nem feltétlenül ok-okozat."},{"t":"tf","q":"Az A típus hiperreaktivitása a vérnyomás és a pulzus hirtelen emelkedésével jár.","a":true,"e":"A katekolaminszint is nő, ami szívaritmiához és artériakárosodáshoz vezethet."}]},{"id":"u02l4","title":"Pozitív pszichológia és tudatosság","theory":[["Pozitív pszichológiai tényezők","<b>Optimizmus</b>: kedvező egészségmagatartás, a pesszimizmus és az optimizmus is tanult reakció (Seligman, 1992). <b>Jövőorientáltság</b>: a jövőbeli következményekkel számol; egészségtudatosabbak, kevesebb káros szer. <b>Belső kontroll</b>: motiváltság a rendszeres sportra, étkezésre. <b>Társas támasz</b>: elégedettség esetén kedvezőbb egészségmagatartás."],["Tudatos és nem tudatos magatartás","Nem tudatos: a szervezet egészségfenntartó körülményeket keres (Szondi). <b>Rosenbaum (1990)</b>: az önkontroll-kutatás az alap. Önkontroll: <b>helyreállító</b> és <b>reformatív</b>. A reformatív önkontroll a „tanult leleményesség” alapja: maladaptív gondolatok, érzések, viselkedés monitorozása; problémamegoldás; emóciószabályozás."],["Egészségtudat","Az optimális egészségmagatartás a korai életszakaszban kialakult szokásokra épül. Fő meghatározók: egészségügyi kultúra, nevelés, oktatás. A fokozott egészségtudat patológiás formája szomatoform zavarokban a <b>hipochondriázis</b> forrása lehet."]],"qs":[{"t":"mc","q":"Ki szerint tanult magatartás az optimizmus és a pesszimizmus is?","o":["Seligman","Antonovsky","Parsons","Rosenbaum"],"a":0,"e":"Seligman (1992)."},{"t":"tf","q":"A jövőorientált egyének kisebb arányban élnek káros szerekkel.","a":true,"e":"Egészségtudatosabbak és motiváltabbak az egészségfejlesztésre."},{"t":"mc","q":"Melyik az önkontroll két típusa Rosenbaum szerint?","o":["Helyreállító és reformatív","Aktív és passzív","Belső és külső","Tudatos és automatikus"],"a":0,"e":"A reformatív önkontroll a tanult leleményesség alapja."},{"t":"fill","q":"A reformatív önkontroll a „tanult ___” alapja.","a":["leleményesség","lelemenyesseg"],"e":"Elemei: monitorozás, problémamegoldás, emóciószabályozás."},{"t":"mc","q":"Mihez vezethet a fokozott egészségtudat patológiás formája?","o":["Hipochondriázishoz","Koherenciaérzéshez","Optimizmushoz","Betegszerephez"],"a":0,"e":"Szomatoform zavarokban."},{"t":"tf","q":"A pesszimista ember jobban törődik az egészsége megőrzésével.","a":false,"e":"Az optimizmus segíti a kedvező egészségmagatartást."},{"t":"tf","q":"A belső kontroll nélkül kisebb a motiváció egészségfejlesztő programban részt venni.","a":true,"e":"A rendszeres sportolás vagy étkezés kontrollja belső motiváltságot igényel."}]},{"id":"u02l5","title":"Egészséghiedelem- és konfliktuselméleti modell","theory":[["Egészséghiedelem-modell (HBM)","Célja az egészségmagatartás és az együttműködés (compliance) értelmezése. Fő tényezők: <b>észlelt hajlam</b> (sérülékenység), <b>észlelt fenyegetettség</b> (súlyosság), <b>ár/haszon arány</b>, <b>akcióra késztető jelzések</b> (belső: közérzet; külső: tömegkommunikáció, interperszonális interakció). Demográfiai és pszichoszociális faktorok módosítják. Jósol: pl. rákszűrésen való részvétel, terápiás utasítások betartása."],["HBM bizonyítékok","Észlelt sérülékenység: pozitív korreláció az együttműködéssel. Észlelt súlyosság: nincs kapcsolat az objektív súlyossággal; a nagyon súlyos kimenetel feltételezése <b>akciógátló</b>. Haszon: ha hisz benne, él vele; gátló: félelem, anyagiak. Egyéb: orvossal való kapcsolat, csoportkonformitás, életkor."],["Konfliktuselméleti modell","A HBM módosított változata: a beteget <b>aktív döntéshozónak</b> látja, de a döntés lehet racionális és irracionális. 5 fázis: (1) a jelen viselkedés megkérdőjelezése, (2) alternatívák keresése, (3) mérlegelés, (4) tentatív döntés, (5) teljes elköteleződés negatív visszajelzések ellenére is."],["Megküzdés a döntési konfliktusban","Kimenetel 3 faktortól függ: <b>kockázat, remény, időnyomás</b>. 5 stratégia: (1) konfliktusátélés hiánya (nem észleli a kockázatot), (2) hiány, mert talál alternatívát, (3) <b>defenzív elkerülés</b> (halogatás, tagadás), (4) <b>hipervigilancia</b> (kapkodás, pillanatnyi enyhülés), (5) <b>vigilancia</b> (racionális döntés esélye nagy)."]],"qs":[{"t":"mc","q":"Melyik NEM az egészséghiedelem-modell fő tényezője?","o":["Társas státusz presztízse","Észlelt hajlam","Ár/haszon arány","Akcióra késztető jelzések"],"a":0,"e":"A fő tényezők: hajlam, fenyegetettség, ár/haszon, jelzések."},{"t":"match","q":"Párosítsd a döntési stratégiát a jellemzőjével!","pairs":[["Defenzív elkerülés","Halogatás, tagadás"],["Hipervigilancia","Kapkodó megoldáskeresés"],["Vigilancia","Racionális döntés"]],"e":"A kockázat, remény és időnyomás kombinációi."},{"t":"mc","q":"Mi a konfliktuselméleti modell és a HBM fő különbsége?","o":["A beteget aktív, de nem mindig racionális döntéshozónak tekinti","Csak a fenyegetettséget vizsgálja","Csak gyerekekre alkalmazható","Nem számol a stresszel"],"a":0,"e":"A döntés lehet racionális és irracionális."},{"t":"fill","q":"A konfliktuselméleti modell szerint a döntési konfliktus kimenetele a kockázat, a remény és az ___ függvénye.","a":["időnyomás","idonyomas","idő nyomás"],"e":"Ez a három faktor 5 megküzdési stratégiát határoz meg."},{"t":"tf","q":"A nagyon súlyos kimenetel feltételezése akciógátló lehet.","a":true,"e":"A HBM-vizsgálatok szerint az észlelt súlyosság nem jósol egyértelműen."},{"t":"mc","q":"Hány fázisa van az egészséggel kapcsolatos döntésnek a konfliktuselméleti modellben?","o":["5","3","4","7"],"a":0,"e":"A viselkedés megkérdőjelezésétől a teljes elköteleződésig."},{"t":"tf","q":"A HBM szerint hinni kell a kezelés hatékonyságában és elérhetőnek kell tartani az árát.","a":true,"e":"Ez az ár/haszon arány lényege."},{"t":"mc","q":"Mikor valószínű a racionális döntés és nem túl erős a stressz?","o":["Vigilancia","Hipervigilancia","Defenzív elkerülés","Konfliktusátélés hiánya"],"a":0,"e":"Súlyos kockázat észlelése mellett van remény a megoldásra."}]},{"id":"u02l6","title":"Betegség-reprezentáció: fogalom","theory":[["Fogalom","<b>Leventhal (1980)</b>: az egyén betegségről kialakított implicit, általános hiedelme. <b>Diefenbach (2008)</b>: a betegek hiedelmei és elvárásai a betegségről, testi tünetekről. <b>Betegség-séma</b>: integrált kognitív struktúra a tünetek csoportjairól és a javító lépésekről. <b>Betegség-kogníció</b> (Cyrol és Ditto, 1990): a beteg mentális aktivitása az állapot tisztázására."],["Befolyásoló tényezők","Személyes tapasztalatok (laikus reprezentációk); <b>orvosi modellek</b>; kultúra; életkor (főleg gyerekeknél); család; pszichoszociális megközelítés; attribúció. <b>Leventhal önszabályozási modellje</b>: kognitív rész (kultúra, tudás, egyéni tapasztalat) és érzelmi rendszer (érzelem → testi érzet → betegségként értelmezhető)."],["Orvosi modell és kultúra","<b>Doyal és Doyal</b>: a test gép, részei külön kezelhetők; egészség = jól működő részek; betegség mérhető rossz működés; belső vagy külső okok; a kezelés a működés helyreállítása. <b>Népi betegségek</b> (Helman, Rubel): adott kultúra tagjai egyetértenek a tünetekben, okban, kezelésben (pl. „szívszorítás”)."]],"qs":[{"t":"mc","q":"Ki szerint a betegség-reprezentáció az egyén implicit, általános hiedelme a betegségről?","o":["Leventhal (1980)","Lipowski","Helman","Kasl"],"a":0,"e":"Ez Leventhal és munkatársai definíciója."},{"t":"mc","q":"Mi Leventhal modelljének két része?","o":["Kognitív rész és érzelmi rendszer","Primer és szekunder értékelés","Megközelítő és elkerülő","Biológiai és kulturális"],"a":0,"e":"Az érzelmek testi érzeteket kelthetnek, amelyeket betegségjelként értelmezhetünk."},{"t":"fill","q":"Az orvosi modell szerint az emberi szervezet olyan ___, amelynek részei külön-külön is kezelhetők.","a":["gép","gep"],"e":"Doyal és Doyal öt elképzelése közül az első."},{"t":"mc","q":"Mi a betegség-kogníció?","o":["A beteg mentális aktivitása az állapot tisztázására és a gyógymód megtalálására","A betegszerep felvétele","Az orvosi diagnózis","A gyógyszerszedés"],"a":0,"e":"Cyrol és Ditto (1990)."},{"t":"tf","q":"A „szívszorítás” példa a népi betegségre.","a":true,"e":"A kultúra oki magyarázatot, diagnózist, megelőzést és kezelést is nyújt hozzá."},{"t":"match","q":"Párosítsd a szerzőt a gondolatával!","pairs":[["Leventhal","Önszabályozási modell"],["Doyal és Doyal","Gépmodell a testről"],["Diefenbach","Hiedelmek és elvárások"],["Helman, Rubel","Népi betegségek"]],"e":"Fontos szerzők a betegség-reprezentáció témájában."},{"t":"tf","q":"A betegség-reprezentáció kialakulásában a kultúra nem játszik szerepet.","a":false,"e":"A kultúra, a tudás és az egyéni tapasztalat egyaránt forrás."}]},{"id":"u02l7","title":"Reprezentáció: család, attribúció, hatás","theory":[["Család, életkor, attribúció","Susman: a beteg gyerek és a szülő rákfogalma hasonló; Zborowski, Crane és Martin: a szülői minták a felnőttkori betegségmagatartást is formálják; Dielman, Mechanic: csekély hatás. <b>Lipowski</b>: intrapszichikus, viselkedéses és társas-szociális összetevő. <b>Helman</b>: a laikusok az okot helyezhetik az egyénen belülre, a természetbe, a társadalomba vagy a természetfelettibe."],["Hatás az egészségre","<b>Leventhal</b>: a megküzdés közvetít a reprezentáció és a kimenetel között. <b>Hagger és Orbell (2003)</b>: a kontrollálhatóságba és gyógyíthatóságba vetett hit a problémafókuszú, a következmény, identitás, időbeli lefolyás az érzelemközpontú megküzdéssel jár együtt; a megküzdés módosíthatja a hatást. Ha nő a kontrollba vetett hit, javul a fizikai és szociális működés."]],"qs":[{"t":"match","q":"Párosítsd a szerzőt a gondolatával!","pairs":[["Lipowski","Három reakcióösszetevő"],["Susman","Hasonló rákfogalom szülő-gyerek"],["Hagger és Orbell","Megküzdés módosítja a hatást"]],"e":"Fontos kutatások a család és a hatás témájában."},{"t":"tf","q":"Hagger és Orbell szerint a kontrollálhatóságba vetett hit a problémafókuszú megküzdéssel jár együtt.","a":true,"e":"A következmény- és identitásdimenziók az érzelemközpontú megküzdéssel."},{"t":"mc","q":"Hová helyezheti a laikus az egészség-betegség okát Helman szerint?","o":["Az egyénen belülre, a természetbe, a társadalomba, a természetfelettibe","Csak a genetikába","Csak a környezetbe","Csak az orvosi hibába"],"a":0,"e":"Négy terület."},{"t":"tf","q":"A szülői betegségnézetek hatása a gyermek hiedelmeire minden kutatásban egyértelműen igazolódott.","a":false,"e":"Dielman és Mechanic csekély kapcsolatot talált."},{"t":"mc","q":"Mi a megküzdés szerepe Leventhal szerint?","o":["Közvetítő a reprezentáció és a kimenetel között","Nincs szerepe","Csak a diagnózist befolyásolja","Helyettesíti a reprezentációt"],"a":0,"e":"Hagger és Orbell szerint módosíthatja is a hatást."},{"t":"mc","q":"Melyik Lipowski három összetevőjének egyike?","o":["Intrapszichikus aspektus","Gazdasági aspektus","Genetikai aspektus","Jogi aspektus"],"a":0,"e":"Intrapszichikus, viselkedéses és társas-szociális."},{"t":"tf","q":"Ha fokozódik a beteg kontrollba vetett hite, az fokozatos javuláshoz vezethet a fizikai állapotában.","a":true,"e":"Ez a betegség-reprezentáció megváltoztatásának lehetséges haszna."}]}],"color":"#1cb0f6"},{"id":"u03","title":"Stressz és megküzdés","desc":"GAS, Lazarus, immunrendszer, támasz","lessons":[{"id":"u03l1","title":"A stressz és az általános adaptációs szindróma","theory":[["Stressz, stresszor","<b>Selye</b>: a stressz a szervezet <b>nem specifikus válasza</b> bármilyen igénybevételre. A stressz alkalmazkodás, a szervezet egyensúlyának megőrzése a túlélésért. <b>Stresszor</b>: minden inger, amely alkalmazkodásra készteti a szervezetet (fizikai behatások, pszichoszociális stresszorok)."],["GAS: 3 szakasz","<b>Általános Adaptációs Szindróma</b> (Selye): (1) <b>alarm</b> – rövid, szimpatikus aktiváció, adrenalin, noradrenalin ↑, emésztés gátolt (Cannon: fight or flight); (2) <b>ellenállás</b> – hosszabb stressz, agyalapi mirigy–mellékvesekéreg-tengely, kortikoszteroidok (kortizol); a tartós hormonhatás károsít (fekély); (3) <b>kimerülés</b> – a szervezet feléli tartalékait."],["Selye kísérletei","Különböző stresszorok azonos szervi elváltozásokat okoztak: a <b>mellékvesekéreg megnagyobbodása</b> és túlműködése, a <b>csecsemőmirigy és nyirokcsomók sorvadása</b>, <b>gyomor- és bélfekélyek</b>."]],"qs":[{"t":"mc","q":"Ki szerint a stressz a szervezet nem specifikus válasza bármilyen igénybevételre?","o":["Selye","Lazarus","Cannon","Kobasa"],"a":0,"e":"Selye definíciója."},{"t":"match","q":"Párosítsd a GAS szakaszát a jellemzőjével!","pairs":[["Alarm","Szimpatikus aktiváció, adrenalin"],["Ellenállás","Kortizol, HPA-tengely"],["Kimerülés","Tartalékok felélése"]],"e":"A GAS három szakasza."},{"t":"fill","q":"A stresszt kiváltó ingereket ___ nevezzük.","a":["stresszornak","stresszor","stresszorok"],"e":"Minden olyan inger, ami alkalmazkodásra készteti a szervezetet."},{"t":"tf","q":"Az alarmszakasz hosszan tartó, és a parasszimpatikus hatás fokozódik benne.","a":false,"e":"Rövid ideig tart, a szimpatikus hatás fokozódik."},{"t":"mc","q":"Melyik hormon biztosítja az alkalmazkodást az ellenállási szakaszban?","o":["Kortizol (kortikoszteroid)","Inzulin","Melatonin","Oxitocin"],"a":0,"e":"Az agyalapi mirigy–mellékvesekéreg-tengely fokozott működése révén."},{"t":"mc","q":"Melyik NEM Selye kísérleteinek megfigyelése?","o":["A mellékvesekéreg sorvadása","A mellékvesekéreg megnagyobbodása","A csecsemőmirigy sorvadása","Gyomorfekély kialakulása"],"a":0,"e":"A mellékvesekéreg megnagyobbodik és túlműködik."},{"t":"mc","q":"Kinek a „fight or flight” reakciójával azonos az alarmszakasz?","o":["Cannon","Selye","Lazarus","Antonovsky"],"a":0,"e":"Cannon vészreakciója az akut veszély elhárítására irányuló energiamobilizálás."},{"t":"tf","q":"A kimerülési szakaszban a szervezet feléli tartalékait.","a":true,"e":"Hosszabb ideig tartó alkalmazkodás esetén."}]},{"id":"u03l2","title":"Akut és krónikus stressz élettana","theory":[["Akut stresszválasz","A limbikus területek aktiválódnak, az információ a kérgi asszociációs területekhez jut. Új vagy fenyegető inger esetén a <b>hypothalamus</b> aktiválja a neuroendokrin rendszereket és a szimpatikus idegrendszert. Gyors változások: vérnyomás ↑, pulzus ↑, pupilla tágul, nyálelválasztás és verejtékezés ↑, a vese kiválasztása ↓, vázizom vérellátása ↑, emésztőrendszeré ↓."],["Krónikus stressz hatásai","<b>Szív-érrendszer</b>: vérnyomás, pulzus, vércukor, vérzsír ↑ (hipertónia, szklerózis). <b>Emésztés</b>: fekélyek (colitis ulcerosa, Crohn, reflux, IBS). <b>Immunrendszer</b>: gátlás (daganatok állatkísérletben, allergia, autoimmun). <b>Szexuális működés</b>: meddőség, vetélés. <b>Izom-csont</b>: tenziós fejfájás, hát- és derékfájás. Asztma. Hangulat- és alvászavar."],["Források","A krónikus stresszforrások többsége a <b>társas kapcsolatokkal</b> és a beilleszkedéssel függ össze. Férfiaknál a <b>munkahelyi</b> stressz, nőknél a <b>házastársi</b> stressz kiemelt. Akut súlyos stressz, életesemények hosszú távú változásokat okozhatnak; a korai hatás az anyadepriváció."],["Információfeldolgozás: 3 lépés","(1) <b>Kapufunkció</b> (hippokampusz): a stresszorok az új, ellentmondásos, veszélyes ingerek; gyengítheti: fáradtság, gyógyszer, alkohol, személyiség. (2) <b>Összehasonlító funkció</b>: korábbi tapasztalattal, tudattalanul. (3) <b>Döntési funkció</b>: részben tudatos, részben tudattalan."]],"qs":[{"t":"mc","q":"Melyik agyi terület aktiválja a szimpatikus idegrendszert akut stresszben?","o":["Hypothalamus","Kisagy","Híd","Nyúltvelő"],"a":0,"e":"Új vagy fenyegető ingernél jelet kap, és vészreakciót vált ki."},{"t":"tf","q":"Akut stresszben a vázizmok vérellátása fokozódik, az emésztőrendszeré csökken.","a":true,"e":"A harcra vagy menekülésre való felkészülés része."},{"t":"match","q":"Párosítsd a rendszert a krónikus stressz hatásával!","pairs":[["Emésztőrendszer","Fekélyek, IBS"],["Immunrendszer","Immungátlás"],["Izom-csont","Tenziós fejfájás"],["Szív-érrendszer","Hipertónia"]],"e":"A krónikus stressz sokféle testi hatást okoz."},{"t":"mc","q":"Melyik a kapufunkció?","o":["Az inger átjut: semleges vagy alkalmazkodást igénylő","Döntés a reakcióról","Összevetés a múlttal","Hormontermelés"],"a":0,"e":"A hippokampuszba lokalizálható."},{"t":"fill","q":"A kapufunkciót gyengítheti a fáradtság, a gyógyszer, az ___ és a személyiség.","a":["alkohol","alkoholhatás"],"e":"Ezek befolyásolják az ingerek szűrését."},{"t":"tf","q":"A nők körében a munkahelyi stressz, a férfiak körében a házastársi stressz a kiemelt.","a":false,"e":"Éppen fordítva: férfiaknál a munkahelyi, nőknél a házastársi."},{"t":"mc","q":"Melyik az információfeldolgozás második lépése?","o":["Összehasonlító funkció","Kapufunkció","Döntési funkció","Kimerülés"],"a":0,"e":"Összevetés a korábbi tapasztalattal, tudattalanul."},{"t":"mc","q":"Mi a krónikus stressz hatása az immunrendszerre?","o":["Immungátlás","Immunerősítés","Nincs hatás","Csak lázas állapot"],"a":0,"e":"Daganatok (állatkísérletek), allergiás és autoimmun kórképek."}]},{"id":"u03l3","title":"Lazarus modellje és a megküzdés","theory":[["Lazarus: megküzdés","<b>Megküzdés</b>: minden kognitív vagy viselkedéses erőfeszítés, amellyel az egyén azokat a külső vagy belső hatásokat próbálja kezelni, amelyeket úgy értékel, hogy felülmúlják erőforrásait. A kognitív értékelés szerepét hangsúlyozza."],["Elsődleges és másodlagos értékelés","<b>Elsődleges</b>: pozitív vagy negatív a jelentés? Negatívnál: (1) pillanatnyi veszély, (2) tartós jövőbeli fenyegetés, (3) <b>kihívás</b>; általában nem tudatos. <b>Másodlagos</b>: elegendők-e az erőforrások? Stressz akkor van, ha úgy érezzük, nem."],["Két fő mód","Lazarus két fő módot különített el: <b>problémamegoldásra irányuló erőfeszítések</b> és <b>érzelmek szabályozása</b> (érzelemközpontú megküzdés – a szorongás, agresszió csökken). Szándékos, erőfeszítést igénylő, tudatos reakciók a nagy megterhelésekre."]],"qs":[{"t":"mc","q":"Mit jelent az elsődleges értékelés Lazarus modelljében?","o":["Pozitív vagy negatív az esemény jelentése, és milyen típusú a fenyegetés","Az erőforrások mérlegelése","A stresszkezelő program kiválasztása","A fiziológiai válasz mérése"],"a":0,"e":"Pillanatnyi veszély, tartós fenyegetés vagy kihívás."},{"t":"mc","q":"Mikor beszélünk stresszről Lazarus szerint?","o":["Ha úgy érezzük, erőforrásaink nem elegendők","Ha az esemény negatív","Ha emelkedik a pulzus","Ha új ingerrel találkozunk"],"a":0,"e":"Ez a másodlagos értékelés eredménye."},{"t":"tf","q":"Az elsődleges értékelés általában tudatosan zajlik.","a":false,"e":"Általában nem tudatos."},{"t":"match","q":"Párosítsd az elsődleges értékelés kimenetelét a jelentéssel!","pairs":[["Pillanatnyi veszély","Azonnali fenyegetés"],["Tartós fenyegetés","A jövőt is érinti"],["Kihívás","Lehetőség a megküzdésre"]],"e":"Negatív esemény három lehetséges értékelése."},{"t":"fill","q":"Lazarus a megküzdés két fő módja: a problémamegoldás és az ___ szabályozása.","a":["érzelmek","érzelem","erzelmek"],"e":"Az érzelemközpontú megküzdés csökkenti a szorongást és az agressziót."},{"t":"tf","q":"A másodlagos értékelés az erőforrások elégségességéről dönt.","a":true,"e":"Ha nem elegendők, stresszt élünk át."},{"t":"mc","q":"Melyik hangsúlyos Lazarus modelljében?","o":["A kognitív értékelési folyamatok","A hormonális változások","A genetika","A kor"],"a":0,"e":"A stresszorral való megküzdésben a kognitív értékelés a kulcs."}]},{"id":"u03l4","title":"Megküzdési stratégiák és stresszkezelés","theory":[["Lazarus 8 stratégiája","(1) <b>Konfrontáció</b> – korai szakaszban adaptív, tartósan nem; (2) <b>eltávolodás</b> – tartósan maladaptív; (3) <b>érzelmek és viselkedés szabályozása</b>; (4) <b>társas támogatás keresése</b> – az elérhetőség és minőség számít; (5) <b>felelősségvállalás</b> – túlzottan bűntudat; (6) <b>problémamegoldás–tervezés</b>; (7) <b>elkerülés–menekülés</b> – kialakult betegségnél maladaptív; (8) <b>pozitív jelentés keresése</b> – ha irreális, probléma."],["Schwarzer (2002) csoportosítása","Két dimenzió: időtengely és tudatossági szint. <b>Reaktív</b>: a múltra irányul, újraértékel; <b>anticipált</b>: közeli jövő kritikus eseménye; <b>preventív</b>: távoli, bizonytalan kockázat (pl. életbiztosítás); <b>proaktív</b>: általános erőforrások kialakítása, életfeltételek optimalizálása."],["Befolyásoló tényezők","<b>Megküzdési stílus</b>: a stratégiák állandó mintázata. Hat: önértékelés, külső-belső kontroll, optimizmus-pesszimizmus, nem. A kezeléssel kapcsolatos <b>kontroll észlelése</b> a jó kimenettel korrelál; a súlyosság feltételezése az érzelmi megküzdéssel, tagadással, elkerüléssel. <b>Megközelítő</b> út (adaptív, személyes növekedés) vs. <b>elkerülő</b> út (nem adaptív, a stresszor paradox követése)."],["Stresszkezelés","a) <b>Stresszforrások csökkentése</b>: időgazdálkodás, prioritások, figyelemelterelés. b) <b>Hatékonyabb megoldás</b>: többszempontú elemzés, érzések tudatosítása, támogatás kérése. c) <b>Testi reakciók</b>: testmozgás, relaxáció, alvás, zene, táplálkozás. <b>Stresszkezelő programok</b>: 12–16 óra, heti 2 órás alkalmak; pszichoedukáció, kognitív és viselkedésterápiás elemek."]],"qs":[{"t":"match","q":"Párosítsd a Schwarzer-féle megküzdést a jellemzővel!","pairs":[["Reaktív","Múltra irányul, újraértékelés"],["Anticipált","Közeli jövő kritikus eseménye"],["Preventív","Távoli, bizonytalan kockázat"],["Proaktív","Általános erőforrások építése"]],"e":"Schwarzer két dimenziója: idő és tudatosság."},{"t":"mc","q":"Melyik stratégia adaptív a betegség korai szakaszában, de tartósan maladaptív?","o":["Konfrontáció","Társas támogatás keresése","Problémamegoldás","Pozitív jelentés keresése"],"a":0,"e":"Az aktív szembehelyezkedés tartósan rontja az alkalmazkodást."},{"t":"tf","q":"A társas támogatás keresésénél a mennyiség a legfontosabb.","a":false,"e":"Az elérhetőség és a minőség a fontos."},{"t":"mc","q":"Hány megküzdési kategóriát különített el Lazarus a két fő csoporton belül?","o":["8","5","3","12"],"a":0,"e":"Konfrontáció, eltávolodás, szabályozás, társas támogatás, felelősségvállalás, problémamegoldás, elkerülés, pozitív jelentés."},{"t":"fill","q":"Az életbiztosítás példa a ___ megküzdésre.","a":["preventív","preventiv"],"e":"Távoli, nem biztos kockázatra készülünk."},{"t":"tf","q":"A betegség kontrollálhatóságának észlelése összefügg a jó pszichés állapottal.","a":true,"e":"Csabai és Molnár (2009)."},{"t":"mc","q":"Mennyi egy stresszkezelő program jellemző időtartama?","o":["12–16 óra, heti 2 órás alkalmak","3 óra egy nap alatt","50 óra","Egyetlen alkalom"],"a":0,"e":"Pszichoedukációs, kognitív és viselkedésterápiás elemekkel."},{"t":"mc","q":"Melyik a stresszkezelés testi reakciókat befolyásoló technikája?","o":["Relaxáció","Értékek tisztázása","Időgazdálkodás","Környezetváltás"],"a":0,"e":"A c) csoportba tartozik: testmozgás, relaxáció, alvás, zene, táplálkozás."},{"t":"tf","q":"Az elkerülő megküzdés nem adaptív, mert a stresszor paradox módon fokozott figyelmet kap.","a":true,"e":"A zavaró gondolatok és érzelmek felerősödnek."}]},{"id":"u03l5","title":"Pszichológiai immunrendszer és társas támogatás","theory":[["Pszichológiai immunrendszer","Személyiségforrások, amelyek képessé teszik az egyént a stressz tartós elviselésére és a fenyegetésekkel való eredményes megküzdésre úgy, hogy a személyiség integritása ne sérüljön, inkább gazdagodjon. <b>Aktív védettség</b>. Mérése: <b>PIK</b>, 80 itemes teszt (Oláh Attila). A patológia a pszichológiai immunkompetencia gyengeségével, az egészség erősségével korrelál."],["A PI három alrendszere","(1) <b>Megközelítő-Monitorozó</b>: a fizikai környezet megismerése, kontrollja (pl. optimizmus). (2) <b>Alkotó-Végrehajtó</b>: a helyzet és önmagunk átalakítása (Bandura), problémamegoldó képesség. (3) <b>Önregulációs</b>: figyelem-tudat-érzelem feletti kontroll (pl. kitartás). Személyiségjegyek = „pszichológiai antitestek”."],["Társas támogatás","<b>Kaplan (1977)</b>: a mások által biztosított pszichoszociális erőforrások megléte vagy hiánya. Összetevők: pozitív érzelmek kifejezése, egyetértés, biztatás a kifejezésre, anyagi segítség, megerősítés a támogató rendszer tagságáról. Pozitív: az egyedül élők halálozása magasabb. <b>Mechanic</b>: a támogató család is lehet stresszforrás."],["Pozitív és negatív hatások","<b>Megelőzés</b>: csökkenti a bizonytalanságot, jó példa / negatívan: növeli az aggodalmat, bagatellizálás. <b>Megküzdés</b>: pozitív visszajelzés, szimpátia, információ / bántó, sajnálkozó reakciók, félrevezető információ. <b>Felépülés</b>: előírások betartásának támogatása, önállóság vágya / akadályozás, függőség növelése."]],"qs":[{"t":"mc","q":"Hány alrendszere van a pszichológiai immunrendszernek?","o":["3","2","4","5"],"a":0,"e":"Megközelítő-Monitorozó, Alkotó-Végrehajtó, Önregulációs."},{"t":"match","q":"Párosítsd az alrendszert a példával!","pairs":[["Megközelítő-Monitorozó","Optimizmus"],["Alkotó-Végrehajtó","Problémamegoldó képesség"],["Önregulációs","Kitartás"]],"e":"A pszichológiai antitestek az alrendszerekbe csoportosulnak."},{"t":"fill","q":"A pszichológiai immunkompetencia mérésére szolgáló teszt a ___ (80 itemes, Oláh Attila).","a":["PIK","pik"],"e":"Pszichológiai Immunrendszer Kérdőív."},{"t":"tf","q":"A társas támogatás mindig egyértelműen pozitív hatású.","a":false,"e":"Mechanic szerint a támogató család is lehet stresszforrás; a hatás lehet semleges vagy negatív."},{"t":"mc","q":"Melyik társas támogatás összetevő?","o":["Anyagi segítség biztosítása","Kötelező orvosi kezelés","Szigorú kritika","Elszigetelés"],"a":0,"e":"Az összetevők: pozitív érzelmek, egyetértés, biztatás, anyagi segítség, megerősítés."},{"t":"mc","q":"Melyik negatív hatás a felépülés szakaszában?","o":["Függőség-igény növelése","Önállóság vágyának felkeltése","Előírások betartásának támogatása","Egészségre hivatkozás ösztönzőleg"],"a":0,"e":"A negatív hatás: akadályozás, nyomasztó hivatkozás az egészségre, függőség."},{"t":"tf","q":"A házasságban élők halálozási statisztikái kedvezőbbek, mint az egyedülállóké.","a":true,"e":"Az egyedül élők között szignifikánsan magasabb a halálozás."},{"t":"mc","q":"Ki határozta meg a társas támogatást a mások által biztosított pszichoszociális erőforrások megléteként?","o":["Kaplan és mtsai (1977)","Selye","Oláh","Schwarzer"],"a":0,"e":"Nem egydimenziós jelenség."},{"t":"tf","q":"A pszichológiai immunrendszer az egyén aktív védettségét jelenti.","a":true,"e":"Az azonnali aktiválás képességével jellemezhető."}]}],"color":"#ce82ff"},{"id":"u04","title":"Daganat, elhízás, szív-ér","desc":"Szomatikus betegségek lélektana I.","lessons":[{"id":"u04l1","title":"Daganatos betegségek: pszichés hatás","theory":[["Alapok","A betegségek közül a <b>második leggyakoribb halálok</b>. Traumatikus esemény, a halállal azonosítják. <b>Damoklész kardja szindróma</b>: bármikor rosszabbodás jöhet. Jellemző: büntetés és bűntudat gondolata, stigmatizáció (a családé is), szorongás, reménytelenség, depresszió, izoláció."],["Pszichoszociális tényezők","<b>Közvetve</b>: nem megfelelő egészségmagatartás (dohányzás, helytelen táplálkozás, kockázatos szexuális élet, alkohol). <b>Közvetlenül</b>: élettani, hormonális, immunológiai folyamatokon és a stresszkezelésen keresztül. A genetika is szerepet játszik. Megelőzés: <b>primer</b>, <b>szekunder</b> (korai felismerés)."],["Életminőség","Émelygés, hányinger, erős fájdalom, mellékhatások – a stressz és szorongás fokozza. <b>Anticipátoros hányinger</b> alakulhat ki. A szorongás az izomfeszültséggel és a figyelem fájdalomra összpontosításával növeli a fájdalomérzékenységet és csökkenti a tűrőképességet. Testképváltozás → szexuális és önértékelési gondok; fokozott fáradékonyság → depresszió."],["Pszichés következmények","A betegek közel felénél <b>poszttraumás tünetek</b>; kb. 50% számol be <b>kognitív</b> korlátozottságról (koncentráció, emlékezés). Társas támogatás: akut szakaszban nagyobb, krónikusban csökken. Pozitív oldal (poszttraumás növekedés): több értelem az életben, a jelenben élés, mélyebb kapcsolatok."]],"qs":[{"t":"tf","q":"A daganatos betegség a második leggyakoribb halálok a betegségek között.","a":true,"e":"Traumatikus eseményként élik meg, a halállal azonosítják."},{"t":"mc","q":"Mit jelent a Damoklész kardja szindróma?","o":["Bármikor rosszabbodhat az állapot","A kemoterápia mellékhatása","A genetikai hajlam","A betegségtagadás"],"a":0,"e":"A bizonytalan, folyamatos fenyegetettség élménye."},{"t":"match","q":"Párosítsd a tényezőt a típusával!","pairs":[["Dohányzás, alkohol","Közvetett (egészségmagatartás)"],["Immunológiai folyamatok","Közvetlen"],["Korai felismerés","Szekunder prevenció"]],"e":"A pszichoszociális tényezők közvetve és közvetlenül hatnak."},{"t":"fill","q":"A kemoterápia előtti, kondicionált hányinger neve ___ hányinger.","a":["anticipátoros","anticipatoros"],"e":"A stressz és szorongás fokozza."},{"t":"mc","q":"Hogyan hat az erős szorongás a fájdalomra?","o":["Növeli az érzékenységet és csökkenti a tűrést","Csökkenti a fájdalmat","Nincs hatása","Csak a tolerancia nő"],"a":0,"e":"Izomfeszültség és a figyelem fájdalomra összpontosítása révén."},{"t":"tf","q":"A társas támogatás a krónikus szakaszban nagyobb, mint az akutban.","a":false,"e":"Akut szakaszban nagyobb, krónikusban csökken."},{"t":"tf","q":"A betegek közel felénél előfordulnak poszttraumás tünetek.","a":true,"e":"Kb. 50% kognitív korlátozottságról is beszámol."},{"t":"mc","q":"Melyik NEM tartozik a daganatos betegség pozitív pszichés következményei közé?","o":["Elhatalmasodó reménytelenség","A jelenben élés megtanulása","Kapcsolatok elmélyítése","Több értelem keresése az életben"],"a":0,"e":"A reménytelenség a negatív következmény."}]},{"id":"u04l2","title":"Személyiség, stressz és intervenció","theory":[["Rákra hajlamosító személyiség","(1) <b>C típus</b>: konfliktuskerülő, túlalkalmazkodó, negatív érzelmeit tagadó, elfojtó személyiség – ma már <b>kevésbé elfogadott</b> koncepció (soktényezős folyamat: stádium, daganat helye, premorbid helyzet). (2) <b>Küzdőszellem</b>: az előbbi ellentéte."],["Kutatások","<b>Greer (1979)</b>: műtött mellrákos nők, túlélés 5, 10, 15 év után – a küzdőszellemmel és tagadással jellemezhetők túlélése felülmúlta az elfogadó és reménytelen csoportét. <b>Dean és Surtles (1995)</b>: a gyászreakció egészséges; akinél nem volt gyászmunka, rosszabb túlélés (a C típust erősítette). <b>Watson (1999)</b>: tehetetlenség és reménytelenség ↑ visszaesés; depresszió ↑ mortalitás."],["Stressz és család","Kontrollálhatatlan helyzetek immunológiai hatással gyengítik a daganatsejtek elleni védekezést; a társas támasz segíti az <b>NK-sejteket</b>. <b>Család</b>: (1) tagadás, ragaszkodás a régihez, (2) felbomlás, (3) rugalmas alkalmazkodás. Diagnózis után magas összetartozás, majd krízisek, izoláció."],["Pszichológiai intervenciók","<b>Tájékoztatás</b> (kontrollérzés), tanácsadás, pszichoterápia. Célok: megküzdés, életminőség javítása, regressziós állapotok stabilizálása, terápiára szocializálás, motiváció, stigmatizáció és alvászavar kezelése. Eszközök: támogató közeg, relaxáció, Simonton, jóga, tánc, mindfulness, kreatív terápiák, zene, CBT. <b>Családterápia</b>: erőforrások megtalálása, nyílt kommunikáció."]],"qs":[{"t":"mc","q":"Melyik személyiségtípust hozták kapcsolatba a rákkal?","o":["C típus","A típus","B típus","D típus"],"a":0,"e":"Konfliktuskerülő, érzelmeit elfojtó személyiség."},{"t":"tf","q":"A C típus koncepciója ma teljes mértékben elfogadott.","a":false,"e":"Ma már kevésbé elfogadható; soktényezős folyamat."},{"t":"mc","q":"Melyik csoport túlélése volt kedvezőbb Greer vizsgálatában?","o":["Küzdőszellem és tagadás","Elfogadás","Reménytelenség","Mindhárom azonos"],"a":0,"e":"Műtéten átesett mellrákos nők 5, 10, 15 év után."},{"t":"match","q":"Párosítsd a szerzőt a megállapítással!","pairs":[["Greer (1979)","Küzdőszellem és túlélés"],["Dean és Surtles (1995)","Gyászmunka hiánya rosszabb túlélés"],["Watson (1999)","Reménytelenség ↑ visszaesés"]],"e":"Három fontos mellrák-vizsgálat."},{"t":"fill","q":"A társas támasz az ___ sejteket segíti a daganatok elleni védekezésben.","a":["NK","nk","természetes ölő","NK-"],"e":"A kontrollálhatatlan helyzetek ezzel szemben gyengítik a védekezést."},{"t":"mc","q":"Melyik nem a családi reakció típusa daganatos betegség esetén?","o":["Teljes közömbösség a beteg iránt","Tagadás, ragaszkodás a régi rendhez","Felbomlás","Rugalmas alkalmazkodás"],"a":0,"e":"A három típus: tagadás/alacsony alkalmazkodás, felbomlás, rugalmas alkalmazkodás."},{"t":"tf","q":"A tájékoztatás minden esetben fontos, mert kontrollérzést ad.","a":true,"e":"A pszichológiai intervenció alapja."},{"t":"mc","q":"Mi a családterápia egyik célja daganatos betegségben?","o":["Nyílt kommunikáció kialakítása","A beteg elszigetelése","A diagnózis eltitkolása","A gyász megakadályozása"],"a":0,"e":"Valamint az erőforrások megtalálása és elmélyítése."}]},{"id":"u04l3","title":"Obesitas","theory":[["Alapadatok","Évente kb. 300 ezer ember halálához járul hozzá, hatalmas költségteher, sok komorbid zavar. Két szakasz: <b>súlynyerő (dinamikus)</b> – gyarapodás, amit még könnyebb megállítani; <b>súlytartó (statikus)</b> – stabilizálódott."],["BMI és zsíreloszlás","<b>BMI</b> (testtömegindex): Adolphe Quetelet dolgozta ki (1800-as évek). WHO: <b>25 kg/m² felett túlsúly, 30 kg/m² felett elhízás</b>. Hátrány: nem különbözteti meg az izom- és zsírtömeget. A <b>has/csípő hányados</b> alapján: <b>alma típus</b> (android, férfiak) – veszélyesebb (érelmeszesedés, szívinfarktus), <b>körte típus</b> (gynoid, nők)."],["Következmények és etiológia","Légzés és keringés romlása, <b>inzulinrezisztencia</b>, hiperinzulinizmus, 2-es típusú diabétesz, ízületi kopás, gerincbetegségek, csökkent mozgás; stigmatizáció, önértékelési gondok, izoláció. Etiológia: genetikai, hormonális, pszichológiai; <b>primer</b> és <b>szekunder</b> elhízás. <b>Set-point elmélet</b> (Nisbett). Evés: örömforrás, kompenzáció, kínok csökkentése."],["Kezelés","Gyógyszeres (mellékhatások), műtét (kockázatok, kb. 20% visszahízás). <b>Pszichológiai intervenció</b>: (1) információgyűjtés (súlyváltozás, előzmények, komorbiditás, motiváció, énhatékonyság, változásra való felkészültség); (2) célok: először <b>5–10%</b> fogyás. Területek: hiedelmek és attitűdök (motivációs interjú), érzelmi viszonyulások, társas kapcsolatok, környezeti kontroll, mozgás."]],"qs":[{"t":"mc","q":"Melyik BMI-érték felett beszélünk elhízásról a WHO szerint?","o":["30 kg/m²","25 kg/m²","20 kg/m²","35 kg/m²"],"a":0,"e":"25 felett túlsúly, 30 felett elhízás."},{"t":"fill","q":"A BMI módszerét Adolphe ___ dolgozta ki az 1800-as években.","a":["Quetelet","quetelet"],"e":"A BMI nem különbözteti meg az izom- és zsírtömeget."},{"t":"match","q":"Párosítsd a típust a jellemzővel!","pairs":[["Alma (android)","Hasi, férfiakra jellemző, veszélyesebb"],["Körte (gynoid)","Nőkre jellemző"],["Dinamikus fázis","Súlygyarapodás"],["Statikus fázis","Stabilizálódott súly"]],"e":"A zsíreloszlás és az elhízás két szakasza."},{"t":"tf","q":"A BMI hátránya, hogy nagy izomtömegű személyeknél félrevezető lehet.","a":true,"e":"Nem tesz különbséget izom- és zsírtömeg között."},{"t":"mc","q":"Melyik zsíreloszlás jár nagyobb kockázattal (érelmeszesedés, szívinfarktus)?","o":["Alma típus","Körte típus","Mindkettő azonos","Egyik sem"],"a":0,"e":"Hasi, android típus."},{"t":"mc","q":"Mekkora fogyás az első célkitűzés a pszichológiai intervencióban?","o":["5–10%","20–30%","1–2%","50%"],"a":0,"e":"Kis, megvalósítható lépésekkel indulnak."},{"t":"tf","q":"A műtéti kezelésnél nincs visszahízás veszélye.","a":false,"e":"Kb. 20% visszahízás, sok kockázat."},{"t":"mc","q":"Melyik a Nisbett nevéhez köthető elmélet?","o":["Set-point elmélet","Kapukontroll","Egészséghiedelem-modell","Hiperreaktivitás"],"a":0,"e":"A szervezetnek elhízásban is meglehet a „beállított” testsúlya."},{"t":"mc","q":"Mi az elhízás következménye a szénhidrát-anyagcserében?","o":["Inzulinrezisztencia, 2-es típusú diabétesz","Inzulinhiány, 1-es típusú diabétesz","Alacsony vércukor","Pajzsmirigy-túlműködés"],"a":0,"e":"A zsír felhalmozódása inzulinrezisztenciát és hiperinzulinizmust okoz."}]},{"id":"u04l4","title":"Szív- és érrendszeri betegségek","theory":[["Betegségek és rizikófaktorok","Szívkoszorúér-betegségek: angina pectoris (oxigénhiány), szívinfarktus; szívizombetegség, szívritmuszavarok, billentyűbetegségek. <b>Nem módosítható</b>: életkor, férfi nem, genetika, érbetegség, alacsony szocioökonómiai státusz. <b>Módosítható</b>: testi (magas vérnyomás, elhízás, magas vérzsír, cukorbetegség), viselkedéses (mozgásszegény élet, dohányzás, alkohol, társas izoláció), érzelmi (stressz)."],["Ellenségesség","Az <b>ellenségesség és harag</b> a kulcs inkább, mint az A típus általában. Az ellenséges személyek több helyzetet értékelnek stresszként/kihívásként → szimpatikus válasz → vérnyomás és pulzus nő, szívizom-károsodás, érelmeszesedés. <b>Smith tranzakcionális modellje</b>: ellenségesség → társas támogatás csökken → rosszabb negatív érzelem-kezelés → több stressz → még több harag."],["Depresszió, szorongás","Az ellenséges, cinikus viselkedés csökkenti az egészségvédő magatartást. A <b>depresszió</b> emeli a halálos iszkémiás szívbetegség, szívleállás, infarktus esélyét; szívbetegség után gyakori a depresszió és szorongás. Szívinfarktus után a <b>szorongás</b> a legkorábbi és legintenzívebb reakció. Mechanizmus: <b>HPA-tengely</b> túlműködése, vérlemezke-aktivitás ↑ → érelmeszesedés, trombusképzés. Prevenció: dohányzás, alkohol, mozgás, vérnyomás."]],"qs":[{"t":"mc","q":"Melyik a nem módosítható szív- és érrendszeri rizikófaktor?","o":["Genetikai hajlam","Dohányzás","Elhízás","Mozgásszegény életmód"],"a":0,"e":"Nem módosítható: életkor, férfi nem, genetika, érbetegség, alacsony SES."},{"t":"match","q":"Párosítsd a rizikófaktort a csoportjával!","pairs":[["Magas vérnyomás","Testi"],["Dohányzás","Viselkedéses"],["Ellenségesség","Érzelmi"],["Genetikai hajlam","Nem módosítható"]],"e":"A módosítható faktorok: testi, viselkedéses, érzelmi."},{"t":"tf","q":"Szívinfarktus után a szorongás a legkorábbi és legintenzívebb pszichológiai reakció.","a":true,"e":"A depresszió és szorongás a HPA-tengely túlműködésével is összefügg."},{"t":"mc","q":"Mit állít Smith tranzakcionális modellje?","o":["Az ellenségesség csökkenti a társas támogatást, ami még több haraghoz vezet","A depresszió védi a szívet","A kontroll javítja a vérnyomást","Az optimizmus növeli a kockázatot"],"a":0,"e":"Ördögi kör: ellenségesség → kevesebb támogatás → több stressz → több harag."},{"t":"fill","q":"A szív- és érrendszeri betegségeknél inkább az ellenségesség és a ___ a kulcs, mint az A típus általában.","a":["harag"],"e":"Ellenséges személyek több helyzetet értékelnek stresszként."},{"t":"tf","q":"A depresszió növeli a szívleállás és a halálos iszkémiás szívbetegség esélyét.","a":true,"e":"A szorongásos zavarok a szíveredetű halálozást is növelik."},{"t":"mc","q":"Mi járul hozzá a szorongás/depresszió és érelmeszesedés összefüggéséhez?","o":["HPA-tengely túlműködése, vérlemezke-aktivitás növekedése","Alacsony vérnyomás","Csökkent kortizol","Fokozott immunerő"],"a":0,"e":"Ez trombusképzéshez is hozzájárul."},{"t":"tf","q":"Az ellenséges, cinikus viselkedés növeli az egészségvédő magatartást.","a":false,"e":"Csökkenti azt."}]}],"color":"#ff9600"},{"id":"u05","title":"Asztma, fájdalom, diabétesz","desc":"Szomatikus betegségek II., placebo","lessons":[{"id":"u05l1","title":"Asztma","theory":[["Mi az asztma?","Epizodikus és krónikus betegség. Szerepet játszik a <b>simaizom-diszfunkció</b>, a légutak gyulladása és hiperérzékenysége, a duzzanat és a nyáktermelés; a simaizom-összehúzódás a hörgők szűkületét okozza. Szűkül az elvégezhető aktivitás köre, romlik az alvás- és életminőség; gyerekeknél iskolai hiányzás, koncentrációromlás, felnőtteknél munkakiesés, sürgősségi ellátás. Súlyossága az enyhétől a halálosig (kezeletlen) terjed, váltakozó."],["Rizikófaktorok","Az okok nem teljesen tisztázottak. Családi halmozódás; komplex, multigénes genetikai betegség a környezettel kölcsönhatásban. Atópiás dermatitis, por, macskaszőr, lakókörülmények, légszennyezés, elhízás, etnikai kisebbségek, szegénység. <b>Pszichológiai stressz</b> növeli a légzőszervi fertőzések kockázatát. Gyerekeknél a fiúk, felnőtteknél a nők érintettebbek. Kamaszkorra 60–70%-ban megszűnik."],["Kezelés","Triggerek kerülése, gyors tüneti és hosszú távú gyógyszeres kezelés (a betartás fontos; befolyásolja: IQ, informáltság, kultúra, hiedelmek). <b>4 szintű stratégia</b>: oktatás, környezeti kontroll, gyógyszerek szedése, a hatékonyság értékelése. Pszichoszociális beavatkozás, terápia, családterápia. Komorbid: depresszió, szorongás, kognitív romlás (hipoxia miatt)."]],"qs":[{"t":"mc","q":"Mi okozza a hörgők szűkületét az asztmában?","o":["A simaizom összehúzódása","A csontritkulás","Az inzulinhiány","Az izomsorvadás"],"a":0,"e":"Emellett gyulladás, duzzanat, nyáktermelés."},{"t":"tf","q":"Az asztma tünetei mindig jól észlelhetők.","a":false,"e":"Az asztmát időszakosság, váltakozás jellemzi; nem feltétlenül észlelhetők a tünetek."},{"t":"mc","q":"Melyik asztmára vonatkozó állítás helyes?","o":["Kamaszkorra 60–70%-ban megszűnik","Mindig felnőttkorban kezdődik","Soha nem jár szorongással","Csak férfiakat érint"],"a":0,"e":"Gyerekeknél a fiúk, felnőtteknél a nők gyakoribbak."},{"t":"match","q":"Párosítsd a csoportot a következménnyel!","pairs":[["Gyerekek","Iskolai hiányzás"],["Felnőttek","Munkából való kiesés"],["Súlyos eset","Sürgősségi ellátás, hospitalizáció"]],"e":"Az asztma életminőségre gyakorolt hatása."},{"t":"fill","q":"A 4 szintű asztmakezelési stratégia elemei: oktatás, környezeti kontroll, ___ szedése és a hatékonyság értékelése.","a":["gyógyszerek","gyogyszerek","gyógyszer"],"e":"A gyógyszerek betartása fontos."},{"t":"mc","q":"Mit növel a pszichológiai stressz asztmában?","o":["A légzőszervi fertőzések kockázatát","A tüdőkapacitás","Az immunerő","A légzésszám csökkenése"],"a":0,"e":"A pszichológiai stressz növeli a légzőszervi fertőzések kockázatát."},{"t":"tf","q":"Az asztma komorbid zavarai közé tartozik a depresszió és a szorongás.","a":true,"e":"A hipoxia miatt a kognitív képességek romolhatnak."}]},{"id":"u05l2","title":"Krónikus fájdalom és típusai","theory":[["Fogalom","Időben kiterjedt fájdalom, amely betegséget kísér vagy el nem múló sérülés mentén áll fenn; legalább <b>3 hónap</b>, időről időre visszatér, akadályozza a munkát és társas tevékenységet. Az akuttal ellentétben <b>nem adaptív</b>. Rontja az alvást, a szociális működést, korlátozottsághoz, rokkantsághoz, pszichés zavarokhoz vezet; az orvoshoz fordulás és gyógyszervásárlás jelentős oka. Következmény: distressz, depresszió, szorongás, függőségek. Kezelés: CBT, relaxáció."],["Fájdalomtípusok","<b>Szomatikus</b>: fájdalomreceptorok aktiválása felszíni vagy mély szöveti sérülésnél; mély: tompa, sajgó, lokalizált; felszíni: éles, égő, szúró. <b>Viscerális</b>: belső szervek; nem jól lokalizálható, nyomó, szorító. <b>Neuropátiás</b>: neurológiai változás; hasogató, elektromos, szúró, égő (pl. fantomvégtag-fájdalom)."],["Szindrómák","<b>Deréktáji fájdalom</b>: leggyakoribb munkahelyi alkalmatlanság és hiányzás oka. <b>Tenziós fejfájás</b>: homlok, nyak, váll; stressz, kihagyott étkezés, mozgáshiány; kezelés: CBT, stresszkezelés, relaxáció. <b>Migrén</b>: nők 18%-át, férfiak 6%-át érinti; aura, émelygés, fény- és hangérzékenység; termikus és EMG biofeedback. <b>Fibromyalgia</b>: általános fájdalom, nyomásérzékeny pontok, nő–férfi arány 7:1, ismeretlen ok."]],"qs":[{"t":"mc","q":"Legalább mennyi ideig tart a krónikus fájdalom?","o":["3 hónap","1 hét","1 hónap","2 év"],"a":0,"e":"Időről időre visszatér, akadályozza a munkát és a társas tevékenységet."},{"t":"tf","q":"A krónikus fájdalom az akut fájdalomhoz hasonlóan adaptív.","a":false,"e":"A krónikus fájdalom nem tekinthető adaptívnak."},{"t":"match","q":"Párosítsd a típust a jellemzőjével!","pairs":[["Szomatikus (mély)","Tompa, sajgó, lokalizált"],["Viscerális","Belső szerv, nem lokalizálható"],["Neuropátiás","Hasogató, elektromos, égő"]],"e":"A fájdalom három fő típusa."},{"t":"fill","q":"A nők 18%-át és a férfiak 6%-át érintő fájdalomszindróma a ___.","a":["migrén","migren"],"e":"Aurával, émelygéssel és fényérzékenységgel jár."},{"t":"mc","q":"Melyik a fibromyalgia nő–férfi aránya?","o":["7:1","2:1","1:1","1:7"],"a":0,"e":"Oka ismeretlen; általános fájdalom, túlzott nyomásérzékenység."},{"t":"mc","q":"Melyik a leggyakoribb munkahellyel kapcsolatos alkalmatlanság oka?","o":["Hátfájás","Migrén","Fibromyalgia","Tenziós fejfájás"],"a":0,"e":"A hátfájás a vezető oka a munkahelyi hiányzásoknak."},{"t":"tf","q":"A fantomvégtag-fájdalom a neuropátiás fájdalmak közé tartozik.","a":true,"e":"Neurológiai változás eredménye."},{"t":"mc","q":"Melyik kezelés tartozik a migrénhez?","o":["Termikus biofeedback + relaxáció","Műtét","Antibiotikum","Csak pihenés"],"a":0,"e":"Valamint EMG biofeedback."}]},{"id":"u05l3","title":"Fájdalom: elméletek és befolyásoló tényezők","theory":[["Kapukontroll és BPS","<b>Kapukontroll elmélet</b> (Melzack és Wall): központi idegrendszeri folyamatok; az agy aktívan szűri, szelektálja, modulálja az ingereket. <b>Biopszichoszociális modell</b>: a fájdalom nem csak biológiai, hanem a bio-pszichoszociális interakció eredménye; a tapasztalat meghatározza az élményt (intenzitás, időtartam)."],["Kognitív-viselkedéses modellek","<b>Kognitív viselkedéses tranzakciós modell</b> (Kern, Otis, Wise): kognitív-szociális tanuláselmélet és behaviorizmus; a család is szerepet játszik (stresszértékelés, coping elsajátítása); a hatástalan családi válasz fokozza a fenyegetettséget. <b>Félelem-elkerülés modell</b> (Vlaeyen és Linton): kétféle út – adaptív viselkedés vagy <b>katasztrofizáció</b> → aktivitás elkerülése, fokozott érzékenység; az elkerülést megerősíti, hogy nincs fájdalom."],["Befolyásoló tényezők","<b>Életkor</b>: idősek kevésbé számolnak be a fájdalomról (az érzet a korral nem változik); gyerekeknél reaktív, pszichoszociális dominanciájú. <b>Család</b>: a házastárs pozitív figyelme magasabb fájdalmat, gyakoribb fájdalomviselkedést és több alkalmatlanságot jelez. <b>Kultúra</b>: hiedelmek, beavatások, segítségkérés mértéke. Értékelést befolyásol: gyakoriság, mások súlyosságtól való megítélése, elvárások."]],"qs":[{"t":"match","q":"Párosítsd az elméletet a szerzőkkel!","pairs":[["Kapukontroll","Melzack és Wall"],["Félelem-elkerülés","Vlaeyen és Linton"],["Kognitív viselkedéses tranzakciós","Kern, Otis, Wise"]],"e":"Három fájdalommodell."},{"t":"mc","q":"Mit állít a kapukontroll elmélet?","o":["Az agy aktívan szűri és modulálja a fájdalomingereket","A fájdalom csak a sérülés mértékétől függ","A fájdalom kizárólag pszichés","A fájdalom nem tanulható"],"a":0,"e":"Központi idegrendszeri folyamatokat feltételez."},{"t":"tf","q":"A félelem-elkerülés modellben a katasztrofizáció az aktivitás elkerüléséhez vezet.","a":true,"e":"Az elkerülést megerősíti, hogy nincs fájdalom."},{"t":"mc","q":"Mit mutat, ha a házastárs pozitív figyelmet ad a fájdalomra?","o":["Magasabb fájdalom, gyakoribb fájdalomviselkedés","Alacsonyabb fájdalom","Nincs hatás","Csak a gyógyszerszedés nő"],"a":0,"e":"Családi megerősítés fokozza a fájdalomviselkedést."},{"t":"tf","q":"Az idősek kevésbé számolnak be a fájdalomról, mert a fájdalomérzet csökken.","a":false,"e":"A fájdalomérzet a korral nem változik; csak kevésbé számolnak be róla."},{"t":"fill","q":"A Vlaeyen és Linton-féle modell neve: ___-elkerülés modell.","a":["félelem","felelem"],"e":"Adaptív viselkedés vagy katasztrofizáció."},{"t":"mc","q":"Melyik tényező befolyásolja a tünetek értékelését?","o":["Mások súlyosságtól való megítélése és az elvárások","Kizárólag a szövetkárosodás","A testmagasság","A napszak"],"a":0,"e":"Gyakoriság, mások megítélése, elvárások."}]},{"id":"u05l4","title":"Diabétesz","theory":[["A betegség lényege","Az <b>1-es típus</b>: abszolút inzulinhiány (hasnyálmirigy béta-sejtjei pusztulnak, autoimmun, öröklött), sovány, fogyás; elsősorban gyerekek, fiatal felnőttek. Tünetek: szomjúság, fáradtság, súlyvesztés, ketoacidotikus kóma. A <b>2-es típus</b>: <b>inzulinrezisztencia</b>, elhízottak, felnőtt és idős kor; rizikó: családi halmozódás, dohányzás, elhízás, mozgásszegény életmód. Tünetek: szomjúság, fáradtság, hányinger, verejtékezés, idegesség, gyengeség. <b>Gesztációs diabétesz</b>: a terhesség 3. trimeszterében, a szüléssel megszűnik."],["Következmények","Cukor a vizeletben; hosszú távon vakság, lábamputáció, érelmeszesedés, infarktus, impotencia."],["Pszichológiai vonatkozások","Súlyos <b>stressz</b> kapcsolatban áll; diabéteszes serdülőknél gyakoribb volt a szülő elvesztése. Jellegzetes személyiségjegyeket <b>nem sikerült bizonyítani</b>; gyakori a depresszió. <b>Megküzdés</b>: az elkerülő nem jó, az aktív közeledés jobb életminőséget ad; a társas támogatás fontos. <b>Kezelés</b>: vércukorcsökkentés, inzulinhatást növelő gyógyszerek, életmódváltás; család, megküzdés, depresszió, szorongás, stressz csökkentése, csoportterápia, énhatékonyság, CBT, tervek kidolgozása."]],"qs":[{"t":"match","q":"Párosítsd a típust a jellemzővel!","pairs":[["1-es típus","Abszolút inzulinhiány"],["2-es típus","Inzulinrezisztencia"],["Gesztációs","Terhesség 3. trimeszter"]],"e":"A diabétesz típusai."},{"t":"tf","q":"Az 1-es típusú diabétesz autoimmun, a béta-sejtek pusztulnak.","a":true,"e":"Elsősorban gyerekeknél és fiatal felnőtteknél."},{"t":"mc","q":"Melyik a 2-es típusú diabétesz rizikófaktora?","o":["Elhízás","Alacsony testsúly","Erős fizikai aktivitás","Kamaszkor"],"a":0,"e":"Valamint családi halmozódás, dohányzás, mozgásszegény életmód."},{"t":"fill","q":"A 2-es típusú diabéteszben a sejtek ___ rezisztensek.","a":["inzulin","inzulinra"],"e":"Egyre több inzulin kell, mégsem jut be a cukor."},{"t":"mc","q":"Melyik a megküzdési stílus előnyösebb diabéteszben?","o":["Aktív közeledés","Elkerülés","Tagadás","Passzív várakozás"],"a":0,"e":"Az elkerülő megküzdés nem jó."},{"t":"tf","q":"Bizonyított, hogy a diabéteszeseknek jellegzetes személyiségjegyeik vannak.","a":false,"e":"Az alapkonfliktus felderítésére tett kísérletek ellenére nem sikerült bizonyítani."},{"t":"mc","q":"Melyik NEM a diabétesz hosszú távú következménye?","o":["A cukor eltűnése a vérből","Vakság","Lábamputáció","Érelmeszesedés"],"a":0,"e":"A hosszú távú szövődmények: vakság, lábamputáció, érelmeszesedés, infarktus, impotencia."}]},{"id":"u05l5","title":"Placebo","theory":[["Fogalmak","<b>Placebo</b>: minden olyan anyag vagy eljárás, amely az érintett tudomása szerint változtatni képes tüneteket vagy testi észleleteket, de valójában nem rendelkezik a szükséges <b>specifikus hatással</b>. <b>Placebo válasz</b>: a kezelés hatására tapasztalt változások. Hatásterületek: kognitív teljesítmény, szorongás, depresszió, dohányzás, inszomnia, asztma, allergia, fájdalom. Szubjektív és objektív, neurokémiailag mérhető hatás."],["Elméletek","(a) <b>Kísérletvezetői elfogultság</b>, (b) <b>páciens elvárásai</b>, (c) hibavisszajelzési hajlandóság (a változást a placebónak tulajdonítják), (d) <b>kondicionálási hatás</b> (kórházi környezet), (e) szorongáscsökkentés (megváltozik a tünetészlelés), (f) <b>kognitív disszonancia</b> (a befektetés indokolása, racionális énkép)."],["Tág és szűk értelem","<b>Tág értelemben</b> (nem specifikus hatótényezők): orvos, beteg, kezelés tulajdonságai, makro- és mikrokontextus. Ha hozzáadjuk a hatóanyag farmakológiai hatását: <b>teljes gyógyszerhatás elve</b>. <b>Szűk értelemben</b>: a gyógyszer (kezelés) tulajdonságai. Erősebben hat: társas konformitás, <b>diszpozícionális optimizmus</b>, szuggesztibilitás, abszorpció."]],"qs":[{"t":"mc","q":"Mi a placebo?","o":["Olyan anyag/eljárás, amely a tudomás szerint hat, de nincs specifikus hatása","Hatóanyaggal bíró gyógyszer","Káros mellékhatás","A kezelés elutasítása"],"a":0,"e":"Placebo válasz: a változások a kezelés hatására."},{"t":"match","q":"Párosítsd az elméletet a lényegével!","pairs":[["Kondicionálás","Kórházi környezet okozta javulás"],["Kognitív disszonancia","Befektetés indokolása"],["Szorongáscsökkentés","Megváltozó tünetészlelés"]],"e":"A placebohatás magyarázatai."},{"t":"tf","q":"A placebonak csak szubjektív hatása van.","a":false,"e":"Objektív, neurokémiailag mérhető hatása is van."},{"t":"fill","q":"A tág értelemben vett placebohatás a ___ hatótényezők összessége.","a":["nem specifikus","nemspecifikus"],"e":"Orvos, beteg, kezelés tulajdonságai és a kontextus."},{"t":"mc","q":"Melyik tényező fokozza a placebohatást?","o":["Szuggesztibilitás","Szkepticizmus","Magas IQ","Alacsony optimizmus"],"a":0,"e":"Továbbá társas konformitás, diszpozícionális optimizmus, abszorpció."},{"t":"mc","q":"Mit jelent a teljes gyógyszerhatás elve?","o":["Nem specifikus tényezők + a hatóanyag farmakológiai hatása","Csak a hatóanyag hatása","Csak a placebo","A mellékhatások összege"],"a":0,"e":"A tág értelemben vett placebóhoz hozzáadjuk a farmakológiai hatást."},{"t":"tf","q":"A páciens elvárásai szerepet játszanak a placebohatásban.","a":true,"e":"Az egyik magyarázó elmélet."}]},{"id":"u05l6","title":"Placebo etikája és nocebo","theory":[["Etikai álláspontok","<b>Deontológiai</b>: bármilyen megtévesztés erkölcsileg elfogadhatatlan. <b>Utilitárius</b>: a következmény alapján ítélendő meg. <b>Paternalista</b>: nem a megtévesztés miatt elfogadhatatlan, hanem mert gyerekként kezeli a beteget. Konklúzió: nem feltétlenül kell hatóanyag nélküli szert adni a placebohatás kiváltásához; a cél a placebohatás."],["Nocebo","<b>Nil nocere</b> – ne árts. A nocebo a kezelés nem specifikus hatótényezőinek <b>negatív hatása</b>. Kialakítják: társas tanulás (panaszkodás), stressz-szorongás okozta negatív észlelés, katasztrofizáció, szembenállás az orvossal, másodlagos betegségelőnyök."],["Kiknél gyakori a nocebo","Nőknél; negatív affektivitás; fokozott figyelem a testi folyamatokra; pesszimizmus; szomatizáció; abszorpció."]],"qs":[{"t":"match","q":"Párosítsd az etikai álláspontot a lényegével!","pairs":[["Deontológiai","Megtévesztés erkölcsileg elfogadhatatlan"],["Utilitárius","A következmény számít"],["Paternalista","A beteget gyerekként kezeli"]],"e":"Placebóhasználat etikai megítélése."},{"t":"mc","q":"Mit jelent a nocebo?","o":["A kezelés nem specifikus tényezőinek negatív hatása","Hatásos gyógyszer","Placebo kontrollcsoport","Pozitív várakozás"],"a":0,"e":"Nil nocere – ne árts."},{"t":"tf","q":"A placebohatás kiváltásához feltétlenül hatóanyag nélküli szert kell adni.","a":false,"e":"A konklúzió: nem feltétlenül; a cél a placebohatás."},{"t":"fill","q":"A nocebo kapcsán a ___ nocere elv: ne árts.","a":["nil","Nil"],"e":"Nil nocere."},{"t":"mc","q":"Melyik tényező növeli a nocebo valószínűségét?","o":["Katasztrofizáció","Optimizmus","Az orvossal való jó kapcsolat","Alacsony szorongás"],"a":0,"e":"Továbbá a panaszkodás társas tanulása és a másodlagos betegségelőnyök."},{"t":"mc","q":"Kiknél gyakoribb a nocebo?","o":["Nőknél, negatív affektivitásnál, pesszimistáknál","Optimistáknál","Férfiaknál","Gyerekeknél"],"a":0,"e":"Szomatizáló, testi folyamatokra fokozottan figyelő személyeknél."},{"t":"tf","q":"Az utilitárius álláspont a következmények alapján ítéli meg a placebót.","a":true,"e":"A deontológiai a megtévesztést eleve elveti."}]}],"color":"#ff4b4b"},{"id":"u06","title":"Krónikus betegség","desc":"Alkalmazkodás, kontroll, család","lessons":[{"id":"u06l1","title":"A krónikus betegség jellemzői","theory":[["Definíció és epidemiológia","Krónikus betegség: <b>hosszú lefolyású és gyógyíthatatlan</b>. Egy része megfelelő kezeléssel jól szinten tartható, más része folyamatosan vagy fluktuálóan <b>progrediál</b>. Tipikus: szívbetegségek, cukorbetegség, asthma bronchiale, rák; enyhébb halláskárosodás, mozgásszervi betegségek."],["Gyakoriság","A fejlett országok lakosságának kb. <b>50%-a</b> küzd krónikus betegséggel. Leginkább a <b>60 évnél idősebbeket</b> érinti; a gyermekek kb. 10%-a érintett."],["Változások a betegségben","<b>Testi:</b> funkciók, testi integritás fenyegetése (tünetek, vizsgálatok, kezelés mellékhatásai). <b>Élethelyzeti:</b> új helyzet (kórház), külső megjelenés/testkép romlása, szociális szerepek, munkaképesség veszélyeztetése.<br><b>Pszichés:</b> emocionális egyensúly elvesztése (halálfélelem, düh, bűntudat), tehetetlenség, autonómia- és kontrollvesztés, bizonytalanság, önértékelés változása."],["Osztályozás","Szempontok: kiszámíthatóság, fertőzőképesség, életveszélyes jelleg, szembeötlő tünetek, <b>befolyásolhatóság</b>, pszichológiai/viselkedéses zavarok, alkalmazkodási feladatok. A befolyásolhatatlan betegség (pl. neurológiai) kontrollérzést nem ad, tehetetlenséggel jár."]],"qs":[{"t":"mc","q":"Melyik jellemzi a krónikus betegséget a forrás szerint?","o":["Hosszú lefolyású és gyógyíthatatlan","Rövid, akut lefolyású","Mindig fertőző","Mindig jól gyógyítható"],"a":0,"e":"A krónikus betegségek hosszú lefolyásúak és gyógyíthatatlanok."},{"t":"tf","q":"A krónikus betegségek mindegyike szinten tartható megfelelő kezeléssel.","a":false,"e":"Egy részük szinten tartható, más részük folyamatosan vagy fluktuálóan progrediál."},{"t":"fill","q":"A fejlett országok lakosságának kb. ___ százaléka krónikus beteg.","a":["50","ötven"],"e":"Mintegy 50%."},{"t":"mc","q":"Melyik korcsoportot érinti leginkább a krónikus betegség?","o":["60 évnél idősebbeket","Serdülőket","Fiatal felnőtteket","Csecsemőket"],"a":0,"e":"Leginkább a 60 év felettieket; a gyermekek kb. 10%-a érintett."},{"t":"match","q":"Párosítsd a változás típusát a példával!","pairs":[["Testi","fájdalom, gyengeség, kezelés mellékhatása"],["Élethelyzeti","munkaképesség csökkenése"],["Pszichés","autonómia- és kontrollvesztés"]],"e":"A betegség testi, élethelyzeti és pszichés változásokat hoz."},{"t":"mc","q":"Melyik NEM tartozik a betegség pszichés következményei közé?","o":["Fokozott kontrollérzés","Halálfélelem, düh, bűntudat","Bizonytalanság","Az önértékelés változása"],"a":0,"e":"Kontrollvesztés jellemző, nem fokozott kontrollérzés."},{"t":"tf","q":"A befolyásolhatatlan krónikus betegség (pl. neurológiai) tehetetlenség-érzéssel jár.","a":true,"e":"Objektív kontrollérzést nem ad a betegnek."},{"t":"mc","q":"Melyik a krónikus betegségek egyik osztályozási szempontja?","o":["Életveszélyes jellege","A beteg neme","A kórház mérete","A gyógyszer ára"],"a":0,"e":"Szempont még: kiszámíthatóság, fertőzőképesség, szembeötlő tünetek, befolyásolhatóság."}]},{"id":"u06l2","title":"Szakaszok és alkalmazkodás","theory":[["A betegség négy szakasza","1. Tünetektől a diagnózisig (kiemelten stresszes). 2. Kezelés kezdete, <b>„terápiás mézeshetek”</b> (sok támogatás, pozitív élmény). 3. Tartós egyensúly, relapszusokkal tarkítva. 4. <b>Terminális szakasz</b>: kimerülő megküzdési potenciál, gyengülő orvos-beteg kapcsolat, negatív indulat- és viszontindulatáttétel."],["Feladatok az akut szakaszban","Meg kell küzdeni a fájdalommal és korlátozottsággal; alkalmazkodni a kórházhoz/vizsgálatokhoz; jó kapcsolat a személyzettel; érzelmi egyensúly; az énkép túlzott romlásának elkerülése; kapcsolat család és barátok felé; felkészülés a bizonytalan jövőre."],["Alkalmazkodás négy szintje","Az első krízis után: <b>fizikai</b> akadályok (viszony a testhez), <b>szociális</b> nehézségek, <b>családi-társas</b> szerepviszonyok és kommunikáció, valamint a <b>pszichés reakciók</b> – ez a legnagyobb összetevő."],["Pszichés válaszok","<b>1. Érzelmi válaszok:</b> eleinte dezorientáltság, tagadás, szorongás; később düh és depresszió (hasonló a Kübler-Ross-féle gyászszakaszokhoz, mert veszteség).<br><b>2. Reprezentációk:</b> negatív jellemző, de a pozitív jelentés keresése is.<br><b>3. Énkép:</b> testkép, teljesítmény/szociális készségek, identitás."]],"qs":[{"t":"mc","q":"Mi a „terápiás mézeshetek” időszaka?","o":["A kezelés kezdete a diagnózis után, sok támogatással","A terminális szakasz","A tünetek megjelenése","A relapszusok időszaka"],"a":0,"e":"A 2. szakasz: a beteg sok támogatást és pozitív élményt kap."},{"t":"match","q":"Párosítsd a szakaszt a jellemzővel!","pairs":[["1. szakasz","tünetektől a diagnózisig, stresszes"],["2. szakasz","terápiás mézeshetek"],["3. szakasz","tartós egyensúly, relapszusok"],["4. szakasz","terminális, kimerülő megküzdés"]],"e":"A krónikus betegség négy szakasza."},{"t":"fill","q":"A krónikus betegség utolsó szakasza a ___ szakasz.","a":["terminális"],"e":"Itt a megküzdési potenciál kimerülőben van."},{"t":"tf","q":"A betegség kezdetén a düh és a depresszió az uralkodó érzelem.","a":false,"e":"Kezdetben dezorientáltság, tagadás, szorongás; később düh és depresszió."},{"t":"mc","q":"Melyik az alkalmazkodás legnagyobb összetevője?","o":["Pszichés reakciók","Fizikai akadályok","Anyagi helyzet","Munkahelyi kapcsolatok"],"a":0,"e":"A pszichés reakciók alkotják a negyedik, legnagyobb összetevőt."},{"t":"mc","q":"Melyik gyászelmélethez hasonlítanak a betegség érzelmi szakaszai?","o":["Kübler-Ross","Erikson","Kobasa","Caplan"],"a":0,"e":"A krónikus betegség veszteséget hoz, ezért hasonló a Kübler-Ross-féle szakaszokhoz."},{"t":"mc","q":"Az énkép összetevője a forrás szerint:","o":["Testkép, teljesítmény és szociális készségek, identitás","Csak a testkép","Csak az önértékelés","Intelligencia, memória, figyelem"],"a":0,"e":"Három összetevő: testkép, teljesítmény/szociális készségek, azonosságtudat."},{"t":"tf","q":"A terminális szakaszban az orvos-beteg kapcsolat gyengül.","a":true,"e":"Megjelenik a negatív indulat- és viszontindulatáttétel."}]},{"id":"u06l3","title":"Kontroll, szívósság, kezelés","theory":[["Kontroll a betegségben","<b>Belső kontrollosok</b> több egészségvédő viselkedést mutatnak, sikeresebben küzdenek. <b>Oki (primer) kontroll</b>: problémafókuszú, a kiváltó tényezőre irányul – betegségnél nem alkalmazható. <b>Az ok következményei feletti (áttolt) kontroll</b>: az élet nem érintett területein marad belső kontrollos – betegségnél alkalmazható."],["Rothbaum és Thompson","<b>Rothbaum (1982):</b> elsődleges kontroll = a helyzet megváltoztatása (problémafókusz); másodlagos kontroll = az „én” megváltoztatása (emóciófókusz).<br><b>Thompson (1993):</b> a következmények feletti kontroll javítja az életminőséget. Formái: érzelmi reakciók, kapcsolatok, fizikai tünetek, orvosi kezelés és információk kontrollja."],["Szívósság (Kobasa)","A szívós személy kíváncsi, jelentést keres, a stresszt kihívásnak éli meg. 3 dimenzió: <b>elkötelezettség</b>, <b>kontroll</b>, <b>kihívás</b>. Hiánya: unalmasnak és terhesnek látja a világot, passzív, pesszimista. A premorbid szívósság megkönnyíti a megküzdést."],["Kezelés és megküzdés","<b>Von Korff:</b> lépcsőzetes, egyénre szabott modell; elemei: kezelési terv, betegoktatás, állapotkövetés, együttműködés követése; elkerüli a magárahagyatottságot.<br>Megküzdés: tagadás/minimalizálás, információszerzés, érzelmi támasz, problémaorientáció, rövid távú célok, távoli célok feltérképezése, pozitív jelentés keresése."]],"qs":[{"t":"mc","q":"Melyik kontrollforma NEM alkalmazható krónikus betegségben?","o":["Oki (primer) kontroll","Áttolt kontroll","Másodlagos kontroll","Érzelmi reakciók kontrollja"],"a":0,"e":"A kiváltó okra irányuló kontroll betegségnél nem alkalmazható."},{"t":"match","q":"Párosítsd Rothbaum szerint!","pairs":[["Elsődleges kontroll","a helyzet megváltoztatása"],["Másodlagos kontroll","az „én” megváltoztatása (emóciófókusz)"],["Oki kontroll","= problémafókuszú megküzdés"]],"e":"Rothbaum és mtsai (1982)."},{"t":"mc","q":"Ki dolgozta ki a szívósság (hardiness) modelljét?","o":["Kobasa","Thompson","Von Korff","Mechanic"],"a":0,"e":"Kobasa modellje."},{"t":"mc","q":"Melyik NEM a szívósság dimenziója?","o":["Autonómia","Elkötelezettség","Kontroll","Kihívás"],"a":0,"e":"A három dimenzió: elkötelezettség, kontroll, kihívás."},{"t":"fill","q":"Von Korff modellje ___ és egyénre szabott.","a":["lépcsőzetes","lépcsőzetes modell"],"e":"A lépcsőzetes modell segít elkerülni a magárahagyatottság érzését."},{"t":"tf","q":"A belső kontrollosok sikeresebben küzdenek meg egészségügyi problémáikkal, mint a külső kontrollosok.","a":true,"e":"Több egészségvédő viselkedést is mutatnak."},{"t":"mc","q":"Thompson (1993) szerint mi javítja jelentősen az életminőséget?","o":["A betegség következményei feletti kontroll","A betegség okának kiiktatása","A diagnózis elhallgatása","A tünetek tagadása"],"a":0,"e":"A következmények feletti kontroll javítja az életminőséget és a szubjektív állapotot."},{"t":"mc","q":"Melyik a problémaorientált megküzdés példája?","o":["Eljárások, technikák elsajátítása az állapot javítására","Az érzelmi támasz keresése","A súlyosság tagadása","Az értékek átrendezése"],"a":0,"e":"A páciens az állapota javításához szükséges eljárásokat sajátít el."}]},{"id":"u06l4","title":"Család és társas támogatás","theory":[["A család alkalmazkodása","A beteg és a család kölcsönösen hat egymásra. A családtagok a beteghez hasonló fázisokon mennek át: <b>hitetlenkedés, tagadás</b>, orvoskeresés, szakvélemények gyűjtése, majd <b>düh és bűntudat</b>. Veszély: megrekedés egy fázisban, dühkitörések, a folyamatos gondozás miatti <b>kiégés</b>."],["A család krízise","Változások: anyagi nehézségek, családi szerepek és feladatok megváltozása, a családon kívüli kapcsolatok változása, a tagok eltérő pszichés reakciói. <b>Objektív teher</b>: a betegségből adódó feladatok. <b>Szubjektív teher</b>: az ehhez társuló pszichés reakciók, főként stressz."],["Beteg gyermek a családban","A családi támogatás fontosabb a megküzdésben, mint a gyermek kognitív fejlettsége. Leginkább az <b>anyák</b> stressze nő. Lányoknál a vonzó külső elvesztése, fiúknál a gyengeség a nehezebb félelem. Veszély: az egészséges testvér elhanyagolása, testvérféltékenység; az anya kizárhatja a családot."],["Társas támogatás","Kaplan: a jelentős mások által nyújtott pszichoszociális erőforrások. Összetevői: pozitív érzelmek kifejezése, egyetértés/elfogadás, biztatás a kifejezésre, anyagi segítség, megerősítés a kölcsönös támogató rendszerhez tartozásról. <b>Mechanic:</b> még a támogató család is lehet stresszforrás (pl. kudarc nem tolerálása). Magány, izoláció esetén gyakoribbak a betegségek."]],"qs":[{"t":"mc","q":"Mi a családtagok tipikus első reakciója a betegség hírére?","o":["Hitetlenkedés, majd tagadás","Düh","Elfogadás","Bűntudat"],"a":0,"e":"Először hitetlenkedés és tagadás, utána következik a düh és a bűntudat."},{"t":"match","q":"Párosítsd a terhek típusát!","pairs":[["Objektív teher","a betegségből adódó feladatok"],["Szubjektív teher","pszichés reakciók, stressz"]],"e":"A család terhei lehetnek objektívek és szubjektívek."},{"t":"tf","q":"Beteg gyermek esetén a gyermek kognitív fejlettsége fontosabb a megküzdésben, mint a családi támogatás.","a":false,"e":"A családi támogatásnak jóval meghatározóbb szerepe van."},{"t":"mc","q":"Kinek a stressz-szintje emelkedik leginkább beteg gyermek esetén?","o":["Az anyáé","Az apáé","A nagyszülőké","Az egészséges testvéré"],"a":0,"e":"Leginkább az anyák stressze nő meg."},{"t":"mc","q":"Mit állított Mechanic a társas támogatásról?","o":["A támogató család is lehet stresszforrás","A család mindig védőfaktor","A támogatás mindig anyagi","A támogatás egydimenziós"],"a":0,"e":"Pl. ha a család a kudarcot éppúgy nem tudja tolerálni, mint a beteg."},{"t":"fill","q":"A társas támogatás fogalmát Kaplan a jelentős mások által biztosított ___ erőforrásokkal írta le.","a":["pszichoszociális","pszichoszociális erőforrás"],"e":"A pszichoszociális erőforrások meglétét vagy hiányát jelzi."},{"t":"mc","q":"Melyik veszély jellemző beteg gyermekes családban?","o":["Az egészséges testvér elhanyagolása","A szülők közötti teljes egyetértés","A gyermek túlzott önállósága","A család társas kapcsolatainak bővülése"],"a":0,"e":"Testvérféltékenység is kialakulhat."},{"t":"tf","q":"A magányosan, izoláltan élőknél a különböző betegségek előfordulása gyakoribb.","a":true,"e":"A társas támogatás pozitív hatása."}]}],"color":"#2b70c9"},{"id":"u07","title":"Egészségfejlesztés","desc":"Ottawai Karta, színterek, tervezés","lessons":[{"id":"u07l1","title":"Fogalom és történeti háttér","theory":[["Történet","<b>1974 – Lalonde-riport:</b> az egészséget a környezet, életmód és biológiai adottság is meghatározza, mégis az egészségpolitika csak az ellátásra figyel.<br><b>1978 – WHO, Alma-Ata:</b> „Egészséget mindenkinek 2000-re”; multiszektoriális megközelítés, közösségi tervezés.<br><b>1986 – Ottawa:</b> első nemzetközi konferencia, <b>Ottawai Karta</b> – az egészségfejlesztés alapdokumentuma."],["Az Ottawai Karta definíciója","<i>Az egészségfejlesztés az a folyamat, amely képessé teszi az embereket az egészséget meghatározó tényezők felügyeletére, és ezáltal egészségük javítására.</i> A hangsúly a betegségkezelésről az egészség „előállítására” tolódott."],["Öt tevékenységi terület","a) <b>egyéni készségek fejlesztése</b> (egészségnevelés) – ez az alap<br>b) közösségi cselekvések erősítése<br>c) egészséget támogató környezet<br>d) egészségügyi ellátás áthangolása<br>e) egészséget támogató politikai irányelvek"],["Stratégiák, megkülönböztetés","Három fő stratégia: <b>képessé tevés, közbenjárás, pártolás</b>. Az <b>egészségmegőrzés</b> nem szinonim az egészségfejlesztéssel: biomedikális, betegség-oldali megközelítés. Az egyénre és információátadásra építő megközelítések önmagukban nem tartósan hatékonyak."]],"qs":[{"t":"mc","q":"Melyik dokumentum az egészségfejlesztés alapdokumentuma?","o":["Ottawai Karta","Lalonde-riport","Alma-atai nyilatkozat","Maslach-kérdőív"],"a":0,"e":"1986, Ottawa."},{"t":"match","q":"Párosítsd az évet az eseménnyel!","pairs":[["1974","Lalonde-riport"],["1978","Alma-ata, Egészséget mindenkinek 2000-re"],["1986","Ottawai Karta"]],"e":"Az egészségfejlesztés fontos történeti mérföldkövei."},{"t":"fill","q":"Az 1974-es ___-riport hívta fel a figyelmet az egészségügyi paradoxonra.","a":["Lalonde","lalonde"],"e":"Az egészséget környezet, életmód, biológia is meghatározza, mégis az ellátás kapja a figyelmet."},{"t":"mc","q":"Az Ottawai Karta szerint az egészségfejlesztés:","o":["Folyamat, amely képessé teszi az embereket az egészséget meghatározó tényezők felügyeletére","Betegségek kezelése","Csak információátadás","Az orvosok feladata"],"a":0,"e":"Az Ottawai Karta definíciója."},{"t":"mc","q":"Melyik az öt tevékenységi terület alapja?","o":["Egyéni készségek fejlesztése","Politikai irányelvek","Ellátás áthangolása","Támogató környezet"],"a":0,"e":"Az egyéni készségek fejlesztése (egészségnevelés) képezi az alapot."},{"t":"mc","q":"Melyik NEM az egészségfejlesztés három fő stratégiája?","o":["Szűrés","Képessé tevés","Közbenjárás","Pártolás"],"a":0,"e":"Képessé tevés, közbenjárás, pártolás."},{"t":"tf","q":"Az egészségmegőrzés az egészségfejlesztés szinonimája.","a":false,"e":"Az egészségmegőrzés a biomedikális, betegség-oldali megközelítést tükrözi."},{"t":"tf","q":"Az 1980-as évek szemléletváltása szerint csak az egyén információátadáson alapuló befolyásolása tartósan hatékony.","a":false,"e":"A tágabb környezeti körülményeket is meg kell változtatni."}]},{"id":"u07l2","title":"Célcsoportok, színterek, jellemzők","theory":[["Kikre irányul?","<b>Univerzális</b> megelőzés: a teljes népesség, szélesebb csoportok. <b>Szelektív</b>: magasabb kockázatú csoportok (biológiai, pszichológiai, társadalmi tényezők miatt). <b>Indikált</b>: azok, akiknél diagnózis még nem állítható fel, de szubklinikus jelek vannak; speciális programok."],["Színterek és témák","Színtér = fizikai helyszín + társas folyamatok + szabályok. Színterek: <b>család, iskola, munkahely, egészségügy, közösségek</b>. Témák pl. mentális egészség fejlesztése, alkohol-, drogprevenció, depresszió és szorongás prevenciója. Osztályozás: primer, szekunder, tercier prevenció szerint."],["Jellemzők","<b>Interszektorialitás</b>: több ágazat (egészségügy, oktatás, önkormányzat, média, civil, egyház) közös nyelven. <b>Multidiszciplinaritás</b>: több tudományág. <b>Multiplikátor</b> = egészségfejlesztő szakember, aki „közös nyelvet” teremt.<br>Nem csak információ, hanem tudásátadás; nem csak az egészségügy feladata; nem csak az egyéni életmódra fókuszál."]],"qs":[{"t":"match","q":"Párosítsd a megelőzés típusát a célcsoporttal!","pairs":[["Univerzális","a teljes népesség"],["Szelektív","magasabb kockázatú csoportok"],["Indikált","szubklinikus jeleket mutatók"]],"e":"A három célzási szint."},{"t":"mc","q":"Melyik NEM egészségfejlesztési színtér?","o":["Bíróság","Család","Iskola","Munkahely"],"a":0,"e":"Színterek: család, iskola, munkahely, egészségügy, közösségek."},{"t":"mc","q":"Ki a multiplikátor az egészségfejlesztésben?","o":["Az egészségfejlesztő szakember","A háziorvos","A beteg","A politikus"],"a":0,"e":"Különböző szakmák között közös nyelvet teremt, együttműködést hoz létre."},{"t":"fill","q":"Az egészségfejlesztés több ágazat együttműködése, ezért ___ jellegű.","a":["interszektoriális","interszekcionális","interszektorális"],"e":"A forrás „interszekcionalitás”-nak nevezi."},{"t":"tf","q":"Az indikált megelőzés olyanokat céloz, akiknél a diagnózis már felállítható.","a":false,"e":"A diagnózis még nem állítható fel, de szubklinikus jelek vannak."},{"t":"mc","q":"A multidiszciplinaritás jelentése:","o":["Több tudományág ismereteinek ötvözése","Több ágazat együttműködése","Több színtér használata","Több célcsoport"],"a":0,"e":"Pl. egészségfejlesztés, mentálhigiéné, pszichológia, ökológia."},{"t":"tf","q":"Az egészségfejlesztés csak az egészségügyi szektor feladata.","a":false,"e":"Több ágazatot érint."},{"t":"mc","q":"Melyik a szelektív megelőzés példája?","o":["Programok magasabb kockázatú csoportoknak","Programok az egész lakosságnak","Szubklinikus tünetek kezelése","Rehabilitáció"],"a":0,"e":"Olyan csoportok, ahol az adott jelenség gyakoribb."}]},{"id":"u07l3","title":"Kommunikáció és magatartásváltoztatás","theory":[["Kommunikáció laikusokkal","Kérdések: mit mondjunk, kiknek, mennyi idő van, milyenek a körülmények, milyen formában, miért higgyenek nekünk. Tanácsok: <b>egyszerű fogalmazás, ábrák, konkrét tanácsok, a változás előnyei, történetek, visszajelzések figyelése, hitelesség</b>."],["Nyolc feltétel (1)","A magatartásváltoztatáshoz több feltételnek kell fennállnia. Az <b>első három szükséges és elegendő</b>:<br>A. szilárd elhatározás<br>B. nincs akadály a környezetben<br>C. készségek a viselkedés végrehajtására"],["Nyolc feltétel (2)","A többi öt <b>erősíti</b> a szándékot:<br>D. az előnyök meghaladják a hátrányokat<br>E. társas nyomás<br>F. a viselkedés egybevág az önképpel<br>G. inkább pozitív, mint negatív érzelmi reakció<br>H. észlelt önhatékonyság"]],"qs":[{"t":"mc","q":"Melyik NEM tartozik a három szükséges és elegendő feltétel közé?","o":["Társas nyomás","Szilárd elhatározás","Készségek a végrehajtásra","Nincs környezeti akadály"],"a":0,"e":"A társas nyomás az erősítő feltételek közé tartozik."},{"t":"fill","q":"A nyolc feltétel közül az első ___ szükséges és elegendő az új magatartáshoz.","a":["három","3"],"e":"A többi öt erősíti a szándékot."},{"t":"match","q":"Párosítsd a feltételt a betűjellel!","pairs":[["A","szilárd elhatározás"],["C","készségek"],["H","észlelt önhatékonyság"],["E","társas nyomás"]],"e":"A–H feltételek."},{"t":"mc","q":"Melyik praktikus tanács laikus célközönséghez?","o":["Meséljünk történeteket","Használjunk szakkifejezéseket","Kerüljük az ábrákat","Általános tanácsokat adjunk"],"a":0,"e":"Egyszerű fogalmazás, ábrák, konkrét tanácsok, történetek."},{"t":"tf","q":"Az észlelt önhatékonyság az erősítő feltételek egyike.","a":true,"e":"A H feltétel."},{"t":"mc","q":"A „tervezett viselkedés egybevág az önképpel” melyik típusú feltétel?","o":["Erősítő","Szükséges és elegendő","Akadály","Kommunikációs"],"a":0,"e":"Az F feltétel, erősítő."},{"t":"tf","q":"A laikusokkal való kommunikációban konkrét tanácsokat érdemes adni.","a":true,"e":"Ez a praktikus tanácsok egyike."}]},{"id":"u07l4","title":"Tervezés és értékek","theory":[["Stratégia – program – projekt","<b>Stratégia</b>: legnagyobb egység, prioritások, hosszú távú terv, több éves/évtizedes. <b>Program</b>: homogén intervenciók összessége, ütemezés és költségvetés, monitorozó bizottság irányítja. <b>Projekt</b>: tovább nem osztható tevékenységi terv, ütemezéssel, költségvetéssel, rendszerint egy személy irányítja."],["A tervezés lépései","1. <b>Helyzetfelmérés</b>: szükséglet- és erőforrás-elemzés (a célcsoport erőforrásai is!). 2. <b>Célok</b> (aim: hosszú táv; objective: mérhető rövid/közép táv; target). 3. <b>Prioritások</b>. 4. Megvalósítás. 5. <b>Értékelés</b>: folyamat (process) és eredmény (outcome). Cél: a közösség által kinyilvánított szükségletek elsőbbsége."],["Értékek","Az egészségfejlesztés nem értéksemleges. Alapérték az <b>autonómia</b> (önrendelkezés): felhatalmazás (empowerment) és részvétel (participation) útján; alulról építkezik; addig terjed, amíg másokat nem sért. További érték a <b>társadalmi igazságosság</b>: méltányosság (equity), a méltánytalan egyenlőtlenségek csökkentése."]],"qs":[{"t":"mc","q":"Melyik a legnagyobb tervezési egység?","o":["Stratégia","Program","Projekt","Intervenció"],"a":0,"e":"1 stratégia = több program = számos projekt."},{"t":"match","q":"Párosítsd az egységet a jellemzővel!","pairs":[["Stratégia","hosszú távú, prioritásokkal"],["Program","monitorozó bizottság irányítja"],["Projekt","általában egy személy irányítja"]],"e":"Stratégia > program > projekt."},{"t":"mc","q":"Mi a tervezés első lépése?","o":["Helyzetfelmérés (szükséglet- és erőforrás-elemzés)","Megvalósítás","Értékelés","Prioritások felállítása"],"a":0,"e":"Először a probléma és a rendelkezésre álló erőforrások feltérképezése."},{"t":"tf","q":"Az erőforrás-elemzésnél elsősorban a szakemberek saját erőforrásait kell felmérni.","a":false,"e":"Elsősorban a célcsoport erőforrásait."},{"t":"mc","q":"A „célkitűzés” (objective) jellemzője:","o":["Rövid-, középtávú, mérhető","Hosszú távú cél","Csak politikai","Értékelési terv"],"a":0,"e":"A cél (aim/goal) hosszú távú."},{"t":"fill","q":"Az értékelés két fajtája: folyamat és ___ (outcome) értékelés.","a":["eredmény"],"e":"Process és outcome."},{"t":"mc","q":"Melyik az egészségfejlesztés egyik alapértéke?","o":["Autonómia (önrendelkezési jog)","Normatív cél","Szakmai uralom","Információmonopólium"],"a":0,"e":"Empowermenttel és participationnel valósítható meg."},{"t":"tf","q":"A méltányosság (equity) a társadalmi igazságosság érvényesülését szolgálja.","a":true,"e":"A méltánytalan egyenlőtlenségek csökkentése."}]}],"color":"#00cd9c"},{"id":"u08","title":"Prevenció","desc":"Szintek, stratégiák, szűrés","lessons":[{"id":"u08l1","title":"A prevenció szintjei","theory":[["Fogalom","Prevenció: mindazon törekvések, amelyek az <b>egészség fejlesztését, megőrzését</b>, egészségkárosodás esetén az egészség mielőbbi <b>visszaállítását</b> és a károsodás súlyosbodásának kivédését szolgálják."],["Szintek","<b>Primer:</b> a betegség kialakulásának megelőzése, egészségvédelem (pl. védőoltás).<br><b>Szekunder:</b> korai diagnózis, azonnali kezelés (pl. szűrés).<br><b>Tercier:</b> kezelés és rehabilitáció.<br>+ <b>Primordiális:</b> a kockázati tényezők kialakulásának megelőzése; általában össztársadalmi/kormányzati tevékenység."],["Kockázati és oki tényező","Kockázati tényező: bizonyíthatóan társul a megbetegedéssel (nem zavaró hatás vagy torzítás miatt), de önmagában <b>nem jelent oksági összefüggést</b>. <b>Minden oki tényező kockázati tényező, de nem minden kockázati tényező oki tényező.</b>"]],"qs":[{"t":"match","q":"Párosítsd a prevenciós szintet a példával!","pairs":[["Primer","védőoltás"],["Szekunder","szűrővizsgálat"],["Tercier","rehabilitáció"]],"e":"A hagyományos háromszintű felosztás."},{"t":"mc","q":"Mi a primordiális prevenció célja?","o":["A kockázati tényezők kialakulásának megelőzése","Korai diagnózis","Rehabilitáció","Védőoltás"],"a":0,"e":"Általában össztársadalmi/kormányzati tevékenység."},{"t":"tf","q":"Minden kockázati tényező egyben oki tényező is.","a":false,"e":"Minden oki tényező kockázati tényező, de fordítva nem."},{"t":"mc","q":"A szekunder prevenció lényege:","o":["Korai diagnózis, azonnali kezelés","Betegségkialakulás megelőzése","Rehabilitáció","Törvényi szabályozás"],"a":0,"e":"Pl. szűrés."},{"t":"fill","q":"A védőoltás a ___ prevenció példája.","a":["primer","elsődleges"],"e":"A betegség kialakulását akarjuk megelőzni."},{"t":"mc","q":"A kockázati tényező önmagában:","o":["Nem jelent oksági összefüggést","Mindig oki tényező","Mindig véd a betegségtől","Mindig genetikai"],"a":0,"e":"Csak bizonyítottan társul a megbetegedéssel."},{"t":"tf","q":"A tercier prevenció a kezelést és rehabilitációt foglalja magában.","a":true,"e":"Harmadlagos megelőzés."}]},{"id":"u08l2","title":"Primer prevenció stratégiái","theory":[["Cél és stratégiák","Cél: általános egészségvédelem, egészségmegőrzés, betegségmegelőzés, kockázati tényezők kiiktatása és a védekezőképesség kialakítása. Stratégiák: <b>magas kockázatúakat célzó</b>, <b>populációs</b>, <b>középút</b>/kombinált."],["Magas kockázatúak stratégiája","Lényege: magas kockázatú személyek felkutatása és kockázatuk csökkentése. <b>Előny:</b> az alacsony kockázatúaknak nem kell fölös vizsgálat; egyénnek megfelelő; illeszkedik a hagyományos orvosi szemlélethez. <b>Hátrány:</b> túlmedikalizálás, kérdéses költség, a siker tüneti és időleges."],["Populációs stratégia","Lényege: egy vagy több kockázati tényező populációs eloszlását kedvező irányba eltolni. <b>Előny:</b> radikális, hatékony. <b>Hátrány:</b> megvalósíthatóság, költség, eredményesség problémás.<br>Tömeges beavatkozás: szabályozni (dohányzás, alkohol, elhízás, mozgáshiány) vagy bevezetni (vízfluorozás, sójódozás, vitaminok)."]],"qs":[{"t":"mc","q":"Melyik a populációs stratégia lényege?","o":["A kockázati tényező eloszlásának eltolása kedvező irányba","Csak a magas kockázatúak kezelése","Korai felismerés","Rehabilitáció"],"a":0,"e":"Radikális és hatékony, de nehezen megvalósítható."},{"t":"mc","q":"A magas kockázatúakat célzó stratégia egyik előnye:","o":["Az alacsony kockázatúaknak nem kell fölös vizsgálat","Radikálisan hatékony","Olcsó és gyors","Tartós hatású"],"a":0,"e":"Hátránya: túlmedikalizáció, tüneti és időleges siker."},{"t":"match","q":"Párosítsd a stratégiát a hátránnyal!","pairs":[["Magas kockázatúak","túlmedikalizálódik a prevenció"],["Populációs","megvalósíthatóság, költség"]],"e":"Mindkettőnek vannak hátrányai."},{"t":"mc","q":"Melyik példa a „bevezetés” típusú tömeges beavatkozásra?","o":["Víz fluorozása","Dohányzás szabályozása","Alkoholfogyasztás szabályozása","Környezetszennyezés csökkentése"],"a":0,"e":"Bevezetni: fluorozás, sójódozás, vitaminok, gyógyszerek, klórozás."},{"t":"tf","q":"A magas kockázatú stratégia sikere tüneti és időleges lehet.","a":true,"e":"Ez a stratégia egyik hátránya."},{"t":"fill","q":"Az egy vagy több kockázati tényező eloszlását eltoló stratégia neve ___ stratégia.","a":["populációs"],"e":"Populációs stratégia."},{"t":"mc","q":"Melyik NEM a primer prevenció célja?","o":["A prognózis javítása rehabilitációval","Egészségmegőrzés","Betegségmegelőzés","Kockázati tényezők kiiktatása"],"a":0,"e":"Ez a tercier prevenció célja."}]},{"id":"u08l3","title":"Másodlagos megelőzés és szűrés","theory":[["Cél és eszköz","Szekunder prevenció: korai (preklinikai) felismerés és korai intervenció a prognózis javítására. Legjellemzőbb eszköze a <b>szűrővizsgálat</b>. Típusai: tömeges, előírt, célzott. <b>Hatékonyság</b>: erőforrások és eredmény viszonya; <b>hatásosság</b>: csökkenti a morbiditást, mortalitást."],["Szervezett rákszűrés","Szervezett országos lakossági rákszűrések: <b>25–65 éves nők</b> méhnyakrák-szűrése (3 évente citológia); <b>45–65 éves nők</b> emlőrák-szűrése (2 évente mammográfia). Szűrés fajtái: szelektív (nagy rizikójú csoport), tömegszűrés (egy betegségre), alkalmi (családorvosi)."],["A szűrés kritériumai","<b>Betegség:</b> súlyos, gyakori, ismert kórtörténet. <b>Populáció:</b> meghatározott kockázati csoport és hozzáállás. <b>Teszt:</b> érzékeny és fajlagos. <b>Kezelés:</b> a korán indított hatékony. <b>Értékelhetőség:</b> költséghatékonyság, részvételi arány (QALY/€)."]],"qs":[{"t":"mc","q":"A szekunder prevenció legjellemzőbb eszköze:","o":["Szűrővizsgálat","Védőoltás","Rehabilitáció","Törvényi szabályozás"],"a":0,"e":"Korai felismerés a preklinikai szakaszban."},{"t":"match","q":"Párosítsd a szűrést a gyakorisággal!","pairs":[["Méhnyakrák (25–65 év)","3 évente citológia"],["Emlőrák (45–65 év)","2 évente mammográfia"]],"e":"Szervezett országos lakossági rákszűrés."},{"t":"mc","q":"A szűrés költséghatékonyságát mérő mutató:","o":["QALY/€","Prevalencia","Szenzitivitás","Prediktív érték"],"a":0,"e":"Egészségnyereség / ráfordítás."},{"t":"tf","q":"A szűrés kritériuma, hogy a betegség súlyos és gyakori legyen.","a":true,"e":"A betegségre vonatkozó kritérium."},{"t":"mc","q":"A hatásosság a szűrésnél azt jelenti, hogy:","o":["Csökkenti a morbiditást és mortalitást","Olcsó","Gyors","Sok ember vesz részt"],"a":0,"e":"A hatékonyság az erőforrások és eredmény viszonya."},{"t":"fill","q":"A szűrés a betegség ___ (tünetek előtti) szakaszát célozza.","a":["preklinikai","preklinikus"],"e":"A szűréssel vizsgálható preklinikai szakasz."},{"t":"mc","q":"Melyik a szűrés fajtája a forrás szerint?","o":["Alkalmi (családorvosi)","Pszichoterápiás","Kényszer","Rehabilitációs"],"a":0,"e":"Szelektív, tömegszűrés és alkalmi."}]},{"id":"u08l4","title":"Szűrőtesztek, tercier prevenció","theory":[["Teszt kritériumai","Reprodukálhatóság, <b>validitás</b>, specifitás, szenzitivitás, prediktivitás. A validitás (szűrőképesség) a szenzitivitásból és specifitásból áll. <b>Szenzitív</b>: azonosítja a pozitív személyeket. <b>Specifikus</b>: valóban azonosítja a negatívakat."],["Prediktív érték","<b>Pozitív prediktív érték:</b> pozitív eredménynél milyen valószínűséggel beteg a személy. <b>Negatív prediktív érték:</b> negatív eredményből milyen valószínűséggel következik a betegségmentesség.<br>Négymezős tábla: A (igaz pozitív), B (álpozitív), C (álnegatív), D (igaz negatív). Egészségnyereség: A, D; veszteség: B, C."],["Tercier prevenció","Cél: a prognózis javítása, szövődmények megelőzése, a funkcionalitás megőrzése vagy visszaállítása <b>kezeléssel és rehabilitációval</b>. Népegészségügyileg a keringési, mentális és mozgásszervi betegségeké a legnagyobb jelentőség. Terminológiai zavar: a gyakorlatban gyakran „másodlagosnak” nevezik."],["Alapproblémák","Hozzájárul-e a szűrés a lakosság egészségi állapotának javításához? Biztosított-e a kiszűrtek további kivizsgálása? Javítja-e a prognózist?"]],"qs":[{"t":"match","q":"Párosítsd a fogalmat a jelentéssel!","pairs":[["Szenzitivitás","azonosítja a pozitív személyeket"],["Specifitás","azonosítja a negatív személyeket"],["Pozitív prediktív érték","pozitív teszt: milyen eséllyel beteg"]],"e":"A szűrőteszt mutatói."},{"t":"mc","q":"A négymezős táblában melyik az álpozitív?","o":["B","A","C","D"],"a":0,"e":"A: igaz pozitív; B: álpozitív; C: álnegatív; D: igaz negatív."},{"t":"mc","q":"Mit mér a negatív prediktív érték?","o":["Negatív eredményből milyen eséllyel következik a betegségmentesség","A betegek aránya","A teszt költsége","A teszt reprodukálhatósága"],"a":0,"e":"A teszt eredményességét fejezi ki."},{"t":"tf","q":"A validitást a szenzitivitás és a specifitás adja meg.","a":true,"e":"A szűrőképességre irányul."},{"t":"mc","q":"Mi a tercier prevenció célja?","o":["Prognózis javítása, szövődmények megelőzése, funkció megőrzése","Betegségkialakulás megelőzése","Korai szűrés","Kockázati tényezők szabályozása"],"a":0,"e":"Kezelés és rehabilitáció révén."},{"t":"fill","q":"A klinikai gyakorlatban a tercier prevenciót gyakran ___nak nevezik.","a":["másodlagos","szekunder"],"e":"Pl. keringési betegségek szekunder prevenciója."},{"t":"tf","q":"A tercier prevenció népegészségügyi jelentősége a mentális betegségeknél is nagy.","a":true,"e":"Keringési, mentális és mozgásszervi betegségek."},{"t":"mc","q":"Melyik tartozik az egészségveszteséghez a négymezős táblában?","o":["B és C","A és D","Csak A","Csak D"],"a":0,"e":"Egészségnyereség: A és D."}]}],"color":"#e5a000"},{"id":"u09","title":"Fejlődési krízisek","desc":"Erikson, serdülőkor, családi életciklus","lessons":[{"id":"u09l1","title":"A krízis fogalma és típusai","theory":[["Mi a krízis?","Krízis: válság, fordulat; traumatikus vagy stresszel teli változás. Megoldása megküzdő mechanizmusainkat fejlesztve növeli az <b>énerőt, önbizalmat, problémamegoldó képességet</b>.<br><b>Caplan:</b> krízis akkor alakul ki, ha a személy veszélyeztető helyzettel kerül szembe, amelyet a szokásos problémamegoldó eszközeivel nem tud megoldani vagy elkerülni."],["Típusok","<b>Fejlődési krízis:</b> adott életkorban új feladat (Erikson szakaszai).<br><b>Akcidentális krízis:</b> külső stressz, trauma, negatív életesemény (Holmes skála: legsúlyosabb a házastárs halála, a válás).<br>Együtt jelentkezésük: <b>krízismátrix</b>, destruktív kimenet veszélye."],["A fejlődési krízisek jellemzői","<b>Normatív</b> krízisek: az életútba beépítettek, nem kerülhetők el. Minden új életszakaszba lépés krízissel jár: megváltozó elvárások, elvesztett vívmányok és szerepek, új feladatok, bizonytalanság. Hosszabb periódusok, dinamikus változásokkal; az akcidentális krízis ilyenkor többszörös sérülékenységet okoz. A krízis dinamikája időben behatárolt, jellegzetes szakaszokkal."]],"qs":[{"t":"mc","q":"Ki fogalmazta meg: krízis akkor alakul ki, ha a szokásos problémamegoldás nem elég a veszélyeztető helyzet megoldásához?","o":["Caplan","Erikson","Holmes","Kübler-Ross"],"a":0,"e":"Caplan krízisdefiníciója."},{"t":"match","q":"Párosítsd a krízis típusát a jellemzővel!","pairs":[["Fejlődési krízis","adott életkor új feladata"],["Akcidentális krízis","külső trauma, negatív esemény"],["Együttes jelentkezés","krízismátrix"]],"e":"Két fő típus, együtt: krízismátrix."},{"t":"tf","q":"A fejlődési krízisek normatívak, nem kerülhetők el.","a":true,"e":"Beépítettek az életútba."},{"t":"mc","q":"A Holmes-skála szerint melyik a legsúlyosabb életesemény?","o":["A házastárs halála","Munkahely-változtatás","Költözés","Házasságkötés"],"a":0,"e":"Utána következik a válás."},{"t":"fill","q":"A fejlődési és akcidentális krízis együttes megjelenése a ___.","a":["krízismátrix","krizismatrix"],"e":"Destruktív kimenetelre veszélyeztet."},{"t":"mc","q":"Mit okoz a krízis megoldása sikeres esetben?","o":["Nő az énerő és a problémamegoldó képesség","Mindig regresszió","Fixáció","Csökken az önbizalom"],"a":0,"e":"A megküzdő mechanizmusok fejlődnek."},{"t":"mc","q":"Miért jár krízissel minden új életszakaszba lépés?","o":["Megváltoznak az elvárások, az egyén elveszíti korábbi szerepeit","Mert mindig betegséggel jár","Mert külső trauma","Mert a szülők kényszerítik"],"a":0,"e":"Új feladatok és bizonytalanság is jelentkeznek."}]},{"id":"u09l2","title":"Erikson: alapok és kisgyermekkor","theory":[["Erikson elmélete","Pszichoszociális fejlődés: a személyiség a <b>születéstől a halálig</b> fejlődik; a hangsúly a környezeti és társas tapasztalatokon van. Alapja az <b>epigenetikus elv</b> (fokozatos kibontakozás). Nyolc szakasz; mindegyik egy <b>identitás-krízis</b>, két pólussal. A pozitív pólus növeli az „énerőt”, a pozitív többségben kell legyen."],["Szakaszok 1–2","<b>Csecsemőkor (0–2 év):</b> bizalom vs. bizalmatlanság. A következetes gondozás biztonságot ad; a bizalom–bizonytalanság optimális aránya a <b>remény</b> forrása.<br><b>Kisgyermekkor (2–3 év):</b> autonómia vs. szégyen és kétely. A szülők engedik az önállóságot → autonómia; türelmetlenség → kétely. Testi funkciók ellenőrzése (anális-urethrális zóna: elengedés–visszatartás), <b>akarat</b>."],["3. szakasz","<b>Óvodáskor (3–5 év):</b> kezdeményezés vs. bűntudat. Türelmes válaszok, szabad kísérletezés → kezdeményezés; korlátozás, leértékelés → bűntudat. Kialakul a <b>szándék, tervezés</b>. Veszély: ha a gyerek alapvetően bűnösnek érzi magát, agresszív, manipulatív lehet."]],"qs":[{"t":"match","q":"Párosítsd az életkort Erikson szakaszával!","pairs":[["0–2 év","bizalom vs. bizalmatlanság"],["2–3 év","autonómia vs. szégyen és kétely"],["3–5 év","kezdeményezés vs. bűntudat"]],"e":"Az első három szakasz."},{"t":"mc","q":"Miért „pszichoszociális” Erikson elmélete?","o":["A társas-környezeti tapasztalatokra helyez hangsúlyt","Csak ösztönökről szól","Csak a gyermekkorról szól","Csak a szociológiai adatokra épít"],"a":0,"e":"Nem a biológiai tényezőkön van a hangsúly."},{"t":"tf","q":"Erikson szerint a fejlődés a serdülőkor végén befejeződik.","a":false,"e":"A fejlődés élethosszig tartó folyamat."},{"t":"fill","q":"Erikson elméletének alapja az ___ elv.","a":["epigenetikus"],"e":"Fokozatos, szakaszokban történő kibontakozás."},{"t":"mc","q":"Melyik az első szakasz „én-erőssége”?","o":["Remény","Akarat","Hűség","Szeretet"],"a":0,"e":"A bizalom és bizonytalanság optimális aránya a remény forrása."},{"t":"mc","q":"Mit eredményez, ha a szülők türelmetlenek és túl sokat várnak a kisgyerektől?","o":["Kétely a saját képességeiben","Bizalom","Kezdeményezés","Teljesítmény"],"a":0,"e":"Autonómia vs. szégyen és kétely."},{"t":"mc","q":"Mi a veszélye a 3. szakaszban, ha a gyermek alapvetően bűnösnek érzi magát?","o":["Agresszív, manipulatív célelérés","Túlzott bizalom","Izoláció","Stagnálás"],"a":0,"e":"Kezdeményezés vs. bűntudat."},{"t":"tf","q":"Erikson szerint mindkét pólus megtapasztalása fontos, csak a pozitívnak kell többségben lennie.","a":true,"e":"Egyensúly kell."}]},{"id":"u09l3","title":"Iskoláskor és serdülőkor","theory":[["Iskoláskor (6–11 év)","<b>Teljesítmény vs. kisebbrendűség</b>. Egybeesik a freudi latenciával, de itt is van krízis. Megerősítés, dicséret → teljesítménykésztetés (szorgalom); kudarc, kritika → <b>kisebbrendűségi érzés</b>. A játékot a produktív helyzetek, „szerszámok” (írás, számolás) iránti igény váltja."],["Serdülőkor (12–18 év)","<b>Identitás vs. szerepkonfúzió</b>. Feladatok (Hajduska): leválás a szülőkről, szexuális szerep és identitás integrálása, intim kapcsolat, jövendő társadalmi szerepre szocializáció. Krízisek: autoritás-, teljesítmény-, identitás-krízis, szociális gátlás. Eredmény: <b>hűség</b>. Az identitáskrízis a húszas évek elejére-közepére oldódik."],["Identitás-státuszok","<b>Moratórium:</b> az elkötelezettségek időbeli kitolása.<br><b>Korai zárás:</b> „rövidre zárt” krízis, meg nem küzdött azonosság.<br><b>Identitásdiffúzió:</b> nincs elköteleződés, nincsenek követendő értékek; stagnálás, regresszió."],["Serdülőkori problémamegoldás","Éretlen problémamegoldás, családi minták és kortársak hatása. Sajátos megoldások: szökés/csellengés, alkohol- és drogabúzus, önkárosító viselkedés (feszültségcsökkentő, kortárs minták), öngyilkossági gondolatok/kísérlet (serdülőkorban a 2–3. halálok; fiúknál befejezett, lányoknál kísérlet gyakoribb)."]],"qs":[{"t":"mc","q":"Melyik Erikson 4. szakasza?","o":["Teljesítmény vs. kisebbrendűség","Identitás vs. szerepkonfúzió","Kezdeményezés vs. bűntudat","Intimitás vs. izoláció"],"a":0,"e":"Iskoláskor, 6–11 év."},{"t":"match","q":"Párosítsd az identitás-státuszt a jellemzővel!","pairs":[["Moratórium","az elköteleződések kitolása"],["Korai zárás","meg nem küzdött azonosság"],["Diffúzió","nincs elköteleződés, értékek"]],"e":"Az identitásalakulás típusai."},{"t":"fill","q":"A serdülőkori krízis sikeres megoldásának „nyeresége” a ___.","a":["hűség"],"e":"Hűség a csoporthoz, értékekhez, a jövő megvalósíthatóságába vetett bizalom."},{"t":"mc","q":"Melyik NEM serdülőkori krízis Hajduska szerint?","o":["Intimitáskrízis","Autoritáskrízis","Teljesítménykrízis","Identitáskrízis"],"a":0,"e":"Autoritás-, teljesítmény-, identitás-krízis és szociális gátlás."},{"t":"tf","q":"Serdülőkorban fiúknál inkább a befejezett öngyilkosság, lányoknál a kísérlet gyakoribb.","a":true,"e":"A kísérletek száma nő, a befejezetteké nem."},{"t":"mc","q":"Mi a kisebbrendűségi érzés kialakulásának fő oka iskoláskorban?","o":["Nem megerősített, sikertelen próbálkozások","Túlzott dicséret","Szülői engedékenység","Kortársak hiánya"],"a":0,"e":"Ha nem dicsérik meg, átéli a csökkentértékűséget."},{"t":"mc","q":"Az identitáskrízis ideális esetben mikorra oldódik meg?","o":["A húszas évek elejére–közepére","12 éves korra","30 éves korra","40 éves korra"],"a":0,"e":"Utána továbbhaladhat más életfeladatok felé."},{"t":"tf","q":"Az identitásdiffúzió azt jelenti, hogy a serdülő szilárdan elkötelezett értékek mellett.","a":false,"e":"Diffúzióban nincsenek követendő értékek, nincs elköteleződés."}]},{"id":"u09l4","title":"Felnőttkor és időskor","theory":[["Fiatal felnőttkor (19–40)","<b>Intimitás vs. izoláció</b>. Feladatok: leválás a szülői házról, foglalkozási szerep, családalapítás. Legfontosabb: intim, tartós kapcsolat. Félelem az énvesztéstől → elmagányosodás. Az intimitás elkerülése: felszínes, gyakran váltó kapcsolatok. Alapérzés: kölcsönös szeretet."],["Felnőttkor (40–65)","<b>Generativitás vs. stagnálás</b>. Alkotóképesség: új generáció alapítása és nevelése, munka, gondoskodás, értékek átörökítése. Hiánya: stagnálás, üresség, énközpontúság.<br><b>Életközépi krízis</b> (Jung: 35–45 év): betegségek, az élet végességének érzése („kapuzárási pánik”), szexuális/nemi szerepek változása, családi rendszer változásai, „kétfrontos harc”, munkahely elvesztése."],["Időskor (60+)","<b>Énintegritás vs. kétségbeesés</b>. Az integrált ember méltósággal tekint életútjára, a halál kevésbé rémisztő. Kétségbeesés: az idő túl rövid az újrakezdéshez, halálfélelem. Életesemények: biológiai hanyatlás, betegségek, kiszolgáltatottságtól való félelem, szerepek átalakulása. Én-minőség: <b>bölcsesség</b>."]],"qs":[{"t":"match","q":"Párosítsd az életkort Erikson szakaszával!","pairs":[["19–40 év","intimitás vs. izoláció"],["40–65 év","generativitás vs. stagnálás"],["60+ év","énintegritás vs. kétségbeesés"]],"e":"Erikson 6–8. szakasz."},{"t":"mc","q":"Mi a fiatal felnőttkor legfontosabb feladata?","o":["Intim, tartós kapcsolat létesítése","Identitás kialakítása","Autonómia megszerzése","Iskolai teljesítmény"],"a":0,"e":"Az én elvesztésétől való félelem izolációhoz vezet."},{"t":"mc","q":"Mit jelent a generativitás?","o":["Új generáció alapítása, nevelése, gondoskodás, alkotás","Önmagunkra figyelés","Szerepkonfúzió","Halálfélelem"],"a":0,"e":"Hiánya stagnáláshoz, üresség-érzéshez vezet."},{"t":"fill","q":"Az időskori szakasz én-minősége a ___.","a":["bölcsesség","bolcsesseg"],"e":"Az integritás a bölcsesség én-minősége."},{"t":"tf","q":"Jung szerint az életközépi krízis 35–45 éves korra tehető.","a":true,"e":"Más szerzők 33–55 évet is megadnak."},{"t":"mc","q":"Mi a „kapuzárási pánik”?","o":["Az élet végességének érzése életközépen","Serdülőkori krízis","Az óvodás-kori szorongás","Nyugdíjba vonulás öröme"],"a":0,"e":"Az életközépi krízis része."},{"t":"mc","q":"Mi okozhat kétségbeesést időskorban?","o":["Az idő túl rövid az újrakezdéshez, halálfélelem","A kortársak hiánya","A túlzott teljesítmény","A házasság"],"a":0,"e":"Az integritás ellenpólusa."},{"t":"tf","q":"Az intimitás elkerülése tartós megoldás a fiatal felnőttkori krízisben.","a":false,"e":"Csak átmenetinek tűnik; izolációhoz vezet."}]},{"id":"u09l5","title":"Családi életciklus I.","theory":[["Hill és Rodgers felosztása","A család normatív krízisei; a ciklusokat az <b>első gyermek életkora</b> határozza meg: 1. újonnan házasodott pár; 2. csecsemős család; 3. kisgyermekes; 4. iskolás korú gyermekes; 5. serdülőkorú gyermekes; 6. kibocsátó család; 7. magukra maradt, aktív szülők; 8. inaktív öreg házaspár."],["1–2. szakasz","<b>Újonnan házasodott pár:</b> összecsiszolódás, házastársi identitás, a közös keretek kiépítése; nehezítő: szülői nyomás, lakásgond, korai gyerek.<br><b>Csecsemős család (0–3 év):</b> a szülés pszichológiailag nehezen feldolgozható; <b>baby blues</b> a szülés utáni 3. napon; szerepbizonytalanság, kimerültség; a 2–3. évben a szobatisztaságra szoktatás; az apává válás lassabb; kistestvér születése."],["3–4. szakasz","<b>Kisgyermekes család (3–6 év):</b> óvodakezdés (fokozatos beszoktatás), az anya munkába áll (szerepkonfliktus), az apa pályakezdési terhei; nyílt konfliktusok nőnek, de az elégedettség nem csökken.<br><b>Iskolás korú gyermekes család (6–14 év):</b> iskolakezdés, kamaszkor előjelei, szülők vs. kortársak, válások (traumatizál, a gyermeket is megterheli)."]],"qs":[{"t":"mc","q":"Mi határozza meg a családi életciklus szakaszait Hill és Rodgers szerint?","o":["Az első gyermek életkora","A házasság hossza","A szülők kora","A család jövedelme"],"a":0,"e":"Nyolc szakaszos felosztás."},{"t":"fill","q":"A szülés utáni 3. napon jelentkező depresszív hangulati állapot a ___ blues.","a":["baby","baby blues"],"e":"Depresszív állapot hetekkel, hónapokkal később is jelentkezhet."},{"t":"match","q":"Párosítsd a szakaszt az életkorral!","pairs":[["Csecsemős család","0–3 év"],["Kisgyermekes család","3–6 év"],["Iskolás korú gyermekes","6–14 év"]],"e":"A család ciklusai."},{"t":"mc","q":"Az anya-gyermek kapcsolat központi problémája a 2–3. életévben:","o":["Szobatisztaságra szoktatás","Iskolakezdés","Pályaválasztás","Kamaszkori lázadás"],"a":0,"e":"A gyermek érdekei és a környezet elvárásai ütközhetnek."},{"t":"tf","q":"A kisgyermekes családban a nyílt konfliktusok száma nő, de a házassággal való elégedettség nem csökken.","a":true,"e":"Kárpótló a több pénz, biztonság, életszínvonal."},{"t":"mc","q":"Melyik nehezíti az újonnan házasodott pár összecsiszolódását?","o":["Szülői nyomás, megoldatlan lakásgond","Közös érdeklődés","Anyagi biztonság","Érzelmi egyetértés"],"a":0,"e":"Lojalitási kérdések is nehezíthetik."},{"t":"mc","q":"Melyik a 3. szakasz tipikus eseménye?","o":["Óvodakezdés","Nyugdíjba vonulás","Elköltözés","Megözvegyülés"],"a":0,"e":"Fontos a fokozatos beszoktatás."}]},{"id":"u09l6","title":"Családi életciklus II.","theory":[["5. szakasz: serdülőkorú gyermekes család (14–18)","A kapcsolatnak az aszimmetrikustól a <b>szimmetrikus</b> felé kell haladnia. A serdülő önálló identitása szerveződik, leválik a családi normáktól, a kortársakban egyenrangú létformát keres. A szülők rugalmatlansága bizonytalanságukból fakad."],["6–7. szakasz","<b>6. kibocsátó család:</b> a család funkciója az önálló életre való felkészítés; ha a házastárssal költöznek a szülőkhöz, lojalitási feszültségek jönnek.<br><b>7. magukra maradt, aktív szülők:</b> megkönnyebbülés, több idő egymásra, de feszültség, érzelmi kiüresedés is; a kapcsolat megújítása szükséges; új szerepek: anyós-após, nagyszülő."],["8. szakasz","<b>Inaktív öreg házaspár:</b> beszűkülő életlehetőségek (anyagi korlátok, csökkenő erőnlét), pótaktivitás keresése; függetlenség igénye a gyerekektől. <b>Megözvegyülés:</b> szerep-reintegráció, a család támogatása nélkülözhetetlen, a házastársi szerep elvesztését új családi szerepek ellensúlyozzák."]],"qs":[{"t":"mc","q":"Mi a serdülőkorú gyermekes család fő feladata?","o":["Aszimmetrikus kapcsolat szimmetrikussá alakítása","Beszoktatás","Összecsiszolódás","Megözvegyülés feldolgozása"],"a":0,"e":"A serdülő egyenrangúságot keres."},{"t":"match","q":"Párosítsd a szakaszt a jellemzővel!","pairs":[["Kibocsátó család","felkészítés az önálló életre"],["Magukra maradt szülők","új szerepek: nagyszülő, anyós-após"],["Inaktív öreg házaspár","megözvegyülés, szerep-reintegráció"]],"e":"6–8. szakasz."},{"t":"tf","q":"A gyermek kirepülése a szülők számára kizárólag nehézséget jelent.","a":false,"e":"Megkönnyebbülés is, de feszültség és kiüresedés is lehet."},{"t":"mc","q":"A 8. szakaszban a megözvegyülés után mi ellensúlyozza a házastársi szerep elvesztését?","o":["Új családon belüli feladatok és szerepek","Új házasság","Munkahelyi előrelépés","Kortársak"],"a":0,"e":"A család támogatása nélkülözhetetlen."},{"t":"fill","q":"A gyermekeik kirepülése után a megújuló szerepek közé tartozik az anyós-após és a ___ szerep.","a":["nagyszülő","nagyszülői"],"e":"Új szerepkörök a 7. szakaszban."},{"t":"mc","q":"Miért lehetnek rugalmatlanok a serdülők szülei?","o":["Bizonytalanok szülői szerepükben","Kevés idejük van","Nem szeretik a gyereket","Anyagi okokból"],"a":0,"e":"Értékekhez ragaszkodással csökkentik a szorongásukat."},{"t":"tf","q":"A kibocsátó család fő funkciója a gyermek önálló életre való felkészítése.","a":true,"e":"Ehhez szükséges készségek kialakítása."}]}],"color":"#a560e8"},{"id":"u10","title":"Krízis, gyász, kiégés","desc":"Gyász, öngyilkosság, burnout, intervenció","lessons":[{"id":"u10l1","title":"Akcidentális krízis és haldoklás","theory":[["A krízis szakaszai","Stressz → szorongásos készenléti állapot, a problémamegoldó eszközök mozgósítása. Ha a korábbi stratégia eredménytelen: feszültség nő, „próbahiba” megoldáskeresés. Siker → fejlődés. Ha kimerül az alkalmazkodóképesség: a személyiség felbomlása (öngyilkosság vagy pszichotikus reakció), mélyülő regresszió, <b>dekompenzáció</b>."],["Akcidentális krízis","Lényegi eleme a <b>tárgyvesztés</b> (fontos személy, dolog, érzés, testi épség elvesztése). Caplan: váratlan, sorscsapásszerű események (katasztrófák, balesetek). Pl. szeretett személy elvesztése, anyagi veszteség, csőd, munkahely elvesztése, súlyos betegség, erőszakos cselekmény. A veszteségek halmozódhatnak."],["Haldoklás (Kübler-Ross)","<b>Tanatológia</b>: a haldoklók és gyászolók pszichés gondozásával foglalkozó tudomány. Kübler-Ross 5 szakasza: 1. <b>tagadás</b>, 2. <b>düh</b>, 3. <b>alkudozás</b>, 4. <b>depresszió</b>, 5. <b>belenyugvás</b>. A hozzátartozók is hasonló szakaszokon mennek át, de a beteggel nem szinkronban."],["Halálfélelem","A halálfélelem a szeparációs félelem késői, felnőttkori származéka (Bagdy). Feifel: a teljes megsemmisüléstől, identitásvesztéstől való félelem."]],"qs":[{"t":"match","q":"Párosítsd a Kübler-Ross-szakaszt a jellemzővel!","pairs":[["Tagadás","„Ez nem lehet igaz!”"],["Düh","„Miért éppen velem?”"],["Alkudozás","„Ígérem, jó leszek”"],["Belenyugvás","„Ám legyen!”"]],"e":"A haldoklás szakaszai."},{"t":"mc","q":"Mi az akcidentális krízis lényegi eleme?","o":["Tárgyvesztés","Fejlődési feladat","Életkori váltás","Normatív átmenet"],"a":0,"e":"Fontos személy, dolog, érzés vagy testi épség elvesztése."},{"t":"mc","q":"Melyik a Kübler-Ross-féle második szakasz?","o":["Düh, harag","Alkudozás","Depresszió","Tagadás"],"a":0,"e":"Tagadás, düh, alkudozás, depresszió, belenyugvás."},{"t":"tf","q":"A hozzátartozók általában szinkronban vannak a haldokló stádiumaival.","a":false,"e":"Gyakran nincsenek szinkronban (pl. a család még a kezelést erőlteti)."},{"t":"fill","q":"A haldoklók és gyászolók pszichés gondozásával foglalkozó tudomány a ___.","a":["tanatológia","tanatologia"],"e":"Interdiszciplináris tudomány."},{"t":"mc","q":"A halálfélelem a forrás szerint minek a késői származéka (Bagdy)?","o":["Szeparációs félelem","Teljesítményfélelem","Szociális szorongás","Fóbia"],"a":0,"e":"Feifel: megsemmisüléstől, identitásvesztéstől való félelem."},{"t":"mc","q":"Mi történik, ha az alkalmazkodóképesség teljesen kimerül?","o":["A személyiség felbomlása, dekompenzáció","Fejlődés","Új megoldás","Spontán gyógyulás"],"a":0,"e":"Öngyilkosság vagy pszichotikus reakció formájában is."},{"t":"tf","q":"Caplan szerint az akcidentális krízist váratlan, sorscsapásszerű események váltják ki.","a":true,"e":"Pl. katasztrófák, balesetek."}]},{"id":"u10l2","title":"A gyász folyamata","theory":[["Fogalmak","<b>Gyász</b>: veszteség által kiváltott reakció (érzelmi, kognitív, viselkedéses, szomatikus tünetek, kapcsolati változás). <b>Gyászreakció</b>: a tárgyvesztést követi, legalább fél, akár egy évig tart. <b>Gyászmunka</b>: a gyászreakció normális feldolgozása. Kast: a tárgyvesztés identitásvesztéssel fenyeget."],["A normális gyász fázisai (Averill)","<b>Sokk</b> → <b>tárgyvesztés tudatosulása</b> → <b>adaptáció</b>. 0. <b>Anticipációs gyász</b> (Pilling): előre foglalkoznak a halállal.<br>Sokk: percektől napokig; bénultság, tagadás, a halott „jelenléte”; kontrollált szakasz a temetésig. A temetési rítus lezárja a sokkot."],["Depresszív szakasz és átdolgozás","<b>Tudatosulás (első 3 hónap):</b> legnehezebb időszak; erős érzelmek, a gondolkodás a halottra szűkül (monoideás), rövid, nem pszichotikus hallucinációk, döntésképtelenség, testi tünetek.<br><b>Átdolgozás (3 hónap után):</b> csökkenő intenzitás, tudatos emlékezés, visszaesés évfordulókon."],["Adaptáció és Worden","<b>Adaptáció</b> (1 év után): helyreáll az egyensúly, új kapcsolatok; az elhunyt belső emlékkép. <b>Worden 4 feladata:</b> 1. a veszteség valóságának elfogadása, 2. a fájdalom átélése, 3. alkalmazkodás az elhunyt nélküli környezethez, 4. a kapcsolat érzelmi átértékelése, képesség az élet folytatására."]],"qs":[{"t":"match","q":"Párosítsd a normális gyász fázisát a jellemzővel!","pairs":[["Sokk","bénultság, tagadás"],["Tudatosulás","legnehezebb, első 3 hónap"],["Átdolgozás","csökkenő érzelmi intenzitás"],["Adaptáció","1 év után, új kapcsolatok"]],"e":"A gyász fázisai."},{"t":"mc","q":"Mi az anticipációs gyász (Pilling)?","o":["A hozzátartozók előre foglalkoznak a halállal","Késleltetett gyász","Krónikus gyász","A temetés utáni gyász"],"a":0,"e":"Életveszélyes körülmények, betegség esetén."},{"t":"tf","q":"A gyászreakció során előforduló rövid hallucináció a gyászoló pszichózisát jelzi.","a":false,"e":"Nem pszichózis: csak a halottra irányul, nem bizarr, nem fenyegető."},{"t":"fill","q":"A gyászreakció normál feldolgozását gyász___nak nevezzük.","a":["munka","gyászmunka"],"e":"Gyászmunka."},{"t":"mc","q":"Melyik NEM Worden gyászmunka-feladata?","o":["A halott idealizálása","A veszteség valóságának elfogadása","A fájdalom átélése","Alkalmazkodás az elhunyt nélküli környezethez"],"a":0,"e":"A negyedik: érzelmi átértékelés és az élet folytatása."},{"t":"mc","q":"Mikorra várjuk az adaptációt?","o":["Kb. 1 év után","1 hét után","1 hónap után","3 év után"],"a":0,"e":"Tünetek enyhülnek, új tárgykapcsolatok alakulnak ki."},{"t":"mc","q":"Mit tesz a temetési rítus?","o":["Tudatosítja és lezárja az elválást, a sokk szakaszát","Növeli a tagadást","Elnyomja az érzelmeket","Lerövidíti a gyászt"],"a":0,"e":"Keretet ad az érzelmek kifejezéséhez, közösségi támogatás."},{"t":"tf","q":"A gyász akkor feldolgozott, ha a gyászoló képes az élet folytatására és együtt él az elhunyt emlékével.","a":true,"e":"Az elhunytra belső emlékképként gondol."}]},{"id":"u10l3","title":"Akut és komplikált gyász","theory":[["Akut gyász (Lindemann, 1944)","Határozott pszichés és szomatikus tünetekkel járó klinikai entitás közvetlenül a krízis után. Lehet típusos vagy atípusos (késleltetett, túlzó, elmaradó). Érzelmek: <b>bűntudat, düh, megkönnyebbülés, emancipáció, szorongás, segítségnélküliség, tagadás, ürességérzés</b>, régi konfliktusok újraaktiválódása."],["Freud: gyász és melankólia","A gyászban a <b>külvilág</b> szegényedik el, a depresszióban az <b>én</b>. Gyászmunka: a libidó visszavonása az elvesztett tárgyról és új tárgy keresése. Gyászban az önvád az elhunyttal kapcsolatos, depresszióban mindent áthat (bűnösségi téveszme lehet)."],["Pilling: komplikált gyász","A „patológiás” helyett; a halálesetek kb. <b>10–25%</b>-a. Típusok: <b>időtartam</b> szerint krónikus/elhúzódó és késleltetett; <b>intenzitás</b> szerint bagatellizáció és hipertrófikus; <b>megnyilvánulás</b> szerint torzult gyász."],["Hajlamosító tényezők","Váratlan veszteség, dependens vagy ambivalens kötődés, gyermek/fiatal halála, korábbi feldolgozatlan veszteségek, depresszió, öngyilkosság, erőszakos halál, halmozott gyász, rossz testi/lelki egészség, baleset okozása. Veszélyeztetettebbek: alacsony szocioökonómiai státuszúak, férfiak."]],"qs":[{"t":"match","q":"Párosítsd a komplikált gyász csoportját a típussal!","pairs":[["Időtartam szerint","krónikus, késleltetett"],["Intenzitás szerint","bagatellizáció, hipertrófikus"],["Megnyilvánulás szerint","torzult gyász"]],"e":"Pilling felosztása."},{"t":"mc","q":"Mi a különbség Freud szerint a gyász és a depresszió között?","o":["Gyászban a külvilág, depresszióban az én szegényedik el","Ugyanaz","Gyászban az én szegényedik el","Depresszióban nincs önvád"],"a":0,"e":"Depresszióban az önvád mindent áthat."},{"t":"fill","q":"A halálesetek kb. 10–25%-a alakul ___ gyásszá.","a":["komplikált"],"e":"Pilling a „patológiás” helyett vezette be."},{"t":"mc","q":"Mi jellemzi a bagatellizációt?","o":["Hiányzik a normális gyászreakció, mintha mi sem történt volna","Túlzott, tartós érzelem","Elhúzódó mumifikáció","Késői megjelenés testi tünetekkel"],"a":0,"e":"Típusai: munkába menekülés, segítségbe menekülés."},{"t":"mc","q":"Melyik a „segítségbe menekülés”?","o":["A professzionális segítők tipikus megoldása: másoknak segít magán helyett","Tartós visszahúzódás","Mumifikáció","Hallucináció"],"a":0,"e":"A bagatellizáció egyik típusa."},{"t":"tf","q":"A mumifikáció a krónikus gyász szélsőséges formája (az elhunyt tárgyai érintetlenek).","a":true,"e":"Pl. nem rendezi át a szobát."},{"t":"mc","q":"Melyik NEM hajlamosít komplikált gyászra?","o":["Hosszan előkészített, kiegyensúlyozott kapcsolat","Váratlan veszteség","Ambivalens kötődés","Gyermek halála"],"a":0,"e":"Hajlamosít többek közt a dependens és ambivalens kötődés."},{"t":"tf","q":"Az özvegy férfiak öngyilkossági aránya háromszorosa a kontrollcsoporténak.","a":true,"e":"Rosszabb a szociális támogató rendszerük."}]},{"id":"u10l4","title":"Gyermeki haláltudat és gyász","theory":[["Gyermeki haláltudat","<b>2–5 év:</b> animista, reverzibilis („most alszik”). <b>5–9 év:</b> perszonifikáló (a halál élő személy, pl. a kaszás). <b>9 évtől:</b> reális halálkép (a testi élet végleges megszűnése). <b>Serdülőkor:</b> felerősödő halállal való foglalkozás, fantáziák arról, ki menne el a temetésre."],["Gyermeki halálfélelem és gyász","A halálfélelem gyökere a <b>szeparációs szorongás</b>, összekapcsolódik a sérüléstől való félelemmel; fontos, hogy a gyerek kifejezhesse. Gyász: 6 hónapos kor előtt nincs azonnali gyászreakció; 6–24 hónaposan szeparációs félelem. A beszélő gyereknek segíteni kell a gyászmunkában, különben neurotikus tünetek, aszocialitás."],["Specifikus gyászok","Öngyilkossággal, gyilkossággal kapcsolatos gyász; prenatális, perinatális gyász, gyermekhalál. A gyász után nő a mortalitás: az első héten kétszeres, az első 6 hónapban négyszeres halálozás a gyászolók között."]],"qs":[{"t":"match","q":"Párosítsd az életkort a haláltudattal!","pairs":[["2–5 év","animista, reverzibilis"],["5–9 év","perszonifikáló"],["9 év felett","reális halálkép"]],"e":"A gyermeki haláltudat szakaszai."},{"t":"mc","q":"Mi a gyermeki halálfélelem gyökere?","o":["Szeparációs szorongás","Teljesítményszorongás","Iskolai kudarc","Kortárs-elutasítás"],"a":0,"e":"Összekapcsolódik a sérüléstől való félelemmel."},{"t":"tf","q":"6 hónapos kor előtt a csecsemőnél nincs azonnali gyászreakció.","a":true,"e":"6–24 hónaposan már szeparációs félelem jelenik meg."},{"t":"fill","q":"A 2–5 éves gyerek haláltudata ___ („most alszik”).","a":["animista","reverzibilis"],"e":"A halált visszafordíthatónak éli meg."},{"t":"mc","q":"Mi történhet, ha a beszélő gyereknek nem segítenek a gyászmunkában?","o":["Neurotikus tünetek, aszocialitás","Gyors gyógyulás","Teljesítményjavulás","Semmi"],"a":0,"e":"Fontos a félelem kifejezésének lehetősége."},{"t":"mc","q":"Melyik gyászfajta tartozik a specifikus gyászok közé?","o":["Perinatális gyász","Anticipációs gyász","Átdolgozás","Sokk"],"a":0,"e":"Ide tartozik az öngyilkossággal és gyilkossággal kapcsolatos gyász is."},{"t":"mc","q":"A gyászolók halálozása az első 6 hónapban kb. hányszoros?","o":["Négyszeres","Kétszeres","Tízszeres","Változatlan"],"a":0,"e":"Az első héten kétszeres."}]},{"id":"u10l5","title":"Öngyilkosság: epidemiológia és kockázat","theory":[["Epidemiológia és Durkheim","Humán jelenség, minden korban előfordul. Magyar ráta 1980–2004: 45 → 26/100 ezer; a keleti, észak-keleti megyék 2–3-szor magasabbak. A tudományos megközelítés <b>Durkheimmel</b> kezdődött: <b>egoista</b> (társas kötelékek hiánya, izoláció), <b>altruista</b> (önfeláldozás a társadalomért), <b>anómiás</b> (célok és lehetőségek ellentéte)."],["Nem, kísérlet, jelzések","Az áldozatok 65–75%-a <b>férfi</b>; gyakoribb tavasszal, a nap első felében, premenstruumban. A <b>kísérlet nőknél gyakoribb</b>. A befejezettek 16–32%-ánál szerepel korábbi kísérlet; 15–50% jelzi szándékát. Az első kísérlet után a befejezett öngyilkosság kockázata <b>50–100-szoros</b>."],["Rihmer: rizikófaktorok","<b>Elsődleges:</b> pszichiátriai betegség (affektív, szorongásos, alkohol-/drogbetegség, személyiségzavar, mánia), korábbi kísérlet, családi halmozódás, csökkent szerotoninaktivitás.<br><b>Másodlagos:</b> korai veszteségek, izoláció, súlyos testi betegség, munkanélküliség, súlyos negatív életesemények, dohányzás.<br><b>Harmadlagos</b> (nem változtatható): férfinem, serdülő fiúk/idős nők, vulnerábilis periódusok."],["Protektív tényezők és depresszió","Védők: jó szociális/családi háttér, terhesség, a szülés utáni első év, több gyerek, gyakorló vallásosság, pszichiátriai betegek kezelése. Az öngyilkosok közel 60%-a major depressziós (skizofrénia 10–12%, szerfüggés 10–15%); fele-kétharmaduk az utolsó hónapban orvosnál jelenik meg. Depresszió önmagában nem elég: impulzuskontroll- és problémamegoldás-zavar is kell."]],"qs":[{"t":"match","q":"Párosítsd Durkheim öngyilkosság-típusát a jellemzővel!","pairs":[["Egoista","izoláció, társas kötelékek hiánya"],["Altruista","önfeláldozás a társadalomért"],["Anómiás","vágyak és lehetőségek ellentéte"]],"e":"Durkheim három típusa."},{"t":"mc","q":"Ki kezdte a téma tudományos megközelítését?","o":["Durkheim","Freud","Erikson","Caplan"],"a":0,"e":"A francia szociológus Durkheim."},{"t":"mc","q":"Melyik nem követ el gyakrabban öngyilkossági kísérletet?","o":["Nők","Férfiak","Egyformán","Serdülő fiúk"],"a":0,"e":"A befejezett öngyilkosság férfiaknál gyakoribb (65–75%)."},{"t":"fill","q":"Az első kísérlet után a befejezett öngyilkosság kockázata ___-szorosra nő.","a":["50-100","50–100","ötven-százszorosra","50-100-szorosra"],"e":"A kísérleten átesettek fokozottan veszélyeztetettek."},{"t":"mc","q":"Rihmer szerint melyik harmadlagos rizikófaktor?","o":["Férfinem","Depresszió","Korábbi kísérlet","Alkoholbetegség"],"a":0,"e":"Nem megváltoztatható; önmagában kicsi a prediktív értéke."},{"t":"tf","q":"Minden depressziós személy öngyilkos lesz.","a":false,"e":"Impulzuskontroll- és problémamegoldás-zavar, pszichoszociális tényezők is kellenek."},{"t":"mc","q":"Melyik védőfaktor?","o":["Terhesség","Munkanélküliség","Izoláció","Családi halmozódás"],"a":0,"e":"Védők még: több gyerek, gyakorló vallásosság, kezelés."},{"t":"mc","q":"Az öngyilkosok hány százaléka szenved major depresszióban?","o":["Közel 60%","10–12%","Kb. 5%","Kb. 90%"],"a":0,"e":"Skizofrénia 10–12%, szerfüggés 10–15%."}]},{"id":"u10l6","title":"Öngyilkosság: preszuicidális szindróma, beavatkozás","theory":[["Cry for help, preszuicidális szindróma","Az öngyilkosok kis hányada közli konkrétan szándékát; a „segélykiáltást” (<b>cry for help</b>) ha a környezet nem érzékeli, a folyamat a <b>preszuicidális szindróma</b> (Ringel) felé halad. Triász: 1. <b>dinamikus beszűkülés</b> (gondolkodás, érzelem, kapcsolatok, értékek), 2. <b>gátolt, önmagára fordított agresszió</b>, 3. <b>öngyilkossági fantáziák</b>."],["Veszély megítélése (1–5)","1. „Jobb lenne nem élni” típusú kijelentések. 2. Erős halálvágy, nem egyértelmű döntés. 3. Kifejezett elhatározás, de nincs konkrét terv (veszélyeztető állapot). 4. Pontos terv (<b>közvetlen veszélyeztető állapot</b>). 5. Az adott állapotban már előzetes próbálkozások."],["Beavatkozás","Azonnali <b>krízisintervenció</b>; közvetlen veszély esetén kórházi beutalás (kényszerintézkedés is, dokumentálva), felügyelet a mentők kiérkezéséig. Súlyos állapotban sürgősségi pszichiátriai ellátás. Hatékony prevenció: depresszió korai felismerése és kezelése, utógondozás, egészségügyi személyzet képzése, felvilágosítás (tanárok, lelkészek, vezetők is), krízisközpontok."],["Rizikónövelő tényezők (összefoglalás)","Szuicid gondolatok, pszichiátriai és szomatikus betegségek, pszichoszociális tényezők (támogatottság hiánya, munkanélküliség), gyermekkori traumák, családi hatások, reménytelenség, impulzivitás, gondolati beszűkültség. Védők: gyermek a családban, felelősségérzés, életelégedettség, ép valóságteszt, megküzdés, támogatottság."]],"qs":[{"t":"match","q":"Párosítsd a preszuicidális szindróma elemét a leírással!","pairs":[["Dinamikus beszűkülés","gondolkodás, érzelem, kapcsolatok szűkülése"],["Gátolt agresszió","a harag a saját személy ellen fordul"],["Fantáziák","a cselekmény és következményei elképzelése"]],"e":"A szindróma három eleme."},{"t":"mc","q":"Mi a „cry for help”?","o":["Segélykiáltás, szándék közlése a környezetnek","Gyászmunka","Kényszerbeutalás","Rizikófaktor"],"a":0,"e":"Ha nem érzékelik, a folyamat a preszuicidális szindróma felé halad."},{"t":"mc","q":"Melyik a veszélyeztetettség 4. szintje?","o":["Pontos terv a tett végrehajtására","„Jobb lenne nem élni”","Erős halálvágy","Előzetes próbálkozások"],"a":0,"e":"Közvetlen veszélyeztető állapot."},{"t":"tf","q":"Közvetlen veszély esetén kórházi beutalás kényszerintézkedéssel is kezdeményezhető.","a":true,"e":"Gondos dokumentációval, indoklással."},{"t":"mc","q":"Melyik hozzájárul a megelőzéshez a forrás szerint?","o":["A depresszió korai felismerése és kezelése","A tünetek tagadása","Az utógondozás elhagyása","A felvilágosítás elkerülése"],"a":0,"e":"Valamint az egészségügyi személyzet képzése, utógondozás."},{"t":"fill","q":"A preszuicidális szindróma a ___ szindrómája, az önpusztító cselekmény közvetlen előzménye.","a":["szuicid","öngyilkosság","öngyilkossági"],"e":"A hozzá vezető út végső állomása."},{"t":"mc","q":"Melyik a protektív faktor?","o":["Megfelelő terápiás kapcsolat","Impulzivitás","Reménytelenség","Alkoholfogyasztás"],"a":0,"e":"Valamint megfelelő szociális támogatottság, megküzdés."},{"t":"mc","q":"A veszélyeztető állapot (3. szint) jellemzője:","o":["Kifejezett elhatározás, de nincs konkrét terv","Pontos terv","Már volt próbálkozás","Csak homályos kijelentés"],"a":0,"e":"A 4. szinten már pontos terv van."}]},{"id":"u10l7","title":"Helfer-szindróma, burnout, krízisintervenció","theory":[["Burnout (Freudenberger, 1974)","Krónikus emocionális megterhelés nyomán fellépő fizikai, emocionális, mentális kimerülés, reménytelenséggel, inkompetencia-érzéssel, negatív attitűdökkel. <b>3 komponens:</b> érzelmi kimerültség, deperszonalizáció (betegek személytelen kezelése), kétség a saját hatékonyságban. Mérése: <b>Maslach (MBI)</b>."],["Burnout fázisai és védekezés","Ciklus: <b>idealizmus → realizmus → stagnálás → frusztráció → apátia</b> → intervenció. Védő: önismeret, rugalmasság, társas kapcsolatok, tematikus segítő csoportok. Maslach és Pines: <b>detached concern</b> (távolságtartó törődés). Prodromális jel: „mea culpa” reakció."],["Helfer-szindróma (Schmidbauer, 1977)","A segítés a saját ingatag egyensúly fenntartásának rejtett szükséglete: a segítő viselkedés a belső üresség, félelmek elhárítása. Háttér: korai közvetett szülői elutasítás, merev azonosulás a felettes-énnel. Jellemzők: saját segítségszükséglet tagadása, hiányzó kölcsönösség, nárcisztikus igények, függés a külső megerősítéstől. Kiégés kezdőszakasza lehet. Típus: „foglalkozás áldozata”, „kalóz”."],["Krízisintervenció","A krízisállapot oldására irányuló célzott segítség; <b>nem terápia</b>, a cél az egyensúly helyreállítása. Eszközei: érzelmi támogatás, megerősítés, ventiláció, tanácsadás, realitás képviselete, adaptív megoldások. Három szint: vészhelyzeti kezelés, krízistámogatás, szűkebb krízisintervenció. Színterek: osztály, ambulancia, krízisközpont, telefonos lelki segély. Kb. 6–8 alkalom (a rövid dinamikus terápia 20–40)."]],"qs":[{"t":"match","q":"Párosítsd a burnout komponensét a leírással!","pairs":[["Érzelmi kimerültség","fáradtság, erőforrások kiürülése"],["Deperszonalizáció","személytelen betegkezelés"],["Csökkent hatékonyság","kétség a saját munka eredményességében"]],"e":"A Maslach-féle alskálák."},{"t":"mc","q":"Ki írta le először a burnout szindrómát?","o":["Freudenberger","Schmidbauer","Maslach","Kobasa"],"a":0,"e":"1974."},{"t":"mc","q":"Melyik a burnout első fázisa a ciklusban?","o":["Idealizmus","Realizmus","Apátia","Frusztráció"],"a":0,"e":"Idealizmus → realizmus → stagnálás → frusztráció → apátia."},{"t":"mc","q":"Ki írta le a helfer-szindrómát?","o":["Schmidbauer","Freudenberger","Lindemann","Caplan"],"a":0,"e":"1977."},{"t":"tf","q":"A helfer-szindrómás segítő azért segít, hogy ne kelljen észrevennie saját szükségleteit.","a":true,"e":"A segítés a belső üresség és félelmek elhárítása."},{"t":"fill","q":"A burnout mérésére a ___-féle kérdőív (MBI) szolgál.","a":["Maslach","maslach"],"e":"Maslach Burnout Inventory."},{"t":"tf","q":"A krízisintervenció pszichoterápia, amely a személyiség átalakítására törekszik.","a":false,"e":"Nem terápia; célja az egyensúly helyreállítása."},{"t":"mc","q":"Melyik a krízisintervenció legfontosabb eszköze?","o":["Érzelmi támogatás","Konfrontáció","A kora gyermekkor feltárása","Értelmezés"],"a":0,"e":"A feltárást, konfrontációt, értelmezést kerüljük."},{"t":"match","q":"Párosítsd a krízisintervenció szintjét a céllal!","pairs":[["Vészhelyzeti kezelés","az öndestrukció megakadályozása"],["Krízistámogatás","korábbi egyensúly visszanyerése"],["Szűkebb értelemben vett","jobb egyensúly, későbbi megküzdés"]],"e":"Három pszichodinamikai csoport."}]}],"color":"#ff86d0"},{"id":"u11","title":"Addiktológia","desc":"Szerek, alkohol, játék, dohányzás","lessons":[{"id":"u11l1","title":"Alapfogalmak és szerek","theory":[["Megerősítők, úzus, abúzus","<b>Természetes megerősítők</b>: sport, művészet, szexualitás. <b>Mesterséges megerősítők</b>: alkohol, drog – az adott kultúra kevésbé fogadja el. Ha a szer nem elfogadott: <i>abúzus</i> (rendellenes használat), nem <i>úzus</i>. A mesterséges megerősítők kiszorítják a természeteseket, az érdeklődés a szerre szűkül: <b>addikció</b>."],["Addikció és szakszavak","<b>Addikció</b>: olyan viselkedés, amely felett a személy nem tud kontrollt gyakorolni, kényszeresen ismétli, káros következményekkel jár, sóvárog (craving) utána. Két fajta: <b>kémiai</b> és <b>viselkedési</b>. <b>Kábítószer</b>: jogi szó (illegális szerek listája). <b>Drog</b>: magyarul az illegális szer. <b>Pszichoaktív szer</b> (BNO, DSM): átjut a vér-agy gáton, a KIR-re hat, legális vagy illegális egyaránt. <b>Dizájner drog</b>: módosított szerkezet, így nincs listán."],["Szerek csoportosítása","Szempontok: legális/illegális, természetes/szintetikus, kemény/könnyű, használati mód (szájon át, szippantva, intramuszkulárisan, intravénásan – nő a kockázat), kémiai szerkezet, pszichoaktív hatás. Hatás szerint: <b>stimulánsok</b> (kokain, amfetamin, koffein, nikotin), <b>hallucinogének</b> (LSD, meszkalin, pszilocibin, fenciklidin; extasy), <b>depresszánsok</b> (alkohol, nyugtatók, altatók, ópiátok)."],["Magyar droghelyzet","1990-es évek: máktea, heroin, szipuzás. Közepétől: könnyű drogok (fű, diszkódrogok: extasy, speed). 2000-es évek elején a <b>rekreációs droghasználat</b> dominált: hétvégén, nem függő módon. Egy részük mégis függővé válik."]],"qs":[{"t":"mc","q":"Mi a pszichoaktív szer legfontosabb jellemzője?","o":["A vér-agy gáton átjutva a KIR-re hat","Mindig illegális","Mindig szintetikus","Csak függőséget okoz"],"a":0,"e":"A BNO és a DSM is ezt a kifejezést használja; független a szer jogi státuszától."},{"t":"mc","q":"Melyik a jogi műszó az illegális szerek listájára?","o":["Kábítószer","Pszichoaktív szer","Addikció","Dizájner drog"],"a":0,"e":"A kábítószer jogi szó; félrevezető, mert pl. a stimuláns nem kábít."},{"t":"tf","q":"A dizájner drogok a szer kémiai szerkezetének módosításával kerülik ki az illegalitást.","a":true,"e":"Mivel az új szerkezet nincs a hivatalos listán."},{"t":"match","q":"Párosítsd a szert a hatás szerinti csoporttal.","pairs":[["Kokain","Stimuláns"],["LSD","Hallucinogén"],["Ópiátok","Depresszáns"],["Nikotin","Stimuláns"]],"e":"Az extasy stimulánsnak és hallucinogénnek is sorolható."},{"t":"mc","q":"Mikor beszélünk abúzusról úzus helyett?","o":["Ha a használt mesterséges megerősítő a társadalom által nem elfogadott","Ha a szert egyedül használják","Ha a szer természetes eredetű","Ha a szer legális"],"a":0,"e":"Az úzus elfogadott szerhasználat, az abúzus rendellenes szerhasználat."},{"t":"fill","q":"A mesterséges megerősítők gyakori használatnál kiszorítják az életből a ___ megerősítőket.","a":["természetes"],"e":"Pl. sport, művészet, szexualitás."},{"t":"mc","q":"Melyik jellemezte a 2000-es évek elejét a magyar illegális droghelyzetben?","o":["Rekreációs droghasználat","Máktea dominanciája","A szipuzás uralma","A heroinisták számának nagy növekedése"],"a":0,"e":"A rekreációs használat hétvégi, nem függő módon történik."},{"t":"tf","q":"Az addikciók két fő fajtája a kémiai és a viselkedési addikció.","a":true,"e":"A kémiai addikció pszichoaktív szerekhez kötődik."}]},{"id":"u11l2","title":"Diagnosztika: abúzus, dependencia","theory":[["F10-F19 és a kódok","BNO-10: <b>F10</b> alkohol, F11 opiátok, F12 kannabisz, F13 nyugtató/altató, F14 kokain, F15 egyéb stimuláns (koffein), F16 hallucinogén, F17 dohányzás, F18 illékony oldószer, F19 több szer. A kód 2. számjegye a szer, a 3. a kórkép: .0 intoxikáció, .1 abúzus, .2 dependencia, .3 megvonás, .4 megvonás delíriummal, .5 pszichotikus, .6 amnesztikus, .7 késői pszichotikus. Minden szert és minden klinikai állapotot külön diagnosztizálni kell."],["Abúzus (F1x.1)","Maladaptív szerhasználat, 12 hónapon belül <b>legalább 1</b> az alábbiakból: szerepelvárások elmulasztása (munka, iskola, otthon); használat fizikailag veszélyes helyzetben (pl. vezetés); ismételt jogi problémák; használat a szociális/interperszonális gondok ellenére. A tünetek <b>sosem felelnek meg a dependenciának</b> – egy szernél vagy abúzus, vagy dependencia."],["Dependencia (F1x.2)","12 hónapon belül <b>legalább 3</b> a 7-ből: (1) tolerancia, (2) megvonás, (3) tervezettnél több/hosszabb használat, (4) sikertelen kontroll- vagy leszokási kísérlet, (5) sok idő a szerre, (6) fontos tevékenységek feladása, (7) folytatás a tudott ártalmak ellenére. Tolerancia vagy megvonás = <b>szomatikus</b> dependencia, a többi pszichológiai. A koffein nem diagnosztizálható."],["Ivási piramis, DSM-V","<b>Magas kockázatú ivás</b> (még nem diagnózis): nőknél heti több mint 7 ital vagy alkalmanként több mint 3; férfiaknál heti több mint 14 vagy alkalmanként több mint 4. (1 ital = 3 cl tömény, kb. 1 dl bor.) Dependens is lehet aktuálisan absztinens (védett környezet, gyógyszer, elvonókúra) vagy aktív. <b>DSM-V</b>: egységes szerhasználati zavar, enyhe/súlyos; bekerül a kóros játékszenvedély."]],"qs":[{"t":"mc","q":"Melyik BNO-kód az alkoholhoz tartozik?","o":["F10","F11","F14","F17"],"a":0,"e":"F10 alkohol, F11 opiátok, F14 kokain, F17 dohányzás."},{"t":"mc","q":"Hány kritérium szükséges a dependencia diagnózisához 12 hónapon belül?","o":["Legalább 3 a 7-ből","Legalább 1 a 4-ből","Legalább 5 a 7-ből","Mind a 7"],"a":0,"e":"Az abúzushoz elég legalább 1 a 4-ből."},{"t":"tf","q":"Ugyanarra a szerre egyszerre adható abúzus és dependencia diagnózis.","a":false,"e":"Az abúzus tünetei sosem felelnek meg a dependenciának; a kettő nincs együtt."},{"t":"match","q":"Párosítsd a kódot a kórképpel.","pairs":[["F1x.0","Akut intoxikáció"],["F1x.2","Dependencia"],["F1x.3","Megvonási szindróma"],["F1x.6","Amnesztikus szindróma"]],"e":"A kód 3. számjegye mutatja a kórképet."},{"t":"mc","q":"Mi jelzi a szomatikus dependenciát?","o":["Tolerancia vagy megvonás","Sóvárgás","Jogi problémák","Tervezettnél hosszabb használat"],"a":0,"e":"A többi kritérium a pszichológiai függőséget írja le."},{"t":"mc","q":"Melyik a magas kockázatú ivás küszöbe férfiaknál?","o":["Heti &gt;14 ital vagy alkalmanként &gt;4","Heti &gt;7 ital","Alkalmanként &gt;3 ital","Napi 1 ital"],"a":0,"e":"Nőknél a küszöb feleannyi: heti több mint 7, alkalmanként több mint 3."},{"t":"fill","q":"A DSM-5 a ___ zavara néven vonja össze az abúzust és a dependenciát.","a":["szerhasználat","szerhasználati"],"e":"Enyhe és súlyos formát különböztet meg."},{"t":"tf","q":"A magas kockázatú ivás már pszichiátriai diagnózis.","a":false,"e":"Kockázati tényező; a diagnózis az abúzus vagy dependencia."}]},{"id":"u11l3","title":"Szerindukálta kórképek","theory":[["Intoxikáció és megvonás","<b>Intoxikáció</b>: reverzibilis, szerspecifikus, keresztmetszeti állapot (nem mond a függőségről). Alkoholnál dózisfüggő: kevés élénkít, oldja a gátlást; több agressziót, agitáltságot okoz; sok nyugtat, kómát. Hat az elvárás, személyiség, kontextus is. <b>Patológiás intoxikáció</b> csak alkoholnál: kis mennyiségtől hirtelen agresszió, pszichotikus állapot, terminális alvás, amnézia. <b>Megvonás</b>: hosszú, nagy használat után; alkoholnál vegetatív (izzadás, tachycardia, tremor), pszichés (szorongás, insomnia, hallucináció), alkalmi epilepsziás roham."],["Delirium tremens","Megvonás után kialakuló <b>delírium</b>: tudatzavar, tájékozatlanság, hallucinációk (gyakran bogarak), széteső gondolkodás, nyugtalanság. Az alkoholbetegek kb. <b>15%</b>-át érinti, 40–50 éves kor körül jellemző. A legsúlyosabb szakasz 1–3 nap, mortalitás 1–3%. Sürgősségi ellátást igényel."],["Pszichotikus zavar","Szer okozza, nem endogén; többnyire pár hét–1 hónap alatt rendeződik. Okozhatja: amfetamin, extasy, kokain (rendszeres használók 50%-ában; tipikus a bőr alatti bogarak = taktilis hallucináció), LSD (bad trip, flashback). Kannabisz: kockázati tényező, amotivációs szindróma. Alkohol: hallucinózis, féltékenységi paranoia. Elkülönítés: a kórelőzményben nincs pszichózis."],["Amnesztikus szindróma, karakteropátia","<b>Korsakow</b> (alkohol): anterográd amnézia, dezorientáció, konfabuláció; <b>tiamin (B1) hiány</b> okozza (rossz táplálkozás, felszívódási zavar). Előfutára a <b>Wernicke-encephalopathia</b> (szemizombénulás, nystagmus, ataxia, konfúzió) – B-vitamin-pótlással még reverzibilis. Kannabisz, extasy: verbális memória 2–2,5 év absztinencia után is romlott; szerves oldószerek a legneurotoxikusabbak. <b>Alkoholos karakteropátia</b>: erkölcsi leépülés, megbízhatatlanság, gátlástalanság, érdeklődés beszűkülése."]],"qs":[{"t":"mc","q":"Melyik kórkép csak alkoholnál fordul elő?","o":["Patológiás intoxikáció","Flashback","Bad trip","Amotivációs szindróma"],"a":0,"e":"Kis mennyiségtől hirtelen agresszió, terminális alvás, utólagos amnézia."},{"t":"mc","q":"Az alkoholbetegek kb. hány százalékánál alakul ki delirium tremens?","o":["15%","1%","50%","90%"],"a":0,"e":"A halálozás 1–3%, a súlyos állapot 1–3 nap alatt lezajlik."},{"t":"mc","q":"Melyik vitamin hiánya áll a Korsakow-szindróma hátterében?","o":["Tiamin (B1)","C-vitamin","D-vitamin","A-vitamin"],"a":0,"e":"A hiányt táplálkozási elégtelenség és felszívódási zavar okozza."},{"t":"tf","q":"A Wernicke-encephalopathia még visszafordítható B-vitamin-pótlással.","a":true,"e":"Ha nem kezelik, kialakulhat a Korsakow-szindróma."},{"t":"match","q":"Párosítsd a szert a jellemző szerindukálta tünettel.","pairs":[["Kokain","Bőr alatti bogarak hallucinációja"],["LSD","Flashback"],["Kannabisz","Amotivációs szindróma"],["Alkohol","Féltékenységi paranoia"]],"e":"Mindegyik a forrásban szereplő szerspecifikus kép."},{"t":"fill","q":"A Korsakow-szindrómában a hiányzó emlékeket mesével kitöltő jelenség a ___.","a":["konfabuláció","konfabulacio"],"e":"Nem hazugság."},{"t":"tf","q":"A szer okozta pszichotikus zavar általában hónapokig-évekig tart a szer elhagyása után is.","a":false,"e":"Általában pár hét, kb. 1 hónap alatt rendeződik."},{"t":"mc","q":"Melyik tünet NEM jellemző az alkoholmegvonásra?","o":["Eufória és gátlástalanság","Tremor","Insomnia","Tachycardia"],"a":0,"e":"Az eufória az enyhe intoxikációra jellemző."}]},{"id":"u11l4","title":"Alkoholbetegség: epidemiológia","theory":[["Hogyan becsüljük a számukat?","Az alkoholista tagadja a fogyasztást, ezért becslések kellenek. <b>Jellinek</b>: a májcirrózisban elhunytak számából. <b>Ledermann</b>: az egy főre jutó, kereskedelmi forgalomban eladott tiszta szesz mennyiségéből (nem tartalmazza az illegális alkoholt; ~11 liter 2002-ben). WHO: férfiaknak napi 40 g, nőknek napi 20 g, hetente legalább 2 absztinens nappal."],["Számok, életút","Problémás ivó kb. <b>1 millió</b>; KSH 2011: becsült alkoholista 475 000, nyilvántartott 16 035. A fogyasztás 1984-ig nőtt, utána kis csökkenés, majd stagnálás. Férfiaknál az alacsony iskolázottságúak, nőknél a középkorú diplomások felülreprezentáltak (üres fészek). Első ivás kb. 12 évesen, első kezelés kb. <b>40</b> évesen. Várható élettartam legalább <b>10 évvel</b> rövidebb. Két típus: tizenéves kezdet (deviancia, impulzivitás) és lassú, integrált kezdet."],["Szomatikus szövődmények","Az alkohol kis molekulájú szerves oldószer: minden sejtbe bejut. <b>Bőr</b>: rosacea (borvirág). <b>Máj</b>: zsírmáj, alkoholos hepatitis, cirrhosis, rák. <b>Emésztés</b>: gastritis, fekély, hasnyálmirigy-gyulladás, daganatok. <b>Szív-ér</b>: hipertónia, stroke, kardiomiopátia (mérsékelt fogyasztás csökkentheti az érelmeszesedést). <b>Idegrendszer</b>: opticus neuropátia, polineuropátia, kisagyi ataxia, miopátia. Terhességben alacsony születési súly."],["Nemek, serdülők, család","Nők szervezete kevesebb vizet tartalmaz, ugyanannyi alkoholtól magasabb a véralkoholszint. A nők kisebb mennyiséget, inkább töményet, gyakrabban egyedül, később kezdve isznak; partnerük szokása erősen hat rájuk. A serdülőkor kritikus időszak (agyi, hormonális érés). Az alkoholista család diszfunkcionális, a gyerek azonosul a szülő mintáival. Halálozásban az alkohol vezet a szerek között."]],"qs":[{"t":"mc","q":"Melyik módszer a májcirrózisban elhunytakból becsli az alkoholisták számát?","o":["Jellinek","Ledermann","Prochaska","Weinstein"],"a":0,"e":"A Ledermann-módszer az eladott tiszta szeszből számol."},{"t":"mc","q":"Mire épül a Ledermann-féle becslés?","o":["Az egy főre jutó eladott tiszta alkohol mennyiségére","A májcirrózis okozta halálozásra","Kérdőíves vizsgálatra","A kezelésbe kerültek számára"],"a":0,"e":"Hátránya, hogy az illegális alkoholt nem tartalmazza."},{"t":"tf","q":"Az első alkoholos kezelés átlagosan kb. 40 éves korban történik.","a":true,"e":"Az első ivás viszont kb. 12 évesen."},{"t":"mc","q":"Kik felülreprezentáltak a nők között az alkoholbetegek mintájában?","o":["Magasabb végzettségűek","Alacsony végzettségűek","Fiatal tinédzserek","Falusi lakosok"],"a":0,"e":"Férfiaknál az alacsony iskolázottságúak."},{"t":"match","q":"Párosítsd a szervet a szövődménnyel.","pairs":[["Bőr","Rosacea"],["Máj","Cirrhosis"],["Szem","Opticus neuropátia"],["Kisagy","Ataxia"]],"e":"Az alkohol minden szervet károsíthat."},{"t":"mc","q":"Miért emeli meg ugyanaz az alkoholmennyiség jobban a nők véralkoholszintjét?","o":["Kevesebb a víztartalmuk, több a zsír","Gyorsabb a lebontásuk","Több a vérük","Kevesebbet isznak"],"a":0,"e":"Az alkohol így kevésbé hígul fel."},{"t":"fill","q":"Az alkoholizmus a várható élettartamot legalább ___ évvel rövidíti meg.","a":["10","tíz","10 évvel"],"e":"A forrás szerint minimum 10 évvel."},{"t":"tf","q":"Az alkoholista pályafutás gyorsabb, mint a kemény drogos karrier.","a":false,"e":"Az alkoholista karrier évtizedekig tart, a kemény drogosé rövidebb."}]},{"id":"u11l5","title":"Etiológia és elméletek","theory":[["Modellek, biológia","<b>Modellek</b>: démonikus-szakrális (ókor), <b>morális</b> (erkölcsi bűn), <b>betegségmodell</b> (19. sz.; absztinencia, addiktív identitás, AA), <b>önmedikalizációs</b> (pszichiátriai zavar tünete), <b>szociális</b> (tanulási alesettel), <b>integratív</b> (kettős diagnózis, mindkettő primer). <b>Biológia</b>: első fokú rokonoknál 7-szeres kockázat; egypetéjű ikreknél kétszeres konkordancia; <b>Blum és Comings: jutalomhiányos szindróma</b> (alacsony D2-receptorsűrűség); frontális alulműködés. Nincs specifikus alkoholista személyiség."],["Pszichoanalízis","<b>Korai</b>: orális, regresszív, vágyteljesítő (Abraham, Szondi, Radó); a szuperego és az ego oldódik. <b>Intrapszichikus</b> (Wurmser, Khantzian): öngyógyítás, deficitek kompenzálása – a szer illeszkedik a problémához: ópiát erős érzelmekre, stimuláns ürességre, kokain depresszióra/önértékelésre. <b>Interperszonális</b> (Bálint, Kohut): a szer archaikus tárgy, mindig rendelkezésre áll. <b>Menninger</b>: lassú öngyilkosság."],["Tanuláselmélet","<b>Operáns</b>: pozitív megerősítés = húzás (örömszerzés), negatív = lökés (rossz állapot elkerülése); a végén a normál szintet sem éri el. <b>Klasszikus</b>: ingerek társulnak a szerrel – kondicionált megvonás, sóvárgás, tolerancia. Terápia: averzív kondicionálás (antaethyl/Esperal), kioltás, <b>ingerkontroll</b> a külső triggerekre, készségfejlesztés a belső triggerekre (magány, unalom)."],["Kognitív modell","S-O-R-C: a különbség a gondolkodásban van. Hiedelmek: <b>facilitáló</b> (jó közérzet), <b>megkönnyebbülésre irányuló</b>, <b>szükségletorientált</b> („muszáj”), <b>megengedő</b> („úgyis vacak az életem”), <b>kontrollhiedelmek</b> (kezdetben túlbecsült). Módszerek: szerhasználati napló, előny-hátrány elemzés (4 cella), séma- és maghiedelem-munka."]],"qs":[{"t":"mc","q":"Ki írta le a jutalomhiányos szindrómát?","o":["Blum és Comings","Wurmser és Khantzian","Prochaska és DiClemente","Hollander"],"a":0,"e":"Alacsony dopamin D2-receptorsűrűség, természetes örömök nem elegendők."},{"t":"mc","q":"Hányszoros az alkoholizmus kockázata az alkoholista első fokú rokonainál?","o":["7-szeres","2-szeres","20-szoros","Nincs különbség"],"a":0,"e":"Az egypetéjű ikrek konkordanciája kétszerese a kétpetéjűekének."},{"t":"match","q":"Párosítsd a szerző/elmélet a gondolattal.","pairs":[["Wurmser, Khantzian","Öngyógyítás, kontrollszerzés"],["Bálint","Archaikus tárgy"],["Menninger","Lassú öngyilkosság"],["Abraham","Orális mohóság"]],"e":"Pszichoanalitikus megközelítések."},{"t":"mc","q":"A tanuláselméleti „lökés” mechanizmus lényege:","o":["A rossz állapotból a normál felé juttat","A normálból pozitív állapotba juttat","Ingerkioltás","Modellkövetés"],"a":0,"e":"A „húzás” a normálból a pozitív irányba visz."},{"t":"mc","q":"Melyik hiedelemtípus: „Úgyis vacak az életem”?","o":["Megengedő","Facilitáló","Szükségletorientált","Kontroll"],"a":0,"e":"Megmagyarázza, miért nem tartja vissza az ártalmak tudata."},{"t":"tf","q":"A belső triggerek (pl. magány, unalom) elkerüléssel kezelhetők.","a":false,"e":"Elkerülhetetlenek, ezekre készségfejlesztés kell; a külső triggerekre az ingerkontroll."},{"t":"fill","q":"A betegségmodell szerint a betegben ___ identitást kell kialakítani.","a":["addiktív","addiktiv"],"e":"Tudja, hogy nem képes kontrollt tartani – ez nem hibáztatás."},{"t":"tf","q":"Az integratív modell szerint a szerzavar és a pszichiátriai zavar közül csak az egyik primer.","a":false,"e":"Kettős diagnózis: mindkettő primer probléma, mindkettőt kezelni kell."}]},{"id":"u11l6","title":"Terápia és megelőzés","theory":[["Motiváció, Prochaska","Terápiás nehézség: a szer örömet ad, ambivalens a betegségbelátás. <b>Prochaska–DiClemente</b> (a változás transztheoretikus modellje): fontolgatás előtti, fontolgatás, felkészülés, cselekvés, fenntartás. <b>Miller–Rollnick motivációs interjú</b> (rogersi szemlélet): empátia, vita kerülése, <b>diszkrepancia</b> kialakítása, ellenállás feldolgozása, önbizalom erősítése."],["Rövid intervenció","<b>5A</b>: Ask, Assess, Advise, Assist, Arrange. <b>Szűrő 4 kérdés</b> (egy igen is problémás ivás; a 2. és 4. a kulcs): mérsékelni kellene? bosszantotta a kritika? bűntudat? reggeli ivás? <b>FRAMES</b>: feedback, responsibility, advice, menu, empathy, self-efficacy. Csak a kezdeti szakaszban hatásos, függőnél nem."],["Kezelés menete","Először motiváció, majd <b>detoxifikálás</b> (kórházban, a megvonási tünetek megszűnéséig). Az absztinencia csak lépcső: ekkor a legrosszabb az állapot. Cél: bent tartás, monitorozás, <b>relapszus-prevenció</b>. <b>Lapszus</b> (botlás) ≠ <b>relapszus</b> (visszaesés): a botlás tanulási tapasztalat. <b>Buda Béla</b>: gyógyult, aki nem sóvárog, és akkor sem nyúl a szerhez, ha módja van rá. Gyógyszeres: disulfiram (antaethyl)."],["Iskolák, AA, megelőzés","Nincs minden más felett álló irányzat; legelterjedtebb a kognitív viselkedésterápia. <b>AA</b>: 12 lépés, első: beismerjük, hogy nincs hatalmunk az alkohol felett. <b>Ártalomcsökkentés</b> (1980-as évek, AIDS): tűcsere, metadonfenntartás. Prevenció: <b>primer</b> (felvilágosítás, kínálat csökkentése), <b>szekunder</b> (korai felismerés), <b>tercier</b> (kezelés, rehabilitáció)."]],"qs":[{"t":"mc","q":"Melyik a Prochaska–DiClemente modell első szakasza?","o":["Fontolgatás előtti","Cselekvés","Felkészülés","Fenntartás"],"a":0,"e":"Sorrend: fontolgatás előtti, fontolgatás, felkészülés, cselekvés, fenntartás."},{"t":"match","q":"Párosítsd az 5A elemet a jelentéssel.","pairs":[["Ask","Fogyasztás megkérdezése"],["Assess","Súlyosság, készenlét felmérése"],["Advise","Változtatás tanácsolása"],["Arrange","Utánkövetés"]],"e":"Az Assist: segítés a célkitűzésben."},{"t":"mc","q":"A motivációs interjú melyik alapelve a jelen viselkedés és a céljai közti ellentmondás tudatosítása?","o":["Diszkrepancia kialakítása","Vita kerülése","Empátia","Ellenállás feldolgozása"],"a":0,"e":"A diszkrepancia motiválja a változást."},{"t":"tf","q":"A botlást (lapszust) tanulási tapasztalatként kell átkeretezni.","a":true,"e":"Így a remény és a kontrollhit nem esik szét; a beteget nem küldjük el a terápiából."},{"t":"fill","q":"A terápia első feladata a ___, vagyis a méregtelenítés.","a":["detoxifikálás","detoxifikacio","detoxikálás","detox"],"e":"Utána kezdődik a tényleges kezelés."},{"t":"mc","q":"Buda Béla szerint mikor gyógyult a beteg?","o":["Ha nem sóvárog, és ellenőrzés nélkül sem nyúl a szerhez","Ha egy évig absztinens","Ha kórházból kikerül","Ha nincs megvonási tünete"],"a":0,"e":"Az absztinencia önmagában nem előgyógyulás."},{"t":"mc","q":"Melyik terápia a legelterjedtebb a függőségekben?","o":["Kognitív viselkedésterápia","Pszichoanalízis","Hipnózis","Játékterápia"],"a":0,"e":"Gyakorlatias, a viselkedés megváltoztatására fókuszál."},{"t":"tf","q":"Az ártalomcsökkentés (pl. tűcsere) az AIDS miatt jelent meg az 1980-as években.","a":true,"e":"Megkereső programok, nem a betegnek kell kezelésre mennie."}]},{"id":"u11l7","title":"Viselkedési addikciók, dohányzás","theory":[["Viselkedési addikciók, spektrumok","BNO: F63 (kóros játékszenvedély, pirománia, kleptománia, trichotillománia), F65 parafíliák, F50 evészavarok, F55 nem függőséget okozó szerek abúzusa. DSM-V: internetfüggés kutatási kategória. <b>Hollander</b> impulzív–kompulzív spektruma: <i>impulzív</i> = kockázatkereső, húzás; <i>kompulzív</i> = kockázatkerülő, szorongáscsökkentő, lökés. Közös: a ritualizált, ismétlődő viselkedés gátlásának képtelensége. Buda: a „medikalizáció” elmossa a felelősséget."],["Kóros játékszenvedély","F63.0, tipikus viselkedési addikció (dependencia-kritériumok érvényesek). Élettartam-prevalencia 1,9–3,3%; öngyilkossági gondolat 38%, kísérlet 13–20%, halál 8%. <b>4 fázis</b>: nyerés, vesztés, kétségbeesés, reménytelenség. Típusok: <b>menekülő</b> (nők, idősek), <b>akciókereső</b> (fiatal férfiak), normál problémás. <b>Intermittáló megerősítés</b>, gyors visszajelzés növeli az addiktív potenciált. Kognitív torzítások: játékos tévedése, illuzórikus korreláció, babonás kontroll, szelektív memória. Terápia: szókratészi kérdezés, GA (Gamblers Anonymous)."],["Dohányzás pszichológiája","A dohányzás addikció: biokémiai hatás + tanult magatartás (a nikotin szorongásoldó, a cigaretta kondicionált stresszoldó). Megvonáskor pszichés tünetek (koncentráció, ingerlékenység). Iniciáció serdülőkorban: a cigaretta a felnőtt világ szimbóluma, <b>kortárshatás</b>, <i>best friend</i> effect. Az önbizalom keresztmetszeti vizsgálatban magasabb, longitudinálisan eredetileg alacsonyabb. <b>Weinstein: irreális optimizmus</b> (torz kockázatészlelés: „bármikor abbahagyhatom”). <b>Tomkins</b>: affektuskontroll – pozitív érzések maximalizálása, negatívak minimalizálása."],["Dohányzás népegészségügye","2000-ben kb. 1,22 milliárd dohányos (férfiaknál kb. ötszörös arány, fiatalon kisebb a különbség); ezek ~1 milliárdja fejlődő/átmeneti gazdaságú országban él. WHO 2004: 58,8 millió halálesetből 5,4 millió dohányzással függ össze. Kezdés leggyakrabban 13–14 évesen; minél korábban, annál nehezebb a leszokás. Prevenció: serdülőknél primer, később szekunder/tercier (családorvos szerepe). Dependencia: legalább 1 hónap folyamatos dohányzás, sikertelen leszokási kísérlet."]],"qs":[{"t":"mc","q":"Melyik BNO-csoportba tartozik a kóros játékszenvedély?","o":["F63","F50","F65","F55"],"a":0,"e":"F63.0; F65 a parafíliák, F50 az evészavarok."},{"t":"mc","q":"Mi jellemzi az impulzív véget Hollander spektrumában?","o":["Kockázatkeresés, húzásmechanizmus","Kockázatkerülés, szorongáscsökkentés","Csak kémiai szerek","Megvonási tünetek"],"a":0,"e":"A kompulzív véget a lökés és a szorongáscsökkentés jellemzi."},{"t":"match","q":"Párosítsd a játékos típust a jellemzővel.","pairs":[["Menekülő","Nők, idősek, monoton játékok"],["Akciókereső","Fiatal férfiak, izgalom"],["Normál problémás","Nincs súlyos premorbid zavar"]],"e":"Az akciókereső antiszociálisnak is nevezett."},{"t":"mc","q":"Melyik a játékos karrier helyes sorrendje?","o":["Nyerés, vesztés, kétségbeesés, reménytelenség","Vesztés, nyerés, kétségbeesés, remény","Kétségbeesés, nyerés, vesztés, remény","Nyerés, kétségbeesés, vesztés, remény"],"a":0,"e":"Kezdetben a nyerés pozitív megerősítés."},{"t":"tf","q":"Az intermittáló megerősítés növeli a játék addiktív potenciálját.","a":true,"e":"Magas válaszgyakoriság, ellenáll a kioltásnak."},{"t":"fill","q":"Weinstein szerint a dohányosokat az irreális ___ tartja fenn a szokásban.","a":["optimizmus"],"e":"Torz kockázatészlelés, amely csökkenti a szorongást."},{"t":"mc","q":"Mi a legfontosabb meghatározó a serdülőkori dohányzásban?","o":["Kortárshatás","A szülők foglalkozása","Iskolai végzettség","Az ár"],"a":0,"e":"Az iniciáció többnyire baráti társaságban történik."},{"t":"tf","q":"A WHO 2004-es becslése szerint a halálesetek 5,4 millióját dohányzás okozta.","a":true,"e":"58,8 millió halálesetből."},{"t":"mc","q":"Melyik elmélet szerint maximalizáljuk a pozitív és minimalizáljuk a negatív érzéseket (dohányzás fenntartása)?","o":["Tomkins affektuskontroll","Bálint archaikus tárgy","Hollander spektrum","Ledermann"],"a":0,"e":"A rövid távú hatás megerősít, a kockázat csak hosszú távon jelentkezik."}]}],"color":"#58cc02"},{"id":"u12","title":"Fejlődési zavarok, autizmus","desc":"Pervazív zavarok, beszéd, mozgás","lessons":[{"id":"u12l1","title":"Gyermekkori zavarok: kereteink","theory":[["Mikor beszélünk betegségről?","Gyermekkorban pszichiátriai betegségről akkor beszélünk, ha a <b>viselkedés, érzelem vagy gondolkodás</b> eltérése: tartós (legalább <b>2 hét</b>), elég súlyos ahhoz, hogy megzavarja a mindennapokat, és hátrányos a gyermeknek vagy a gondviselőnek. Figyelembe kell venni a fejlődési szintet és a szociokulturális közeget. A tünetek többsége egy korábbi életszakaszban a fejlődés természetes velejárója."],["Rizikófaktorok a gyermekben","Alacsony IQ (súlyos tanulási zavarral <b>40%-os</b> rizikó), problémás temperamentum, szomatikus betegség (különösen epilepszia), specifikus fejlődészavar (beszéd, kommunikáció), iskolai teljesítményzavar, alacsony önértékelés, nem. A fiúk sérülékenyebbek, náluk gyakoribbak a fejlődési és viselkedési zavarok. A faktorok általában egymást erősítik."],["Családi és külső rizikók","<b>Család</b>: válás, anya pszichiátriai betegsége, apai kriminalitás/alkoholizmus, bántalmazás, szegénység, nyílt szülői konfliktus, ellentmondásos vagy kritikus nevelés. Legkedvezőbb a <b>meleg, de határokat tanító</b> légkör; alulkövetelés = hiányzó megküzdési stratégiák, túlkövetelés = szorongás, depresszió. <b>Külső</b>: rossz iskolai szervezet, bullying, kortárscsoport, média, negatív életesemények."],["Védőfaktorok","<b>Önbizalom, pozitív énkép</b> (az élet első 7–8 évében alakul, utána viszonylag állandó; sok pozitív visszajelzés kell hozzá), <b>stabil temperamentum</b>, <b>jó intelligencia</b>. Az utóbbi kettő segíti az alkalmazkodást a stresszes helyzetekhez."]],"qs":[{"t":"mc","q":"Legalább mennyi ideig tartó eltérés szükséges gyermekkori pszichiátriai betegség megítéléséhez?","o":["2 hét","1 hét","6 hónap","1 év"],"a":0,"e":"A tartósság mellett a súlyosság és a funkcionális károsodás is szempont."},{"t":"tf","q":"Gyermekkori kórkép esetén mindig szokatlan, különleges tünetcsoportra kell gondolni.","a":false,"e":"A legtöbb tünet a fejlődés természetes velejárója vagy átmenetileg minden gyermeknél előfordul."},{"t":"mc","q":"Mekkora a rizikó, ha az alacsony IQ súlyos tanulási zavart okoz?","o":["40%","4%","90%","Nincs többletrizikó"],"a":0,"e":"Az alacsony IQ gyengíti a differenciált megküzdési stratégiák kialakítását."},{"t":"match","q":"Párosítsd a nevelési hibát a következménnyel.","pairs":[["Alulkövetelés","Megküzdési stratégiák hiánya"],["Túlkövetelés","Szorongás, depresszió"],["Kritikus nevelés","Negatív énkép"]],"e":"A legkedvezőbb a meleg, de határokat szabó nevelés."},{"t":"mc","q":"Melyik szomatikus betegség különösen nagy rizikófaktor?","o":["Epilepszia","Hererejtés","Allergia","Fogszuvasodás"],"a":0,"e":"Krónikus betegségeknél halmozódnak az érzelmi és viselkedészavarok, főleg epilepsziánál."},{"t":"mc","q":"Melyik NEM védőfaktor?","o":["Problémás temperamentum","Jó intelligencia","Stabil temperamentum","Pozitív énkép"],"a":0,"e":"A problémás temperamentum rizikófaktor."},{"t":"fill","q":"A pozitív énkép az élet első 7–8 évében alakul, és utána viszonylag ___.","a":["állandó","allando"],"e":"Sok pozitív visszajelzés kell a kialakulásához."},{"t":"tf","q":"A fiúk gyermekkorban sérülékenyebbek, náluk hamarabb kialakul pszichiátriai betegség.","a":true,"e":"Az iskoláskorban gyakoriak a fejlődési zavarok és viselkedési problémák."}]},{"id":"u12l2","title":"Autizmus (F84.0)","theory":[["Pervazív fejlődési zavarok","<b>F84</b>: a reciprok szociális interakciók és a kommunikációs sémák <b>minőségi abnormalitása</b>, amely minden helyzetben meghatározza a működést. <b>Gyermekkori autizmus (F84.0, BNO-10)</b>: abnormális fejlődés <b>3 éves kor előtti</b> kezdettel; 3 terület: <i>reciprok szociális interakció, kommunikáció, korlátozott, ismétlődő, sztereotip viselkedés</i>. Nem specifikus: fóbia, alvás- és táplálkozási zavar, dührohamok, önagresszió."],["DSM-IV kritériumok","Összesen <b>legalább 6</b> tünet: <b>(1) szociális interakció</b> ≥2 (nem verbális viselkedés csökkenése, kortárskapcsolatok hiánya, közös öröm spontán keresésének hiánya, érzelmi kölcsönösség hiánya); <b>(2) kommunikáció</b> ≥1 (beszéd késése/hiánya, beszélgetés kezdeményezésének zavara, sztereotip nyelv, fantáziajáték hiánya); <b>(3) beszűkült, ismétlődő minták</b> ≥1 (sztereotip érdeklődés, rutinokhoz ragaszkodás, motoros manírok, tárgyrészekkel foglalatoskodás). 3 éves kor előtt elmaradás legalább egy területen."],["Gyakoriság és okok","Fiúknál <b>4:1–5:1</b> arányban gyakoribb. Nincs kimutatható specifikus biológiai ok. Idegrendszeri eltérések: fennmaradó primitív reflexek, EEG-eltérések, gyakran epilepszia, pre- és perinatális rizikók. <b>Genetikai</b> tényezőre utal a halmozódás és a fiúk gyakoribb érintettsége. Biokémia: kb. <b>egyharmadnál magasabb a szerotoninszint</b> a vérben. A szülők depressziója és szorongása <b>következmény</b>, nem ok."]],"qs":[{"t":"mc","q":"Mely életkor előtt kezdődik a gyermekkori autizmus (BNO-10)?","o":["3 éves","1 éves","5 éves","7 éves"],"a":0,"e":"Az atípusos autizmus ennél később kezdődik, vagy nem teljesül mindhárom terület."},{"t":"mc","q":"Melyik NEM az autizmus három tünetterületének egyike?","o":["Szorongás","Szociális interakció","Kommunikáció","Sztereotip, ismétlődő viselkedés"],"a":0,"e":"A szorongás, fóbia, dührohamok nem specifikus kísérő tünetek."},{"t":"tf","q":"A DSM-IV szerint legalább 6 tünet kell, ebből legalább 2 a szociális interakció területéről.","a":true,"e":"Továbbá legalább 1-1 a kommunikációból és az ismétlődő mintákból."},{"t":"mc","q":"Milyen a fiú:lány arány autizmusban?","o":["4:1–5:1","1:1","1:3","10:1"],"a":0,"e":"Genetikai ok felé mutat a fiúk gyakoribb érintettsége."},{"t":"fill","q":"Az autisztikus gyermekek kb. egyharmadánál magasabb a vér ___szintje.","a":["szerotonin","szerotonin-"],"e":"Jelentősége tisztázatlan."},{"t":"tf","q":"Az autisztikus gyermekek szüleinek depressziója az autizmus oka.","a":false,"e":"A szülők depressziója és szorongása következmény: a gyermektől nem kapnak pozitív választ."},{"t":"match","q":"Párosítsd a tünetet a területtel.","pairs":[["Rutinokhoz ragaszkodás","Ismétlődő minták"],["Fantáziajáték hiánya","Kommunikáció"],["Kortárskapcsolatok hiánya","Szociális interakció"]],"e":"A DSM-IV három tünetcsoportot ír le."}]},{"id":"u12l3","title":"Autizmus-rokon zavarok","theory":[["Rett-szindróma (F84.2)","<b>Csak lányokon</b>. Normális fejlődés után (BNO: 7–24. hó) a beszéd, motoros készségek, célirányos kézhasználat leépül; lassul a fejkörfogat-növekedés. Sztereotip kézmozgások (rázó, mosó, a testközépvonalra szimmetrikus, kéz benyálazása), lihegés/hiperventilláció, 4 éves kor körül törzsataxia, apraxia. Majdnem mindig súlyos mentális retardáció. A szociális érdeklődés megtartott; 4–5 éves kor után a differenciáldiagnózis az autizmustól nem nehéz."],["Dezintegratív zavar (F84.3)","<b>Teljesen normális fejlődés</b> (DSM: legalább 2 évig), majd pár hónap alatt a megszerzett készségek elvesznek (DSM: 10. életév előtt, legalább 2 területen: beszéd, szociális/adaptív viselkedés, <b>hólyag- és végbélkontroll</b>, játék, motorika). Autisztikus abnormalitások, sztereotip manírok. Más nevei: Heller-szindróma, dezintegratív pszichózis. Néha neurológiai háttér (pl. kanyaró-encephalitis), ezért az állapotot ismételt neurológiai vizsgálat kíséri."],["Atípusos autizmus, F84.4","<b>Atípusos autizmus (F84.1)</b>: a kezdet 3 éves kor után, vagy nem teljesül mind a három kritériumcsoport; gyakori súlyos retardációban és súlyos receptív nyelvi zavarban. <b>F84.4</b>: súlyos mentális retardáció (IQ 50 alatt) + hiperaktivitás + sztereotip mozgás; a stimulánsok nem hatnak, <b>diszfóriát</b> okozhatnak."],["Asperger-szindróma (F84.5)","Az autizmus szociális és érdeklődési abnormalitásai, de <b>nincs nyelvi vagy kognitív fejlődési késés</b> (DSM: 2 éves korig egyszerű szavak, 3 éves korig kommunikatív kifejezések). Gyakori az ügyetlenség. Enyhébb tünetek, kevésbé beszűkült érdeklődés, későbbi felismerés, jobb prognózis; az abnormalitás serdülő- vagy felnőttkorig fennmarad."]],"qs":[{"t":"mc","q":"Melyik zavar fordul elő csak lányokon?","o":["Rett-szindróma","Asperger-szindróma","Dezintegratív zavar","Atípusos autizmus"],"a":0,"e":"Normális fejlődés után a célirányos kézhasználat és a beszéd leépül."},{"t":"mc","q":"Mi különbözteti meg alapvetően az Asperger-szindrómát az autizmustól?","o":["Nincs nyelvi vagy kognitív fejlődési késés","Későbbi életkori kezdet","Nincs szociális probléma","Csak fiúknál fordul elő"],"a":0,"e":"A szociális és érdeklődési abnormalitás megvan."},{"t":"match","q":"Párosítsd a zavart a jellemzőjével.","pairs":[["Rett-szindróma","Kézmosó/rázó sztereotípia"],["Heller-szindróma","Hólyagkontroll elvesztése"],["Asperger","Ép nyelvi fejlődés"],["F84.4","IQ 50 alatt, hiperaktivitás"]],"e":"Mindegyik az F84 csoport tagja."},{"t":"tf","q":"A dezintegratív zavarban a gyermek legalább 2 évig látszólag normálisan fejlődik.","a":true,"e":"Utána vész el a készségek egy része (DSM: 10. életév előtt)."},{"t":"mc","q":"Mi jellemzi az F84.4 kórképben a stimulánsok hatását?","o":["Nem hatnak, diszfóriát okozhatnak","Nagyon hatásosak","Csak szorongást oldanak","Altatnak"],"a":0,"e":"Ellentétben a normál IQ-jú hiperkinetikus gyerekekkel."},{"t":"fill","q":"Rett-szindrómában a fejkörfogat növekedése ___.","a":["lelassul","lassul","elmarad","lelassúl"],"e":"Ezzel együtt a beszéd és a kézhasználat leépül."},{"t":"tf","q":"Az atípusos autizmus kezdete 3 éves kor előtti.","a":false,"e":"Vagy 3 év utáni a kezdet, vagy nem teljesül mindhárom kritériumcsoport."},{"t":"mc","q":"Mikor könnyű a Rett-szindróma elkülönítése az autizmustól?","o":["4–5 éves kor után","1 éves korban","Csecsemőkorban","Soha"],"a":0,"e":"Tipegő/óvodás korban a Rett-szindrómás gyermek is mutathat autisztikus vonásokat."}]},{"id":"u12l4","title":"A pervazív zavarok kezelése","theory":[["Oktatás és család","<b>Speciális oktatás</b> a legfontosabb: jól strukturált program, a gyermek egyéni szükségleteivel számolva. <b>Családtámogatás</b>: önsegítő csoportok, alapítványok; segíteni kell a szülőket a csalódottság és félelmek feldolgozásában, tudatosítani, hogy az ambivalens érzések természetesek."],["Specifikus és viselkedéses kezelés","Beszédterápia, foglalkoztató terápia, idősebbeknél pszichoterápia, a kommunikáció facilitációja; jobban működőknél egyéni verbális pszichoterápia és szociális készségfejlesztő tréningcsoport. <b>Viselkedésterápia</b>: klasszikus és operáns kondicionálás, <b>órarend</b> az idő strukturálására, a szociálisan pozitív viselkedés megerősítése (pl. a kézfogás megtanítása)."],["Gyógyszeres kezelés","Ma nincs olyan gyógyszer, amely az autizmus <b>alapvető tüneteit</b> befolyásolná. A <b>haloperidol</b> csökkenti a sztereotípiákat és az agresszív dührohamokat, a súlyos viselkedészavarok kezelésében a leghatékonyabbnak tűnik, de az extrapiramidális mellékhatások (diszkinézia, disztónia) jelentősek."]],"qs":[{"t":"mc","q":"Melyik a legfontosabb kezelési elem az autisztikus gyermek fejlesztésében?","o":["Speciális, strukturált oktatás","Altatók","Pszichoanalízis","Szülő nélküli nevelés"],"a":0,"e":"Az oktatási program legyen jól strukturált és egyénre szabott."},{"t":"tf","q":"Van gyógyszer, amely az autizmus alapvető tüneteit megszünteti.","a":false,"e":"A gyógyszeres lelkesedés csökkent; nincs ilyen szer."},{"t":"mc","q":"Mire hatásos a haloperidol autizmusban?","o":["Sztereotípiákra és agresszív dührohamokra","A beszédfejlődésre","A szociális kölcsönösségre","A tanulásra"],"a":0,"e":"Mellékhatás: extrapiramidális tünetek (diszkinézia, disztónia)."},{"t":"match","q":"Párosítsd a módszert a céllal.","pairs":[["Órarend","Az idő strukturálása"],["Operáns megerősítés","Szociálisan pozitív viselkedés"],["Szociális készségtréning","Jobban működők csoportja"],["Családi önsegítő csoport","Szülők támogatása"]],"e":"A kezelés sokrétű, egyénre szabott."},{"t":"fill","q":"A szülőknek meg kell tanulniuk, hogy a gyermekkel kapcsolatos ___ érzéseik természetesek.","a":["ambivalens"],"e":"A családtámogatás része."},{"t":"tf","q":"Az autizmus kezelésében a klasszikus és operáns kondicionálásnak nincs szerepe.","a":false,"e":"Jelentős szerepük van a viselkedés fejlesztésében."}]},{"id":"u12l5","title":"Beszéd, mozgás, iskolai teljesítmény","theory":[["Dadogás és hadarás","<b>Dadogás (F98.5)</b>: a beszéd ritmikus áramlását hangok, szótagok, szavak gyakori ismétlése vagy elnyújtása, tétovázás, szünetek szakítják meg; csak akkor zavar, ha jelentősen rontja a folyamatosságot. <b>Hadarás (F98.6)</b>: nagyon gyors, szabálytalan, löketszerű beszéd, a folyamatosság megszakad, de <b>nincs ismétlés és tétova szünet</b>; annyira súlyos, hogy rontja a beszéd érthetőségét, hibás szerkezetek jelennek meg."],["Sztereotip mozgászavar (F98.4)","Akaratlagos, ismétlődő, sztereotip, nem funkcionális és gyakran ritmusos mozgások, amelyek nem részei pszichiátriai vagy neurológiai zavarnak. <b>Nem önveszélyes</b>: fej vagy test ringatása, hajhúzás, kézrázás, ujjtördelő manírok. <b>Önveszélyes</b>: ismételt fejbeverés, arcpofozás, szemnyomás, harapdálás. Leggyakrabban mentális retardációban. Nem ide tartozik: tic, trichotillománia, körömrágás."],["Fejlődés és iskolai teljesítmény","A specifikus fejlődészavarok (beszéd, kommunikáció) és az <b>iskolai teljesítményzavar</b> rizikófaktorok a pszichiátriai zavarokra. Hiperkinetikus gyerekeknél gyakori a nyelvi és motoros fejlődés késése és a kognitív működés zavara; impulzivitásuk miatt hibás, befejezetlen a házi feladat. Az <b>alacsony intelligencia és a tanulási részképesség-zavarok</b> növelik a magatartászavar valószínűségét. Sok elmarasztalás alacsony önértékeléshez, negatív énképhez vezet."]],"qs":[{"t":"mc","q":"Melyik beszédzavarra jellemző a gyors, löketszerű beszéd ismétlések és tétova szünetek nélkül?","o":["Hadarás","Dadogás","Elektív mutizmus","Tic"],"a":0,"e":"A hadarás F98.6; a dadogás F98.5."},{"t":"mc","q":"Mi jellemzi a dadogást?","o":["Hangok, szótagok, szavak ismétlése vagy elnyújtása","Beszédképtelenség bizonyos helyzetekben","Gyors beszéd ismétlés nélkül","Kényszeres szóhasználat"],"a":0,"e":"Csak akkor zavar, ha jelentősen rontja a beszéd folyamatosságát."},{"t":"match","q":"Párosítsd a mozgást a csoporttal.","pairs":[["Fej ringatása","Nem önveszélyes"],["Ismételt fejbeverés","Önveszélyes"],["Tic","Nem ide tartozik"]],"e":"Az F98.4 sztereotip mozgászavar leggyakrabban mentális retardációban fordul elő."},{"t":"tf","q":"A sztereotip mozgászavar diagnózisa akkor is adható, ha a mozgás más pszichiátriai zavar tünete.","a":false,"e":"Ilyenkor csak a meglévő zavart kell diagnosztizálni."},{"t":"mc","q":"Mit növel az alacsony intelligencia és a tanulási részképesség-zavar?","o":["A magatartászavar valószínűségét","A védőfaktorokat","A hadarást","A tic gyakoriságát"],"a":0,"e":"Több más faktoron keresztül."},{"t":"fill","q":"Hiperkinetikus gyerekeknél gyakori a nyelvi és ___ fejlődés késése.","a":["motoros"],"e":"Emellett a kognitív működés zavara is gyakori."},{"t":"tf","q":"A tic a sztereotip mozgászavar (F98.4) kizáró diagnózisa.","a":true,"e":"A tic, a trichotillománia és a körömrágás nem tartozik ide."}]}],"color":"#1cb0f6"},{"id":"u13","title":"Viselkedés- és érzelmi zavarok","desc":"ADHD, magatartás, tic, ürítés","lessons":[{"id":"u13l1","title":"ADHD: kritériumok és okok","theory":[["Hiperkinetikus zavar (F90)","Az élet korai szakaszában (általában az első 5 évben) kialakuló zavarcsoport: a kognitív részvételt igénylő tevékenységekben <b>kitartás hiánya</b>, csapongás, rendezetlen, túlzott aktivitás. A gyerekek nyughatatlanok, impulzívak, balesetre hajlamosak, szociális gátlásaik hiányoznak, ezért népszerűtlenek, elszigeteltek lehetnek. Másodlagos szövődmény: aszociális viselkedés, csökkent önértékelés."],["DSM-IV kritériumok","<b>A1 figyelmetlenség</b>: legalább 6 a 9-ből; <b>A2 hiperaktivitás–impulzivitás</b>: legalább 6 a 9-ből (a–f hiperaktivitás, g–i impulzivitás); a tünetek legalább <b>6 hónapja</b> fennállnak. Kezdet <b>7 éves kor előtt</b>, károsodás legalább <b>2 helyzetben</b> (pl. iskola és otthon). Altípusok: <b>kombinált</b> (A1 és A2), <b>főleg figyelemhiányos</b> (csak A1), <b>főleg hiperaktív-impulzív</b> (csak A2)."],["Okok","<b>Genetikai</b> komponens nagy; fiúknál sokkal gyakoribb (lányoknál korábban tartják kórosnak a viselkedést); a szülőknél, főleg az apánál homológ terheltség. Régebben organikus okokat feltételeztek (vírus-encephalitis, frontális lebeny sérülése, nehézfémmérgezés; „minimális cerebrális diszfunkció”). A perinatális rizikó nem gyakoribb, mint más pszichiátriai zavaroknál; az anyáknál terhesség alatt gyakoribb volt az erős dohányzás és a hányás."]],"qs":[{"t":"mc","q":"Legalább hány tünet szükséges a DSM-IV szerint a figyelmetlenség (A1) kritériumához?","o":["6 a 9-ből","3 a 9-ből","9 a 9-ből","2 a 4-ből"],"a":0,"e":"A tünetek legalább 6 hónapja fennállnak."},{"t":"mc","q":"Melyik az ADHD kombinált altípusa?","o":["A1 és A2 kritériumok is teljesülnek","Csak A1","Csak A2","Egyik sem"],"a":0,"e":"Főleg figyelemhiányos: csak A1; főleg hiperaktív-impulzív: csak A2."},{"t":"tf","q":"A DSM-IV szerint a tüneteknek legalább két helyzetben (pl. iskola és otthon) funkciózavart kell okozniuk.","a":true,"e":"Kezdet a 7. életév előtt."},{"t":"fill","q":"A DSM-IV szerint a tünetek megjelenése a ___. életév előtt szükséges.","a":["7","hetedik","7."],"e":"A hetedik életév előtti kezdet kritérium."},{"t":"mc","q":"Melyik nemben gyakoribb az ADHD?","o":["Fiúk","Lányok","Egyenlő","Csak serdülő lányok"],"a":0,"e":"Lányoknál a hiperkinetikus viselkedést korábban tartják kórosnak."},{"t":"tf","q":"A perinatális rizikófaktorok gyakoribbak ADHD-ban, mint más pszichiátriai zavarokban.","a":false,"e":"Nem gyakoribbak; az anyáknál a terhesség alatt az erős dohányzás és a hányás volt gyakoribb."},{"t":"match","q":"Párosítsd a megfelelő tünetet a csoporttal.","pairs":[["Elveszti a feladathoz szükséges dolgokat","Figyelmetlenség"],["Fészkelődik az ülésen","Hiperaktivitás"],["Kimondja a választ a kérdés vége előtt","Impulzivitás"]],"e":"A hiperaktivitás a–f, az impulzivitás g–i tünetek."}]},{"id":"u13l2","title":"ADHD: klinikai kép és kezelés","theory":[["Életkori megjelenés","<b>Csecsemő</b>: alvás- és étkezési zavar, irritabilitás, sírás; mászáskor extrém balesetveszély. <b>Tipegő/óvodás</b>: mindig rohan, céltalan aktivitás, rosszul koordinált; impulzív (kirohan az utcára, nem reagál dicséretre-büntetésre); csekély kitartás. <b>Iskoláskor</b>: nyugtalan, elhagyja a helyét, impulzivitás miatt hibás házi feladat, veszélyes tettek (magas tetőn sétál). <b>Serdülőkor</b>: a nagymotoros hiperaktivitás csökken, <b>kisizmokra tevődik át</b>, nem „nő ki” belőle; az impulzivitás gyakran az „osztály bohóca” szerepben jelenik meg."],["Viselkedésterápia","A kezelésbe a gyermeket, a szülőt és a tanárt is be kell vonni. <b>Kontingencia-program</b> (operáns kondicionálás): megerősítőkkel fejleszti a viselkedés-szabályozást, koncentrációt; folyamatos adagolást igényel, ezért idő- és személyigényes. <b>Szukcesszív megközelítés</b> (goal-attainment): kis, elérhető lépések. Iskoláskorban hatékony az <b>öninstrukciós tréning</b>."],["Gyógyszeres kezelés","Leggyakrabban a <b>methylphenidat</b> (Ritalin) stimuláns. Mellékhatás: elalvási zavarok, idegesség, aspecifikus tünetek; <b>5 év alatt</b> meg kell fontolni a kezdést. Súlyos mentális retardációval járó F84.4-ben a stimulánsok nem hatnak."]],"qs":[{"t":"mc","q":"Hogyan változik a hiperaktivitás serdülőkorban?","o":["A kisizmokra tevődik át, de nem tűnik el","Teljesen megszűnik","Fokozódik a nagymotoros aktivitás","Csak lányoknál marad"],"a":0,"e":"Sokan tévesen hiszik, hogy kinőhető."},{"t":"match","q":"Párosítsd az életkort a jellemzővel.","pairs":[["Csecsemőkor","Alvás- és étkezési zavar, sírás"],["Óvodáskor","Céltalan rohangálás, balesetek"],["Iskoláskor","Hibás, befejezetlen házi feladat"],["Serdülőkor","Kisizmok hiperaktivitása"]],"e":"A tünetek életkoronként más formában jelennek meg."},{"t":"mc","q":"Mi a kontingencia-program lényege?","o":["Operáns megerősítők a viselkedés szabályozására","Gyógyszer","Játékterápia","Büntetés"],"a":0,"e":"Folyamatos megerősítést igényel, ezért idő- és személyigényes."},{"t":"tf","q":"Az öninstrukciós tréning iskoláskorban különösen hatékony kognitív módszer.","a":true,"e":"A kognitív terápia a lelki és szociális konfliktusok megoldását segíti."},{"t":"fill","q":"A leggyakrabban alkalmazott gyógyszer ADHD-ban a ___ (Ritalin).","a":["methylphenidat","metilfenidát","methylphenidát","metilfenidat"],"e":"Mellékhatásai: elalvási zavar, idegesség."},{"t":"mc","q":"Mi a goal-attainment (szukcesszív megközelítés) lényege?","o":["A célt kis, elérhető lépésekkel közelítik meg","Egyszerre kitűzött nagy cél","Büntetés","Elkerülés"],"a":0,"e":"Ha az egyszerűbb teljesül, jöhetnek a nehezebb feladatok."},{"t":"tf","q":"Az impulzivitás gyakran az osztály bohócának szerepében jelenik meg.","a":true,"e":"Impulzív kiszólások, durva tréfák, gyakran tényleges kárral."}]},{"id":"u13l3","title":"Magatartászavar (F91)","theory":[["Definíció, BNO","Visszatérő és tartós <b>disszociális, agresszív vagy dacos</b> magatartás, amely durván áthágja a kornak megfelelő elvárásokat. Izolált disszociális cselekmény nem elég; nem javasolt a diagnózis, ha a zavar kevesebb mint <b>6 hónapja</b> áll fenn. Példák: extrém harciasság, kegyetlenkedés emberekkel/állatokkal, rombolás, gyújtogatás, lopás, hazudozás, iskolakerülés, elszökés. Kizáró: szkizofrénia, mánia, pervazív zavar, hiperkinetikus zavar, depresszió. Egy része felnőttkori disszociális személyiségzavarba torkollhat."],["DSM-IV kritériumok","A visszatérő minta, amelyben mások jogait vagy a szociális normákat megszegik: <b>legalább 3</b> kritérium az elmúlt <b>1 évben</b> és <b>legalább 1</b> az elmúlt 6 hónapban. Csoportok: <b>agresszió emberek/állatok ellen</b>, <b>vagyonrongálás</b>, <b>csalás vagy lopás</b>, <b>súlyos szabálysértés</b> (13 éves kor előtt éjszakai kimaradás, iskolakerülés, elszökés). Típus: <b>gyermekkori kezdet</b> (10 éves kor előtt) vagy serdülőkori; súlyosság: enyhe, mérsékelt, súlyos."],["Etiológia","Nincs egyetlen ok, bio-pszicho-szociális stresszorok. <b>Külső</b>: szociális depriváció, szülői felügyelet hiánya, szülői betegség, erős testi fenyítés, <b>média</b> (jutalmazott agresszió utánzása, érzéketlenné tevő hatás); az agresszív szülők gyermekeinél a modelltanulás és az <b>agresszorral való azonosulás</b> magyaráz. A rossz családi élet fontosabb a csonka családnál. <b>Belső</b>: fiúk, nehéz temperamentum (difficult baby), kötődési zavar, limbikus eltérések; gyenge szuperego, empátiahiány; elhárítás: tagadás, externalizáció. Gyakori kísérő: hiperkinetikus zavar és depresszió."],["Lefolyás és kezelés","Egyharmaduk felnőttként is súlyos alkalmazkodási zavarokat mutat. Jó prognózis: kitartó szülői támogatás, jó intellektuális és szociális készségek, jó kortárskapcsolatok. Kezelés: komplex (pszichiátriai, jogi, szociális, iskolai, családi); a feltáró terápiánál hatékonyabb a <b>kognitív viselkedésterápia és a szociális tréning</b>, a <b>szülőtréning</b> és a családterápia. Gyógyszer a társult zavarokra; a neuroleptikumok csökkentik az agressziót."]],"qs":[{"t":"mc","q":"Legalább mennyi ideig kell fennállnia a zavarnak a BNO szerint a magatartászavar diagnózisához?","o":["6 hónap","2 hét","1 hónap","3 év"],"a":0,"e":"Izolált disszociális cselekmény önmagában nem elég."},{"t":"tf","q":"A DSM-IV szerint legalább 3 kritérium kell az elmúlt 1 évben és legalább 1 az elmúlt 6 hónapban.","a":true,"e":"Négy csoportból: agresszió, rongálás, csalás/lopás, szabálysértés."},{"t":"mc","q":"Mi a gyermekkori kezdetű magatartászavar határa a DSM-IV szerint?","o":["10 éves kor előtt","5 éves kor előtt","13 éves kor előtt","18 éves kor előtt"],"a":0,"e":"Ha 10 éves kor előtt nincs jellegzetes zavar, serdülőkori kezdetű."},{"t":"mc","q":"Melyik hatékonyabb magatartászavarban a feltáró egyéni terápiánál?","o":["Kognitív viselkedésterápia és szociális tréning","Hipnózis","Kizárólag gyógyszer","Pszichoanalízis"],"a":0,"e":"Mellette szülőtréning és családterápia is fontos."},{"t":"match","q":"Párosítsd a faktort a csoporttal.","pairs":[["Nehéz temperamentum","Belső"],["Erős testi fenyítés","Külső"],["Agresszorral azonosulás","Nevelési hatás"],["Empátiahiány","Pszichológiai"]],"e":"A magatartászavar nem vezethető vissza egyetlen okra."},{"t":"tf","q":"A csonka család erősebben korrelál az antiszociális viselkedéssel, mint a rossz családi élet.","a":false,"e":"A rossz családi élet, feszültségek, verekedések fontosabbak."},{"t":"fill","q":"A magatartászavarok egy része felnőttkorban disszociális ___zavarba torkollhat.","a":["személyiség","személyiségzavar"],"e":"Ezért is fontos a korai ellátás."},{"t":"tf","q":"A magatartászavar jól elkülöníthető a hiperaktív zavartól, mert nincs közöttük átfedés.","a":false,"e":"Az emocionális zavartól jól elkülöníthető, a hiperaktívtól kevésbé: sok az átfedés."}]},{"id":"u13l4","title":"Altípusok, oppozíciós zavar, F92","theory":[["F91.0 és F91.1","<b>F91.0 családi körre korlátozódó</b>: disszociális, agresszív viselkedés csaknem teljesen az otthonra korlátozódik (szökés, pénzlopás is kell); gyakran kistestvér születésekor alakul ki; prognózisa jobb. <b>F91.1 nem szocializált</b> (kortárscsoportba nem beilleszkedő): átható kortárskapcsolati zavar (izoláció, elutasítottság, nincs közeli barát), emocionális zavar gyakori, legkifejezettebb az iskolában."],["F91.2 és F91.3","<b>F91.2 szocializált</b>: a kortárscsoportba jól beilleszkedett egyén tartós disszociális viselkedése; tartós barátságok, a csoport helyesli (csoportos lopás, garázdálkodás, iskolakerülés); az emocionális zavar elhanyagolható. <b>F91.3 oppozíciós (kihívó) zavar</b>: tartósan negativisztikus, ellenséges, provokatív, dacos viselkedés, jellemzően <b>9–10 éves kor alatt</b>; <b>nincs</b> törvénybe ütköző cselekmény (lopás, zaklatás, rombolás)."],["Oppozíciós zavar DSM-IV","Negatív, ellenséges, dacos viselkedés legalább <b>6 hónapig</b>, és legalább <b>4</b> a 8-ból: gyakori önuralomvesztés, vitatkozás felnőttekkel, aktív szembeszállás, szándékos bosszantás, mások hibáztatása, sértődékenység, düh, bosszúállás. Alacsony frusztrációtűrés, jellemzően a jól ismert felnőttekkel szemben."],["F92: kevert zavarok","<b>F92.0 depressziós magatartászavar</b>: magatartászavar + tartós depresszív hangulat (extrém boldogtalanság, érdeklődés elvesztése, önvád, reménytelenség, alvás- és étvágyzavar). <b>F92.8</b>: magatartászavar + markáns emocionális tünetek (szorongás, kényszerek, deperszonalizáció, fóbiák, hipochondriázis). A düh és gyűlölet inkább a magatartászavar része."]],"qs":[{"t":"mc","q":"Melyik zavar jellemzője a kortárscsoportba jól beilleszkedett egyén tartós disszociális viselkedése?","o":["F91.2 szocializált","F91.1 nem szocializált","F91.0 családi körre korlátozódó","F91.3 oppozíciós"],"a":0,"e":"Az elkülönítés kulcsa a tartós kortársbarátságok."},{"t":"match","q":"Párosítsd a kódot a zavarral.","pairs":[["F91.0","Családi körre korlátozódó"],["F91.1","Kortárscsoportba nem beilleszkedő"],["F91.2","Kortárscsoportba beilleszkedő"],["F91.3","Oppozíciós zavar"]],"e":"Az F91.3-nál nincs törvénybe ütköző cselekmény."},{"t":"tf","q":"Oppozíciós zavarban jellemzőek a lopások és a rombolás.","a":false,"e":"Éppen ez különbözteti meg a többi magatartászavartól."},{"t":"mc","q":"Legalább hány tünet kell a DSM-IV oppozíciós zavarhoz a 8-ból?","o":["4","2","6","8"],"a":0,"e":"A viselkedés legalább 6 hónapig áll fenn."},{"t":"fill","q":"Az F92.0 a magatartászavar tartós ___ hangulattal kombinálódva.","a":["depressziós","deprimált","depresszív"],"e":"Extrém boldogtalanság, reménytelenség, alvászavar."},{"t":"mc","q":"Melyik zavar alakul ki gyakran kistestvér születésekor és jobb a prognózisa?","o":["F91.0 családi körre korlátozódó","F91.1","F91.2","F92.8"],"a":0,"e":"Nozológiai érvényessége bizonytalan."},{"t":"tf","q":"A F92.8-ban a düh és a gyűlölet inkább az emocionális zavar része.","a":false,"e":"Inkább a magatartászavar részei, és meglétük nem erősíti meg és nem zárja ki a diagnózist."}]},{"id":"u13l5","title":"Emocionális és szocializációs zavarok","theory":[["F93: emocionális zavarok","A normális fejlődés eltúlzott formái. <b>Szeparációs szorongás (F93.0)</b>: a szeretett személytől (többnyire anyától) való elválástól félelem, leggyakrabban 6–11 évesen, iskolától való távolmaradás formájában; fiúknál és lányoknál egyformán (3,5–5,4%); a szülő gyakran szorongó, megerősíti. Kezelés: kognitív viselkedésterápia – a szülőnek meg kell értenie a szerepét, fokozatos szeparációs helyzetek, jutalmazás; átmenetileg gyógyszer."],["Fóbiás szorongás, iskolafóbia","<b>F93.1</b>: életkori félelmek eltúlzott formája (2 éves korig idegen inger; 3 év körül állatok, sötétség, szellemek, fertőzés). <b>Iskolafóbia</b>: fokozatos kezdet, testi panaszok (hasi fájdalom, fejfájás), leggyakrabban korai serdülőkorban; hátterében érzelmi problémák, önbizalomhiány, nagy függőségi igény. Terápia: egyéni pszichoterápia + családterápia. <b>F93.2</b> szociális szorongás: idegenekkel szembeni túlzott bizalmatlanság. <b>F93.3 testvér-rivalizáció</b>: regresszió (enuresis, encopresis), alvászavar, indulatkitörés, visszahúzódás."],["F94: szocializáció zavarai","A közös abnormalitás a szociális működésben; súlyos környezeti zavar vagy depresszió szerepe feltételezett. <b>F94.0 elektív (szelektív) mutizmus</b>: egyes helyzetekben jól beszél, másokban nem; DSM: legalább 1 hónap, nem csak az iskolakezdés első hónapja, nem nyelvhiány miatt. 10 000 gyerekből 2–5, többségük lány; <b>97%-ban szociális fóbia</b>; nem dac; kezelés: logopédiai és pszichológiai, kényszerítés ront."],["Kötődési zavarok","<b>F94.1 reaktív kötődési zavar</b>: az első 5 évben kezdődik, szülői elhanyagolás, abúzus, súlyos félrenevelés következménye; testi gyarapodás lassulása, szegényes mimika, visszahúzódás, agresszió vagy apátia. <b>F94.2 diszinhibíciós (gátlástalan) kötődési zavar</b>: diffúz, válogatás nélküli barátságosság, felszínes kortárskapcsolatok; intézeti szindróma."]],"qs":[{"t":"mc","q":"Melyik életkorban a leggyakoribb a szeparációs szorongás?","o":["6–11 év","0–1 év","15–18 év","Felnőttkor"],"a":0,"e":"Gyakran az iskolától való félelemként jelentkezik."},{"t":"tf","q":"A szeparációs szorongás fiúknál gyakoribb, mint lányoknál.","a":false,"e":"Egyforma arányban (3,5–5,4%) fordul elő."},{"t":"mc","q":"Mi jellemzi az iskolafóbiát?","o":["Fokozatos kezdet, testi panaszok","Hirtelen elnémulás","Rombolás","Hólyagkontroll elvesztése"],"a":0,"e":"Hasi fájdalom, hasmenés, fejfájás; hátterében érzelmi problémák."},{"t":"mc","q":"Hány százalékban társul szociális fóbia szelektív mutizmushoz?","o":["97%","10%","50%","Soha"],"a":0,"e":"A mutizmus ritka: 10 000 gyerekből 2–5."},{"t":"match","q":"Párosítsd a kódot a zavarral.","pairs":[["F93.0","Szeparációs szorongás"],["F93.3","Testvér-rivalizáció"],["F94.0","Elektív mutizmus"],["F94.1","Reaktív kötődési zavar"]],"e":"F93 emocionális, F94 szocializációs zavarok."},{"t":"tf","q":"A szelektív mutista gyerek dacból hallgat.","a":false,"e":"Valójában kevésbé hajlamosak ellenkezésre; szorongás áll a háttérben."},{"t":"mc","q":"Melyik zavarra jellemző a válogatás nélküli, felszínes barátságosság?","o":["F94.2 diszinhibíciós kötődési zavar","F94.1 reaktív kötődési zavar","F93.2","F94.0"],"a":0,"e":"A reaktív zavar a szülői elhanyagolás következménye, visszahúzódással, apátiával."},{"t":"fill","q":"Az F94.1 az élet első ___ évében kezdődik.","a":["5","öt","ötödik"],"e":"Elhanyagolás, abúzus, félrenevelés következménye."}]},{"id":"u13l6","title":"Tic és ürítési zavarok","theory":[["Tic (F95)","A tic <b>önkéntelen, gyors, visszatérő, nem ritmusos</b> motoros mozgás vagy hang, hirtelen kezdődik, céltalan; rövid időre elnyomható, a stressz fokozza, <b>alvás megszünteti</b>. Egyszerű motoros: szemhunyorítás, nyakhajlítás, vállemelés, grimaszolás. Egyszerű vokális: torokköszörülés, köhögés, szipákolás. Komplex vokális: obszcén szavak (<b>coprolalia</b>, a Tourette-esetek kb. 30%-ában). Elhúzódó (2 hónapnál tovább tartó) tic: szakvizsgálat."],["Típusok, okok","<b>F95.0 átmeneti</b>: legfeljebb 12 hónap. <b>F95.1 krónikus motoros vagy vokális</b>: egyik a kettőből (sosem mindkettő), több mint 1 év. <b>F95.2 Gilles de la Tourette</b>: több motoros és legalább 1 vokális tic együtt; serdülőkorban rosszabbodik. Kezdet 21 éves kor előtt; átlagosan 7 évesen. A krónikus tic gyakorisága &gt;4%, Tourette &lt;1%. A Tourette örökletes, egygénes zavar. Tourette-ben gyakoribb a figyelemzavar (10×), alkalmazkodási zavar (17×), pánik (13×), depresszió (11×). Kezelés: támogató tájékoztatás, <b>viselkedésterápia</b>; nehéz esetben haloperidol, pimozid."],["Enuresis (F98.0)","Ismételt akaratlan bevizelés legalább heti 1 alkalommal, 5 éves kor után, nem szervi okból; éjszakai (nocturna) vagy nappali (diurna). <b>Primer</b>: sosem volt tiszta időszak; <b>szekunder</b>: előtte legalább 6 hónapig szobatiszta volt. Fiúknál kétszer gyakoribb. Háttér: szülői túlzott szigor, anális regresszió (figyelemkérés), elfojtott harag, kistestvér születése; Hermann: „gúnyos azonosítás”. Kezelés: viselkedésterápia (ébresztéses módszer, hólyagtréning); a gyermeket büntetni nem szabad."],["Encopresis és egyéb F98","<b>Encopresis (F98.1)</b>: nem megfelelő helyen székelés, mindig nappal; ritkább és súlyosabb, mint az enuresis. Típusok: <b>manipulatív szennyezés</b>, <b>krónikus hasmenés</b>, <b>krónikus székrekedés</b> (visszatartás). Kezelés: gyermekpszichoterápia (rajz, játék), családterápia, viselkedés- és relaxációs terápia. Egyéb F98: táplálási zavar és rumináció (F98.2), pica – nem élelmiszer evése (F98.3), körömrágás, ujjszopás, orrpiszkálás (F98.8)."]],"qs":[{"t":"mc","q":"Mi jellemzi a ticet?","o":["Önkéntelen, gyors, nem ritmusos mozgás vagy hang","Ritmikus, akaratlagos sztereotípia","Mindig szervi eredetű","Alvásban fokozódik"],"a":0,"e":"A tic alvásban megszűnik, stressz fokozza."},{"t":"match","q":"Párosítsd a kódot a tic típusával.","pairs":[["F95.0","Átmeneti, legfeljebb 12 hónap"],["F95.1","Krónikus motoros vagy vokális"],["F95.2","Tourette-szindróma"]],"e":"A krónikus tic és Tourette hátterét azonosnak gondolják."},{"t":"mc","q":"Mi jellemzi a Tourette-szindrómát?","o":["Több motoros és legalább 1 vokális tic","Csak vokális tic","Csak egy motoros tic","Átmeneti tic"],"a":0,"e":"A tünetek 21 éves kor előtt kezdődnek."},{"t":"tf","q":"A coprolalia a Tourette-szindrómások kb. 30%-ánál fordul elő.","a":true,"e":"Obszcén szavak váratlan kirobbanása."},{"t":"mc","q":"Melyik a legjobb eredményt adó pszichoterápia ticeknél?","o":["Viselkedésterápia","Pszichoanalízis","Hipnózis","Pszichodráma"],"a":0,"e":"Mellette a tájékoztatás és a tanácsadás nélkülözhetetlen."},{"t":"match","q":"Párosítsd a zavart a definícióval.","pairs":[["Primer enuresis","Soha nem volt tiszta időszak"],["Szekunder enuresis","Előtte min. 6 hónapig szobatiszta"],["Encopresis","Mindig nappalra korlátozódik"]],"e":"Az enuresis fiúknál kétszer gyakoribb."},{"t":"tf","q":"Enuresis esetén a szülőnek szigorúan meg kell büntetnie a gyermeket.","a":false,"e":"Nem szabad megbüntetni, megalázni; a viselkedésterápiák általában eredményesek."},{"t":"fill","q":"Az encopresis típusai: manipulatív szennyezés, krónikus hasmenés és krónikus ___.","a":["székrekedés","szekrekedes","székrekedés (visszatartás)"],"e":"A visszatartásnál nő a bélelzáródás veszélye."},{"t":"mc","q":"Mit jelent a pica?","o":["Nem élelmiszer rendszeres evése","Ételmegtagadás","Ismételt felbüfögés","Körömrágás"],"a":0,"e":"A rumináció a táplálék ismételt felbüfögése."}]}],"color":"#ce82ff"},{"id":"u14","title":"Pszichotikus és hangulatzavarok","desc":"Szkizofrénia, depresszió, mánia, bipoláris zavar","lessons":[{"id":"u14l1","title":"Osztályozás, pszichózis","theory":[["BNO és DSM","<b>BNO-10</b>: WHO adja ki, leíró jellegű, az F-fejezet a mentális és viselkedészavarok. <b>DSM</b> (APA, első kiadás 1952): explicit, operacionális kritériumok, ateoretikus, nő a reliabilitás. A DSM-III (1980) törölte a neurózis kategóriát. A BNO és a DSM 90-95%-ban egymásra fordítható."],["Az F-fejezet","F0 organikus; F1 pszichoaktív szerek; <b>F2 pszichotikus zavarok</b>; <b>F3 hangulatzavarok</b>; F4 neurotikus, stresszhez társuló és szomatoform; F5 fiziológiai zavarok; F6 személyiségzavarok; F7 mentális retardáció; F8-9 gyermekkori zavarok."],["DSM tengelyek, pszichózis","DSM-III/IV 5 tengely: I. klinikai zavarok; II. személyiségzavar és mentális retardáció; III. szomatikus betegségek; IV. pszichoszociális stresszorok (1-6); V. működés (GAF, 1-100).<br><b>Pszichózis</b>: elvész a realitáskontroll; tünetei a téveszme, hallucináció, súlyosan dezorganizált viselkedés és beszéd. Előtte ki kell zárni a testi és a szer okozta pszichózist."]],"qs":[{"t":"mc","q":"Melyik kód jelöli a hangulatzavarokat a BNO-ban?","o":["F3","F2","F4","F6"],"a":0,"e":"F2 pszichotikus, F3 hangulatzavarok, F4 neurotikus, F6 személyiségzavarok."},{"t":"mc","q":"Melyik rendszer kiadója az APA?","o":["DSM","BNO-10","Csak a BNO-8","Egyik sem"],"a":0,"e":"A DSM-et az Amerikai Pszichiátriai Társaság adja ki, a BNO-t a WHO."},{"t":"tf","q":"A DSM-III (1980) törölte a neurózis kategóriát.","a":true,"e":"Utódkategóriák: szorongásos, szomatoform, disszociatív zavarok, neurotikus személyiségzavarok."},{"t":"mc","q":"A DSM melyik tengelyén szerepel a személyiségzavar?","o":["II. tengely","I. tengely","III. tengely","V. tengely"],"a":0,"e":"A II. tengelyen: személyiségzavar és mentális retardáció (korán kezdődő, tartós zavarok)."},{"t":"fill","q":"A GAF-skála a működés átfogó értékelése, ___ pontos skálán.","a":["100","0-100","1-100"],"e":"1-100 (0-100) pont, az V. tengelyen."},{"t":"match","q":"Párosítsd a kódot a zavarcsoporttal.","pairs":[["F2","pszichotikus zavarok"],["F3","hangulatzavarok"],["F6","személyiségzavarok"],["F7","mentális retardáció"]],"e":"BNO-10 F-fejezet."},{"t":"mc","q":"Mi a pszichotikus tünet?","o":["Téveszme","Fóbia","Kényszergondolat","Pánikroham"],"a":0,"e":"Pszichotikus tünet: téveszme, hallucináció, dezorganizált viselkedés/beszéd."},{"t":"tf","q":"Pszichózisban a realitáskontroll ép marad.","a":false,"e":"Épp ez különbözteti meg a neurózistól: a pszichózisban elvész."}]},{"id":"u14l2","title":"Szkizofrénia: története, tünetei","theory":[["Epidemiológia, történet","Az átlagnépesség kb. <b>1%</b>-át érinti, fiatalon kezdődik; férfiaknál korábban, több negatív tünettel, rosszabb prognózissal. Társuló: öngyilkosság (1/3 kísérli meg), alkohol (30-50%), drog, depresszió.<br><b>Kraepelin</b> (1896): dementia praecox, a kórlefolyás a lényeg. <b>Bleuler</b> (1911): szkizofrénia, a gondolkodás és érzelem hasadtsága. <b>Schneider</b> (1959): elsőrangú tünetek."],["Bleuler 4A","Alapvető tünetek: <b>asszociációs zavar</b> (fellazult, inkoherens gondolkodás, neologizmus), <b>affektív zavar</b> (elsivárosodás, inkongruens érzelem), <b>ambivalencia</b>, <b>autizmus</b> (visszahúzódás). A járulékos tünetek: téveszme, hallucináció, katatón tünetek (ma: pozitív tünetek)."],["Pozitív és negatív tünetek","<b>Crow és Andreasen</b>: pozitív (többlet) tünetek: téveszme, hallucináció, formai gondolkodászavar, bizarr viselkedés; akut fázis, dopamin-hiperfunkció. <b>Negatív</b> (hiány) tünetek: apátia, abulia, anhedónia, alógia, érzelmi elsivárodás, szociális visszahúzódás; frontális atrófia, dopamin-hipofunkció."],["Schneider-féle elsőrangú tünetek","11 tünet, nagy diagnosztikai erővel: hangok (gondolatecho, párbeszédes, kommentáló), gondolatelvonás, -betétel, -szétáradás, befolyásoltatásos élmények (érzés, késztetés, cselekvés), szomatikus passzivitás-élmény, téves jelentéstulajdonítás (tévpercepció)."]],"qs":[{"t":"mc","q":"Ki vezette be a szkizofrénia fogalmát 1911-ben?","o":["Bleuler","Kraepelin","Schneider","Crow"],"a":0,"e":"Bleuler: hasadtelméjűség; Kraepelin: dementia praecox."},{"t":"mc","q":"Melyik NEM tartozik a Bleuler-féle 4A-hoz?","o":["Anhedónia","Asszociációs zavar","Ambivalencia","Autizmus"],"a":0,"e":"4A: asszociáció, affektus, ambivalencia, autizmus."},{"t":"tf","q":"Kraepelinnél a diagnózis alapja a kórlefolyás volt.","a":true,"e":"Korai kezdet, progresszió, tartós dementia; Bleulernél a tünet számít."},{"t":"match","q":"Párosítsd a szerzőt a hozzájárulással.","pairs":[["Kraepelin","dementia praecox"],["Bleuler","4A alaptünetek"],["Schneider","elsőrangú tünetek"],["Crow és Andreasen","pozitív/negatív tünetek"]],"e":"A szkizofrénia fogalmának története."},{"t":"mc","q":"Melyik negatív tünet?","o":["Abulia (akaratnélküliség)","Hallucináció","Téveszme","Inkoherens beszéd"],"a":0,"e":"A negatív tünetek hiánytünetek: abulia, apátia, anhedónia, alógia."},{"t":"mc","q":"Melyik neurotranszmitter-eltérés áll a pozitív tünetek hátterében?","o":["Dopamin-hiperfunkció (limbikus)","Dopamin-hipofunkció","Szerotoninhiány","GABA-többlet"],"a":0,"e":"Pozitív tünetek: dopamin-hiperfunkció; negatív: hipofunkció, frontális zavar."},{"t":"fill","q":"A szkizofréniában az átlagnépesség kb. ___ százalékát érinti.","a":["1","egy"],"e":"Prevalencia kb. 1%."},{"t":"tf","q":"Szkizofréniában az öngyilkossági kísérlet a betegek kb. harmadánál előfordul.","a":true,"e":"Társuló zavarok: öngyilkosság, alkohol, drog, depresszió."}]},{"id":"u14l3","title":"Szkizofrénia: kritériumok, típusok","theory":[["DSM-IV kritériumok","<b>A</b>: 2 vagy több, 1 hónapig: téveszme, hallucináció, inkoherens beszéd, szétesett/katatón viselkedés, negatív tünetek (1 elég, ha bizarr téveszme vagy kommentáló/párbeszédes hang). <b>B</b>: szociális/foglalkozási károsodás. <b>C</b>: legalább <b>6 hónap</b> (ebből 1 hónap aktív szak). Szkizoaffektív, hangulat-, szer- és testi eredetet ki kell zárni."],["Kórlefolyás","Premorbid személyiség, prodróma, akut fázis (schub, pozitív tünetek), remisszió, relapszus, kompenzált állapot (negatív tünetek). 1 éven belül 41% kerül újra kórházba, gyógyszerelhagyásnál 70%. Reziduális forma: korábban volt akut epizód, most nincs pozitív tünet."],["Alcsoportok (F20.x)","<b>Paranoid</b> (F20.0): üldöztetéses/nagyzásos téveszme, hanghallás, késői kezdet, legjobb prognózis. <b>Hebefrén</b> (F20.1): inkoherens beszéd, inadekvát érzelem, legkoraibb kezdet (15-25 év), legrosszabb prognózis. <b>Katatón</b> (F20.2): stupor, viaszhajlékonyság, negativizmus, mutizmus, echolália/echopraxia. <b>Simplex</b> (F20.6): csak negatív tünetek, lassú leépülés. Szkizofreniform zavar: 1-6 hónap."]],"qs":[{"t":"mc","q":"Legalább mennyi ideig kell fennállnia a zavar jeleinek a DSM-IV szerint?","o":["6 hónap","1 hét","2 hét","1 év"],"a":0,"e":"Ebből legalább 1 hónap aktív szak (A kritérium)."},{"t":"mc","q":"Melyik típus prognózisa a legjobb?","o":["Paranoid","Hebefrén","Simplex","Katatón"],"a":0,"e":"A paranoidé a legjobb, a hebefrénia és simplex a legrosszabb."},{"t":"mc","q":"Melyik altípusra jellemző a viaszhajlékonyság?","o":["Katatón","Paranoid","Simplex","Hebefrén"],"a":0,"e":"Katatón: katalepszia, flexibilitas cerea, stupor, negativizmus."},{"t":"mc","q":"Melyik altípus kezdődik a legkorábban (15-25 év)?","o":["Hebefrénia","Paranoid","Katatón","Reziduális"],"a":0,"e":"A hebefrénia a legkoraibb, legszétesettebb forma."},{"t":"match","q":"Párosítsd a típust a jellemzővel.","pairs":[["Paranoid","üldöztetéses téveszme, hangok"],["Hebefrén","inadekvát érzelem, szétesettség"],["Katatón","stupor, negativizmus"],["Simplex","csak negatív tünetek"]],"e":"F20.0-F20.6 típusok."},{"t":"tf","q":"A szkizofreniform zavarnál a tünetek 1-6 hónapig állnak fenn.","a":true,"e":"Hat hónap felett szkizofréniát diagnosztizálunk."},{"t":"tf","q":"Szkizofrénia diagnózisához nem kell pszichotikus tünet.","a":false,"e":"Ma legalább egy pozitív (pszichotikus) tünet szükséges; ha nincs, az szkizotípiás zavar."},{"t":"fill","q":"Az akut fázist ___ néven is nevezzük (német szó).","a":["schub","sub"],"e":"Schub: a pozitív tünetek dominálnak."}]},{"id":"u14l4","title":"Szkizofrénia: etiológia, kezelés","theory":[["Biológiai okok","Nem pszichogén. Poligénes öröklődés: monozigóta ikreknél kb. 67%, dizigótáknál kb. 15% konkordancia; örökbefogadásnál a biológiai rokonság számít. <b>Dopamin-hipotézis</b>: mezolimbikus-mezokortikális (pozitív tünetek), nigrostriatális (mozgás), tuberoinfundibuláris (prolaktin). Frontális atrófia, megnagyobbodott kamrák. Neurodevelopmentális modell: szinapszis túlprodukció és hibás visszametszés; pre- és perinatális ártalmak, anyai influenza a 2. trimeszterben."],["Pszichológiai elméletek","Freud: autoerotizmus, dekatexis. <b>Federn</b>: énhatárok gyengesége. <b>Klein</b>: paranoid-szkizoid pozíció. <b>Mahler</b>: autisztikus/szimbiotikus fázisban reked. Kernberg: self-tárgy differenciálás sikertelen. Családi: <b>Bateson double-bind</b>, Fromm-Reichmann szkizofrenogén anya, <b>kifejezett érzelmek (EE)</b> a visszaesés kockázata."],["Kezelés","Elsődleges a <b>farmakoterápia</b> (neuroleptikum): akut fázisban típusos, fenntartásként atípusos; depot készítmény a nem szedés ellen. Mellékhatások: akatízia, akut disztónia, okulogyriás krízis, parkinsonos tünetek, tardív diszkinézia. Pszichoszociális: pszichoedukáció (családnak is), készségfejlesztés, szocioterápiás csoportok; redukált célok."]],"qs":[{"t":"mc","q":"Mekkora a monozigóta ikrek konkordanciája szkizofréniában a jegyzet szerint?","o":["kb. 67%","kb. 15%","kb. 5%","100%"],"a":0,"e":"Dizigótáknál kb. 15%."},{"t":"mc","q":"Ki írta le a double-bind elméletet?","o":["Bateson","Federn","Mahler","Kohut"],"a":0,"e":"Bateson: kettős kötés a családi kommunikációban."},{"t":"mc","q":"Melyik dopaminpálya felel a pozitív tünetekért?","o":["Mezolimbikus","Nigrostriatális","Tuberoinfundibuláris","Frontális GABA"],"a":0,"e":"A nigrostriatális a mozgásért, a tuberoinfundibuláris a prolaktinért felel."},{"t":"match","q":"Párosítsd a mellékhatást a leírással.","pairs":[["Akatízia","mozgáskényszer, nyugtalanság"],["Akut disztónia","kóros izomtónus-fokozódás"],["Tardív diszkinézia","késői akaratlan szájmozgások"],["Parkinsonos tünet","remegés, rigiditás"]],"e":"Extrapiramidális mellékhatások."},{"t":"mc","q":"Mit jelent az EE (kifejezett érzelmek)?","o":["Magas érzelemkifejezés a családban, visszaesési kockázat","Betegnél az érzelmek hiánya","Pozitív megerősítés","Terápiás technika"],"a":0,"e":"Braun és Rapter-féle kifejezett érzelmek."},{"t":"tf","q":"Szkizofréniában a pszichoterápiával gyógyítani lehet.","a":false,"e":"Elsődleges a farmakoterápia; a pszichoszociális kezelés segítő, redukált célú."},{"t":"tf","q":"Depot készítmény a gyógyszer elhagyása ellen használható.","a":true,"e":"Pl. havi egy injekció."},{"t":"fill","q":"Federn szerint a pszichózis lényege a deficites ___ .","a":["énhatár","énhatárok","enhatar","enhatarok"],"e":"Federn: külső-belső énhatárok gyengesége."}]},{"id":"u14l5","title":"Egyéb pszichotikus zavarok","theory":[["Szkizotípiás zavar (F21)","Személyiségzavar a szkizofrénia spektrumban: különc viselkedés, gondolkodás és affektus anomáliái, hideg érzelmek, szociális visszahúzódás, mágikus/misztikus tartalmak. Szkizofrén hozzátartozók körében gyakoribb. Nincsenek valódi pszichotikus tünetek, legfeljebb átmeneti epizódok."],["Paranoid és akut zavarok","<b>Perzisztáló deluzív zavar (F22)</b>: rendszerezett, <b>nem bizarr</b> téveszme legalább 1 hónapig; a szkizofrénia A-kritériuma nem teljesül. Altípusok: erotomániás, grandiózus, féltékenységi, perzekutoros, szomatikus, kevert. Etiológia: Freud látens homoszexualitás, Cameron paranoid pszeudoközösség.<br><b>Akut és átmeneti pszichotikus zavar (F23)</b>: hirtelen kezdet (2 hét), 1 nap-1 hónap, stresszre adott válasz, teljes visszatérés a korábbi szintre."],["Szkizoaffektív zavar (F25)","A szkizofrénia és a hangulatzavar tünetei együtt: mániás (F25.0), depressziós (F25.1) vagy kevert (F25.2) típus."]],"qs":[{"t":"mc","q":"Melyik zavarra jellemző a nem bizarr téveszme?","o":["Deluzív (paranoid) zavar","Hebefrénia","Szkizotípiás zavar","Akut pszichózis"],"a":0,"e":"F22: rendszerezett, nem bizarr téveszmék."},{"t":"mc","q":"Mennyi ideig áll fenn az akut és átmeneti pszichotikus zavar?","o":["1 nap és 1 hónap között","6 hónap","1 év","Élethossziglan"],"a":0,"e":"Hirtelen kezdet, stresszre adott válasz, teljes gyógyulás."},{"t":"match","q":"Párosítsd az altípust a témával.","pairs":[["Erotomániás","a beteg iránt szerelmes személy"],["Grandiózus","nagyzásos, különleges képesség"],["Féltékenységi","a partner hűtlen"],["Szomatikus","testi betegség vagy fogyatékosság"]],"e":"A téveszmés zavar altípusai."},{"t":"mc","q":"Melyik kód a szkizoaffektív zavaré?","o":["F25","F21","F22","F23"],"a":0,"e":"F21 szkizotípiás, F22 deluzív, F23 akut."},{"t":"tf","q":"A szkizotípiás zavart a szkizofrénia spektrumhoz sorolják.","a":true,"e":"Bár személyiségzavar, a genetikai kapcsolat miatt."},{"t":"tf","q":"Az akut pszichotikus zavar után a személy nem tér vissza a korábbi szintre.","a":false,"e":"Mindig visszatér a korábbi funkcionális szintre."},{"t":"fill","q":"A szkizoaffektív zavarnak mániás, depressziós és ___ típusa van.","a":["kevert"],"e":"F25.0, F25.1, F25.2."},{"t":"mc","q":"Cameron szerint mi segíti a paranoid zavar kialakulását?","o":["Paranoid pszeudoközösség","Hasítás","Orális fixáció","Tanult tehetetlenség"],"a":0,"e":"Cameron: hét fajta kedvező helyzet, pl. szociális izoláció."}]},{"id":"u14l6","title":"Hangulatzavarok: alapok, etiológia","theory":[["Hangulatzavarok, epidemiológia","F30 mániás epizód; F31 bipoláris; F32 depressziós epizód; F33 ismétlődő depresszió; F34 perzisztáló hangulatzavar. Élettartam-prevalencia <b>8,3-24,2%</b>, nőknél <b>2-3x</b> gyakoribb. Kezdet a 20-30-as években. Genetika: bipoláris zavarnál a monozigóta konkordancia 74-90%, unipolárisnál 43-50%."],["Etiológiai típusok","<b>Szomatogén</b> (testi ok), <b>endogén</b> (belső, kiváltó ok nélkül, vegetatív jegyek, gyógyszerre jól reagál), <b>pszichogén</b> (veszteség, trauma; gyermekkori gyökerek), <b>reaktív</b> (aktuális ok, krízis). A stresszor precipitáló, nem oki szerepű."],["Pszichodinamikus elméletek","<b>Freud</b> (1917, Gyász és melankólia): az elveszett, ambivalensen szeretett tárgy introjekciója, befelé fordított agresszió, szigorú felettes én; orális-szadisztikus fixáció. <b>Abraham</b>: elfojtott, önmaga ellen fordított gyűlölet. <b>Bibring</b>: önértékelés összeomlása. <b>Klein</b>: a depresszív pozíció; mánia = elhárítás. <b>Arieti</b>: domináns másik. <b>Kohut</b>: nárcisztikus hiány. <b>Blatt</b>: anaklitikus és introjektív típus."],["Viselkedéses és kognitív elméletek","<b>Lewinsohn</b>: szociális készséghiány, kevés pozitív megerősítés. <b>Seligman</b>: tanult tehetetlenség; depressziós attribúciós stílus: belső, globális, stabil. <b>Beck</b>: kognitív triád (én, világ, jövő), kognitív torzítások (túláltalánosítás, perszonalizáció, katasztrofizálás). Biológia: monoamin-hipotézis (szerotonin, noradrenalin), HPA-tengely kortizol-emelkedés, rövidebb REM-latencia."]],"qs":[{"t":"mc","q":"Hányszor gyakoribb a hangulatzavar nőknél?","o":["2-3-szor","10-szer","Egyenlő","Fele annyi"],"a":0,"e":"Gyermekkorban a nemek között nincs különbség."},{"t":"mc","q":"Ki írta a Gyász és melankólia című művet (1917)?","o":["Freud","Beck","Seligman","Klein"],"a":0,"e":"Freud a melankóliát az introjektált tárgy elleni agresszióval magyarázta."},{"t":"match","q":"Párosítsd a szerzőt az elmélettel.","pairs":[["Beck","kognitív triád"],["Seligman","tanult tehetetlenség"],["Lewinsohn","szociális készséghiány"],["Bibring","önértékelés összeomlása"]],"e":"Depresszióelméletek."},{"t":"mc","q":"Mi a depressziós attribúciós stílus?","o":["Belső, globális, stabil okok negatív eseményre","Külső, specifikus, átmeneti okok","Csak külső okok","Csak pozitív események értékelése"],"a":0,"e":"Pl. „én mindent elrontok és ez már így is marad”."},{"t":"mc","q":"Mit jelent a Beck-féle kognitív triád?","o":["Negatív kép önmagáról, a világról és a jövőről","Három gyógyszer","Három terápiás ülés","Szorongás, düh, bűntudat"],"a":0,"e":"Az én, a világ és a jövő negatív szemlélete."},{"t":"tf","q":"Depresszióban rövidebb a REM-latencia.","a":true,"e":"Hamarabb álmodik, az első REM fázis hosszabb."},{"t":"tf","q":"A stresszor az endogén depresszió kiváltó oka.","a":false,"e":"Az endogén depresszió kiváltó ok nélkül indul; a stresszor precipitáló szerepű."},{"t":"fill","q":"A depresszió monoamin-hipotézise szerint csökkent ___ aktivitás áll a háttérben (a kiemelt transzmitter).","a":["szerotonin"],"e":"Később a szerotoninnak tulajdonítottak kiemelt jelentőséget."}]},{"id":"u14l7","title":"Depresszió, mánia, bipoláris, terápia","theory":[["Depressziós epizód","Alaptünetek: csökkent érdeklődés/örömképesség, negatív gondolkodás, energiacsökkenés. DSM-IV: <b>5 vagy több</b> tünet <b>2 hétig</b>, közte levert hangulat vagy az érdeklődés elvesztése. Fokozatok: enyhe (2-3 tünet), mérsékelt (4+), súlyos pszichotikus tünetek nélkül/azokkal. Differenciáldiagnózis: gyász (nincs tartós önleértékelés). Hangulatzavarban 5-15% hal meg öngyilkosságban; legkritikusabb a javulás szakasza."],["Mánia és bipoláris zavar","<b>Mánia</b> (DSM-IV): emelkedett, expanzív vagy irritált hangulat legalább <b>1 hétig</b>, 3+ tünet: nagyzás, csökkent alvásigény, beszédkényszer, gondolatrohanás, disztraktibilitás, fokozott aktivitás, kockázatos tevékenység. <b>Hipománia</b>: legalább 4 nap. <b>Bipoláris I</b>: depresszió + teljes mánia; <b>II</b>: depresszió + hipománia. Rapid ciklus: 4+ epizód/12 hónap. F33: legalább 2 depressziós epizód; F34: ciklotímia, disztímia (2 év)."],["Terápia","Depresszió: antidepresszívum (SSRI), pszichoterápia: szupportív, pszichodinamikus (empátia, nem vigasztalás), <b>kognitív viselkedésterápia</b> (20-25 ülés, gondolatnapló, viselkedésaktiváció), interperszonális, pár- és családterápia; fényterápia (szezonális), alvásmegvonás, <b>ECT</b> (súlyos, rezisztens). Mánia: <b>lítium</b> első vonalban, antipszichotikum, karbamazepin, valproát; fenntartó kezelés."]],"qs":[{"t":"mc","q":"Hány tünet kell a major depresszív epizódhoz (DSM-IV)?","o":["5 vagy több, 2 hétig","2, 1 hétig","9, 1 hónapig","3, 2 évig"],"a":0,"e":"Legalább az egyik a levert hangulat vagy az érdeklődésvesztés."},{"t":"mc","q":"Legalább mennyi ideig tart a mániás epizód a DSM-IV szerint?","o":["1 hét","4 nap","2 hét","1 hónap"],"a":0,"e":"A hipománia legalább 4 nap."},{"t":"mc","q":"Melyik a mánia első vonalbeli gyógyszere?","o":["Lítium-karbonát","SSRI","Benzodiazepin","Placebo"],"a":0,"e":"Alternatíva: karbamazepin, valproát."},{"t":"match","q":"Párosítsd a zavart a jellemzővel.","pairs":[["Bipoláris I","depresszió + teljes mánia"],["Bipoláris II","depresszió + hipománia"],["Ciklotímia","2 éven át enyhe hipomán/depresszív tünet"],["Disztímia","tartósan enyhe depresszív hangulat 2 éve"]],"e":"F31, F34."},{"t":"tf","q":"A mániás fázis végén nő az öngyilkosság veszélye.","a":true,"e":"Amikor a beteg bűnbánóvá válik; a kevert epizód is magas kockázat."},{"t":"tf","q":"A kognitív terápia a depresszióban a negatív automatikus gondolatok módosítására irányul.","a":true,"e":"Gondolatnapló, viselkedésaktiváció, 20-25 ülés."},{"t":"mc","q":"Mikor javallt az ECT?","o":["Súlyos, pszichotikus vagy gyógyszer-rezisztens depresszió","Enyhe szomorúság","Minden depresszió","Fóbia"],"a":0,"e":"Mániában is hatékony, ha lítium nem adható."},{"t":"fill","q":"A rapid ciklus legalább ___ epizódot jelent 12 hónapon belül.","a":["4","négy","negy"],"e":"DSM-IV kritérium."}]}],"color":"#ff9600"},{"id":"u15","title":"Szorongás, szomatoform, disszoc.","desc":"Fóbiák, OCD, PTSD, szomatizáció, konverzió","lessons":[{"id":"u15l1","title":"Neurózis és szorongás","theory":[["Neurózis fogalma","BNO-9 szerint: lelki eredetű, funkcionális zavar, <b>ép realitáskontroll</b>, én-idegen (egodiszton) tünetek, belátás, megtartott szociális funkciók; nem antiszociális, nem átmeneti. DSM-III utódkategóriái: szorongásos, szomatoform, disszociatív zavarok; a karakterneurózis a személyiségzavarokhoz (F6) került. BNO F4: F40 fóbiák, F41 pánik/GAD, F42 OCD, F43 stressz, F44 disszociatív, F45 szomatoform."],["Pszichodinamikus értelmezés","Öt fogalom: intrapszichikus konfliktus (tudattalan), fixáció, regresszió, elhárítás, tünet mint kompromisszum. A neurózis <b>reaktualizált fejlődési konfliktus</b>. Fixáció: ödipális (libidó), anális (agresszió), orális (depresszió). Fóbia és hisztéria: ödipális fázis; kényszer: anális fázis. <b>Freud</b>: pszichoneurózisok (fóbia, konverzió, kényszer), aktuálneurózisok (szorongásos neurózis, neuraszténia), nárcisztikus neurózisok (pszichózisok, hipochondria)."],["A szorongás","A szorongás hiánya is kóros; kóros, ha túlméretezett, indokolatlan, funkcióromlást okoz. Jelei: testi (vegetatív, motoros), szubjektív, viselkedéses, kognitív szint. Pszichodinamikus hierarchia: felettes-én szorongás (bűntudat), kasztrációs, szeretetvesztés, szeparációs, paranoid, dezintegrációs szorongás (a legkorábbi, pszichotikus)."]],"qs":[{"t":"mc","q":"Mi különbözteti meg a neurózist a pszichózistól?","o":["Ép realitáskontroll","Szervi ok","Téveszme","Hallucináció"],"a":0,"e":"A neurotikus tünetei én-idegenek, a realitáskontroll ép."},{"t":"mc","q":"Melyik fázishoz köti a pszichodinamikus felfogás a kényszert?","o":["Anális","Orális","Ödipális","Látencia"],"a":0,"e":"Orális: depresszió; ödipális: fóbia, hisztéria."},{"t":"tf","q":"A neurózist a DSM-III törölte, tünetek szerint utódkategóriákra bontva.","a":true,"e":"Szorongásos, szomatoform, disszociatív zavarok."},{"t":"match","q":"Párosítsd az elhárító/fixációs pontot.","pairs":[["Orális fixáció","depresszió"],["Anális fixáció","kényszer"],["Ödipális fixáció","fóbia, hisztéria"]],"e":"Pszichodinamikus neurózistípusok."},{"t":"mc","q":"Mi a tünet a pszichodinamikus felfogás szerint?","o":["Kompromisszum a késztetés és a tiltás között","Tudatos döntés","Genetikai hiba","Szimuláció"],"a":0,"e":"A tünet kompromisszumképződmény."},{"t":"mc","q":"Melyik a legkorábbi, pszichotikus szintű szorongás?","o":["Dezintegrációs szorongás","Bűntudat","Kasztrációs szorongás","Szeparációs szorongás"],"a":0,"e":"A felettes-én szorongás a legérettebb."},{"t":"fill","q":"A neurózis a pszichodinamikus nézet szerint reaktualizált ___ konfliktus.","a":["fejlődési","fejlodesi"],"e":"Regresszió a fixáció pontjára."},{"t":"tf","q":"Freud az aktuálneurózisokhoz sorolta a neuraszténiát és a szorongásos neurózist.","a":true,"e":"Nincs gyermekkori intrapszichikus konfliktus, hanem szexuális kielégítetlenség."}]},{"id":"u15l2","title":"Pánikzavar","theory":[["Pánikroham és pánikzavar","<b>Pánikroham</b> (DSM-IV): váratlan, intenzív félelem; legalább <b>4 tünet</b> hirtelen alakul ki, max. intenzitás <b>10 percen</b> belül: palpitáció, izzadás, remegés, légszomj, mellkasi fájdalom, hányinger, szédülés, derealizáció/deperszonalizáció, megőrüléstől és halálfélelem, paresztézia, hidegrázás. <b>Pánikzavar</b>: visszatérő pánikrohamok + legalább 1 hónapig tartós aggódás a következő roham miatt. Nőknél gyakoribb. Szövődmény: alkohol, gyógyszerfüggés, depresszió, agorafóbia."],["Etiológia","Genetika (családi halmozódás), pánikot kiváltó szerek (koffein, CO2). <b>Kognitív modell</b>: a testi jelek katasztrofizáló értelmezése, ördögi kör; hiperventiláció (CO2 csökken, lúgos pH, szédülés). Pszichodinamikus: Freud aktuálneurózis; <b>Kulcsár Zsuzsa</b>: nincs önmegnyugtató kapacitás; <b>Mentzos</b>: a self elvesztésétől való félelem, szeparációs szorongás; regresszív reszomatizáció."],["Terápia","Kognitív: normalizáló értelmezés, pszichoedukáció. Viselkedésterápia: interoceptív expozíció (pl. futás, léggömbfújás), in vivo expozíció, pániknapló (önmonitorozás), öninstrukció, relaxáció, légzéstréning. Pszichodinamikus: mentalizáció, biztonságot nyújtó tárgy. Gyógyszer: antidepresszánsok a rohamok ellen, rohamok között benzodiazepinek."]],"qs":[{"t":"mc","q":"Hány perc alatt éri el maximumát a pánikroham?","o":["10","60","30 másodperc","24 óra"],"a":0,"e":"Legalább 4 tünet hirtelen fejlődik ki."},{"t":"mc","q":"Pánikzavarhoz legalább mennyi ideig tartó aggódás kell a roham után?","o":["1 hónap","1 hét","6 hónap","2 év"],"a":0,"e":"DSM-IV: tartós aggódás újabb rohamoktól legalább egy hónapig."},{"t":"tf","q":"A pánikroham tipikusan kiszámítható, azonosítható kiváltó okú.","a":false,"e":"Váratlan, nincs azonosítható kiváltó ok; ez különbözteti meg a fóbiától."},{"t":"mc","q":"Mi történik hiperventillációkor?","o":["CO2 szint csökken, lúgos pH","CO2 emelkedik","Oxigén csökken","Vérnyomás nem változik"],"a":0,"e":"Agyi erek összehúzódnak, szédülés."},{"t":"match","q":"Párosítsd a szerzőt az értelmezéssel.","pairs":[["Kulcsár Zsuzsa","hiányzó önmegnyugtató kapacitás"],["Mentzos","self elvesztésétől való félelem"],["Freud","aktuálneurózis"]],"e":"Pszichodinamikus pánikelméletek."},{"t":"mc","q":"Melyik a pánik viselkedésterápiás módszere?","o":["Interoceptív expozíció","Szisztematikus túlceremonizálás","Hipnózis","Alvásmegvonás"],"a":0,"e":"A félt testi érzéseknek tesszük ki a beteget."},{"t":"fill","q":"A pánikbetegek tipikusan a ___ osztályra kerülnek, ahol kizárják a szervi okot.","a":["sürgősségi","surgossegi","sürgősségire","surgossegire"],"e":"Szervi ok kizárása után pánikzavar."},{"t":"tf","q":"A pánikrohamok közötti időszakban az antidepresszánsok a rohamok csökkentésére hatékonyak.","a":true,"e":"Rohamok között benzodiazepin is szóba jön."}]},{"id":"u15l3","title":"Fóbiák","theory":[["Fóbiák típusai","Fóbia: körülírt helyzetre korlátozott, kerülő magatartással (passzív elkerülés); a személy tudja, hogy félelme irracionális. <b>Agorafóbia</b>: olyan helyzetektől való félelem, ahonnan nehéz a menekülés vagy nincs segítség; a fóbiák fele-kétharmada; szorongáshierarchia. <b>Szociális fóbia</b>: mások figyelmének kitett helyzetek, a megszégyenülés és a látható szorongásjelek miatt. <b>Specifikus fóbia</b>: állat, magasság, repülés, vér-injekció-sérülés, szituációs típus."],["Etiológia","<b>Pszichoanalitikus</b>: ödipális konfliktus, elfojtás és <b>eltolás</b> külső tárgyra (Kis Hans). <b>Mowrer kétfaktoros elmélete</b> (1949): 1. klasszikus kondicionálás (semleges inger szorongáskeltővé válik), 2. operáns: az elkerülés csökkenti a szorongást, negatív megerősítés tartja fenn. Szociális fóbia: veleszületett gátlásosság, kritikus szülők; kognitív modell: az önmagára irányuló figyelem."],["Terápia","Viselkedésterápia: <b>szisztematikus deszenzitizálás</b> (relaxáció + szorongáshierarchia, gyengétől az erősig, in vivo házi feladat), <b>ingerelárasztás</b> (flooding; drasztikus, gyors). Pszichodinamikus: személyiségre irányuló. A kombinált kezelés hatékonyabb."]],"qs":[{"t":"mc","q":"Mi az agorafóbia lényege?","o":["Félelem olyan helyzetektől, ahonnan nehéz menekülni","Állatoktól való félelem","Mások előtti szereplés","Betegségtől való félelem"],"a":0,"e":"Gyakran pánikzavarral társul."},{"t":"mc","q":"Ki írta le a kétfaktoros tanuláselméletet?","o":["Mowrer","Beck","Skinner","Freud"],"a":0,"e":"1949: klasszikus és operáns kondicionálás."},{"t":"mc","q":"Mi tartja fenn a fóbiát a kétfaktoros elmélet szerint?","o":["Negatív megerősítés (elkerülés)","Büntetés","Kioltás","Habituáció"],"a":0,"e":"Az elkerülés csökkenti a szorongást."},{"t":"match","q":"Párosítsd a terápiát a leírással.","pairs":[["Szisztematikus deszenzitizálás","fokozatos kitétel, relaxáció"],["Ingerelárasztás","drasztikus, menekülés nélküli kitétel"],["In vivo","valós helyzetben, házi feladatként"]],"e":"Fóbiák viselkedésterápiája."},{"t":"tf","q":"A fóbiát passzív elkerülés jellemzi, a kényszert aktív.","a":true,"e":"Kényszerben aktív elkerülés/rituálé."},{"t":"tf","q":"Pszichoanalitikus értelmezés szerint a fóbiás szorongás tudattalan belső szorongást fed el.","a":true,"e":"Elfojtás, majd eltolás külső tárgyra."},{"t":"fill","q":"A fóbia a görög ___ szóból ered.","a":["phobosz","phobos","fobosz"],"e":"Phobosz: félelem."},{"t":"mc","q":"Melyik NEM a DSM-IV specifikus fóbiatípusa?","o":["Pánik típus","Állat","Vér-injekció-sérülés","Szituációs"],"a":0,"e":"A típusok: állat, természeti környezet, vér-injekció-sérülés, szituációs, egyéb."}]},{"id":"u15l4","title":"GAD és kényszerbetegség","theory":[["Generalizált szorongás (GAD)","DSM-III óta. Túlzott aggodalmaskodás számos dologgal kapcsolatban legalább <b>6 hónapig</b>, nem kontrollálható; legalább 3 tünet: fáradékonyság, koncentrációzavar, ingerlékenység, izomfeszültség, alvászavar. Trait jellegű, lassan alakul, nők közt gyakoribb, a legmagasabb a komorbiditás. Terápia: kognitív (értékelés, megbirkózás, önértékelés), relaxáció, pszichodinamikus, gyógyszer."],["Kényszerbetegség (OCD)","<b>Kényszergondolat</b>: visszatérő, nem kívánt gondolat; a személy elnyomná, saját pszichéjének termékeként ismeri fel (agresszív, szexuális, szennyeződés, vallási). <b>Kényszercselekedet</b>: ismétlődő viselkedés vagy mentális rituálé (kontroll, tisztálkodás, rendezés, számolás) a szorongás csökkentésére; <b>restauratív</b> vagy <b>preventív</b>. A tünetek énidegenek, időigényesek. Epidemiológia: a 4. leggyakoribb kórkép; monozigóta konkordancia 64%; szerotonin; homloklebeny, nucleus caudatus."],["OCD magyarázatok, terápia","Kognitív: <b>gondolat-akció fúzió</b>, perfekcionizmus, a nem kívánt gondolat elnyomása erősíti. Freud: anális fixáció, reakcióképzés, izoláció, meg nem történtté tevés; a kényszergondolat az Id, a kényszercselekedet a Superego. Terápia: SSRI (nagyobb dózis), <b>ingerexpozíció és válaszgátlás</b>, túlceremonizálás, habituációs tréning. Kezelésnél 1/3 gyógyul, 1/3 javul, 1/3 nem változik."]],"qs":[{"t":"mc","q":"Legalább mennyi ideig kell fennállnia a GAD aggodalmának?","o":["6 hónap","1 hét","1 hónap","2 év"],"a":0,"e":"Legalább 3 kísérő tünettel."},{"t":"mc","q":"Melyik a leghatékonyabb kényszerre ható viselkedésterápiás módszer?","o":["Ingerexpozíció és válaszgátlás","Hipnózis","Alvásmegvonás","Szisztematikus relaxáció önmagában"],"a":0,"e":"Szokásos rituálé megakadályozása."},{"t":"mc","q":"Mit jelent a gondolat-akció fúzió?","o":["A gondolatot egyenlőnek érzi a tettel","Gondolatrohanás","Cselekvéskényszer hiánya","Téveszme"],"a":0,"e":"Kognitív OCD-modell."},{"t":"match","q":"Párosítsd a fogalmat a jelentéssel.","pairs":[["Obszesszió","kényszergondolat"],["Kompulzió","kényszercselekedet"],["Restauratív","helyreállító rituálé"],["Preventív","megelőző rituálé"]],"e":"OCD fogalmak."},{"t":"tf","q":"OCD-ben a tünetek énidegenek, a beteg felismeri, hogy túlzottak.","a":true,"e":"Ez különbözteti meg a kényszeres személyiségzavartól."},{"t":"tf","q":"A kényszerbetegségben a szerotonin szerepe elhanyagolható.","a":false,"e":"SSRI-t adnak, a depressziónál nagyobb dózisban."},{"t":"fill","q":"A kényszerbetegség régi neve neurózis ___ .","a":["anancastica"],"e":"Ma OCD."},{"t":"mc","q":"Melyik OCD-ben érintett agyterület?","o":["Homloklebeny, nucleus caudatus","Kisagy","Nyúltvelő kizárólag","Occipitális lebeny"],"a":0,"e":"Válaszgátlás, tervezés, szervezés."}]},{"id":"u15l5","title":"Szomatoform zavarok","theory":[["Csoport és szomatizációs zavar","Vezértünet a testi panasz, orvosilag megmagyarázhatatlan. F45: <b>szomatizációs zavar</b> (Briquet-szindróma), nem differenciált, hipochondriázis, szomatoform vegetatív diszfunkció, állandó fájdalomzavar. Szomatizáció: multiplex, 30 éves kor előtt induló, krónikus; kell 8 tünet: <b>4 fájdalom, 2 emésztési, 1 szexuális, 1 pszeudoneurológiai</b>. Nőknél 5-10x gyakoribb, gyakran alacsonyan iskolázott. Nem differenciált: 1 tünet, min. 6 hónap. DSM-V: komplex szomatikus tünetzavar."],["Mechanizmusok","<b>Alexitímia</b> (érzelmek megnevezésének nehézsége), testi hipervigilancia, <b>szomatoszenzoros amplifikáció</b>, katasztrofizálás, <b>perszeveratív kogníció</b> (rágódás). A betegségnek előnye is van (mentesít, figyelmet kelt). Etiológia: gyerekkori betegségek, szomatizáló szülő modellje, trauma, hiper- vagy hipokortizolizmus, alacsony oxitocin. Kezelés: háziorvosi ellátás, fix időpontok, nem szembesítünk, trauma feldolgozása."],["Hipochondriázis és társai","<b>Hipochondriázis</b>: szüntelen aggódás súlyos betegség miatt, a testi jelek félreértelmezése, negatív leletek ellenére, legalább 6 hónap; a baj a tünet jelentése (szomatizációnál maga a tünet). Freud: nárcisztikus neurózis; Ferenczi; Sullivan: kapcsolat a paranoiával. <b>Testdiszmorfiás zavar</b>: képzelt külső hiba. <b>Szomatoform vegetatív diszfunkció</b>: vegetatívan beidegzett szervek. <b>Állandó fájdalomzavar</b>: szervi alap nélküli tartós fájdalom."]],"qs":[{"t":"mc","q":"Melyik a szomatizációs zavar másik neve?","o":["Briquet-szindróma","Münchhausen","Da Costa","Ganser"],"a":0,"e":"A csoport prototípusa, régi neve krónikus hisztériás neurózis."},{"t":"mc","q":"Hány tünet kell a szomatizációs zavarhoz a DSM szerint?","o":["8","1","3","12"],"a":0,"e":"4 fájdalom, 2 emésztési, 1 szexuális, 1 pszeudoneurológiai."},{"t":"mc","q":"Mit jelent az alexitímia?","o":["Az érzelmek megnevezésének és kifejezésének nehézsége","Fájdalomérzés hiánya","Amnézia","Téveszme"],"a":0,"e":"A beteg érzelem helyett testi tünetet mond."},{"t":"match","q":"Párosítsd a fogalmat a jelentéssel.","pairs":[["Alexitímia","érzelmeket nem tud megnevezni"],["Amplifikáció","testi ingerek felnagyítása"],["Perszeveráció","terméketlen rágódás"],["Hipervigilancia","fokozott testi éberség"]],"e":"A szomatizáció pszichológiai tényezői."},{"t":"tf","q":"Szomatizációs zavarban a beteg szimulál.","a":false,"e":"Nem szimulál, elfojt; az orvos nem találja az okot."},{"t":"tf","q":"A szomatizációs betegeknek betegségelőnyük is van.","a":true,"e":"Mentesülés a kötelezettségek alól, figyelem."},{"t":"mc","q":"Mi a hipochondriázis lényege?","o":["A tünet katasztrofizáló jelentése, súlyos betegségtől félés","Sok szervet érintő testi tünet","Hirtelen bénulás","Emlékezetkiesés"],"a":0,"e":"A szomatizációnál maga a tünet a baj."},{"t":"fill","q":"A szomatizálók kezelésénél a háziorvos ___ időpontra hívja vissza a beteget.","a":["fix","rögzített","rogzitett"],"e":"Így nem kell tüneteket produkálni a találkozásért."}]},{"id":"u15l6","title":"Disszociatív és konverziós zavarok","theory":[["Alapfogalmak","Konverziós (disszociatív) zavar: pszeudoneurológiai, monoszimptómás (érző- vagy mozgászavar), a régi <b>hisztéria</b>. A BNO a disszociatív, a DSM a szomatoform csoportba sorolja. Disszociáció: a tudat integratív funkciói (emlékezet, tudat, érzékelés) szétválnak. <b>Charcot</b>: hisztéria; <b>Janet</b>: dezintegráció, a trauma emlékét elkülönítve tárolja; Freud: elfojtás, konverzió (ödipális konfliktus). Ma kontinuumban gondolkodunk, mindig trauma okozza. Ritka, alacsony iskolázottságú nőknél gyakoribb."],["Alcsoportok (F44)","<b>Amnézia</b>: szelektív, körülírt, traumatikus információ kiesése. <b>Fuga</b>: váratlan elutazás, új identitás, amnézia a múltra. <b>Stupor</b>, <b>transz és megszállottság</b>, <b>mozgászavar</b> (bénulás, afónia, tremor), <b>konvulzió</b> (epilepsziát utánoz, de nincs bevizelés, nyelvharapás), <b>anesztézia és érzészavar</b> (kesztyűanesztézia, pszichogén vakság), multiplex személyiség. A <b>la belle indifférence</b> a tünet iránti közöny. A tünet gyorsan elmúlhat, szuggesztióra reagál."],["Deperszonalizáció, strukturális disszociáció","<b>Deperszonalizáció</b>: a személy kívülről látja magát, a realitásérzékelés megtartott; <b>derealizáció</b>: a külvilág megváltozott. <b>Strukturális disszociáció</b>: EP (emocionális személyiség) és ANP (látszólag normális személyiség). Elsődleges: PTSD; másodlagos: 2-es típusú trauma, borderline; harmadlagos: az ANP is felbomlik, többszörös személyiségzavar. Terápia: konfrontáció az emlékekkel, ingerexpozíció, hosszú előkészítés."]],"qs":[{"t":"mc","q":"Ki használta először a disszociáció kifejezést (dezintegrációként)?","o":["Janet","Charcot","Beck","Kohut"],"a":0,"e":"A trauma emlékét elkülönülten tároltnak tekintette."},{"t":"mc","q":"Melyik a konverziós tünetre jellemző közöny?","o":["La belle indifférence","Alexitímia","Anhedónia","Abulia"],"a":0,"e":"Nyugodtan beletörődik a tünetbe."},{"t":"mc","q":"Mi jellemző a disszociatív fugára?","o":["Váratlan elutazás, új identitás","Tartós szorongás","Rögzült aggodalom","Hirtelen sírás"],"a":0,"e":"Utólag amnézia a fuga állapotra."},{"t":"match","q":"Párosítsd az alcsoportot a leírással.","pairs":[["Amnézia","szelektív emlékezetkiesés"],["Fuga","elutazás, új identitás"],["Mozgászavar","bénulás, afónia"],["Konvulzió","epilepsziára emlékeztető roham"]],"e":"F44 alcsoportok."},{"t":"tf","q":"A deperszonalizációnál a realitásérzékelés megtartott.","a":true,"e":"A személy külső szemlélőnek érzi magát."},{"t":"tf","q":"Disszociatív konvulziónál gyakori a nyelvharapás és súlyos sérülés.","a":false,"e":"Ritkán vizel be, nem harapja el a nyelvét."},{"t":"fill","q":"A tudatos, kesztyűszerű érzéskiesés neve kesztyű___ .","a":["anesztézia","anaesthesia","anesztezia"],"e":"Csuklótól lefelé érzéketlen."},{"t":"mc","q":"Melyik strukturális disszociációs szint jellemző a PTSD-re?","o":["Elsődleges","Másodlagos","Harmadlagos","Egyik sem"],"a":0,"e":"Másodlagos: 2-es típusú trauma; harmadlagos: többszörös személyiség."}]},{"id":"u15l7","title":"PTSD és akut stressz","theory":[["Akut stressz és trauma","Traumaspektrum: kötelező kritérium egy külső életesemény; az ok-diagnózis. Trauma osztályozása: egyéni/kollektív, imperszonális/interperszonális, <b>1-es típus</b> (egyszeri) vagy <b>2-es típus</b> (elhúzódó). Legsúlyosabb: egyéni, interperszonális, 2-es típus. <b>Akut stresszzavar</b>: PTSD-szerű, de &lt; 1 hónap, disszociatív tünetek (min. 3). Peritraumatikus disszociáció később PTSD-kockázat."],["PTSD kritériumai (DSM-IV)","<b>A</b>: életveszély/testi épség veszélye, rémület, tehetetlenség. <b>B</b>: betöréses tünetek (flashback, álmok). <b>C</b>: elkerülés és érzelmi eltompulás (3+). <b>D</b>: hiperarousal (alvászavar, irritabilitás, hipervigilancia; 2+). <b>E</b>: több mint 1 hónap. Késleltetett kezdet lehetséges. A trauma utáni PTSD-arány 10-15%; nemi erőszaknál kb. 50%, természeti katasztrófánál 4%. A tünetek súlyossága nem arányos a trauma súlyosságával."],["Háttér és terápia","A traumás emlék szenzoros, szubkortikális szinten tárolódik (érzelmi, nem deklaratív). Komplex PTSD (F62): kötődési traumatizáció. Terápia: konfrontáció az emlékekkel, <b>ingerexpozíció</b>, szorongáskezelés, hosszú előkészítő szakasz (újratraumatizálás veszélye)."]],"qs":[{"t":"mc","q":"Mennyi idő után beszélünk PTSD-ről (és nem akut stresszzavarról)?","o":["1 hónapnál tovább","1 hétnél tovább","6 hónap után","1 év után"],"a":0,"e":"Az akut stresszzavar 1 hónapnál rövidebb."},{"t":"mc","q":"Melyik a PTSD betöréses tünete?","o":["Flashback","Anhedónia","Hipervigilancia","Amnézia"],"a":0,"e":"A B-kritérium: akaratlan újraélés."},{"t":"match","q":"Párosítsd a kritériumot a tünetcsoporttal.","pairs":[["B","betörés, flashback"],["C","elkerülés, eltompulás"],["D","hiperarousal"],["E","1 hónapnál tovább"]],"e":"DSM-IV PTSD."},{"t":"mc","q":"Melyik trauma-forma a legsúlyosabb variáció?","o":["Egyéni, interperszonális, 2-es típusú","Kollektív, imperszonális, 1-es típusú","Természeti katasztrófa","Autóbaleset"],"a":0,"e":"Jegyzet szerint az utóbbi a legsúlyosabb."},{"t":"tf","q":"A PTSD a trauma után mindenkinél kialakul.","a":false,"e":"Csak az átélők kb. 10-15%-ánál."},{"t":"tf","q":"Az akut stresszzavarban disszociatív tünetek is szerepelnek.","a":true,"e":"Legalább 3 tünet, pl. bénultság, derealizáció."},{"t":"fill","q":"Az elhúzódó, ismétlődő trauma a ___ -es típusú trauma.","a":["2","második","masodik"],"e":"A 1-es típus egyszeri, körülírt."},{"t":"mc","q":"Hogyan tárolódik a traumás emlék?","o":["Szenzoros, szubkortikális szinten","Csak deklaratív memóriában","Nem tárolódik","Szemantikus hálóban"],"a":0,"e":"Ezért érzelmi, nem értelmi jellegű."}]}],"color":"#ff4b4b"},{"id":"u16","title":"Személyiségzavarok","desc":"Excentrikus, dramatikus, szorongó csoportok","lessons":[{"id":"u16l1","title":"Általános kritériumok","theory":[["Alapok és történet","DSM-ben a <b>II. tengelyen</b> (DSM-III óta külön). Korán kezdődő, tartós; a klinikai zavarok (I. tengely) epizodikusak. Történet: típustanok (Hippokratész, Sheldon, Kretschmer), <b>Karl Abraham</b> karakterneurózis, <b>Kurt Schneider</b> (1924) 10 fajta pszichopátia. Karakterneurózis: az egész személyiség védekezik, nem tünet."],["Általános diagnosztikai kritériumok","Az élmény és viselkedés tartós, rugalmatlan, maladaptív mintája, amely jelentősen eltér a kultúra elvárásaitól, legalább <b>2 területen</b>: kogníció, affektivitás, interperszonális kapcsolatok, impulzuskontroll. Minden helyzetben érvényesül (nem csak adott helyzetben, mint a szociális fóbia), szenvedést vagy funkcióromlást okoz, stabil és korai kezdetű; gyermekkorban nem diagnosztizáljuk. A kritériumok <b>politetikusak</b>: több tétel van, mint ami kell."],["Csoportok","<b>Excentrikus</b>: paranoid, szkizoid, szkizotípiás. <b>Dramatikus</b>: antiszociális, borderline, hisztrionikus, nárcisztikus. <b>Szorongó</b>: kényszeres, elkerülő, dependens. Szintek: neurotikus és borderline (súlyosabb). DSM-V terv: multiaxiális rendszer törlése, 5 típus (borderline, szkizotípiás, elkerülő, kényszeres, antiszociális/pszichopátiás), dimenzionális értékelés."]],"qs":[{"t":"mc","q":"Melyik DSM-tengelyen szerepel a személyiségzavar?","o":["II.","I.","III.","IV."],"a":0,"e":"II. tengely: személyiségzavar és mentális retardáció."},{"t":"mc","q":"Minimum hány területen kell eltérés lennie az általános kritérium szerint?","o":["2","1","4","Mind a 4"],"a":0,"e":"Kogníció, affektivitás, interperszonális kapcsolatok, impulzuskontroll."},{"t":"mc","q":"Ki írt le 1924-ben 10 pszichopátiát?","o":["Kurt Schneider","Kraepelin","Cleckley","Kernberg"],"a":0,"e":"Schneider osztályozása a legátfogóbb volt."},{"t":"match","q":"Párosítsd a zavart a csoporttal.","pairs":[["Paranoid","excentrikus"],["Borderline","dramatikus"],["Kényszeres","szorongó"],["Szkizotípiás","excentrikus"]],"e":"DSM-csoportok."},{"t":"tf","q":"A személyiségzavar kritériumai politetikusak.","a":true,"e":"Több tétel szerepel, mint amennyinek teljesülnie kell."},{"t":"tf","q":"A személyiségzavarokat gyermekkorban is diagnosztizáljuk.","a":false,"e":"A diagnózis nem gyermekkorban születik."},{"t":"mc","q":"Melyik DSM-csoportba tartozik az antiszociális, a borderline, a hisztrionikus és a nárcisztikus zavar?","o":["Dramatikus (B)","Excentrikus (A)","Szorongó (C)","Disszociatív"],"a":0,"e":"Dramatikus, érzelmektől fűtött (B) csoport."},{"t":"mc","q":"Mi különbözteti meg a személyiségzavart az I. tengely zavaraitól?","o":["Tartós, korán kezdődő minta","Epizodikus lefolyás","Szervi ok","Téveszme"],"a":0,"e":"A klinikai zavarok epizodikusak."}]},{"id":"u16l2","title":"Paranoid és szkizoid","theory":[["Paranoid személyiségzavar (F60.0)","Gyanakvás, rejtett jelentések keresése, krónikus sértődöttség, igazságtartalom iránti rigid ragaszkodás, grandiozitás, szégyen, irigység. A gyanakvó hiedelmek nem téveszmék. A realitást nem torzítja, de jelentőségét rosszul állapítja meg. Dinamika (Klein): <b>hasítás</b>, <b>projekció</b>, <b>projektív identifikáció</b>; a mentalizáció elakad a pszichés ekvivalencia szintjén. Terápia: egyéni, a munkaszövetség kiépítése; csoportban rosszul működnek."],["Szkizoid személyiségzavar (F60.1)","Magányos, visszahúzódó, nem vágyik társaságra (ez különbözteti meg az elkerülőtől), érzelmileg tompa, közönyös. Belül érzékeny, kreatív. A szkizotípiástól: nincs szkizofréniához köthető genetikai kapcsolat. <b>Fairbairn</b>: a félelem, hogy a vágyai felfalják az anyát („Piroska fantázia”). <b>Bálint</b>: alaphiba. Kétféle szorongás: túl közel (elárasztás), túl távol (magány). Terápia: csoport is jó lehet, a közelséget nem viseli."]],"qs":[{"t":"mc","q":"Mi a paranoid személyiségzavar központi elhárítása Klein szerint?","o":["Hasítás","Reakcióképzés","Elfojtás","Szublimáció"],"a":0,"e":"Paranoid-szkizoid pozíció: projekció, projektív identifikáció."},{"t":"mc","q":"Mi különbözteti meg a szkizoidot az elkerülő személyiségtől?","o":["Nem vágyik társaságra","Fél a kritikától","Impulzivitás","Hangulatingadozás"],"a":0,"e":"Az elkerülő vágyik a kapcsolatra, de fél."},{"t":"mc","q":"Melyik szerző „Piroska fantáziájáról” írt?","o":["Fairbairn","Bálint","Masterson","Cleckley"],"a":0,"e":"A szkizoid attól fél, hogy a vágyai felfalják a másikat."},{"t":"tf","q":"A paranoid személyiségzavarban a gyanakvó hiedelmek téveszmeszerűek.","a":false,"e":"Nem hasonlítanak téveszmékre, nincs pszichózis."},{"t":"tf","q":"Paranoid betegnek csoportterápia ajánlott.","a":false,"e":"Gyanakvásuk miatt egyéni terápia jobb."},{"t":"match","q":"Párosítsd a személyiségzavart a jellemzővel.","pairs":[["Paranoid","gyanakvás, krónikus sértődöttség"],["Szkizoid","tompa érzelmek, magány"]],"e":"Excentrikus csoport."},{"t":"fill","q":"A szkizoid személyiségnél a túl közelségtől az elárasztás, a túl távolságtól a ___ szorongás lép fel (egy szó).","a":["magány","magánytól","magany"],"e":"Kétféle szorongás."},{"t":"mc","q":"Melyik a paranoid zavar két fő elhárítása?","o":["Projekció és projektív identifikáció","Elfojtás és konverzió","Reakcióképzés és izoláció","Tagadás és szublimáció"],"a":0,"e":"A kontrollszükséglet alacsony önértékelést jelez."}]},{"id":"u16l3","title":"Szkizotípiás és antiszociális","theory":[["Szkizotípiás zavar (F21)","Szkizofrénia spektrum, egész életen át tartó vonások. Három kulcsjellemző: <b>mágikus gondolkodás</b>, gyanakvás/paranoid képzetek, szociális izoláció. Beszéd: körülményes, metaforikus, nem inkoherens. Percepció: illúziók, nem hallucinációk. Nincsenek téveszmék. Biológiai eltérések (figyelemzavar, szemmozgás)."],["Antiszociális zavar","DSM-IV: 15 éves kor óta mások jogainak semmibevétele, 3+ tünet: normaszegés, csalás/hazudozás, impulzivitás, agresszivitás, vakmerőség, felelőtlenség, <b>lelkiismeret-furdalás hiánya</b>; legalább 18 év, 15 év előtt viselkedészavar. <b>Cleckley</b> (1941): pszichopátia; <b>Hare</b> katalógusa. Pszichopátia és ASPD nem azonos. Okok: genetika, minimális agyi diszfunkció, ADHD, csökkent bőrelektromos válasz, elhanyagolás, bántalmazás; gyenge felettes én. Terápia: ambuláns, büntetés-jutalom, nincs gyógyszer; ritka az öngyilkosság (agresszió kifelé)."]],"qs":[{"t":"mc","q":"Ki írta le 1941-ben a szociopátiát?","o":["Cleckley","Hare","Kernberg","Schneider"],"a":0,"e":"Cleckley szerint nem szorong, nem szeret, nem tanul a tapasztalatból."},{"t":"mc","q":"Melyik NEM szkizotípiás jellemző?","o":["Hallucináció","Mágikus gondolkodás","Gyanakvás","Szociális izoláció"],"a":0,"e":"Nincs hallucináció és téveszme."},{"t":"mc","q":"Mekkora életkortól kell a viselkedészavar jele antiszociális zavarnál?","o":["15 éves kor előtt","8 éves kor előtt","18 éves kor után","30 éves kor után"],"a":0,"e":"A diagnózishoz legalább 18 év kell, de 15 év előtti viselkedészavar adat."},{"t":"match","q":"Párosítsd a szerzőt a témával.","pairs":[["Cleckley","szociopátia leírása 1941"],["Hare","pszichopátia-katalógus"],["Schneider","10 típusú pszichopátia"]],"e":"Antiszociális zavar története."},{"t":"tf","q":"Antiszociális zavarban gyakori az öngyilkosság.","a":false,"e":"Ritka, mert az agressziót kifelé irányítják."},{"t":"tf","q":"A szkizotípiás személyiségzavar a szkizofrénia spektrumához tartozik.","a":true,"e":"Genetikailag kötődik a szkizofréniához."},{"t":"fill","q":"Az antiszociális zavar egyik fő jellemzője a lelkiismeret-___ hiánya.","a":["furdalás","furdalas"],"e":"Bűntudat és empátia hiánya."},{"t":"mc","q":"Melyik biológiai eltérés jellemzi a pszichopátiát?","o":["Csökkent bőrelektromos válasz","Fokozott megrezzenési reflex","Magas szorongás","Hiperkortizolizmus"],"a":0,"e":"Veszélyhelyzetben kevésbé élnek át félelmet."}]},{"id":"u16l4","title":"Borderline: szerveződés, hasítás","theory":[["Kernberg: borderline szint","Szerveződési szintek: neurotikus, borderline, pszichotikus. Borderline: <b>identitásdiffúzió</b>, primitív elhárítások, a realitásvizsgálat hétköznapokban ép, stresszben sérül. Neurotikus: ép identitás, érett elfojtás. Éngyengeség: csökkent szorongástűrés, csökkent impulzuskontroll, csökkent szublimációs képesség; specifikusan: primer folyamat gondolkodás, primitív elhárítások, patológiás internalizált tárgykapcsolatok."],["Hasítás következményei","Primitív elhárítások: <b>hasítás</b>, projekció, projektív identifikáció, idealizálás, devalválás, omnipotencia, tagadás. A hasítás miatt nem látja a jót és rosszat egy emberben: identitásdiffúzió, váltakozó idealizálás és leértékelés, szélsőséges érzelmek; magasabb érzelmek (gyász, hála, bűntudat) nehézsége; éretlen tárgykapcsolatok, tárgyhűség hiánya."]],"qs":[{"t":"mc","q":"Melyik a borderline fő elhárítása?","o":["Hasítás","Elfojtás","Intellektualizáció","Reakcióképzés"],"a":0,"e":"Primitív elhárítások köre."},{"t":"mc","q":"Kernberg szerint mi hiányzik borderline szinten a neurotikushoz képest?","o":["Integrált identitás","Szorongás","Munkaképesség","Verbalitás"],"a":0,"e":"Identitásdiffúzió jellemző."},{"t":"mc","q":"Mikor sérül a borderline realitásvizsgálata?","o":["Stresszhelyzetben","Mindig","Soha","Csak alvás közben"],"a":0,"e":"Hétköznapban ép, stresszben romlik."},{"t":"match","q":"Párosítsd a szintet a jellemzővel.","pairs":[["Neurotikus","ép identitás, érett elhárítás"],["Borderline","identitásdiffúzió, primitív elhárítás"],["Pszichotikus","sérült realitásvizsgálat"]],"e":"Kernberg szerveződési szintek."},{"t":"tf","q":"A hasítás miatt a borderline a másikat jónak vagy rossznak látja.","a":true,"e":"Idealizál és leértékel, nincsenek átmenetek."},{"t":"tf","q":"A borderline személyiségszerveződésű emberek nem tudnak impulzust kontrollálni és szublimálni.","a":true,"e":"Csökkent impulzuskontroll és szublimációs képesség."},{"t":"fill","q":"A borderline szinten az identitás ___.","a":["diffúz","diffuz"],"e":"Identitásdiffúzió."},{"t":"mc","q":"Melyik érzelem nehezen megélhető hasítás miatt?","o":["Hála, gyász, bűntudat","Düh","Félelem","Öröm"],"a":0,"e":"Komplex pozitív-negatív integrációt igényelnek."}]},{"id":"u16l5","title":"Borderline: klinikum, etiológia","theory":[["Klinikum, epidemiológia","BNO: érzelmileg labilis (F60.3). Két fő vonás: <b>instabilitás</b> (kapcsolatok, énkép, hangulat) és <b>impulzivitás</b> (autoagresszió, önsértés, öngyilkossági kísérlet). Krónikus üresség, intenzív harag, átmeneti paranoid vagy disszociatív tünetek. Prevalencia 1,8-5,9%, nőknél 7x gyakoribb a klinikumban (férfiaknál alkohol, börtön); a kórházban kezelt személyiségzavarosok 63%-a BPD. Sok a szexuális bántalmazott. Azért gyakori a klinikumban, mert szenvednek és segítséget keresnek."],["Etiológia","<b>Kernberg</b>: a Mahler-féle újraközeledési alszakasz (16-24 hónap), a tárgyállandóság hiánya, veleszületett agresszió, negatív introjektumok. <b>Masterson és Rinsley</b>: az anya visszavonja szeretetét az önállósodáskor. <b>Adler</b>: deficitmodell, hiányzik a megtartó-megnyugtató belső tárgy. Gyermekkori (főleg szexuális) abúzus és elhanyagolás. Terápia: nehéz az önsértés miatt, de keresik a segítséget."]],"qs":[{"t":"mc","q":"Melyik a borderline két fő vonása?","o":["Instabilitás és impulzivitás","Gyanakvás és izoláció","Perfekcionizmus és merevség","Csábítás és nagyzolás"],"a":0,"e":"Önsértés érzelemcsillapító célú."},{"t":"mc","q":"Melyik fejlődési szakaszhoz köti Kernberg a borderline kialakulását?","o":["Újraközeledési alszakasz (16-24 hó)","Orális fázis","Látencia","Serdülőkor"],"a":0,"e":"Mahleri szeparáció-individuáció."},{"t":"mc","q":"Ki írta le a deficit vagy elégtelenségi modellt?","o":["Adler","Masterson","Fairbairn","Kohut"],"a":0,"e":"Inkonzisztens anyai magatartás miatt nincs megtartó belső tárgy."},{"t":"match","q":"Párosítsd a szerzőt az állítással.","pairs":[["Kernberg","újraközeledési alszakasz, hasítás"],["Masterson","az anya visszavonja a szeretetet"],["Adler","hiányzó megnyugtató belső tárgy"]],"e":"Borderline etiológia."},{"t":"tf","q":"A BPD a klinikumban nőknél gyakoribb.","a":true,"e":"Kb. 7-szeres a gyakoriság."},{"t":"tf","q":"A borderline személyiségzavar nem jár önsértéssel.","a":false,"e":"Az önsértés érzelemszabályozó eszköz."},{"t":"fill","q":"A borderline zavar prevalenciája 1,8 és 5,9 ___ között van (egység).","a":["százalék","szazalek","%"],"e":"1,8-5,9%."},{"t":"mc","q":"Miért kerül sok BPD beteg a kórházba?","o":["Szenvednek és segítséget keresnek, öngyilkossági kísérlet","Mert kötelező","Mert nem szenvednek","Mert antiszociálisak"],"a":0,"e":"Önveszélyeztető viselkedés miatt is bekerülnek."}]},{"id":"u16l6","title":"Hisztrionikus és nárcisztikus","theory":[["Hisztrionikus (F60.4)","Túlzott emocionalitás és figyelemfelkeltés, 4+ tünet: kényelmetlen, ha nem ő van a középpontban, szexuálisan csábító, gyorsan váltakozó felszínes érzelmek, külső megjelenés, impresszionisztikus beszéd, teatralitás, szuggesztibilitás, a kapcsolatokat intimebbnek látja. Hisztériás (érett, jó impulzuskontroll, ödipális) és hisztrionikus (orális, impulzív, primitív elhárítás) különbsége. Kognitív stílus: globális, impresszionisztikus; elhárítás: elfojtás, tagadás, disszociáció."],["Nárcisztikus zavar","DSM-IV: 5+ tünet: nagyzoló én, siker- és szépségfantáziák, különlegesség-érzés, csodálat igénye, jogosultság, kizsákmányolás, <b>empátiahiány</b>, irigység, gőg. Típusok: <b>arrogáns</b> (adó) és <b>vékonybőrű</b> (vevő, szégyenlős). <b>Kohut</b>: szülői empátiahiány, archaikus self megreked, az agresszió másodlagos. <b>Kernberg</b>: patológiás grandiózus self (ideális self + ideális tárgy + valódi self összeolvadása), az agresszió elsődleges, irigység."]],"qs":[{"t":"mc","q":"Hány tünet kell a nárcisztikus zavarhoz (DSM-IV)?","o":["5 vagy több","3","4","9"],"a":0,"e":"A hisztrionikushoz és a kényszereshez 4."},{"t":"mc","q":"Ki szerint másodlagos az agresszió a nárcisztikus zavarban?","o":["Kohut","Kernberg","Freud","Klein"],"a":0,"e":"Kohutnál az agresszió a ki nem elégített igények következménye."},{"t":"mc","q":"Melyik a vékonybőrű nárcisztikus jellemzője?","o":["Szégyenlős, fél a kritikától","Gőgös, kérkedő","Antiszociális","Impulzív"],"a":0,"e":"Csak „vételi” irányban működik."},{"t":"match","q":"Párosítsd a zavart a jellemzővel.","pairs":[["Hisztrionikus","teatralitás, figyelemfelkeltés"],["Nárcisztikus","nagyzolás, empátiahiány"],["Hisztériás","érett, jó impulzuskontroll"]],"e":"Dramatikus csoport."},{"t":"tf","q":"Kernberg szerint a nárcisztikus agresszió elsődleges.","a":true,"e":"Belülről fakad, irigységben nyilvánul meg."},{"t":"tf","q":"A hisztrionikus személyiségre a primitív hasítás és idealizálás is jellemző.","a":true,"e":"A hisztériás magasabb szinten működik."},{"t":"fill","q":"A nárcisztikus zavar egyik kulcsa az ___ hiánya.","a":["empátia","empátiája","empatia"],"e":"Nem képes felismerni mások érzéseit."},{"t":"mc","q":"Melyik elhárítás jellemző a hisztrionikus kognitív stílusra?","o":["Elfojtás, tagadás, disszociáció","Intellektualizáció","Projekció","Izoláció"],"a":0,"e":"Az érzelmi arousalt csökkentik."}]},{"id":"u16l7","title":"Kényszeres, elkerülő, dependens","theory":[["Kényszeres személyiségzavar","Rendszeretet, perfekcionizmus, kontroll a rugalmasság kárára, 4+ tünet: részletekhez ragaszkodás, a feladat befejezését akadályozó perfekcionizmus, munkába temetkezés, aggályosság, gyűjtögetés, nehéz delegálás, fukarság, merevség. Anális fázis, szigorú felettes én, elhárítások: affektusizoláció, intellektualizáció, reakcióképzés, meg nem történtté tevés. A tünetek énazonosak (OCD-től eltérően). Döntésképtelenség, hajlam depresszióra."],["Elkerülő zavar","Szociális gátoltság, a meg nem felelés érzése, a negatív megítélés miatti túlérzékenység; 4+ tünet. Vágyik a kapcsolatra, de fél a kudarctól és megszégyenüléstől (ez különbözteti meg a szkizoidtól). Közel áll a vékonybőrű nárcisztikushoz, de nincs benne csendes grandiozitás. Genetikai szégyenlősség, bizonytalan kötődés, elutasító környezet."],["Dependens zavar (F60.7)","Általános, túlzott igény a gondoskodásra, kapaszkodó, alárendelődő magatartás, szeparációs félelem, 5+ tünet: nehéz döntéshozatal tanács nélkül, nem tud nemet mondani, nem kezdeményez, szorongás egyedül, sürgősen új kapcsolatot keres. Borderline-tól: elhagyáskor alárendelődik és kapaszkodik, a borderline dühvel és manipulációval reagál. Okok: kontrolláló, függetlenséget nem támogató család, bizonytalan kötődés; a kapaszkodás agressziót is leplezhet. Orális karakterrel rokon."]],"qs":[{"t":"mc","q":"Mi különbözteti meg az OCD-t a kényszeres személyiségzavartól?","o":["OCD tünetei énidegenek","A személyiségzavar énidegen","Az OCD korábban kezdődik","Nincs különbség"],"a":0,"e":"A személyiségzavarnál énazonosak is lehetnek."},{"t":"mc","q":"Hány tünet kell a dependens zavarhoz?","o":["5","4","3","9"],"a":0,"e":"DSM-IV-TR."},{"t":"mc","q":"Mi jellemző az elkerülő személyiségre?","o":["Vágyik a kapcsolatra, de fél az elutasítástól","Nem vágyik társaságra","Kizsákmányol másokat","Téveszmék"],"a":0,"e":"A szkizoid nem vágyik a kapcsolatra."},{"t":"match","q":"Párosítsd a zavart a jellemzővel.","pairs":[["Kényszeres","perfekcionizmus, kontroll"],["Elkerülő","félelem a megszégyenüléstől"],["Dependens","kapaszkodás, szeparációs félelem"]],"e":"Szorongó csoport."},{"t":"tf","q":"A dependens személy elhagyáskor dühvel és manipulációval reagál.","a":false,"e":"Ez a borderline; a dependens alárendelődik és kapaszkodik."},{"t":"tf","q":"A kényszeres személyiségzavarban a perfekcionizmus a befejezést is akadályozhatja.","a":true,"e":"Pl. nem éri el saját szigorú standardjait."},{"t":"fill","q":"A kényszeres személyiségzavar a pszichoanalitikus felfogásban az ___ fázishoz kötődik.","a":["anális","analis"],"e":"Szigorú felettes-én, agresszió problémája."},{"t":"mc","q":"Melyik csoportba tartozik a dependens, kényszeres és elkerülő zavar?","o":["Szorongó csoport","Dramatikus","Excentrikus","Pszichotikus"],"a":0,"e":"Mind a szorongással való megbirkózás köré szerveződik."}]}],"color":"#2b70c9"},{"id":"u17","title":"Kérdőíves tesztek","desc":"MMPI, TCI, Young – felépítés, profilok","lessons":[{"id":"u17l1","title":"Pszichodiagnosztikai tesztek alapjai","theory":[["Klinikai adatszerzés","Források: <b>első interjú</b>, <b>pszichodiagnosztikai tesztek</b>, <b>megfigyelés</b>. A teszt szisztematikus, standard eljárás: számszerűsíthető skálákkal vagy kategóriarendszerrel írja le a viselkedést (maximális vagy tipikus teljesítmény)."],["Tesztek típusai","<b>Teljesítménytesztek</b> (intelligencia, neuropszichológiai, memória): maximális teljesítményt mérnek, motiváció és koncentráció kell. <b>Személyiségvizsgálók</b>: projektív (Rorschach, TAT, PFT, Szondi) és kérdőíves (MMPI, Eysenck, TCI, Young). Itt nincs jó vagy rossz eredmény – ezt hangsúlyozni kell."],["Konstrukciós elvek","<b>Teoretikus</b>: jól meghatározott vonást mérünk, az irodalomból fogalmazunk állításokat (pl. TCI). <b>Empirikus</b>: állításokat gyűjtenek, az eredmények elemzése után szelektálják a kérdéseket (pl. MMPI)."],["Kritériumok és etika","Jó teszt: <b>valid</b> (azt méri, amire készült), <b>reliábilis</b> (megbízható, pontos), <b>standardizált</b>, ismert normák. Etika: csak képzett szakember veszi fel, titkos, az eredményre hivatkozva nem avatkozunk a páciens életébe, óvatos interpretáció. A véleményben csak valószínűsítünk."]],"qs":[{"t":"mc","q":"Melyik NEM a klinikai adatszerzés forrása?","o":["Első interjú","Pszichodiagnosztikai teszt","Megfigyelés","Genetikai vizsgálat"],"a":3,"e":"A három forrás: első interjú, tesztek, megfigyelés."},{"t":"mc","q":"Melyik konstrukciós elv empirikus?","o":["MMPI","TCI","Mindkettő","Egyik sem"],"a":0,"e":"Az MMPI empirikus (kórrajzokból válogatott itemek), a TCI teoretikus."},{"t":"tf","q":"A személyiségkérdőíveknél hangsúlyozni kell, hogy nincs jó és rossz eredmény.","a":true,"e":"Személyiségvizsgáló eljárásoknál ez alapszabály."},{"t":"match","q":"Párosítsd a fogalmat a jelentésével!","pairs":[["Validitás","azt méri, amire készült"],["Reliabilitás","megbízhatóság, pontosság"],["Standardizáltság","ismert normákhoz viszonyítunk"]],"e":"A tesztek három alapkritériuma."},{"t":"mc","q":"Mi a teoretikus konstrukció lényege?","o":["Irodalomból fogalmazott állítások egy jól definiált vonás mérésére","Betegcsoportok válaszai alapján szelektált tételek","Véletlenszerű itemgyűjtés","Rajzok elemzése"],"a":0,"e":"Teoretikus: elmélet alapján, kész a teszt; empirikus: eredmények alapján szelektálnak."},{"t":"tf","q":"A pszichológiai véleményben az eredmények alapján biztosat lehet állítani.","a":false,"e":"Csak valószínűsíthetünk, biztosat soha nem mondhatunk."},{"t":"fill","q":"A teszt veszélye, hogy a személyiséget ___ (elszíntelenítik).","a":["elszürkítik","elszürkíti","elszürkítés"],"e":"A teszthasználat veszélye: elszürkítik a személyiséget, ronthatják az önbecsülést."},{"t":"mc","q":"Melyik tartozik a teljesítménytesztek közé?","o":["MAWI","MMPI","Rorschach","TCI"],"a":0,"e":"A MAWI intelligenciateszt, azaz teljesítményteszt."}]},{"id":"u17l2","title":"MMPI: felépítés","theory":[["Az MMPI alapadatai","1946-ban jelent meg, felnőtt klinikai betegekre készült (egészségesekkel is felvehető). <b>566 állítás</b> (550 + 16 ismétlődő), kitöltés 1–1,5 óra. Kórrajzokból, anamnézisekből válogatott itemek, <b>empirikus</b> alapon."],["Mit mér?","Viselkedéses és tüneti jellegzetességeket, a pszichopatológiai állapot súlyosságát; intrapszichés történésekről nem beszél. Egyetlen skála sem fedi le egy betegség kritériumait: a skálák együttmozgását figyeljük. Három konstelláció: <b>neurózis, pszichózis, pszichopátia</b>."],["Validitásskálák","Három van: <b>L</b> (hazugság), <b>F</b> (megbízhatóság), <b>K</b> (korrekció). Jelzik, hogy a vizsgált személy próbált-e szimulálni vagy disszimulálni."],["Tíz klinikai főskála","<b>Hd</b> hipochondria, <b>D</b> depresszió, <b>Hy</b> hisztéria, <b>Pp</b> pszichopátia, <b>Mf</b> maszkulinitás–femininitás, <b>Pa</b> paranoiditás, <b>Pt</b> pszichaszténia (szorongás), <b>Sc</b> szkizoídia, <b>Ma</b> hipománia, <b>Si</b> szociális introverzió. Az Mf és az Si nem klinikai skála!"]],"qs":[{"t":"mc","q":"Hány állításból áll az MMPI?","o":["566","240","244","100"],"a":0,"e":"550 + 16 ismétlődő = 566."},{"t":"mc","q":"Melyik NEM validitásskála?","o":["Hy","L","F","K"],"a":0,"e":"A validitásskálák: L, F, K. A Hy hisztéria klinikai skála."},{"t":"match","q":"Párosítsd a skálát a jelentéssel!","pairs":[["L","hazugság"],["F","megbízhatóság"],["K","korrekció"]],"e":"Az MMPI három validitásskálája."},{"t":"match","q":"Párosítsd a klinikai skálát a nevével!","pairs":[["Hd","hipochondria"],["Pt","pszichaszténia"],["Ma","hipománia"],["Pa","paranoiditás"]],"e":"Klinikai főskálák."},{"t":"tf","q":"Az Mf és az Si skála nem klinikai skála.","a":true,"e":"Mf (maszkulinitás–femininitás) és Si (szociális introverzió) nem klinikai."},{"t":"tf","q":"Az MMPI intrapszichés történésekről ad információt.","a":false,"e":"Viselkedéses és tüneti jellegzetességeket mér, intrapszichés történésekről nem beszél."},{"t":"mc","q":"Milyen elven állították össze az MMPI-t?","o":["Empirikus","Teoretikus","Projektív","Faktoranalitikus elmélet alapján, itemek nélkül"],"a":0,"e":"Kórrajzokból, anamnézisekből válogatták az itemeket."},{"t":"fill","q":"Az MMPI 1946-ban jelent meg, kitöltése kb. 1–1,5 ___ alatt történik.","a":["óra","óra alatt","ora"],"e":"A felvétel 1–1,5 óra."}]},{"id":"u17l3","title":"MMPI: skálacsoportok, T-értékek","theory":[["Triász és tetrád","<b>Neurotikus triász</b>: Hd, D, Hy. <b>Pszichotikus tetrád</b>: Pa, Pt, Sc, Ma (a Pt és az Sc a magskálák). A klinikai skálák sorrendje számít."],["Kiegészítő skálák","Kontrollskálák (17), vonásskálák (15: acting out, agresszió), kiegészítő neurózisskálák (18: szorongás, depresszió, hiszteroiditás), egyéb klinikai (17: kriminalitás, alkoholprobléma, alkalmazkodási zavar), differenciáldiagnosztikai (17, matematikailag képezték az alapskálákból)."],["T-értékek","Nyerspontból értékpont, majd <b>T-érték</b>. <b>50T</b> átlag, <b>40–60T</b> normál, 30–40T és 60–70T hangsúlyos vonások övezete, <b>30 alatt és 70 felett</b> patológiás övezet. Kiértékelés kézzel vagy számítógéppel."]],"qs":[{"t":"mc","q":"Mely skálák alkotják a neurotikus triászt?","o":["Hd, D, Hy","Pa, Pt, Sc","Pp, Ma, Si","L, F, K"],"a":0,"e":"Neurotikus triász: Hd, D, Hy."},{"t":"mc","q":"Mely skálák alkotják a pszichotikus tetrádot?","o":["Pa, Pt, Sc, Ma","Hd, D, Hy, Pp","Pp, Mf, Si, K","D, Pt, Sc, Si"],"a":0,"e":"Pszichotikus tetrád: Pa, Pt, Sc, Ma."},{"t":"mc","q":"Melyik T-érték tartományt tekintjük normálisnak?","o":["40–60T","30–40T","70T felett","80–90T"],"a":0,"e":"40–60T normál; 50T az átlag."},{"t":"tf","q":"70T felett a pontszám patológiás övezetbe esik.","a":true,"e":"30 alatt és 70 felett patológiás övezet."},{"t":"match","q":"Párosítsd a kiegészítő skálacsoportot a tartalmával!","pairs":[["Kontrollskálák","teszthelyzet és önkontroll"],["Vonásskálák","acting out, agresszió"],["Egyéb klinikai","kriminalitás, alkoholprobléma"]],"e":"Kiegészítő skálák."},{"t":"mc","q":"Melyek a pszichotikus tetrád magskálái?","o":["Pt és Sc","Pa és Ma","Hd és D","Pp és Hy"],"a":0,"e":"A Pt és az Sc a magskálák."},{"t":"fill","q":"Az MMPI-ben az átlagos T-érték ___.","a":["50","50T"],"e":"50T az átlag."},{"t":"tf","q":"A differenciáldiagnosztikai skálákat matematikailag az alapskálákból képezték.","a":true,"e":"17 ilyen skála van."}]},{"id":"u17l4","title":"MMPI: profilok és kiértékelés","theory":[["Neurotikus profil","A neurotikus triász és a Pt emelkedik, a profil egésze kevésbé tolódik 70T felé. <b>Súlyosabb</b>: 70–80T, D akár 90T körül, Pt↑, Sc is emelkedhet. <b>Enyhe</b>: D-völgy a triászban, testi tünetek, Si↑. A bal oldal a tüneteket, a jobb az alkalmazkodást mutatja."],["Pszichotikus profil","A jobb oldal (tetrád) emelkedik, főleg Pt és Sc. Pa/Ma a minőséget jelzi (paranoid vagy mániás). F 80T felett is belefér. A <b>Hy emelkedése a pszichózis ellen</b> szól. Pp: megromlott alkalmazkodás; Es (énerő) alacsony, Imp↑."],["Pszichopátiás profil és szuicidum","A profil <b>közepe</b> (Pp) emelkedik ki, nincs szenvedés; ↑Ma – 49-es kód. Mindig nézzük: Imp, önkontroll, szociális felelősség, empátia, tolerancia. Szuicidumveszélyre utalhat: ↑D, ↑Pt, ↑A, agresszió túlkontrollja, Es↓."],["Kiértékelés menete","1) Valid-e a profil (szimulál/disszimulál)? 2) Alacsony, magas vagy normál lefutás? 3) Főskálák sorrendbe állítása. 4) Csúcskódok keresése. 5) Hozzájuk passzoló alskálák. 6) Diagnózis, ha elvárják – előre kérjünk pontos klinikai kérdést."]],"qs":[{"t":"mc","q":"Mi jellemző a pszichopátiás profilra?","o":["A profil közepe (Pp) emelkedik ki, nincs szenvedés","A bal oldal emelkedik, nagy szenvedéssel","Csak az L skála magas","Minden skála 30T alatt"],"a":0,"e":"A pszichopátiás profil közepe emelkedik, szenvedésről nincs szó."},{"t":"mc","q":"Melyik skála emelkedése szól a pszichózis ellen?","o":["Hy","Sc","Pt","Pa"],"a":0,"e":"A Hy megemelkedése a pszichózis ellen szól."},{"t":"tf","q":"Pszichotikus profilnál az F skála 80T felett is elfogadható.","a":true,"e":"Mert a pszichózis okozza."},{"t":"mc","q":"Mit mutat az enyhe neurotikus profil?","o":["D-völgy a triászban, testi tünetek, Si↑","Pa és Ma extrém magas","Es nagyon alacsony","Csak az L emelkedett"],"a":0,"e":"Enyhe neurózisnál D-völgy formátum, testi tünetek jellemzők."},{"t":"match","q":"Párosítsd a profil oldalát a jelentéssel!","pairs":[["Bal oldal","tünetek"],["Jobb oldal","alkalmazkodás"],["Pa, Ma","pszichózis minősége"]],"e":"A bal oldal mutatja a tüneteket, a jobb az alkalmazkodást."},{"t":"mc","q":"Mi a kiértékelés ELSŐ lépése?","o":["A profil validitásának ellenőrzése","Diagnózis felállítása","A csúcskódok keresése","Az alskálák elemzése"],"a":0,"e":"Először: valid-e a profil, szimulál-e vagy disszimulál."},{"t":"tf","q":"A szuicidumveszélyre utalhat a ↑D, ↑Pt, ↑A és az alacsony Es.","a":true,"e":"Ezek együtt jelezhetik az öngyilkossági veszélyt."},{"t":"fill","q":"Az énerőt jelző skála rövidítése ___ (alacsony a pszichotikus profilban).","a":["Es","ES","es"],"e":"Es = énerő; pszichózisban tipikusan alacsony."}]},{"id":"u17l5","title":"Cloninger modellje és a TCI","theory":[["Temperamentum és karakter","A személyiség két összetevője. <b>Temperamentum</b>: öröklött, relatíve stabil, automatikus emocionális válaszok, a személyiség érzelmi magja – limbikus rendszer, striatum. <b>Karakter</b>: belátásos tanulással változik, a temperamentum, a család és az élettapasztalat alakítja – hippocampus, halántéklebeny."],["Dimenziók","Temperamentum (4): <b>újdonságkeresés, ártalomkerülés, jutalomfüggőség, kitartás</b>. Karakter (3): <b>önirányítottság, együttműködés, transzcendencia</b>. Cloninger integrálja a biológiát és pszichológiát, az egészséget és betegséget (kontinuum)."],["Kialakulás","1) TPQ: 3 temperamentumfaktor, 80 tétel – elkülöníti a személyiségzavarok típusait, de az egészségest a betegtől nem. 2) + kitartás és a karakterfaktorok. 3) <b>TCI</b>: 240 tétel, elkülöníti az egészségest a betegtől és a zavar altípusait."],["A TCI jellemzői","240 állítás, igaz–nem igaz, 25–40 perc. Van junior (7–14 év), interjús és társjellemzős változat; számítógépen is kitölthető, egyéni és csoportos felvétel. <b>30 megválaszolatlan tételnél</b> értékelhetetlen; kézzel nem értékelhető."]],"qs":[{"t":"mc","q":"Hány tételes a TCI?","o":["240","80","244","566"],"a":0,"e":"A TCI 240 tételes, a TPQ 80 tételes volt."},{"t":"mc","q":"Melyik a temperamentumdimenzió?","o":["Újdonságkeresés","Önirányítottság","Együttműködés","Transzcendencia"],"a":0,"e":"A másik három a karakterdimenziók."},{"t":"match","q":"Párosítsd az összetevőt az agyi struktúrával!","pairs":[["Temperamentum","limbikus rendszer, striatum"],["Karakter","hippocampus, halántéklebeny"]],"e":"Különböző agyi struktúrákhoz kötődnek, de kapcsolatban állnak."},{"t":"tf","q":"A karakter belátásos tanulással folyamatosan változik.","a":true,"e":"A temperamentum ezzel szemben öröklött, relatíve stabil."},{"t":"mc","q":"Mit nem tudott a TPQ?","o":["Elkülöníteni az egészségest a betegtől","Mérni az újdonságkeresést","Megkülönböztetni a személyiségzavar típusait","Mérni az ártalomkerülést"],"a":0,"e":"A TPQ csak a zavarok típusait különítette el, az egészségest és a beteget nem."},{"t":"mc","q":"Hány megválaszolatlan tételnél értékelhetetlen a TCI?","o":["30 felett","5 felett","60 felett","Minden hiánynál"],"a":0,"e":"30 megválaszolatlan állításnál értékelhetetlen."},{"t":"fill","q":"A TCI junior változata ___ és 14 éves kor között használható.","a":["7","hét"],"e":"Junior változat: 7–14 évesek."},{"t":"tf","q":"A TCI-t empirikus alapon állították össze.","a":false,"e":"Teoretikus alapon készült."}]},{"id":"u17l6","title":"TCI: faktorok, értékelés, zavarok","theory":[["Temperamentumfaktorok","<b>NS</b> újdonságkeresés (dopamin): magas – impulzív, féktelen, hamar megunja. <b>HA</b> ártalomkerülés (szerotonin): magas – óvatos, aggodalmaskodó, félénk. <b>RD</b> jutalomfüggőség (noradrenalin): magas – empatikus, elismerésre vágyó. <b>P</b> kitartás: magas – szorgalmas, perfekcionista."],["Karakterfaktorok","<b>Önirányítottság</b>: felelősség, célok, önelfogadás, kielégülés-halasztás. <b>Együttműködés</b>: tolerancia, empátia, segítőkészség. <b>Transzcendencia</b>: önmagán túli azonosulás, spiritualitás. A karakterfaktorok mutatják, hogy van-e személyiségzavar (50-es vágóérték); a temperamentum, hogy milyen."],["T-értékek a TCI-ben","Átlagos: <b>45–55</b>; enyhén átlag alatti 40–45, felette 55–60; jelentősen alatti 30–40, felette 60–70; nagyon jelentősen alatti 30 alatt, felette 70 felett."],["Zavarok a TCI-ben","<b>A klaszter</b> (paranoid, szkizoid, szkizotip): alacsony jutalomfüggőség. <b>B klaszter</b> (antiszociális, nárcisztikus, borderline, hisztrionikus): alacsony önirányítottság és együttműködés, magas újdonságkeresés. <b>C klaszter</b> (elkerülő, dependens, kényszeres): magas ártalomkerülés."],["További klinikai minták","Major depresszió: magas HA és transzcendencia, alacsony önirányítottság és együttműködés. Szorongás: magas HA. Impulzivitás: magas HA és NS, alacsony önirányítottság/együttműködés. Szerdependencia: magas NS. Szuicídumveszély: magas jutalomfüggőség. Kényszeres: magas kitartás."]],"qs":[{"t":"match","q":"Párosítsd a faktort a neurotranszmitterrel!","pairs":[["Újdonságkeresés","dopamin"],["Ártalomkerülés","szerotonin"],["Jutalomfüggőség","noradrenalin"]],"e":"Cloninger szerint ezek a faktorok biológiai hátterei."},{"t":"mc","q":"Mi jelzi, hogy VAN-E személyiségzavar?","o":["A karakterdimenziók","A temperamentum","Csak a kitartás","A TCI nem jelez"],"a":0,"e":"A karakter mutatja, hogy van-e, a temperamentum azt, hogy milyen."},{"t":"mc","q":"Melyik klaszter jellemzője a magas ártalomkerülés?","o":["C (szorongó)","A (bizarr)","B (teátrális)","Egyik sem"],"a":0,"e":"Elkerülő, dependens, kényszeres – magas HA."},{"t":"mc","q":"Melyik klaszterhez tartozik a borderline személyiségzavar?","o":["B","A","C","Egyikhez sem"],"a":0,"e":"B klaszter: antiszociális, nárcisztikus, borderline, hisztrionikus."},{"t":"mc","q":"Mi az átlagos tartomány a TCI-ben?","o":["45–55 T","40–60 T","30–40 T","60–70 T"],"a":0,"e":"Átlagos: 45–55; 40–45 enyhén alatti."},{"t":"tf","q":"Az A klaszter előrejelzője az alacsony jutalomfüggőség.","a":true,"e":"Paranoid, skizoid, skizotip zavarok."},{"t":"tf","q":"Szerdependenciára a magas ártalomkerülés jellemző.","a":false,"e":"Szerdependenciánál a magas újdonságkeresés a jellemző."},{"t":"fill","q":"Magas ___ (rövidítés: NS) esetén az ember impulzív, hamar megunja a dolgokat.","a":["újdonságkeresés","ujdonsagkeresés","ujdonsagkereses","újdonságkeresés (NS)"],"e":"NS = újdonságkeresés."},{"t":"mc","q":"Melyik a karakterdimenzió?","o":["Együttműködés","Kitartás","Jutalomfüggőség","Ártalomkerülés"],"a":0,"e":"Karakter: önirányítottság, együttműködés, transzcendencia."}]},{"id":"u17l7","title":"Young: sématerápia és kérdőív","theory":[["Miért jött létre?","Integratív elmélet (1990, Young), alapja a kognitív viselkedésterápia (+ pszichoanalízis, Gestalt, kötődéselmélet, tárgykapcsolat, konstruktivizmus). A KVT az I. tengelyes zavaroknál hatásos, a <b>II. tengelyes zavaroknál</b> (személyiségzavarok, krónikus problémák) nem: kicsi az együttműködés, alacsony önismeret, rugalmatlanság, nehéz a kapcsolat, diffúz problémák."],["Korai maladaptív séma","Kiterjedt, mindent átfogó mintázat: kogníciók, emóciók, emlékek, testi érzések. Gyermekkorban alakul ki, életen át finomodik, önfenntartó és önsorsrontó; megváltoztatható, de teljesen nem gyógyítható. Biológiai háttér: <b>amygdala</b> – gyors, nem tudatos, az érzelem megelőzi a kogníciót."],["Megküzdési stílusok és sématartományok","Stílusok: <b>túlkompenzáló</b> (a séma ellentétét játssza), <b>elkerülő</b>, <b>elfogadó</b>. Tartományok: elszakítottság és elutasítottság; károsodott autonómia; határok károsodott volta; kóros másokra irányultság; aggályosság és gátlás."],["A Young-féle kérdőív","<b>244 item</b>, 6 fokú skála. Sémánként az itemek átlagát számoljuk. Ha az érték <b>3 vagy magasabb</b>, a séma aktívnak tekinthető (a 3-hoz közeli értékeket is figyelembe vesszük). A pontszámokat a megküzdési stílusok figyelembevételével értelmezzük."]],"qs":[{"t":"mc","q":"Hány itemből áll a Young-féle séma kérdőív?","o":["244","240","566","80"],"a":0,"e":"244 item, 6 fokú skálán."},{"t":"mc","q":"Mikor tekintünk egy sémát aktívnak?","o":["Ha az átlag 3 vagy több","Ha az átlag 1 alatti","Ha a nyerspont 50T","Ha az F skála emelkedik"],"a":0,"e":"3 vagy magasabb átlagnál aktív a séma."},{"t":"mc","q":"Melyik agyterülethez kötik a sémák kialakulását?","o":["Amygdala","Cerebellum","Occipitális lebeny","Broca-terület"],"a":0,"e":"Az amygdala gyors, nem tudatos, előbb jön az érzelem, mint a kogníció."},{"t":"match","q":"Párosítsd a megküzdési stílust a leírással!","pairs":[["Túlkompenzáló","a séma ellentétét játssza"],["Elkerülő","mintha nem létezne a séma"],["Elfogadó","a séma igaz, megerősíti"]],"e":"A három maladaptív megküzdési stílus."},{"t":"tf","q":"A korai maladaptív sémákat teljesen meg lehet gyógyítani.","a":false,"e":"Változtatni lehet rajtuk, intenzitásuk csökkenthető, de teljesen nem gyógyíthatók."},{"t":"mc","q":"Melyik NEM nagy sématartomány?","o":["Fokozott szociális ingerlékenység","Elszakítottság és elutasítottság","Határok károsodott volta","Aggályosság és gátlás"],"a":0,"e":"Az öt tartomány: elszakítottság/elutasítottság, károsodott autonómia, határok károsodott volta, kóros másokra irányultság, aggályosság/gátlás."},{"t":"mc","q":"Miért nem elég a KVT személyiségzavaroknál?","o":["Rugalmatlanok, az ő problémájuk az én-azonosság része, nem elég a belátás","Túl gyorsan gyógyulnak","Mindig magas az önismeretük","Nincs szükségük kapcsolatra"],"a":0,"e":"Nem elég a belátás, a zavar egoszinton."},{"t":"fill","q":"A sématerápia első fázisa a diagnosztikai és ___ fázis.","a":["edukációs","edukacios","edukációs fázis"],"e":"Az első fázis diagnosztikai és edukációs, a második a változás."}]}],"color":"#00cd9c"},{"id":"u18","title":"Projektív tesztek, Rorschach","desc":"Projekció, alapelvek, Rorschach-jelölés","lessons":[{"id":"u18l1","title":"A projekció fogalma","theory":[["Freudi projekció","Freud (1895): tudattalan impulzusok, érzések, attitűdök másoknak tulajdonítása, <b>elhárító mechanizmus</b>, amelyet intrapszichés konfliktus hív elő; csökkenti az ösztönfeszültséget, áthárítja a felelősséget és védi az önértékelést. Lényege: a folyamat tudattalan, és elhárítás."],["Tágabb értelmezések","Freud másik értelmezése: az érzet okát nem magunkban, hanem kívül keressük – konfliktus nélkül is működik. Rapaport: minden viselkedés projektív. Jung: a tudattalan tartalmak folyamatosan kivetülnek a környezetre."],["Cramer három formája","1) A személy tudatában van, hogy saját gondolatát vetíti (generalizáció, animisztikus gondolkodás). 2) Az én és a tárgy elkülönül, a sajátjaként felismerheti, de a felelősséget másnak tulajdonítja. 3) <b>Klasszikus projekció</b>: tudattalan. Murstein és Pryer: klasszikus, attributív, autisztikus, racionalizált."],["Projektív teszt","Kevéssé strukturált, <b>többértelmű</b> tesztinger, amelyre sokféleképp lehet válaszolni. A válaszok idiografikusak, nem az inger, hanem a személyiség határozza meg őket. <b>Projekciós hajlam</b>: mennyire vezérlik a percepciót belső minták azonos ingerfeltételek mellett."]],"qs":[{"t":"mc","q":"Ki írta le a klasszikus projekciófogalmat 1895-ben?","o":["Freud","Jung","Rapaport","Frank"],"a":0,"e":"A klasszikus projekció Freudtól ered."},{"t":"tf","q":"A klasszikus freudi projekció tudattalan folyamat és elhárító mechanizmus.","a":true,"e":"Ez a két lényegi jegye."},{"t":"mc","q":"Ki tartotta az ember minden viselkedését projektívnak?","o":["Rapaport","Freud","Cramer","Lindzey"],"a":0,"e":"Rapaport (1942) szerint minden viselkedés projektív."},{"t":"mc","q":"Cramer szerint melyik forma tudattalan?","o":["A harmadik, a klasszikus projekció","Az első, generalizáció","A második, felelősség áttolása","Egyik sem"],"a":0,"e":"A harmadik forma a klasszikus, tudattalan projekció."},{"t":"match","q":"Párosítsd a szerzőt a nézetével!","pairs":[["Freud","elhárító mechanizmus"],["Jung","tudattalan tartalmak kivetülése"],["Rapaport","minden viselkedés projektív"]],"e":"A projekció különböző értelmezései."},{"t":"fill","q":"A projektív tesztek ingere kevéssé strukturált, azaz ___.","a":["többértelmű","tobbertelmu","ambivalens","ambiguus","ambiguitás"],"e":"A többértelmű inger sokféle válaszra ad lehetőséget."},{"t":"mc","q":"Mit jelent a projekciós hajlam?","o":["Mennyire vezérlik a percepciót belső minták azonos ingerfeltételek mellett","A tesztfelvétel hossza","A válaszok száma","A teszt standardizáltsága"],"a":0,"e":"A személyiség jellemzője."},{"t":"tf","q":"A projektív tesztekre adott válaszokat az inger határozza meg nagyobb mértékben, mint a személyiség.","a":false,"e":"Éppen fordítva: kevéssé határozza meg az inger, inkább a személyiség jellemzői."}]},{"id":"u18l2","title":"Projektív technikák alapelvei","theory":[["Jellemzők","Lindzey: a technika érzékeny a rejtett, tudattalan összetevőkre, sokféle válasz lehetséges, multidimenzionális, a személy a teszt céljának minimálisan van tudatában. Az értelmezés <b>holisztikus</b> (globális, szemben a kérdőívek atomisztikus szemléletével), <b>nincsenek jó vagy rossz válaszok</b>, nehezen számszerűsíthető."],["Osztályozások","<b>Frank</b>: konstitutív (struktúra adása, pl. agyagozás), interpretatív (jelentés adása: TAT, Rorschach), katartikus (bábozás, pszichodráma), konstruktív (világjáték). <b>Allport</b>: perceptív, apperceptív, produktív. <b>Johnson–Gloye</b>: standard (Rorschach), köztes (DAP, HTP), spontán."],["Strukturálatlanság","Minél kevésbé strukturált a helyzet, annál nagyobb a válasz szabadságfoka. Stone és Dellis szinthipotézise: minél kevésbé strukturált az inger, annál kevésbé tudatos a kapott adat. Frank: az inger jelentése a személyiség függvénye – az egyén „private world”-jét vetíti ki."],["Regresszió és tulajdonítás","A tesztszituáció <b>regresszív</b>: formális (elvont → képi gondolkodás), kronologikus (felnőtt → gyermek), topikus (realitás → képzelet). Tulajdonítások: <b>tükröző</b> (önmagáról beszél), <b>vágyteljesítő</b> (nappali álmodozás), <b>motiváló/reciprok</b> (a világra olyan vonásokat ruház, amelyek magatartását indokolják)."]],"qs":[{"t":"mc","q":"Frank szerint melyik a konstitutív projektív teszt?","o":["Agyagozás","TAT","Rorschach","Pszichodráma"],"a":0,"e":"Konstitutív: a személy struktúrát ad a strukturálatlan ingernek (agyagozás, ujjal festés)."},{"t":"match","q":"Párosítsd Frank típusait a példával!","pairs":[["Interpretatív","TAT, Rorschach"],["Katartikus","bábozás, pszichodráma"],["Konstruktív","világjáték"]],"e":"Frank négy típusa közül három."},{"t":"tf","q":"A projektív tesztekben vannak jó és rossz válaszok.","a":false,"e":"Nincsenek jó vagy rossz válaszok."},{"t":"mc","q":"Melyik a Johnson–Gloye-féle köztes típus példája?","o":["DAP, HTP","Rorschach","Szabadrajz","Ujjal festés"],"a":0,"e":"A köztes típusban kontrollált a produkció, az értelmezés jórészt formalizált."},{"t":"mc","q":"Milyen regresszió, amikor a gondolkodás elvontból képi gondolkodásba tér vissza?","o":["Formális","Kronologikus","Topikus","Affektív"],"a":0,"e":"Kronologikus: felnőttből gyermek; topikus: realitásból képzelet."},{"t":"mc","q":"Mit jelent a tükröző tulajdonítás?","o":["A személy a foltban önmagát látja, önmagáról beszél","Nappali álmodozását folytatja","A világra viselkedését indokoló vonásokat ruház","Elutasítja a feladatot"],"a":0,"e":"Vágyteljesítő: nappali álmodozás; motiváló: magatartását indokoló vonások."},{"t":"tf","q":"A projektív technikák értelmezése holisztikus, a kérdőívek viszont atomisztikus megközelítésűek.","a":true,"e":"A projektív eljárások a személyiség egészét képezik le."},{"t":"fill","q":"Allport három osztálya: perceptív, apperceptív és ___.","a":["produktív","produktiv"],"e":"A produktívba a rajzok, pszichodráma, bábjáték tartoznak."}]},{"id":"u18l3","title":"Rorschach: a jelölés öt oszlopa","theory":[["Alapfeltevés","A strukturálatlan anyag (folt) rendezésében az életünk során kialakult egyéni szemléleti, gondolkodási és viselkedési szokásaink érvényesülnek. A jegyzőkönyv <b>öt oszlopba</b> jelöl."],["Az öt oszlop","1) <b>Felfogásmód</b>: a folt mekkora részét ragadja ki (13 jel). 2) <b>Determinánsok</b>: milyen formai jegyek határozzák meg a választ – forma, szín, árnyalás, fehér háttér, mozgás. 3) <b>Tartalom</b> (48 csoport). 4) <b>Gyakoriság</b> (vulgér–originális). 5) <b>Különleges reakciók</b> (130 jel, 15 csoportban)."],["Felfogásmód jelei","<b>G</b> egész (lényeg), <b>D</b> nagy rész (reális tárgyi világ), <b>Dd</b> kis rész (részletek, precizitás), <b>zw</b> fehér közterület (energetika, oppozíció), <b>DO</b> fehér háttér, fék vagy gátlás. A G-nél a Gzw is benne van, a D-nél a Dzw és DzwG nincs."],["Felfogótípus (FT)","A felfogásmód jeleinek aránya a válaszok számához és a normál standardhoz viszonyítva. Ha egy jel több a viszonyítási alapnál, egyszer-kétszer aláhúzzuk, ha kevesebb, zárójelezzük. Leggyakoribb: G–D–zw és G–D. Globális vázlatot ad a személyiségről, nem patológiát."]],"qs":[{"t":"mc","q":"Hány oszlopban jelölünk a Rorschach jegyzőkönyvben?","o":["5","3","7","10"],"a":0,"e":"Felfogásmód, determinánsok, tartalom, gyakoriság, különleges reakciók."},{"t":"match","q":"Párosítsd az oszlopot a tartalmával!","pairs":[["1. oszlop","felfogásmód"],["2. oszlop","determinánsok"],["3. oszlop","tartalom"],["5. oszlop","különleges reakciók"]],"e":"A jegyzőkönyv oszlopai."},{"t":"mc","q":"Mit jelent a G jel?","o":["Egész folt, a lényeg megragadása","Kis részlet","Fehér közterület","Fehér háttér"],"a":0,"e":"G: egész; D: nagy rész; Dd: kis rész."},{"t":"match","q":"Párosítsd a felfogásmód jelét a jelentéssel!","pairs":[["D","reális tárgyi világ"],["Dd","részletek, precizitás"],["zw","energetika"]],"e":"A felfogásmód jegyeinek jelentése."},{"t":"tf","q":"Az FT (felfogótípus) az egyes patológiákról beszél.","a":false,"e":"Nem patológiát, hanem globális vázlatot ad a személyiségről, életvezetésről, alkalmazkodásról."},{"t":"mc","q":"Hogyan jelöljük az FT-ben, ha egy jel a normál standardhoz képest több?","o":["Aláhúzzuk","Zárójelbe tesszük","Töröljük","Csillaggal jelöljük"],"a":0,"e":"Több: egyszer-kétszer aláhúzzuk; kevesebb: zárójelezzük."},{"t":"fill","q":"A Rorschach-ban a determinánsok oszlopa azt mutatja, hogy a választ milyen ___ jegyek határozzák meg.","a":["formai","formális"],"e":"Forma, szín, árnyalás, fehér háttér, mozgás."},{"t":"tf","q":"A leggyakoribb felfogótípus a G–D–zw és a G–D.","a":true,"e":"Ezek a legáltalánosabbak."}]},{"id":"u18l4","title":"Szukcesszió, forma- és színválaszok","theory":[["Szukcesszió","A felfogásmódok sorrendje. <b>Szigorú</b>: G/DG – D/Dzw – Dd/DO: egyre mélyülő szemlélet, következetesség, komolyan veszi a helyzeteket. <b>Fordított</b>: Dd – D – G: disszimuláció, titkolózás, tudatosan nem egyenes. <b>Szétesett</b>: övezetet átugrik – tartásnélküliség, labilitás, tünetjelző."],["Forma és szín","<b>Forma</b>: racionalitás, mentális kontroll. <b>Szín</b>: érzelmek, indulatok. <b>Fekete</b>: depresszív hangulat, diszfória, szorongás. <b>Fehér</b>: eufória, hangulati ingadozás. <b>Árnyékolás</b>: szorongás."],["F% mutatók","<b>F%</b>: mentális kontroll. <b>F1%</b>: kontroll érzelemmentes helyzetben (optimum 80–85%). <b>F2%</b>: kontroll félelmek, indulatok, fantáziák mellett. F1% > F2%: indulati hárítás, „kiszikkadt értelem”. F2% > F1%: érzelmileg átmelegített értelem, külső motiváció kell."],["F1–F2 eltérés","A különbség 4%-nál enyhe tendencia, nagyobb eltérésnél erőteljes, <b>12% fölött</b> az értelem és az érzelem szétválasztásának központi problémája."],["Színválaszok fejlődési sora","<b>FFb</b>: indulat mentális kontrollal. <b>FbF</b>: az indulat túlsúlyban, a helyzet determinálja a cselekvést, labilis alkalmazkodás. <b>Fb</b>: indulatkitörés, lobbanékonyság, regresszióra hajlam. <b>Fbn</b>: a mentális fék teljes hiánya, indulati szélsőségesség."]],"qs":[{"t":"mc","q":"Mit jelez a fordított szukcesszió?","o":["Disszimulációt, rejtőzködést","Következetes szemléletet","Szétesettséget","Magas intelligenciát"],"a":0,"e":"Dd – D – G: tudatosan nem egyenes, titkolózó."},{"t":"mc","q":"Mit jelez a szigorú szukcesszió?","o":["Következetes, egyre mélyülő szemlélet","Tartásnélküliség","Titkolózás","Pszichotikus állapot"],"a":0,"e":"G – D – Dd sorrend."},{"t":"match","q":"Párosítsd a determinánst a jelentéssel!","pairs":[["Forma","mentális kontroll"],["Szín","érzelmek, indulatok"],["Fekete","depresszív hangulat"],["Fehér","eufória"]],"e":"Az alapvető determinánsok."},{"t":"mc","q":"Mi az F1% optimuma?","o":["80–85%","50–60%","95–100%","20–30%"],"a":0,"e":"Az F1% optimális tartománya 80–85%."},{"t":"mc","q":"Mit jelent, ha F1% > F2%?","o":["Erőteljes indulati hárítás, kiszikkadt értelem","Érzelmileg átmelegített értelem","Optimális kontroll","Kontrollhiány"],"a":0,"e":"Az értelem akkor hatékony, ha nincsenek érzelmek."},{"t":"tf","q":"Ha az F1% és az F2% között 12%-nál nagyobb a különbség, az az értelem és érzelem szétválasztásának központi problémáját jelzi.","a":true,"e":"4% enyhe tendencia, 12% fölött központi probléma."},{"t":"mc","q":"Melyik színválasz jelzi a mentális fék TELJES hiányát?","o":["Fbn","FFb","FbF","Fb"],"a":0,"e":"Az Fbn a regresszió és az indulati szélsőségesség indikátora."},{"t":"fill","q":"Az árnyékolásválaszok a ___ mutatói.","a":["szorongás","szorongás mutatói","szorongas"],"e":"Árnyékolás: szorongás."}]},{"id":"u18l5","title":"Fekete, fehér, árnyék és mozgásválaszok","theory":[["Fekete és fehér színválaszok","<b>nFFb</b>: kísérlet a hangulati letörések kontrolljára; <b>nFbF</b>: törékeny önértékelés, elsodorja a hangulat; <b>nFb</b>: fékezetlen diszfória. <b>aFFb</b>: az eufóriás reakció fékezése; <b>aFbF</b>: egzaltáltság, kritikátlanság; <b>aFb</b>: fékezetlen eufória, alacsony frusztrációs tolerancia."],["Árnyékolásválaszok","<b>FHd</b>: kísérlet a szorongás kontrolljára (– esetben szorongás-projekció, paranoiditás). <b>HdF</b>: a szorongás uralja az értelmi féket. <b>Hd</b>: feldolgozatlan szorongás, pánik, halálfélelem. <b>F(Fb)</b> (+): empátia, decentrálás, másokra való érzékenység."],["B – mozgásválaszok","<b>B</b>: introverzió, gazdag belső élet, mentális rugalmasság, önismeret, „optimális fék”. <b>3–4 B</b> színvonalas jegyzőkönyv; <b>5 vagy több B</b>: túl erős fékek, elfojtott érzelmek. <b>(–) B</b>: pszichotikus állapot."],["Mozgásválasz-típusok","<b>Bsec</b>: gátolt, de menetkész állapot (várakozási bénultság). <b>Bkl</b>: mágikus valóság, fantáziaélet kompenzál. <b>BF</b>: azonosulási feszültség, éretlenség, de terápiás alkalmasság. <b>b</b>: kudarcélmény, önértékelési válság. <b>AsszocB</b>: vágyteljesítő fordulatok. <b>AbsztraktB</b>: pszichotikus, bizarr."],["Adekváció","Az elaboráció sikerét jelzi: <b>(+)</b> kontrollált, sikeres; <b>()</b> bizonytalan, labilis, hullámzó; <b>(–)</b> kontrollálatlan, sikertelen."]],"qs":[{"t":"mc","q":"Hány B-válasz jelent színvonalas jegyzőkönyvet?","o":["3–4","0","5 vagy több","10 felett"],"a":0,"e":"3–4 B = színvonalas; 5-nél több túl erős fék."},{"t":"match","q":"Párosítsd a jelet a jelentéssel!","pairs":[["nFb","fékezetlen diszfória"],["aFb","fékezetlen eufória"],["Hd","feldolgozatlan szorongás"],["B","introverzió, belső élet"]],"e":"Determinánsok jelentése."},{"t":"mc","q":"Mit mutat az 5 vagy több B?","o":["Túl erős fékek, elfojtott érzelmek","Gazdag, jól integrált belső élet","Extraverziót","Fantáziaszegénységet"],"a":0,"e":"Nehezen kötődik, az érzelmek belső megélése intenzív, de nehezen fejezi ki."},{"t":"mc","q":"Mit jelez a (–) adekváció?","o":["Kontrollálatlan, sikertelen elaboráció","Sikeres kontroll","Bizonytalan kontroll","Hullámzó kontroll"],"a":0,"e":"(+) sikeres, () labilis, (–) sikertelen."},{"t":"tf","q":"A BF sok előfordulása azonosulási feszültségre és éretlenségre utal, de terápiás alkalmasságot is jelezhet.","a":true,"e":"A személy keresi önmagát, van befogadási potenciálja."},{"t":"mc","q":"Mit jelez az AbsztraktB?","o":["Pszichotikus, bizarr, fellazult viselkedést","Önismeretet","Fantáziagazdagságot","Mentális rugalmasságot"],"a":0,"e":"Tartalmatlan, nagyfokú izgatottság."},{"t":"mc","q":"Melyik válasz jelez pánikfélelmet, halálfélelmet?","o":["Hd","FHd+","F(Fb)+","BF"],"a":0,"e":"Hd: feldolgozás nélküli szorongás, időnként pszichotikus szintű."},{"t":"fill","q":"A ___ mozgásválasz a mágikus valóság szintje, a fantáziaélet kompenzál (Bkl/Bsec/BF).","a":["Bkl","bkl"],"e":"Bkl: mágikus valóság, fantáziaélet."}]},{"id":"u18l6","title":"Típusmutatók, tartalom, felszólító jelleg","theory":[["Típusmutatók","<b>ÉT</b> (élménytípus): mozgás- és színválaszok aránya, az én és a külvilág viszonya, 12 féle. <b>MF</b> (másodlagos formula): mozgás- és árnyékolásválaszok viszonya, 4 féle, belső erőtér. <b>IT</b> (indulati típus, Mérei): zw- és árnyékolásválaszok aránya, 4 féle – az agresszió és a szorongás összefüggése."],["Tartalmi mutatók","Átlagos válaszszám 12, szóródás (össztartalom/összválasz) 1,1–1,3 (1,3 felett magas elaboráció). Nincs emberválasz: nem vonódott be. Szakmai válasz 60% felett: bezárkózás. <b>M%</b>: átlag 15%, emberi dolgok iránti érzékenység. <b>T%</b> (viselkedéses fék): optimum 35–45%; 70% felett kóros, sztereotip."],["Vulgér–originális","<b>V%</b>: mennyire alkalmazkodik a közgondolkodáshoz (konformitás, normakövetés). <b>RI</b> (Neiger): 16 vulgér válasz alapján, a realitásérzék mutatója. Fékrendszer: F% (mentális), T% (viselkedéses), V% (konformitás)."],["Felszólító jelleg","Versagen: stupor, asszociatív zárlat – konfliktus. Sokk: pánik. Ütközés: megtorpanás. Zavar: lámpaláz. A táblák: <b>I</b> bemutatkozás, <b>II</b> nyers érzelmek, <b>III</b> önismeret, énerő, <b>IV</b> autoritás (apa), <b>V</b> realitás, <b>VI</b> szexualitás, <b>VII</b> nőiség, anya, <b>VIII</b> kapcsolati képesség, <b>IX</b> teljesítmény, <b>X</b> jövő."]],"qs":[{"t":"match","q":"Párosítsd a mutatót azzal, amit viszonyít!","pairs":[["ÉT","mozgás és szín"],["MF","mozgás és árnyékolás"],["IT","zw és árnyékolás"]],"e":"Három típusmutató."},{"t":"mc","q":"Ki vezette be az IT-t (indulati típus)?","o":["Mérei","Neiger","Bellak","Murray"],"a":0,"e":"Az IT Mérei nevéhez fűződik; az RI Neigerhez."},{"t":"mc","q":"Mi a T% optimális tartománya?","o":["35–45%","10–20%","50–70%","70% felett"],"a":0,"e":"Egészséges szabálykövetés; 70% felett kóros."},{"t":"mc","q":"Mit mutat az RI?","o":["A valósághoz való adekvát viszonyt, realitásérzéket","Az indulati feszültséget","Az introverziót","A mentális kontrollt"],"a":0,"e":"16 vulgér válasz alapján számoljuk."},{"t":"match","q":"Párosítsd a táblát a jelentéssel!","pairs":[["IV. tábla","autoritás, apa"],["V. tábla","realitás"],["IX. tábla","teljesítmény"],["X. tábla","jövő"]],"e":"A táblák felszólító jellege."},{"t":"mc","q":"Mit jelent a Versagen?","o":["Stupor, asszociatív zárlat – konfliktus","Pánik","Lámpaláz","Rejtőzködés"],"a":0,"e":"A helyzet konfliktusos a vizsgált személy számára; címadás az utóteszben segít."},{"t":"tf","q":"A 60% fölötti szakmai válaszarány a foglalkozásba való bezárkózást jelezheti.","a":true,"e":"Validitásindikátor is."},{"t":"fill","q":"A szóródás (össztartalom/összválasz) átlaga 1,1–___.","a":["1,3","1.3"],"e":"1,3 felett magasabb fokú elaboráció."}]}],"color":"#e5a000"},{"id":"u19","title":"Teljesítménytesztek, MAWI","desc":"IQ, intelligenciaövezetek, MAWI próbái","lessons":[{"id":"u19l1","title":"Teljesítménytesztek és az IQ","theory":[["Teljesítményteszt","Maximális teljesítményt mérünk a vizsgálati szituációban, gyors és jó megoldás a cél. Fontos a beteg motiváltsága, koncentrációja, készenléti állapota. Példák: intelligenciatesztek (MAWI, HAWIK, Raven, Otis), neuropszichológiai tesztek, memóriavizsgálatok. A személyiségtesztet mindig először kell felvenni."],["Jó intelligenciateszt","<b>Reliábilis</b> (pontos) és <b>valid</b> (azt méri, amit kell). Az IQ története: mentális kor → <b>Stern</b>: mentális életkor / tényleges életkor × 100 → <b>Wechsler</b>: a páciens teljesítménye / korcsoport átlagteljesítménye × 100."],["Wechsler definíciója","Az intelligencia az egyénnek olyan összesített, globális képessége, amely lehetővé teszi, hogy célszerűen cselekedjen, racionálisan gondolkodjon és eredményesen bánjon a környezetével. Funkciókból áll, amelyek elkülöníthetők, mégis összefüggnek."],["Intelligenciaövezetek","68 alatt értelmi fogyatékos (F70 enyhe 50–68, F71 közepes 35–49, F72 súlyos 20–34). <b>69–79</b> igen alacsony, <b>80–90</b> alacsony, <b>91–109</b> átlagos, <b>110–120</b> magas, <b>121–130</b> igen magas, <b>131 felett</b> extrém magas."]],"qs":[{"t":"mc","q":"Mi a Wechsler-féle IQ számítás alapja?","o":["Egyéni teljesítmény / korcsoport átlaga × 100","Mentális kor / életkor × 100","Pontszám összege","Reakcióidő"],"a":0,"e":"Sternnél mentális életkor/tényleges életkor × 100; Wechslernél a korcsoporthoz viszonyítunk."},{"t":"match","q":"Párosítsd az IQ-tartományt a kategóriával!","pairs":[["69–79","igen alacsony"],["91–109","átlagos"],["110–120","magas"],["131 felett","extrém magas"]],"e":"Az intelligenciaövezetek."},{"t":"mc","q":"Melyik intelligenciateszt?","o":["MAWI","MMPI","TCI","Rorschach"],"a":0,"e":"A MAWI teljesítményteszt."},{"t":"tf","q":"A teljesítménytesztek akkor működnek jól, ha a beteg motivált és tud koncentrálni.","a":true,"e":"A megfelelő készenléti állapot nagyon fontos."},{"t":"mc","q":"Mi az F70 kategória?","o":["Enyhe értelmi fogyatékosság","Közepes értelmi fogyatékosság","Súlyos értelmi fogyatékosság","Igen súlyos értelmi fogyatékosság"],"a":0,"e":"F70 enyhe (50–68), F71 közepes (35–49), F72 súlyos (20–34)."},{"t":"fill","q":"Az átlagos intelligencia tartománya 91–___.","a":["109"],"e":"91–109 normális, átlagos."},{"t":"tf","q":"Az IQ fogalmát az mentális kor és az életkor hányadosa vezette be Stern révén.","a":true,"e":"Stern: mentális életkor / tényleges életkor × 100."},{"t":"mc","q":"Melyik sorrend helyes a tesztfelvételben?","o":["Először a személyiségtesztet kell felvenni","Először a teljesítménytesztet","Mindegy","Csak teljesítménytesztet veszünk fel"],"a":0,"e":"Teljesítményteszteknél a gyors, maximális teljesítmény számít."}]},{"id":"u19l2","title":"A MAWI jellemzői","theory":[["Alapadatok","Az intelligencia mérésére és a struktúra megbecslésére szolgál. <b>1970-ben standardizálták</b> (Kun Miklós, Szegedi Márton; 2002 fős reprezentatív minta). <b>10 részpróba</b>, felcserélhetők, megszakítható. <b>10–59 éves</b> korig, <b>45–90 perc</b>."],["Mikor nem vesszük fel?","Ha a beteg pszichotikus, szedált vagy látássérült. Depresszió vagy demencia esetén hosszabb lehet a felvétel. A beteg legyen éber, orientált, tesztre kész. Wechsler a normális eloszlást feltételezi, az egyént a korcsoportjához viszonyítja."],["Mire használjuk?","Intelligenciaérték mérése, struktúra feltérképezése, demencia megállapítása, korspecifikus profil vizsgálata, valamint információ a személyiségről a teszthelyzeti viselkedés alapján. A neuropszichiátriai kórképek különböző mértékben károsítják az intelligenciát."],["Csoportosítás","Első 5 próba <b>verbális</b>, második 5 <b>performációs</b> (cselekvéses). Másik csoportosítás: <b>korállandó</b> (1, 2, 4, 10) és <b>korváltozó</b> (3, 6, 7, 9) próbák. Mutatók: VQ, PQ, IQ (summa)."]],"qs":[{"t":"mc","q":"Hány részpróbából áll a MAWI?","o":["10","5","12","8"],"a":0,"e":"Első 5 verbális, második 5 performációs."},{"t":"mc","q":"Milyen korosztálynál használható a MAWI?","o":["10–59 év","3–14 év","18–80 év","6–17 év"],"a":0,"e":"10 és 59 éves kor között."},{"t":"mc","q":"Mikor NEM vesszük fel a MAWI-t?","o":["Pszichotikus, szedált vagy látássérült betegnél","Depressziós betegnél","Neurotikus betegnél","Egyetemi végzettségűnél"],"a":0,"e":"Depressziónál csak a felvétel ideje nőhet."},{"t":"tf","q":"A MAWI próbái felcserélhetők és a vizsgálat megszakítható.","a":true,"e":"A felvétel 45–90 perc."},{"t":"fill","q":"A MAWI-t 1970-ben standardizálta Kun Miklós és Szegedi ___.","a":["Márton","Marton"],"e":"2002 fős reprezentatív mintán."},{"t":"match","q":"Párosítsd a csoportot a próbákkal!","pairs":[["Korállandó","1, 2, 4, 10"],["Korváltozó","3, 6, 7, 9"],["Verbális","első 5 próba"],["Performációs","második 5 próba"]],"e":"A MAWI csoportosításai."},{"t":"mc","q":"Melyik információt NEM adja a MAWI?","o":["Projektív konfliktusok tartalmát","Intelligenciaszintet","Demenciára utaló jeleket","Intelligenciastruktúrát"],"a":0,"e":"A MAWI teljesítményteszt, nem projektív eljárás."}]},{"id":"u19l3","title":"MAWI: verbális próbák","theory":[["1. Ismeretek, 2. Helyzetek megértése","<b>Ismeretek</b> (25 pont): lexikális tudás, hosszú távú memória, érdeklődés; 4 egymás utáni hibánál befejezzük; jól korrelál az összteljesítménnyel. <b>Helyzetek megértése</b> (10 próba, 0–1–2 pont): normák, tipikus szokások; a beszámíthatóság megállapításánál is mérlegelik."],["3. Számismétlés, 4. Számolási","<b>Számismétlés</b> (17 pont): rendes és fordított sorrend; figyelem fenntartás, közvetlen megjegyzés, koncentráció; végső IQ-val kevésbé korrelál; (5 előre, 3 hátra = értelmi fogyatékosság). <b>Számolási</b>: 10 feladat, időre; logika, problémamegértés; jól korrelál az IQ-val, korállandó."],["5. Összehasonlítás, főfogalom","0–1–2 pont, összesen 24. Az absztrakciós képesség mérése: osztályozás, általánosítás, elvonatkoztatás. <b>Organikus károsodásra érzékeny</b> próba."]],"qs":[{"t":"match","q":"Párosítsd a próbát azzal, amit mér!","pairs":[["Ismeretek","lexikális tudás, hosszú távú memória"],["Számismétlés","figyelem, közvetlen megjegyzés"],["Számolási","logika, problémamegértés"],["Összehasonlítás","absztrakció, fogalomalkotás"]],"e":"A verbális próbák funkciói."},{"t":"mc","q":"Hány pont az Ismeretek próba maximuma?","o":["25","17","24","67"],"a":0,"e":"Minden kérdés 1 pont, 4 egymás utáni hibánál befejezzük."},{"t":"mc","q":"Melyik próba érzékeny az organikus károsodásra?","o":["Összehasonlítás – főfogalom","Ismeretek","Rejtjelzés","Mozaik"],"a":0,"e":"Az absztrakciós képességet méri."},{"t":"tf","q":"A Számismétlés próba végső IQ-val való korrelációja kisebb, mint az Ismereteké vagy a Számolásié.","a":true,"e":"A számismétlés kevésbé korrelál a végső IQ-val."},{"t":"mc","q":"Mely próba mérlegelendő a beszámíthatóság megállapításánál?","o":["Helyzetek megértése","Számolási","Számismétlés","Összehasonlítás"],"a":0,"e":"A helyzetek megértése normákat, tipikus szokásokat mér."},{"t":"fill","q":"A Számismétlésben a próba két része: rendes és ___ sorrend.","a":["fordított","forditott"],"e":"Rendes és fordított sorrendű számismétlés."},{"t":"mc","q":"A Számolási próba milyen típusú?","o":["Időre, korállandó","Időre, korváltozó","Idő nélküli, korváltozó","Rajzos"],"a":0,"e":"10 feladat, időre; korállandó."},{"t":"tf","q":"A Számismétlés maximum pontszáma 17.","a":true,"e":"A hibázásnál 2 hibánál megállunk."}]},{"id":"u19l4","title":"MAWI: performációs próbák","theory":[["6. Rejtjelzés, 7. Képrendezés","<b>Rejtjelzés</b> (időre, 67 pont): szimbólumok társítása; vizuomotoros koordináció, pszichomotoros gyorsaság, tanulási képesség, kitartás; korváltozó. <b>Képrendezés</b>: lényegkiemelés, ok-okozati viszonyok, szociális intelligencia, humor; fontos a beszámíthatóság mérlegelésében; korváltozó."],["8. Képkiegészítés, 9. Mozaik","<b>Képkiegészítés</b> (15 pont): alakfelismerés, analitikus műveletek, lényeges és lényegtelen megkülönböztetése. <b>Mozaik</b> (42 pont, idő + pont): téri tájékozódás, vizuális analízis-szintézis, szemléleti mozgékonyság, frusztrációtűrés; korváltozó."],["10. Szintézis","Idő + pont; rosszul korrelál a MAWI többi próbájával, <b>kultúrafüggetlen</b>. Hipotézisalkotás és -felülvizsgálat, kreativitás, problémamegoldás, téri funkció, analízis-szintézis; korállandó."]],"qs":[{"t":"match","q":"Párosítsd a próbát azzal, amit mér!","pairs":[["Rejtjelzés","vizuomotoros koordináció, gyorsaság"],["Mozaik","téri tájékozódás, frusztrációtűrés"],["Képkiegészítés","alakfelismerés, lényeges/lényegtelen"],["Szintézis","hipotézisalkotás, kreativitás"]],"e":"A performációs próbák."},{"t":"mc","q":"Melyik próba kultúrafüggetlen?","o":["Szintézis","Ismeretek","Helyzetek megértése","Számismétlés"],"a":0,"e":"A szintézis próba rosszul korrelál a többivel, kultúrafüggetlen."},{"t":"mc","q":"Hány pont a Képkiegészítés összpontszáma?","o":["15","42","67","25"],"a":0,"e":"Minden helyes válasz 1 pont."},{"t":"tf","q":"A Rejtjelzés korváltozó, időre végzett próba.","a":true,"e":"Max. 67 pont."},{"t":"mc","q":"Melyik a Mozaik próba maximuma?","o":["42","15","67","24"],"a":0,"e":"Idő szerinti pontok + pontok."},{"t":"mc","q":"Melyik próba méri a szociális intelligenciát és humort is?","o":["Képrendezés","Képkiegészítés","Mozaik","Rejtjelzés"],"a":0,"e":"Képrendezés: lényegkiemelés, ok-okozat, szociális intelligencia."},{"t":"fill","q":"A MAWI 8. próbája a ___.","a":["Képkiegészítés","képkiegészítés","kepkiegeszites","képkiegészítés"],"e":"8. Képkiegészítés, 9. Mozaik, 10. Szintézis."},{"t":"tf","q":"A Szintézis próba jól korrelál a MAWI többi próbájával.","a":false,"e":"Rosszul korrelál velük."}]},{"id":"u19l5","title":"MAWI értelmezése, demencia","theory":[["Demenciagyanú","IQ-küszöbök: deficitet feltételezhetünk, ha a kiemelkedő értelmiségi IQ-ja <b>120 alatt</b>, egyetemi végzettségűé <b>109 alatt</b>, érettségizetté <b>90 alatt</b>, általános iskolásé <b>79 alatt</b> van. Az életkorral romlik: pszichomotórium, perceptuális teljesítmény, téri konfiguráció, tanulékonyság."],["Demenciaindex","(Σ korállandó – Σ korváltozó) / Σ korállandó × 100. <b>10–20</b>: demencia, <b>20 felett</b>: súlyos demencia (leszázalékolás). Mínusz érték: nincs demencia. Ha a korállandó nagyobb, mint a korváltozó, organikus károsodás."],["VQ és PQ","<b>VQ–PQ ≥ 10</b>: jelentős különbség, demenciát valószínűsít; magasabb végzettségű idősnél 10–25 is lehet normális, ha a PQ normális. <b>VQ/PQ</b> viszonyítva az <b>1,51</b> értékhez: ha fölé esik, organikus károsodás, dementálódás."],["Pszeudodemencia","Depressziós pszeudodemencia: koncentrációzavar (50–75%), szelektív memória (negatív események), lassú pszichomotoros tempó. Elkülönítés: hangulatzavar a családban, hetek alatt alakul ki (a valódi évek alatt), a beteg panaszkodik a romlásra, rövid és hosszú távú memória is sérül (valódinál a rövid távú)."]],"qs":[{"t":"mc","q":"Egyetemi végzettségűnél mely IQ alatt feltételezhetünk deficitet?","o":["109","120","90","79"],"a":0,"e":"Kiemelkedő értelmiségi 120, egyetem 109, érettségi 90, általános iskola 79."},{"t":"mc","q":"Mi a demenciaindex értéke, ha súlyos demenciára utal?","o":["20 felett","0 alatt","5 alatt","10 alatt"],"a":0,"e":"10–20 között demencia, 20 felett súlyos demencia."},{"t":"tf","q":"Mínusz demenciaindex esetén nincs demencia.","a":true,"e":"Ha az index negatív, nincs demencia."},{"t":"mc","q":"Mi az 1,51-es érték jelentősége?","o":["VQ/PQ e fölött organikus károsodás valószínű","IQ-átlag","Demenciaindex határa","A MAWI időkorlátja"],"a":0,"e":"VQ/PQ 1,51 fölött organikus károsodást valószínűsít."},{"t":"mc","q":"Mi különbözteti meg a pszeudodemenciát a valódi demenciától?","o":["Hetek alatt alakul ki, a beteg panaszkodik","Évek alatt alakul ki","A beteg nem észleli a romlást","Csak a rövid távú memória sérül"],"a":0,"e":"Valódi demencia évek alatt fejlődik, a betegek ritkán panaszkodnak."},{"t":"match","q":"Párosítsd az iskolai végzettséget az IQ-küszöbbel (alatta deficit)!","pairs":[["Általános iskola","79"],["Érettségi","90"],["Egyetem","109"],["Kiemelkedő értelmiségi","120"]],"e":"Életkor és végzettség szerinti küszöbök."},{"t":"fill","q":"Ha VQ–PQ eltérés ___ vagy nagyobb, az jelentős különbség (demenciát valószínűsít).","a":["10"],"e":"Magasabb végzettségű idősnél 10–25 is belefér, ha PQ normális."},{"t":"tf","q":"Ha a korállandó próbák eredménye nagyobb, mint a korváltozóké, organikus károsodásra gyanakodunk.","a":true,"e":"Ez a demenciaindex alapja."}]},{"id":"u19l6","title":"Differenciáldiagnózis, profilok","theory":[["Differenciáldiagnózis, profilok","Neurotikusok, pszichopaták és paranoid szkizofrének jelentős hányadának IQ-ja nem különbözik a normáltól. Differenciáldiagnosztika: neurotikus tartomány, sine morbo, organikus (H-index). <b>Szubjektív profil</b>: önmagához viszonyítás; <b>objektív profil</b>: korcsoporthoz viszonyítás."],["Szubjektív profil részletei","Az IQ és az eltérés függvényében + vagy – jelet adunk. IQ 79 alatt: eltérés 1,1–2 → egy jel, 2,1 felett → két jel. IQ 80–116: eltérés 1,6–3 → egy jel, 3,1 felett → két jel. IQ 117 felett: 2–3,5 → egy jel, 3,6 felett → két jel."]],"qs":[{"t":"mc","q":"Mihez viszonyít a szubjektív profil?","o":["Önmagához","A korcsoporthoz","A végzettséghez","A normál populációhoz"],"a":0,"e":"Szubjektív: önmagához; objektív: korcsoporthoz."},{"t":"mc","q":"Mihez viszonyít az objektív profil?","o":["A korcsoporthoz","Önmagához","A családhoz","A korábbi IQ-hoz"],"a":0,"e":"Objektív profil: korcsoporthoz hasonlítás."},{"t":"tf","q":"A neurotikusok és pszichopaták IQ-ja jelentős hányadban nem különbözik a normális kontrollszemélyekétől.","a":true,"e":"Ezért az IQ önmagában nem diagnosztikus ezeknél."},{"t":"mc","q":"Melyik a MAWI differenciáldiagnosztikai kategóriája?","o":["Sine morbo","Szuicidum","Pszichopátia","Hisztéria"],"a":0,"e":"Neurotikus tartomány, sine morbo, organikus (H-index)."},{"t":"fill","q":"A MAWI differenciáldiagnosztikai kategóriái: neurotikus tartomány, sine morbo és ___.","a":["organikus"],"e":"H-index is használatos."},{"t":"tf","q":"IQ 79 alatt 2,1 feletti eltérésnél két jelet adunk a szubjektív profilban.","a":true,"e":"1,1–2 között egy jel, 2,1 felett két jel."}]}],"color":"#a560e8"},{"id":"u20","title":"Gyermekdiagnosztika","desc":"Csecsemő-, gyermek-, serdülőkori tesztek","lessons":[{"id":"u20l1","title":"A gyermekdiagnosztika alapelvei","theory":[["Gyermekek és a kommunikáció","A gyermek gondolkodása más logikát követ: az érzelmek és vágyak felülírják a tudást, más viszonyítási keretet használ. A saját gondolati tartalmak feltárására Piaget <b>klinikai kérdezés</b> módszere alkalmas, amely mentes a sugalmazástól és a felnőtt előfeltevéseitől."],["Fejlődési szemlélet","A vizsgálat folyamat, kapcsolatba ágyazott. Ismerni kell a testi, lelki, kognitív és érzelmi érést. <b>Anna Freud</b>: a teljesítmények fejlődési fonalak mentén ragadhatók meg; sorsuk 4 tényező kölcsönhatásától függ: ösztönkésztetések érése, én-funkciók érése, felettes-én érése, környezeti hatások."],["Lépések","1) <b>Szűrővizsgálat</b>: egyszerű, olcsó, érzékeny, specifikus, megbízható, kulturálisan elfogadható. 2) <b>Funkcionális vizsgálat</b>: anamnézis, fizikai állapot, fejlettség, viselkedés, globális fogyatékosság/készség értékelése."],["Menete, szorongás","Kontaktusfelvétel (anamnézis) → elfogadó légkör (exploratív játék: nondirektív/direktív) → pszichodiagnosztika (teljesítmény- és projektív tesztek) → pszichoterápia/tanácsadás → utókövetés. Szorongás formái: szeparációs (tiltakozás – kétségbeesés – apátia), visszahúzódás, túlszorongás; a szorongás miatt alulteljesíthet (szétszórt vagy beszűkült figyelem)."]],"qs":[{"t":"mc","q":"Melyik módszert dolgozta ki Piaget a gyermekek gondolkodásának feltárására?","o":["Klinikai kérdezés","Szabad asszociáció","Világjáték","Kinetikus családrajz"],"a":0,"e":"Mentes a sugalmazástól és a felnőtt előfeltevéseitől."},{"t":"match","q":"Párosítsd a lépést a tartalmával!","pairs":[["Szűrővizsgálat","egyszerű, érzékeny, olcsó"],["Funkcionális vizsgálat","anamnézis, fejlettség, viselkedés"],["Utókövetés","adaptáció, gondozás"]],"e":"A gyermekdiagnosztika lépései."},{"t":"mc","q":"Melyik NEM tartozik Anna Freud négy fejlődési tényezője közé?","o":["Kognitív stílus","Ösztönkésztetések érése","Én-funkciók érése","Felettes-én érése"],"a":0,"e":"A negyedik: környezeti hatások."},{"t":"mc","q":"Mi a hospitalizáció szeparációs szorongásának sorrendje?","o":["Tiltakozás – kétségbeesés – apátia","Apátia – tiltakozás – kétségbeesés","Kétségbeesés – tiltakozás – apátia","Tagadás – harag – alkudozás"],"a":0,"e":"A szorongás formái: szeparációs, visszahúzódás, túlszorongás."},{"t":"tf","q":"A gyermek szorongása miatt képességei alapján alulteljesíthet az intelligenciatesztben.","a":true,"e":"Szétszórt vagy beszűkült figyelem miatt."},{"t":"mc","q":"A gyermekkel való foglalkozás ELSŐ lépése:","o":["Kontaktusfelvétel, anamnézis","Pszichoterápia","Projektív teszt","Utókövetés"],"a":0,"e":"Utána kontaktus megszilárdítása, majd pszichodiagnosztika."},{"t":"fill","q":"A kisgyermek gondolkodásában az érzelmek és ___ felülírják a tudást.","a":["vágyak","vágyak és","vagyak","kívánságok"],"e":"A gyermekek gondolkodási logikája eltér a felnőttekétől."},{"t":"tf","q":"A szűrővizsgálatnak kulturálisan illeszkednie kell és elfogadhatónak kell lennie a szülők számára.","a":true,"e":"Követelmény: egyszerű, olcsó, érzékeny, specifikus, megbízható."}]},{"id":"u20l2","title":"Csecsemőtesztek","theory":[["Brunet–Lézine","Pszichomotoros fejlődési teszt (1951; Brunet és Lézine; Magyarországon 1980-tól, adaptálta Csiky Erzsébet). Négy terület: <b>P</b> poszturális adaptáció, <b>K</b> oculomotoros koordináció (finommozgás), <b>B</b> beszéd, <b>Sz</b> szociabilitás. Eredmény: <b>fejlődési hányados (FQ)</b> = fejlettségi kor / életkor × 100; 70 alatt fejlődési zavar. Koraszülötteknél életkori korrekció."],["Bayley-II","Nancy Bayley (1969, USA); <b>0–42 hónapos</b> korban. Három rész: <b>Mentális Skála</b> (MDI), <b>Pszichomotoros Skála</b> (PDI), <b>Viselkedéses Skála</b> (BRS, 5 fokú). Nem intelligenciateszt. Indexek: M = 100, SD = 15. Elméleti háttér: érési, tanulási és kölcsönhatás-elmélet. Magyar standard nincs."],["Denver II","Frankenburg (1967, II.: 1992); <b>1 hónapos–6 éves</b> korig; <b>125 tétel</b>: nagymotoros, finommotoros, személyes-szociális, beszédkészség. <b>Szűrőteszt</b>: gyanús vagy megkésett jelzés, nem diagnosztizál."],["Korrigált életkor","Koraszülötteknél általában <b>2 éves korig</b> korrigált életkorral számolunk: az első 1,5–2 évben a teljesítmény főként a genetikai program érésén alapul, később erősödik a környezet hatása. Fejlődési tesztek hullámai: Gesell, Cattell, Griffith, majd a 60-as években a szűrőtesztek (Denver, Vineland, Bayley)."]],"qs":[{"t":"match","q":"Párosítsd a Brunet–Lézine területét!","pairs":[["P","poszturális adaptáció"],["K","oculomotoros koordináció"],["B","beszéd"],["Sz","szociabilitás"]],"e":"A teszt négy területe."},{"t":"mc","q":"Mi a Brunet–Lézine eredménye?","o":["Fejlődési hányados","IQ","T-érték","Percentilis"],"a":0,"e":"FQ = fejlettségi kor / életkor × 100; 70 alatt fejlődési zavar."},{"t":"mc","q":"Melyik a Bayley-II három része?","o":["Mentális, pszichomotoros, viselkedéses","Verbális, performációs, számolási","Nagymotoros, finommotoros, beszéd","Memória, figyelem, gondolkodás"],"a":0,"e":"Indexek: MDI, PDI; a viselkedéses skála a BRS."},{"t":"tf","q":"A Bayley-II intelligenciateszt.","a":false,"e":"A Bayley-II nem intelligenciateszt, a fejlődési mérföldkövek elérését méri."},{"t":"mc","q":"Hány tételes a Denver II?","o":["125","240","566","244"],"a":0,"e":"Négy területet vizsgál, szűrőteszt."},{"t":"tf","q":"A Denver II diagnosztikus eszköz.","a":false,"e":"Szűrőfunkciót lát el, jelzi a lemaradást, de nem diagnosztizál."},{"t":"fill","q":"Koraszülötteknél általában ___ éves korig számolunk korrigált életkorral.","a":["2","két","kettő","2 éves"],"e":"Az első 1,5–2 évben az érési folyamatok dominálnak."},{"t":"mc","q":"A Brunet–Lézine fejlődési hányadosa mely érték alatt jelez fejlődési zavart?","o":["70","85","100","50"],"a":0,"e":"70 alatt meglassúbbodott fejlődés, fejlődési zavar."}]},{"id":"u20l3","title":"Intelligenciateszt: IQ, Binet, Wechsler","theory":[["Az IQ története","Binet és Simon: életkori szinteknek megfelelő, egyre nehezedő feladatok → <b>mentális kor</b>. A különbség helyett hányadost számoltak (6 hónap lemaradás nem ugyanaz 6 és 10 évesen). <b>Terman</b>: × 100 (IQ). Wechsler: egyéni teljesítmény / korcsoport átlaga × 100. <b>Spearman</b>: g-faktor, eduktív (nonverbális) és reproduktív (verbális) képességek."],["Budapest–Binet","<b>3–14 éves</b> korig (6 év alatt ajánlott); IQ = mentális kor / életkor × 100. Nem homogén feladatsor; verbális és performációs részek külön nem értékelhetők. 3–10 évig plusz 2 hónapot ér, 11–14 évig 3 hónapot. Átlag IQ: 90–110; 70–90: borderline övezet. Délelőtt tesztelünk."],["Wechsler-család","<b>WPPSI-III</b>: 2 év 6 hó – 7 év 3 hó. <b>WISC-IV</b>: 7–17 év (15 altest: 10 alap, 5 kiegészítő; verbális, perceptuális, munkamemória, feldolgozási sebesség, összpontszám). 18 évtől WAIS (magyar: MAWI). Magyar gyermekváltozat: <b>MAWGYI</b> (német: HAWIK)."],["Értelmi fogyatékosság","<b>Enyhe</b> (IQ 50–55-től 70-ig): később kezdenek beszélni, de önellátók; nehézkes írás-olvasás. <b>Mérsékelt</b> (35–40-től 50–55-ig): lassú fejlődés, gyakran felügyelet kell. <b>Súlyos</b> (20–25-től 35–40-ig): motoros károsodás is. <b>Nagyon súlyos</b> (20–25 alatt): alapvető nonverbális kommunikáció."]],"qs":[{"t":"mc","q":"Ki vezette be az IQ-hányados 100-zal való szorzását?","o":["Terman","Binet","Spearman","Piaget"],"a":0,"e":"Binet mentális kora → hányados; Terman szorozta 100-zal; Wechsler relativizálta."},{"t":"mc","q":"Mit jelent a Spearman-féle g-faktor?","o":["Általános intelligenciafaktor","Genetikai faktor","Gondolkodási faktor","Gyorsasági faktor"],"a":0,"e":"Mellette speciális képességfaktorok is vannak."},{"t":"match","q":"Párosítsd a Wechsler-tesztet az életkorral!","pairs":[["WPPSI-III","2,5–7 év"],["WISC-IV","7–17 év"],["WAIS","18 évtől"]],"e":"A Wechsler-család három korosztálya."},{"t":"mc","q":"Hány altesztből áll a WISC-IV?","o":["15","10","12","8"],"a":0,"e":"10 alap- és 5 kiegészítő altesztből."},{"t":"tf","q":"A Budapest–Binet-ben a verbális és performációs részeket külön lehet értékelni.","a":false,"e":"Vannak ilyen részei, de külön nem értékelhetők."},{"t":"mc","q":"Hány hónapot ér egy plusz a Budapest–Binet 3–10 éves korig?","o":["2","3","1","6"],"a":0,"e":"11–14 éves korig 3 hónapot ér."},{"t":"fill","q":"A MAWI gyermekváltozata a ___.","a":["MAWGYI","Mawgyi","mawgyi"],"e":"A Wechsler gyermektest magyar változata."},{"t":"tf","q":"Gyermekkori IQ-mérést mindig délelőtt érdemes végezni.","a":true,"e":"A fáradtság hatását csökkentjük."}]},{"id":"u20l4","title":"Raven, SON, Bender, Frostig","theory":[["Raven-féle matrix","Nonverbális teljesítményteszt, a globális intelligenciát méri, érzékeny az organikus károsodásra. Szín változat (CPM): 1947, gyermekek, idősek, értelmi sérültek; <b>5½ éves kortól</b>; 36 tábla, progresszív. Absztrakt formák közötti szabályok felismerése. Kiegészítő próbaként javasolt."],["Snijders–Oomen (SON)","Nonverbális intelligenciateszt, <b>siket gyermekeknek</b> dolgozták ki (1943), hallóknak 1958. S.O.N.: 2,5–7 év, S.S.O.N.: 7–17 év. Részfeladatok: szortírozás, mozaik, kombináció, emlékezet, rajzolás."],["Bender-próba","A vizuomotoros érettséget méri. <b>Bender-A</b> (Santucci, 1960; 4–6 év; Mérei ismertette 1970) – olvasás-írás tanulás nehézségeinek előrejelzése. <b>Bender-B</b> (Bender, 1938; 6–12 év): 9 mértani ábra másolása. Értékelés: szögek kivitelezése, irány, relatív pozíció. Aszinkrónia (1–2 év lemaradás): organikus tünet."],["Frostig","Marianne Frostig (1963): a vizuális percepció vizsgálata, <b>4–7 éves</b> korig. A percepciós zavar és a tanulási nehézség szoros kapcsolatban áll; vizsgálati módszer és terápiás csomag a tanulási zavar diagnosztizálására és kezelésére."]],"qs":[{"t":"mc","q":"A Raven színes matrix tesztje hány éves kortól használható standarddal?","o":["5½","3","7","10"],"a":0,"e":"Alatta a Bender-A vagy a SON használható."},{"t":"mc","q":"Kinek készítették eredetileg a Snijders–Oomen tesztet?","o":["Siket gyermekeknek","Vak gyermekeknek","Koraszülötteknek","Autistáknak"],"a":0,"e":"1943-ban, hallóknak 1958-ban."},{"t":"match","q":"Párosítsd a tesztet a funkcióval!","pairs":[["Raven","nonverbális, absztrakt szabályok"],["Bender","vizuomotoros érettség"],["Frostig","vizuális percepció"]],"e":"Gyermekkori teljesítménytesztek."},{"t":"tf","q":"A Bender-B aszinkróniája (1–2 év lemaradás) organikus tünetként értelmezhető.","a":true,"e":"Egyenletes fejlődésnél az értelmi fejlettség és a vizuomotoros koordináció szinkronban van."},{"t":"mc","q":"Hány ábrát másol a gyermek a Bender-B-ben?","o":["9","10","14","24"],"a":0,"e":"9 mértani ábra, 6–12 éveseknél."},{"t":"mc","q":"Mire használható prediktív próbaként a Bender-A?","o":["Olvasás- és írástanulás nehézségeire","Szorongás mérésére","Személyiségzavarra","Demenciára"],"a":0,"e":"Korai felismerés."},{"t":"fill","q":"A Frostig-teszt a vizuális ___ vizsgálatára készült.","a":["percepció","percepcio","percepciójának"],"e":"4–7 éves korig."},{"t":"tf","q":"A Raven teszt eredményét sok nem intelligencia-tényező is befolyásolhatja (pl. figyelemzavar).","a":true,"e":"Ezért kiegészítő próbaként javasolják."}]},{"id":"u20l5","title":"CAT, TAT, PFT","theory":[["CAT","Gyermek Appercepciós Teszt, a TAT gyermekváltozata: <b>3–10 éveseknek</b>, <b>10 kép</b> állatokról (Bellak, 1948). Verbális, projektív, analitikus alapú. Értékelés: a fő téma, a főhős, a figurák észlelése, azonosítás, bevezetett és kihagyott figurák, szorongások, konfliktusok, bűn és bűnhődés, történetek végkifejlete."],["TAT","Murray, 1935 (jelenlegi változat 1943). <b>20 kép</b> két részletben (10 + 10, 1–2 nap különbséggel), életkor és nem szerint változatok, egy fehér tábla. <b>10 éves kortól</b>. Elvek: vágyteljesítő ábrándok, projekció, azonosulás, izoláció, reakcióképzés, racionalizáció. A történet kompromisszumos termék, mint az álom."],["TAT értelmezése","Hős, motívumok, környezeti hatások, megoldás, tematika. Murray 3 réteg: mélyréteg (lappangó vágyak), fantázia, nyíltan jelentkező mozzanatok. <b>Konfliktusképek</b>: az ellenállás jegyei – meseszerűség, jelentéktelenítés, kihagyás, beiktatás, leírás, folytatólagosság."],["PFT (Rosenzweig)","Képi frusztrációs tolerancia teszt (1945; gyermekváltozat 1948: <b>6–14 év</b>). <b>24 rajz</b>, két figura: a bal mond valamit, a jobb válaszát kell kitalálni. Agresszió iránya: <b>extrapunitív</b> (másokat hibáztat), <b>intrapunitív</b> (önmagát), <b>impunitív</b> (nincs agresszió). Mutató: <b>GCR</b> (csoportkonformitás)."]],"qs":[{"t":"mc","q":"Hány képből áll a CAT?","o":["10","20","24","31"],"a":0,"e":"Állatalakokat ábrázoló képek, 3–10 éveseknek."},{"t":"mc","q":"Ki dolgozta ki a TAT-ot?","o":["Murray","Rosenzweig","Bellak","Machover"],"a":0,"e":"1935-ben, a mai változat 1943-ban jelent meg."},{"t":"match","q":"Párosítsd az agresszió irányát!","pairs":[["Extrapunitív","másokat hibáztat"],["Intrapunitív","önmagát hibáztatja"],["Impunitív","nem jelenik meg agresszió"]],"e":"Rosenzweig PFT-je szerint."},{"t":"mc","q":"Hány képből áll a Rosenzweig-féle PFT?","o":["24","10","20","8"],"a":0,"e":"24 sematikus rajz, köznapi frusztrációs helyzetek."},{"t":"tf","q":"A TAT történetei kompromisszumos termékek, mint az álom.","a":true,"e":"Az elhárítás kompromisszumra kényszeríti az érzelmi-indulati feszültséget."},{"t":"mc","q":"Melyik a TAT konfliktusképeinek ellenállási jegye?","o":["Kihagyás","Pontos válasz","Gyors válaszadás","Több magyarázat"],"a":0,"e":"Meseszerűség, jelentéktelenítés, kihagyás, beiktatás, leírás, folytatólagosság."},{"t":"fill","q":"A PFT-ben a csoportkonformitást mutató mutató a ___.","a":["GCR","gcr"],"e":"Group conformity rating."},{"t":"tf","q":"A PFT gyermekváltozata 6–14 éves korig használható.","a":true,"e":"Rosenzweig 1948-ban publikálta."}]},{"id":"u20l6","title":"Bábjáték, Világjáték, Wartegg","theory":[["A játék mint eszköz","A játék a gyermek nyelve. Klein a szimbolikus megértésre helyezte a hangsúlyt, Anna Freud az értelmi fejlődésben betöltött szerepre is. A gyermek csak bizalmi kapcsolatban tud játszani. Szegényes, repetitív játék vagy elsorvadó játékkedv pszichés zavart jelezhet. Mérei: <b>kettős tudat</b> (képzelet és valóság egyszerre)."],["Bábjáték","Madeleine Rambert vezette be; 3–10 éves gyermekeknél. Hatásos, mert képszerű, dramatikus, mozgásra épül, jelképes, biztosítja az érzelmek kivetítését. <b>Többszörös takarás</b>: paraván, figurák mögé bújás, arctalanság, egy báb több szerep."],["Világjáték","Loewenfeld, standardizálta Bühler; fémtálca, homok, játéktárgyak; kb. <b>4 éves kortól</b>. Instrukció: építs világot, amelyben szeretnél lakni. Átlagos építési idő ~20 perc, homokozási idő ~3–7 perc. Tárgyak száma: beszűkült (10–20), szegényes (20–40), normál (40–60), gazdag (60–80). Jelek: dezorganizáció, izoláció (kerítés), üresség, rigiditás."],["Wartegg","Projektív rajzteszt: fekete alapon <b>8 db 4×4 cm fehér négyzet</b> kezdőtémákkal (pont, egyenes, görbe, hegyesszög). Nincs radír, körző, vonalzó. A normál–patologikus elkülönítés csak formális elemzés alapján. Diagnózis 3 tengelyen (Perron): formális-strukturális, tematikus, védekezési módok."]],"qs":[{"t":"mc","q":"Ki vezette be a bábjátékot a gyermekpszichológiába a leírás szerint?","o":["Madeleine Rambert","Melanie Klein","Anna Freud","Lowenfeld"],"a":0,"e":"1938-ban játékanalitikus módszerként alkalmazta."},{"t":"match","q":"Párosítsd a tesztet a leírással!","pairs":[["Bábjáték","paraván, többszörös takarás"],["Világjáték","homok, tálca, játéktárgyak"],["Wartegg","8 négyzet kezdőtémával"]],"e":"Projektív eszközök gyermekeknél."},{"t":"mc","q":"Hány perc az átlagos építési idő a Világjátékban?","o":["Kb. 20","Kb. 5","Kb. 60","Kb. 3"],"a":0,"e":"A homokozási idő ~3–7 perc."},{"t":"mc","q":"Mely tárgyszám jelent normál világot?","o":["40–60","10–20","20–40","80 fölött"],"a":0,"e":"Beszűkült 10–20, szegényes 20–40, gazdag 60–80, magas 80 fölött."},{"t":"tf","q":"A Világjáték jegyzőkönyvezésekor szó szerint jegyzünk.","a":true,"e":"Fénykép vagy rajz, verbális és nonverbális megnyilvánulás, idő, sorrend."},{"t":"mc","q":"Mi jelezheti a Világjátékban az izolációt?","o":["Kerítés","Növény","Ház","Állat"],"a":0,"e":"Regresszióra erősödik, akadályozza a közlekedést."},{"t":"fill","q":"A Wartegg-teszt kezdőtémái: pont, egyenes, görbe és ___.","a":["hegyesszög","hegyes szög"],"e":"Négy archetípus."},{"t":"tf","q":"Mérei szerint az egészségesen fejlődő gyermek pontosan tudja, hol van a képzelet és a valóság határa.","a":true,"e":"Ez a kettős tudat."}]},{"id":"u20l7","title":"Rajzok mint diagnosztikai eszköz","theory":[["Rajzok sajátosságai","A rajz nem önmagában hordoz jelentést, nagy sávszélességű, Gestalt-jellegű. <b>Többszörös okság</b>: egy kórkép sokféleképp jelenhet meg, egy rajzjegy mögött többféle jelentés állhat. Értelmezéshez ismerni kell: instrukciót, életkort, nemet, diagnosztikai státuszt, kézügyességet, intelligenciát, SES-t, kezességet, vizsgálatvezető attitűdjét."],["Rajzteszt-típusok","<b>Buck</b>: ház–fa–ember. <b>Machover</b>: emberrajz – kivetített konfliktusok; Goodenough: rajzkor/<b>RQ</b>, nem helyettesíti az IQ-t. <b>Koch</b>: fa-teszt. Radírozás: mérsékelt radírozás javulással – teljesítménymotiváció; túlzott – bizonytalanság, kompulzív vonások."],["Családrajz","Kinetikus családrajz (mindenki csináljon valamit): globális értékelés, emberalakok, tárgyak. Elvarázsolt család: nagyobb a szimbolikus tér. Corman kérdései: ki a legkedvesebb, legkevésbé kedves, legboldogabb, legkevésbé boldog. Jobb oldal apai, jövő; bal oldal anyai, múlt. Disz-jelek: üreges szem, nyaknélküliség."],["Utóteszt és kérdések","Rajzolás közben semleges válaszok, utána rákérdezünk mindenre; szó szerinti jegyzet. Kérdéstípusok: <b>realitás-</b>, <b>asszociációs</b>, <b>imaginatív</b>. Farajzban: életkor – optimálisan nem tér el 5 évnél többel a személyétől; évszakok (tavasz remény, nyár vitalitás, ősz érés, tél bezárulás)."]],"qs":[{"t":"mc","q":"Ki dolgozta ki a Ház–fa–ember módszert?","o":["Buck","Machover","Koch","Corman"],"a":0,"e":"Buck; a Machover az emberrajz-teszt, Koch a fa-teszt."},{"t":"match","q":"Párosítsd a rajzot a szerzővel!","pairs":[["Ház–fa–ember","Buck"],["Emberrajz","Machover"],["Fa-teszt","Koch"]],"e":"A gyermekrajz-tesztek szerzői."},{"t":"tf","q":"Az alacsonyabb RQ minden esetben értelmi fogyatékosságot jelent.","a":false,"e":"Felhívja a figyelmet esetleges fejlődési zavarra, de lehet személyiségzavar is."},{"t":"mc","q":"Mit jelent a többszörös okság elve a rajzoknál?","o":["Egy rajzjegy mögött többféle jelentés állhat","Minden rajzjegy csak egy zavart jelez","A rajz mindig egy okra utal","A rajz független az instrukciótól"],"a":0,"e":"Egy kórkép is sokféleképp jelenhet meg."},{"t":"mc","q":"Corman szerint melyik kérdés NEM kötelező a családrajz utáni négy között?","o":["Ki a legerősebb?","Ki a legkedvesebb?","Ki a legboldogabb?","Ki a legkevésbé boldog?"],"a":0,"e":"A négy kérdés: legkedvesebb, legkevésbé kedves, legboldogabb, legkevésbé boldog."},{"t":"mc","q":"Melyik évszak a farajzban az optimális vitalitás tapasztalata?","o":["Nyár","Tavasz","Ősz","Tél"],"a":0,"e":"Tavasz: reményteli várakozás; ősz: érés; tél: bezárulás."},{"t":"tf","q":"A rajzolás közben irányító kérdésekkel segítjük a gyermeket.","a":false,"e":"Rajzolás közben semleges válaszokat adunk, rákérdezni utána kell."},{"t":"fill","q":"A farajzban a fa életkora optimálisan legfeljebb ___ évvel tér el a vizsgált személy életkorától.","a":["5","öt","ot"],"e":"Fiatalabb – az érettség hiánya; idősebb – szorongás."}]}],"color":"#ff86d0"},{"id":"u21","title":"Pszichoterápia alapjai","desc":"Fogalom, alaphelyzet, hatótényezők","lessons":[{"id":"u21l1","title":"A pszichoterápia fogalma","theory":[["Miért nehéz definiálni?","A meghatározás problémái: a természettudományi és társadalomtudományi megközelítés együttléte; a gyakorlatban kialakultság; az alkalmazási terület és a módszerek nehéz körülhatárolhatósága; a szakma fiatal kora; a tárgy komplexitási szintje."],["Két út a meghatározásra","Vagy <b>egyenként határozzák meg</b> az egyes módszereket (jellegzetességeikkel), vagy <b>általános definíciót</b> alakítanak ki, amely megvonja a pszichoterápiába tartozó eljárások körét."],["Ennis: három standard","Ahhoz, hogy valami orvosi pszichoterápia (elfogadott gyógyító eljárás) legyen, három standardnak kell megfelelnie: <b>technikai, etikai, tudományos</b>.<br>Technikai: elméleti keret + technikák, összhangban. Etikai: az orvosi etikával összhang. Tudományos: ellenőrizhető hipotézisek, vizsgálható hatékonyság."]],"qs":[{"t":"mc","q":"Melyik NEM tartozik a pszichoterápia definiálásának problémái közé?","o":["A szakma fiatal kora","A módszerek nehéz körülhatárolhatósága","A tárgy komplexitási szintje","A terápiák alacsony költsége"],"a":3,"e":"A költség nem szerepel a definiálási problémák között."},{"t":"mc","q":"Ki szerint kell minden pszichoterápiának három standardnak megfelelnie?","o":["Ennis","Wolberg","Buda","Clarkson"],"a":0,"e":"Ennis: technikai, etikai és tudományos standard."},{"t":"match","q":"Párosítsd az Ennis-standardot a tartalmával!","pairs":[["Technikai","Elméleti keret és összhangban álló technikák"],["Etikai","Az orvosi foglalkozás etikai szabályai"],["Tudományos","Ellenőrizhető hipotézisek, vizsgálható hatás"]],"e":"Ennis három standardja."},{"t":"tf","q":"A tudományos standard szerint az elméletnek korábban megcáfolt hipotézisből is következhet.","a":false,"e":"Nem következhet megcáfolt vagy hitelét vesztett hipotézisből."},{"t":"fill","q":"A pszichoterápia általános definíciója a szakma ___ vonja meg (kompetenciáját, eljárások és szakemberek körét).","a":["határait","szakmai határait","határokat"],"e":"A definíciók a szakmai határokat vonják meg."},{"t":"mc","q":"Mi közös a legtöbb pszichoterápia-definícióban?","o":["Pszichés-kommunikációs eszközökkel segítenek pszichés zavarokban, szakmai keretben","Kizárólag gyógyszeres kezelést jelentenek","Mindig csoportban zajlanak","Mindig lezárt technikasorból állnak"],"a":0,"e":"Eljárások, pszichés zavarok, pszichés-kommunikációs eszközök, szakmai keret, speciális képzettség."}]},{"id":"u21l2","title":"Definíciók: Buda, Süle, Wolberg","theory":[["Buda Béla","A pszichoterápia fogalmát a komolyabb, elméletileg és módszertanilag megalapozott, hosszan tartó, nagyobb személyiségváltozási célú kommunikációs beavatkozásokra kell fenntartani. Segítő, gyógyító beavatkozás, amely <b>interakció és kommunikáció</b> révén változást hoz létre az élmények átélésében, befogadásában és a magatartásban."],["Süle Ferenc","Lélektani eszközökkel végzett gyógyító eljárás, lényege az <b>interperszonális kapcsolat</b>: szakképzett terapeuta kommunikál lelkileg beteg emberrel, aki egészségesebb, integráltabb, önmegvalósítóbb, boldogabb, kreatívabb, társadalmilag hasznosabb lesz."],["Pylkkänen és Wolberg","<b>Pylkkänen</b>: mentális rendellenességű (mentális, szomatikus, szociális tünetek) személyek; cél a zavar megszüntetése/enyhítése; bizonyított pszichológiai elméletek szisztematikus alkalmazása; képesített szakember.<br><b>Wolberg</b>: képzett személy tudatosan szakmai kapcsolatot hoz létre, hogy megszüntesse/módosítsa a tüneteket, megváltoztassa a zavart viselkedési mintákat, elősegítse a személyiség pozitív növekedését."]],"qs":[{"t":"match","q":"Párosítsd a szerzőt a hangsúlyával!","pairs":[["Buda","Hosszan tartó, nagy személyiségváltozási cél"],["Süle","Interperszonális kapcsolat lényege"],["Wolberg","Tudatos szakmai kapcsolat"],["Pylkkänen","Képesített szakember, bizonyított elméletek"]],"e":"A szerzők definícióinak fókuszai."},{"t":"mc","q":"Ki szerint a pszichoterápia lényege az interperszonális kapcsolat?","o":["Süle Ferenc","Ennis","Orlinsky","Clarkson"],"a":0,"e":"Süle: lélektani eszközökkel végzett gyógyító eljárás, lényege az interperszonális kapcsolat."},{"t":"tf","q":"Buda szerint pszichoterápia minden olyan segítő beavatkozás, amely interakció és kommunikáció révén próbál változást létrehozni.","a":true,"e":"Az élmények átélésének, befogadásának módjában és a magatartásban."},{"t":"mc","q":"Wolberg szerint a pszichoterápia célja NEM:","o":["Gyógyszeres kezelés pótlása","Tünetek megszüntetése, csökkentése","Zavart viselkedési minták megváltoztatása","A személyiség pozitív növekedésének elősegítése"],"a":0,"e":"Wolberg három célt említ: tünetek, viselkedési minták, személyiségfejlődés."},{"t":"fill","q":"Pylkkänen szerint a kezelést csak megfelelő ___ rendelkező szakember végezheti.","a":["képesítéssel","pszichoterapeuta képesítéssel","képesítés"],"e":"Pszichoterapeuta képesítés."},{"t":"mc","q":"Melyik definíció hangsúlyozza a „hosszan tartó, nagyobb személyiségváltozási célkitűzéseket”?","o":["Buda Béla","Wolberg","Pylkkänen","Ennis"],"a":0,"e":"Buda Béla."}]},{"id":"u21l3","title":"A pszichoterápiás alaphelyzet","theory":[["A keret és a szerződés","A kezelés a mindennapi kapcsolatoktól eltérő helyzetben és szabályok szerint zajlik. A terapeuta feladata a helyzet (setting) <b>kialakítása</b> (terápiás szerződés) és <b>fenntartása</b> (terápiás keret). A munkakapcsolat erős érzelmi szövetség. A terápia nem adható át, csak lezárható."],["A terápiás ülés","A terápia ülések sorozata, egysége a <b>terápiás ülés</b>: tovább nem bontható, belső struktúrával és dinamikával rendelkezik. Alapfeltétele a zavartalanság, nyugalom, kényelem. Lehetőleg azonos helyen, időben és időtartamban zajlik, előzetes időbeosztás alapján."],["Alaphelyzetek","A társaslélektani szerkezet határozza meg a terápia jellegét, dinamikáját, hatásmechanizmusát; maga is hatótényező. Három alaphelyzet: <b>egyéni</b> (kétszemélyes), <b>csoport</b> (1-2 terapeuta, koterápia), <b>család</b> (több terapeuta, esetleg in situ szupervízió). Bugán-féle alaphelyzetmodell: a családterapeutához átkerül a család információja (áttétel-viszontáttétel)."]],"qs":[{"t":"mc","q":"Mi a terápiás ülés?","o":["A terápia tovább nem bontható egysége","A terápia teljes folyamata","Az első találkozás","A terápia lezárása után folytatott kapcsolat"],"a":0,"e":"Belső struktúrával, dinamikával rendelkező, tovább nem bontható egység."},{"t":"mc","q":"Mit jelent a terápiás szerződés és a terápiás keret viszonya?","o":["A szerződés a helyzet kialakítása, a keret a fenntartása","A szerződés a fenntartás, a keret a kialakítás","Ugyanazt jelentik","A keret csak csoportban létezik"],"a":0,"e":"Kialakítás: terápiás szerződés; fenntartás: terápiás keret."},{"t":"tf","q":"A pszichoterápia átadható másik terapeutának a kezelés folytatásaként.","a":false,"e":"A terápia nem adható át, csak lezárható, és helyette új kezelés kezdhető."},{"t":"match","q":"Párosítsd az alaphelyzetet a jellemzőjével!","pairs":[["Egyéni","Kétszemélyes, általában 1 terapeuta"],["Csoport","1-2 terapeuta (koterápia)"],["Család","Több terapeuta, in situ szupervízió"]],"e":"A három alaphelyzet."},{"t":"fill","q":"A családterápiában a terapeutacsoport jelenléte az ún. „in situ ___”.","a":["szupervízió"],"e":"In situ szupervízió."},{"t":"tf","q":"A terápiás ülésekre lehetőleg azonos helyen, időben és időtartamban kerül sor.","a":true,"e":"Ez a keret állandóságát biztosítja."},{"t":"mc","q":"Melyik a három alaphelyzet közül?","o":["Családterápiás","Szupportív","Integratív","Rövid"],"a":0,"e":"Egyéni, csoport, családterápiás alaphelyzet."}]},{"id":"u21l4","title":"Hatótényezők: kapcsolat és szakaszok","theory":[["Specifikus hatótényezők, Orlinsky","Specifikus hatótényező a terápiás módszer, a terápiás kapcsolat és a terapeuta személyisége. <b>Orlinsky generikus modellje</b> bármely módszerre alkalmazható: páciens és terapeuta személyiségével vesz részt; a környezet közvetlenül hat; a kapcsolat folyamat, mely a szerződésre épül; önkorrekciós folyamat; kölcsönös érzelmi elkötelezettség (terápiás szövetség); a hatás terápián belül, után és az élettérben jelentkezhet."],["Clarkson és a szakaszok","<b>Clarkson</b> 5 kapcsolattípusa: munkaszövetség; áttétel-viszontáttételi; fejlődési szükségből adódó reparatív; személy-személy (valóságos, mag-); transzperszonális.<br><b>Szakaszok</b>: az első találkozás előzményei; bevezető szakasz; középső (munka-) szakasz; befejezés-leválás; a lezárás utáni kapcsolat."],["Szerződés és nem specifikus tényezők","A szóbeli <b>szerződés</b> rögzíti: a cél, a beteg és a terapeuta tennivalói, formai jellemzők, körülmények, kiegészítő megállapodások. A keret védi, tartja a terápiát. <b>Nem specifikus</b> tényezők: feltétel nélküli elfogadás, empátia, kongruencia (hitelesség)."]],"qs":[{"t":"mc","q":"Hány kapcsolattípust különít el Clarkson?","o":["5","3","4","7"],"a":0,"e":"Munkaszövetség, áttétel-viszontáttétel, reparatív, személy-személy, transzperszonális."},{"t":"match","q":"Párosítsd a fogalmat a jelentésével!","pairs":[["Feltétel nélküli elfogadás","Az embert önmagában értéknek tekintjük"],["Empátia","A cselekedetek mögötti miértek megértése"],["Kongruencia","Gondolat és tett összhangja"]],"e":"A nem specifikus hatótényezők."},{"t":"mc","q":"Melyik NEM Clarkson kapcsolattípusa?","o":["Instruáló kapcsolat","Munkaszövetség","Transzperszonális kapcsolat","Reparatív kapcsolat"],"a":0,"e":"Az instruáló kapcsolat nem szerepel."},{"t":"tf","q":"Orlinsky szerint a terápia az interakcióban zajlik, ezért törvényszerűen önkorrekciós folyamat.","a":true,"e":"A páciens és a terapeuta interakciója önkorrekciós."},{"t":"mc","q":"Melyik a terápia szakaszainak helyes sorrendje?","o":["Előzmények, bevezető, munkaszakasz, befejezés-leválás, lezárás utáni kapcsolat","Bevezető, befejezés, munkaszakasz, előzmények","Munkaszakasz, bevezető, leválás","Szerződés, keret, ülés"],"a":0,"e":"Öt szakasz."},{"t":"mc","q":"Mit NEM rögzít a terápiás szerződés?","o":["A terapeuta diagnosztikai besorolását a BNO-ban","A terápia célját","A beteg tennivalóit","A terápia körülményeit"],"a":0,"e":"A cél, a tennivalók, forma, körülmények és kiegészítő megállapodások szerepelnek benne."},{"t":"fill","q":"A terápiás szerződés általában ___ megállapodás.","a":["szóbeli"],"e":"Általában szóbeli."},{"t":"mc","q":"A módszertani skála egyik végén az analitikus, a másikon melyik terápia áll?","o":["Viselkedésterápia","Személyközpontú terápia","Hipnoterápia","Családterápia"],"a":0,"e":"Analitikus: belső irányítottság; viselkedésterápia: meghatározott feladatsor. Közte a pszichodráma, alaklélektani terápia."}]}],"color":"#58cc02"},{"id":"u22","title":"Módszerspecifikus terápiák","desc":"Analitikus, kognitív, humanisztikus, csoport","lessons":[{"id":"u22l1","title":"Analitikus terápiák","theory":[["Standard pszichoanalízis","Alapszabály: <b>szabad asszociáció</b>, egyenletesen lebegő figyelem; <b>fekvő</b> helyzet; feltáró, verbális módszer, eszköze az értelmezés; az anyag nagy része az áttételi-viszontáttételi konstellációból jön. Ambuláns. Kontraindikáció: F0-, F30, F31, F43.0, F7-. Heti <b>3-4 ülés</b>, minimum <b>100 óra</b> (akár többszáz)."],["Pszichoanalitikusan orientált (pszichodinamikus)","Nem időhatáros egyéni terápia, a standardtól legalább egy paraméterében eltér (részleges szabad asszociáció, ülésgyakoriság, fekvő/ülő helyzet) a terhelhetőség szerint. Ambuláns és kórházi. Kontraindikáció: F0-. Heti <b>1-2 ülés</b>, min. <b>60 óra</b>. Gyógyszerrel kombinálható."],["Pszichoanalitikus rövidterápia","Az ülésszám előre meghatározott; a technika a <b>pszichodinamikai fókuszra</b> centrál; célja részleges, a tünetekkel összefüggő változás; <b>ülő</b> helyzet. Heti 1-2 óra, összesen <b>20-30 ülés</b>. Kontraindikáció: F0-, F30, F31, F45, F50, F6-, F7-. Járulékos: fókuszmeghatározás (team, teszt, szupervízió)."]],"qs":[{"t":"mc","q":"Hány ülés/hét jellemző a standard pszichoanalízisre?","o":["3-4","1-2","1","5-7"],"a":0,"e":"Heti 3-4 ülés, minimum 100 óra."},{"t":"match","q":"Párosítsd a terápiát az óraszámmal!","pairs":[["Standard pszichoanalízis","Minimum 100 óra"],["Pszichoanalit. orientált","Minimum 60 óra"],["Pszichoanalit. rövidterápia","20-30 ülés"]],"e":"Ülésszámok."},{"t":"tf","q":"A standard pszichoanalízis fekvő helyzetben zajlik.","a":true,"e":"A rövidterápia ezzel szemben ülő helyzetű."},{"t":"mc","q":"Melyik terápia centrál a pszichodinamikai fókuszra?","o":["Pszichoanalitikus rövidterápia","Standard pszichoanalízis","Jungi terápia","Hipnoterápia"],"a":0,"e":"Előre meghatározott ülésszámmal, fókuszmeghatározással."},{"t":"fill","q":"A standard pszichoanalízis alapszabálya a szabad ___.","a":["asszociáció"],"e":"Szabad asszociáció és egyenletesen lebegő figyelem."},{"t":"mc","q":"Miben tér el a pszichodinamikus terápia a standardtól?","o":["Egy vagy több paraméterében (pl. gyakoriság, ülő helyzet)","Nem feltáró módszer","Csak csoportban végezhető","Mindig időhatáros"],"a":0,"e":"Nem időhatáros, a terhelhetőséghez igazodik."},{"t":"tf","q":"A pszichoanalitikus rövidterápia célja a személyiség teljes átstrukturálása.","a":false,"e":"Célja a személyiség részleges, tünetekkel összefüggő megváltoztatása."}]},{"id":"u22l2","title":"Viselkedés-, kognitív, integratív, személyközpontú","theory":[["Viselkedés- és kognitív terápia","<b>Viselkedésterápia</b>: maladaptív magatartásformák befolyásolása, hiányzók kialakítása a tanulás törvényszerűségei szerint. Kontraindikáció: demenciák, organikus zavarok. 10-50 ülés. <b>Kognitív terápia</b>: a magatartás- és önkép-zavarok hátterében álló diszfunkcionális attitűdök módosítása; speciális kontraindikáció nincs; 20-50 ülés."],["Integratív pszichoterápia","Ötvözi a tudatállapot-módosítást, a tanuláselméleti viselkedéses és kognitív eljárásokat, valamint az interperszonális és kommunikációs folyamatok befolyásolását a kórkép sajátosságai szerint. Indikáció: F40-49, F60-62, F20-29. <b>20-100 ülés</b>, heti 1-2."],["Személyközpontú pszichoterápia","<b>Rogers</b>-i elvekre épül: feltétel nélküli pozitív elfogadás, empátia, kongruencia; tartós pozitív változás viselkedésben, énképben. A terapeuta-kliens viszony minősége a döntő. Kontraindikáció: F20-29. Rövid: 10-50, hosszú: 50-100 ülés, heti 1-2."]],"qs":[{"t":"mc","q":"Melyik terápia épül Rogers elveire?","o":["Személyközpontú","Kognitív","Szimbólumterápia","Aktív analitikus"],"a":0,"e":"Feltétel nélküli elfogadás, empátia, kongruencia."},{"t":"mc","q":"Mit módosít a kognitív terápia?","o":["A diszfunkcionális attitűdöket","A tudattalan konfliktusokat álmokon át","A családi rendszert","A hipnotikus transzot"],"a":0,"e":"A magatartás- és önkép-zavarok hátterében rejlő kóros attitűdöket."},{"t":"match","q":"Párosítsd a terápiát a kontraindikációval!","pairs":[["Viselkedésterápia","Demenciák, organikus zavarok"],["Személyközpontú","F20-29"],["Kognitív","Lényegében nincs speciális"]],"e":"Kontraindikációk."},{"t":"tf","q":"A viselkedésterápia a tanulási folyamatok törvényszerűségeit veszi figyelembe.","a":true,"e":"Maladaptív magatartás befolyásolása, hiányzó kialakítása."},{"t":"fill","q":"Az integratív pszichoterápia ülésszáma ___ ülés (két szám, kötőjellel).","a":["20-100","20–100"],"e":"20-100 ülés, heti 1-2."},{"t":"mc","q":"Mi a döntő a személyközpontú terápiában?","o":["A terapeuta-kliens viszony minősége","Az ülések száma","A fókuszmeghatározás","A feladatsor"],"a":0,"e":"A terápiás folyamatban a terapeuta-kliens viszony milyensége a döntő."},{"t":"mc","q":"Mit ötvöz az integratív pszichoterápia?","o":["Tudatállapot-módosítást, viselkedéses-kognitív és kommunikációs eljárásokat","Csak analitikus technikákat","Csak mozgásterápiát","Csak gyógyszeres és tánc eljárásokat"],"a":0,"e":"A kórkép tüneti és patogenetikai sajátosságai szerint."}]},{"id":"u22l3","title":"Egyéb mélylélektani terápiák","theory":[["Jungi analitikus terápia","Specialitása a személyes tudattalanon túl a <b>kollektív tudattalan</b>, az én és az ősvalónk kapcsolata, a spirituális dimenzió. Kontraindikáció: 100 alatti IQ, gyógyszerrel nem oldható pszichózis. Heti 1-3 ülés, 30-100 ülés."],["Aktív analitikus pszichoterápia","Más analitikus iskolákra épül, de hangsúlyozza a <b>tárgykapcsolatokat</b>, az ép személyiségrészekre épít, és kiemelten kezeli a <b>terapeuta aktivitását</b> (feladat, tiltás, gyakorlatok; pszichoedukatív, pedagógiai, behaviorális elemek). Heti 1-2, 30-80 óra. Kontraindikáció: F20-29, F00-09, F70-79. Járulékos: relaxáció, imagináció, párterápia."],["Szimbólumterápia és dinamikus rövid","<b>Szimbólumterápia</b>: tematikus képi megjelenítéssel mélylélektani feltárás; imaginatív, meditatív, expresszív technika; heti 1-2, 10-100 ülés; kontraindikáció: pszichózisok, F20-29, F30-39.<br><b>Dinamikus rövid pszichoterápia</b>: az <b>álom</b> vagy képélmény a középpontban, face to face; fókuszban az áttétel-viszontáttétel; 10-30 ülés, hetente egy; a kontraktus rögzíti az ülésszámot."]],"qs":[{"t":"mc","q":"Melyik terápia specialitása a kollektív tudattalan?","o":["Jungi analitikus","Szimbólumterápia","Aktív analitikus","Dinamikus rövid"],"a":0,"e":"Jungi analitikus pszichoterápia."},{"t":"mc","q":"Melyik terápia emeli ki a terapeuta aktivitását (feladatadás, tiltás)?","o":["Aktív analitikus","Standard pszichoanalízis","Jungi","Szimbólumterápia"],"a":0,"e":"Pszichoedukatív, pedagógiai, behaviorális elemeket is használ."},{"t":"match","q":"Párosítsd a terápiát a jellemzővel!","pairs":[["Jungi terápia","Kollektív tudattalan"],["Szimbólumterápia","Tematikus képi megjelenítés"],["Dinamikus rövid","Álom a terápia középpontjában"]],"e":"Jellegzetességek."},{"t":"tf","q":"A dinamikus rövid pszichoterápiát face to face helyzetben végzik.","a":true,"e":"Az álom/képélmény az érzelmi megértés közös nyelve."},{"t":"mc","q":"Mi a jungi terápia egyik kontraindikációja?","o":["100 alatti IQ","Fóbia","Hangulatzavar","Életkor 40 felett"],"a":0,"e":"100 alatti IQ és gyógyszerrel nem oldható pszichózis."},{"t":"fill","q":"A szimbólumterápia technikái: imaginatív, meditatív és ___ módszerek.","a":["expresszív"],"e":"Imaginatív, meditatív, expresszív."},{"t":"mc","q":"Hány ülés jellemző a dinamikus rövid pszichoterápiára?","o":["10-30","20-30 triplaülés","100-250","4-25 dupla"],"a":0,"e":"10-30 ülés, hetente egy alkalom."}]},{"id":"u22l4","title":"Hipnoterápia, mozgás- és gyermekterápia","theory":[["Hipnoterápia","A <b>hipnózist</b> (módosult tudatállapot) használja a terápia facilitálására; fontos a <b>szuggesztió</b> és az erős áttételes kapcsolat. Kontraindikáció: F00-09, F70-79. 4 üléstől hosszú terápiáig, heti 1-3. Relaxációs formához kényelmes ülő/fekvő bútor, aktív-éber formához kerékpár ergométer. Viselkedés-, kognitív, pszichodinamikus módszerekkel kombinálható."],["Mozgás- és táncterápia","Első alapelve a <b>test-lélek egysége</b>. Alapja: tárgykapcsolat- és kötődéselméletek, csecsemőkutatások, idegtudomány, mozgás pszicho-neurofiziológiája. Kontraindikáció: F0-, F30, F31 (bipoláris I.), F7-. Legalább 100-250 óra. Csoportlétszám: neurotikusoknál <b>10-14</b>, pszichotikusoknál <b>6-8</b>. Terápiás csoport heti rendszerességgel (holding funkció)."],["Gyermekterápia","A módszerek gyermekekre adaptált formája; szem előtt tartja a <b>fejlődési szempontot</b> és életkori sajátosságokat; esetenként nevelői attitűd; kapcsolattartás a szociális környezettel. Kontraindikáció: F07, F72-79. Heti 1-3 ülés. Szakember: gyermekpszichoterapeuta, gyermekpszichiáter, gyermekpszichológus. Eszköz: játékbattéria. Járulékos: család-, csoportterápia."]],"qs":[{"t":"mc","q":"Mi a mozgás- és táncterápia első alapelve?","o":["A test-lélek egysége","A szabad asszociáció","A kollektív tudattalan","A feltétel nélküli elfogadás"],"a":0,"e":"A koncepció erre épül."},{"t":"match","q":"Párosítsd a csoportot a javasolt létszámmal!","pairs":[["Neurotikusok csoportja","10-14"],["Pszichotikusok csoportja","6-8"]],"e":"Mozgás- és táncterápia csoportlétszám."},{"t":"mc","q":"Mi a hipnoterápia kulcseleme a hipnózis mellett?","o":["Szuggesztió","Álomelemzés","Feladatadás","Játékbatéria"],"a":0,"e":"Szuggesztió és erős áttételes kapcsolat."},{"t":"tf","q":"A hipnoterápia kombinálható viselkedés-, kognitív és pszichodinamikus módszerekkel.","a":true,"e":"Integráltan alkalmazható."},{"t":"mc","q":"Melyik eszköz kell a hipnoterápia aktív-éber formájához?","o":["Kerékpár ergométer","Játékbatéria","Egyirányú tükör","Képzőművészeti eszközök"],"a":0,"e":"A relaxációs formához kényelmes ülő/fekvő bútor."},{"t":"mc","q":"Ki végezheti a gyermekterápiát?","o":["Gyermekpszichoterapeuta, gyermekpszichiáter, gyermekpszichológus","Csak a szülő","Csak gyógypedagógus","Bárki"],"a":0,"e":"A forrás szerinti szakemberek."},{"t":"fill","q":"A gyermekterápia kontraindikációja F07 és F72-___ (szám).","a":["79"],"e":"F07, F72-79."},{"t":"tf","q":"A gyermekterápia a felnőtt terápiákkal azonos eszközrendszert használ.","a":false,"e":"Alapvetően eltérő, egységes eszközrendszerrel dolgozik, szem előtt tartva a fejlődést."}]},{"id":"u22l5","title":"Csoport-, pszichodráma-, család- és párterápia","theory":[["Dinamikus csoport-pszichoterápia","Pszichodinamikus, analitikus szemléletű verbális terápia <b>6-10</b> pácienssel; a tüneti viselkedés és a kapcsolatzavarok összefüggéseit célozza a csoport pszichodinamikai terében. Az egyéni kapcsolatot el nem viselő betegek is kezelhetők. Ambulánsan heti 1-3 duplaülés, osztályon heti 2-5 ülés, 20-100 ülés. Kontraindikáció: F0-, F30, F31, F45, F50, F7-."],["Pszichodráma","A tagok intrapszichés és interperszonális konfliktusait <b>drámajátékba</b> fordítja; az akció, az érzelmi átélés és belátás teszi lehetővé a változást. Oki és tüneti terápia. Minimum 20-70 <b>triplaülés</b>, min. heti egyszer. Szükséges: színpadi tér, székek, párnák. Járulékos: relaxáció, imagináció, hipnózis."],["Család- és párterápia","A családot egységként, rendszerként kezeli; a pácienst az egész családdal való munkával gyógyítja. <b>4-25</b> dupla vagy triplaülés; utánkövető ülés 3-12 hónapon belül. Kontraindikáció: családnélküli, egyedül élő páciens. Opcionálisan koterapeuta vagy in situ szupervízió; önállóan csak rendszeres szupervízióval végezhető."]],"qs":[{"t":"mc","q":"Hány pácienssel zajlik a dinamikus csoport-pszichoterápia?","o":["6-10","2-4","10-14","15-20"],"a":0,"e":"6-10 páciens."},{"t":"match","q":"Párosítsd a terápiát az ülésformával!","pairs":[["Dinamikus csoport (ambuláns)","Heti 1-3 duplaülés"],["Pszichodráma","Triplaülések"],["Családterápia","4-25 dupla vagy triplaülés"]],"e":"Ülésformák."},{"t":"mc","q":"Mit fordít át a pszichodráma drámajátékba?","o":["A tagok intrapszichés és interperszonális konfliktusait","A tünetek diagnózisát","A családi szabályokat","Az álmokat"],"a":0,"e":"Az akció, átélés és belátás hozza a változást."},{"t":"tf","q":"A családterápia kontraindikációja a családnélküli, egyedül élő páciens.","a":true,"e":"A terápia a családdal dolgozik."},{"t":"fill","q":"Családterápia után 3-12 hónapon belül egy ___ ülés lehet szükséges.","a":["utánkövető","utankovet","követő"],"e":"Utánkövető ülés."},{"t":"mc","q":"Mikor végezhető önállóan családterápia?","o":["Ha a rendszeres szupervízió biztosított","Bármikor","Csak koterapeutával","Csak kórházban"],"a":0,"e":"Opcionálisan koterapeuta vagy in situ szupervízió."},{"t":"tf","q":"A dinamikus csoportterápiában az egyéni kapcsolatot el nem viselő betegek is kezelhetők.","a":true,"e":"A csoportban sok ilyen beteg kezelhető."}]}],"color":"#1cb0f6"},{"id":"u23","title":"Rehabilitációs pszichológia","desc":"Szocializáció, sérülés, család, rehabilitáció","lessons":[{"id":"u23l1","title":"Szocializáció és megzavart szocializáció","theory":[["A szocializáció fogalma","Bagdy: a társadalomba beilleszkedés folyamata, melyben az egyén megismeri önmagát és környezetét, elsajátítja az együttélés szabályait. Brim: folyamat, mely által az egyén tudásra, képességekre tesz szert, hogy a csoportok és a társadalom hasznos tagja legyen. Buda: a személyiségfejlődés <b>társadalmi vetülete</b>. Első színtere a <b>család</b>: biztosítja a biológiai szükségleteket és közvetíti a szerepmintákat."],["Sérült ember és a visszajelzések","A sérült ember személyisége is a szocializációban bontakozik ki. A környezet visszajelzései lehetnek elutasítók (minél észrevehetőbb a sérülés, annál inkább), homályosak, torzak; a sérült elháríthatja a kedvezőtlen infót. Ezeknek a „tükröknek” a feldolgozása fontos a <b>reális énkép</b> kialakításához."],["Megzavart szocializáció","A modern család átalakult: nő a teljesítmény-orientált családok száma (több krízis, kisebb tolerancia, rosszabb kudarctűrés, deviancia); a válások száma nő (személyiségzavarok egyik oka). Az érzelmi frusztrációra adott regresszív/agresszív válasz deviáns magatartáshoz vezethet. Az iskola gyakran konformizmust vár; a <b>meg nem oldott konfliktus</b> káros a fejlődésre."]],"qs":[{"t":"mc","q":"Ki szerint a szocializáció a személyiségfejlődés társadalmi vetülete?","o":["Buda","Bagdy","Brim","Spitz"],"a":0,"e":"Buda szerint."},{"t":"mc","q":"Mi a szocializáció első színtere?","o":["A család","Az iskola","A munkahely","A kortárscsoport"],"a":0,"e":"Az érzelmileg legfontosabb közösség."},{"t":"tf","q":"A környezet visszajelzései a sérült ember számára mindig reálisak.","a":false,"e":"Lehetnek homályosak, torzak, hamis képet mutatók."},{"t":"mc","q":"Mi fontos a sérült ember reális énképének kialakításához?","o":["A környezeti „tükrök” elfogadása és feldolgozása","A sérülés titkolása","A visszajelzések elkerülése","Az izoláció"],"a":0,"e":"A visszajelzések megfelelő feldolgozása."},{"t":"match","q":"Párosítsd a szerzőt a szocializáció-definícióval!","pairs":[["Bagdy","Beilleszkedés, együttélés szabályai"],["Brim","Hasznos taggá válás tudása, képességei"],["Buda","A személyiségfejlődés társadalmi vetülete"]],"e":"A három meghatározás."},{"t":"mc","q":"A modern család változásai közül melyik járul hozzá a személyiségzavarokhoz?","o":["A válások számának növekedése","A családok méretének csökkenése","A bölcsődék elterjedése","A tágabb család erősödése"],"a":0,"e":"A válás a személyiségzavarok egyik jelentős oka."},{"t":"tf","q":"A nem megoldott konfliktus negatívan hat a személyiségfejlődésre.","a":true,"e":"A konfliktusok átélése, megoldása viszont a karakterfejlődést segíti."}]},{"id":"u23l2","title":"Hiányos szocializáció és a család krízisei","theory":[["Anya-gyermek kapcsolat","Az anya-gyermek kapcsolat sérülése átmeneti vagy tartós személyiségzavart okozhat; az anya reakciói (örömhiány, kétségbeesés, félelem) másodlagos zavarokat okozhatnak. Az anya és csecsemő között <b>duálunió</b> jön létre. <b>Spitz</b>: hospitalizmus – anyai gondozás és állandó személyes kapcsolat hiányában a külvilág érdektelenné válik. Koraszülötteknél az anya szeparációja sérti az anyai magatartást."],["A sérült gyermek családja: krízisek","1. A sérült gyermek születése: sokk, tagadás, harag-szomorúság, beletörődés, újraszerveződés. <b>Isarin</b>: kettős magatartás – szeretik a gyermeket, de a fogyatékosságot elutasítják.<br>2. Kinő a csecsemőkorból: az utca véleménye, szegregált vs. integrált nevelés.<br>3. Iskola vége: 24 órás program, nem biztos a leválás.<br>4. Félelem a jövőtől: ki gondozza, ha a szülő már nem tudja."],["Az oka és a megközelítés","A sérülés oka: genetikus, méhen belüli, szülési, szülés utáni ártalmak. A korai felismerés megelőzi a <b>szekunder károsodást</b>. A speciális szükségletű kifejezés a többletigényre helyezi a hangsúlyt, nem a deficitre."]],"qs":[{"t":"mc","q":"Mit írt le Spitz?","o":["A hospitalizmust","A duáluniót","A kettős magatartást","A tükörfázist"],"a":0,"e":"Anyai gondozás hiányában a külvilág érdektelenné válik."},{"t":"mc","q":"Kinek a nevéhez fűződik a szülők kettős magatartásának leírása?","o":["Isarin","Spitz","Bion","Brim"],"a":0,"e":"Szeretik gyermeküket, de a fogyatékosságot elutasítják."},{"t":"match","q":"Párosítsd a krízist a tartalmával!","pairs":[["Születés","Sokk, tagadás, harag, beletörődés"],["Csecsemőkor vége","Szegregált vs. integrált nevelés"],["Iskola vége","24 órás program biztosítása"]],"e":"A család krízisei."},{"t":"fill","q":"Az anya és a csecsemő közötti szoros egység neve ___.","a":["duálunió","dualunio","duál unió"],"e":"Duálunió."},{"t":"tf","q":"Az egyes krízisállapotok meg nem oldása a család széthullásához is vezethet.","a":true,"e":"A forrás szerint igen."},{"t":"mc","q":"Mit hangsúlyoz a „speciális szükségletű” kifejezés?","o":["A többletigényt","A deficitet","A betegséget","A rokkantságot"],"a":0,"e":"Nem a deficitre, hanem a többletigényre helyezi a hangsúlyt."},{"t":"mc","q":"Mi NEM a sérülés lehetséges oka?","o":["Tanári elvárások","Genetikus ártalom","Méhen belüli ártalom","Szülési ártalom"],"a":0,"e":"Genetikus, méhen belüli, szülési és szülés utáni ártalmak."}]},{"id":"u23l3","title":"A rehabilitáció és részterületei","theory":[["A rehabilitáció fogalma","Az egészségügyi, mentálhigiénés, oktatási, képzési, átképzési, foglalkoztatási és szociális rendszerekben megvalósuló folyamat, célja a fogyatékos személy képességeinek fejlesztése, társadalmi részvételének szinten tartása és az <b>önálló életvitel</b> elősegítése. Komplex szemlélet, szakemberek együttműködése."],["A sérülés fokozatai (WHO)","1. <b>Károsodás</b> – anatómiai, élettani, pszichológiai veszteség (biológiai működészavar).<br>2. <b>Fogyatékosság</b> – funkciók hiánya (emberi funkciózavar).<br>3. <b>Rokkantság</b> – a mindennapi tevékenységben való akadályozottság (társas szerepek zavara).<br>A WHO osztályozása a személy és környezet dinamikus kölcsönhatásából indul ki."],["Részterületek","<b>Orvosi</b> rehabilitáció (diagnosztika, terápia, prevenció, gondozás); <b>pedagógiai</b> (megfelelő munkahely, munkakörülmény); <b>foglalkozási</b>; <b>szociális</b> (anyagi támogatás, gondozás, lakás, közlekedés, szemléletformálás)."]],"qs":[{"t":"match","q":"Párosítsd a sérülés fokozatát a szinttel!","pairs":[["Károsodás","Biológiai működészavar"],["Fogyatékosság","Emberi funkciózavar"],["Rokkantság","Társas szerepek zavara"]],"e":"A három fokozat."},{"t":"mc","q":"Mi a rehabilitáció célja?","o":["A képességek fejlesztése, társadalmi részvétel, önálló életvitel","A betegség teljes megszüntetése","A sérült intézeti elhelyezése","A család leválasztása"],"a":0,"e":"A forrás definíciója szerint."},{"t":"mc","q":"Melyik rehabilitációs részterület foglalkozik az anyagi támogatással és lakással?","o":["Szociális","Orvosi","Pedagógiai","Pszichológiai"],"a":0,"e":"Anyagi támogatás, gondozás, lakás, közlekedés, szemléletformálás."},{"t":"tf","q":"A rehabilitáció komplex szemlélet, több szakterület együttműködését igényli.","a":true,"e":"Igen."},{"t":"fill","q":"A mindennapi tevékenységben való akadályozottság a ___.","a":["rokkantság"],"e":"A társas szerepek zavara."},{"t":"mc","q":"Mit jelent az orvosi rehabilitáció?","o":["Az orvostudomány saját eszközeivel végzett diagnosztika, terápia, prevenció, gondozás","Munkahely keresése","Anyagi támogatás","Társadalmi szemléletformálás"],"a":0,"e":"Hogy a rokkant ember önállósága visszatérjen."}]},{"id":"u23l4","title":"A pszichológus szerepe, család és gyermek","theory":[["A pszichológus szerepe","Diagnosztikai és terápiás eszközökkel segíti az ép intellektus kibontakozását; a reális önértékelés, a megmaradt és elveszett képességek felismerése, a maradandó károsodás elfogadása során formálódik újra az <b>énkép és értékrend</b>. Bevonjuk a családot, a <b>team</b>munka elengedhetetlen. Cél az integráció; a kapcsolat átalakul: a beteg <b>kliensként</b> képviseli jogait."],["A család megismerése","A sérülés „megrengeti” a családot. Fontos: a sérülés természete, súlyossága, szembetűnősége, kezdete; a gyermek neme; testvérek száma és állapota; születési sorrend (legnehezebb az elsőszülött fiú); szülők életkora; életszakasz; a család mérete és megküzdése; információk; a környezet értékrendje. Korai diagnózis csak korrekt diagnózisra épülhet; kerülni kell a stigmatizálást."],["Testvérek","Az egészséges testvér érezhet irigységet, igazságtalanságot, stresszt a kortársak elutasításától. Pozitív hatás: elfogadóbb lesz, nő a felelősségérzete, önállósága, együttérzése, erősödhet az önértékelése. A sérült testvér frusztrációt, dühöt, szomorúságot, irritációt élhet át."]],"qs":[{"t":"mc","q":"Melyik gyermek helyzete a legnehezebb a születési sorrend szempontjából?","o":["Az elsőszülött fiú","A középső lány","A legkisebb","Ikertestvér"],"a":0,"e":"A forrás szerint az elsőszülött és fiú esetén a legnehezebb."},{"t":"tf","q":"A hagyományos aszimmetrikus orvos-beteg kapcsolat átalakul, a beteg kliensként képviseli jogait.","a":true,"e":"Terápiás team, integráció."},{"t":"mc","q":"Melyik a rehabilitációs team tagja?","o":["Gyógytornász és konduktor","Csak az orvos","Csak a pszichológus","Csak a szociális munkás"],"a":0,"e":"Orvos, pszichológus, gyógypedagógus, gyógytornász, konduktor, szociális munkás, fejlesztő pedagógus."},{"t":"mc","q":"Mi a testvér lehetséges pozitív hatása?","o":["Elfogadóbbá válik, nő a felelősségérzete","Irigység","Elutasítás a kortársaktól","Dühkitörések"],"a":0,"e":"Beépül a másság tapasztalata, erősödik az önértékelés."},{"t":"fill","q":"A korai diagnózis csak ___ diagnózisra épülhet.","a":["korrekt","helyes"],"e":"Korrekt diagnózisra építve."},{"t":"mc","q":"Mit kell elkerülni a korai diagnosztizálásnál és fejlesztésnél?","o":["A stigmatizálást és kirekesztést","A kontrollvizsgálatot","A szociális juttatásokat","A team munkát"],"a":0,"e":"Biztosítani kell a terápiákhoz és juttatásokhoz való hozzájutást."},{"t":"tf","q":"A család megismerésénél a szülők életkora nem számít.","a":false,"e":"A fiatal szülők rugalmasabbak, de szűkösebb az anyagi helyzetük."}]},{"id":"u23l5","title":"Krónikus betegség és sérülésfeldolgozás","theory":[["Tipikus pszichés reakciók krónikus betegségre","Az élettér és kontaktuskör beszűkülése; fokozott egocentrizmus, követelő attitűd; megbélyegzettség, csökkentértékűség érzése; önértékelési zavar; depresszív reakciók; fokozott függőség; érzelmi-szociális regresszió; <b>túlkompenzálás</b> (irreális célok)."],["A traumát követő személyiség-alakulás","1. <b>Sokk, gyászreakció</b>: kétségbeesés, testvázlat- és személyiség-dezintegráció, depresszió, lázadás.<br>2. <b>Átstrukturálódás</b>, megküzdés kezdete: épen maradt képességekre támaszkodás; perfekcionizmus, kimerülés veszélye.<br>3. <b>Pszichológiai és szociális reintegráció</b>. Az életív során újra felmerül a szembesülés."],["Bion betegségmodellje; a feldolgozás tényezői","Bion fázisai: tudomásszerzés, elbizonytalanodás, félelem → hárítás, elutasítás → nyílt/rejtett agresszió (legnagyobb ellenállás) → apátia → <b>belenyugvás</b>, elfogadás, együttműködés.<br>A feldolgozás függ: premorbid személyiség, családi támogatás, intézményrendszer, önsegítő mozgalmak, társadalmi előítéletek, jogi keretek. A korai fejlesztés az első 6 életévet fedi (főleg az első 3 évet)."]],"qs":[{"t":"match","q":"Párosítsd a traumát követő szakaszt a jellemzővel!","pairs":[["1. szakasz","Sokk, gyászreakció"],["2. szakasz","Személyiség átstrukturálódása"],["3. szakasz","Pszichológiai-szociális reintegráció"]],"e":"A traumát követő személyiség-alakulás szakaszai."},{"t":"mc","q":"Bion modelljében melyik fázisban a legnagyobb az aktív ellenállás?","o":["Nyílt vagy rejtett agresszió","Hárítás","Apátia","Belenyugvás"],"a":0,"e":"Agresszió mindenkivel, főleg a közvetlen környezettel."},{"t":"mc","q":"Melyik NEM tipikus krónikus betegségre adott reakció?","o":["Az élettér kitágulása","Depresszív reakciók","Túlkompenzálás","Fokozott függőség"],"a":0,"e":"A jellemző az élettér beszűkülése."},{"t":"tf","q":"A későn szerzett sérülés feldolgozása függ a premorbid személyiségtől és a család támogatásától.","a":true,"e":"Valamint az intézményrendszertől, önsegítő mozgalmaktól stb."},{"t":"fill","q":"Az irreális célok kitűzése a krónikus betegségnél: ___.","a":["túlkompenzálás","tulkompenzalas","túlkompenzálás"],"e":"Túlkompenzálás."},{"t":"mc","q":"Mi Bion modelljének utolsó fázisa?","o":["Belenyugvás, elfogadás","Hárítás","Apátia","Elbizonytalanodás"],"a":0,"e":"Együttműködő, aktív kiútkereső."},{"t":"mc","q":"A korai aktív fejlesztés mely időszakot fedi?","o":["Az első hat életévet","A 6-18 éves kort","Az első évet","A felnőttkort"],"a":0,"e":"Leginkább az első három év a fókusza."}]}],"color":"#ce82ff"},{"id":"u24","title":"Korai fejlesztés","desc":"Célok, alapelvek, prevenció, szűrőtesztek","lessons":[{"id":"u24l1","title":"A korai fejlesztés célja","theory":[["Fogalma","A korai fejlesztés a rehabilitáció része: a <b>0-5 éves</b>, eltérő fejlődésű gyermekek tervszerűen felépített programja (komplex diagnosztika, gyógypedagógiai oktatás, fejlesztés, terápiák, pl. mozgásterápia, konduktív terápia). Sérülésnél 1 évig várható a funkciók visszatérése."],["Négy cél","1. A gyermek <b>optimális fejlődése</b> (az első években leggyorsabb a fejlődés üteme).<br>2. A <b>család támogatása</b>: elfogadás, családi kapcsolatok; kevesebb gyermek kerül intézetbe, megmarad a család kohéziója.<br>3. A <b>társadalmi beilleszkedés</b>: szocializáció, énkép, önértékelés.<br>4. A <b>társadalmi terhek csökkentése</b>: preventív és interventív; megelőzi a másodlagos problémákat; az anyák munkába állhatnak."],["Alapelvek","1. A <b>szülő dönt</b>, hogy kitől milyen segítséget kér; partner a folyamatban; a fejlettségről korrekten, a pozitívumokra helyezve a hangsúlyt kell tájékoztatni.<br>2. A fejlesztést <b>komplex vizsgálat</b> előzi meg (szakértői bizottság); a fejlesztés központja az <b>anya-gyermek kapcsolat</b>; egyénre szabott, kis lépések, állandóság, folyamatosság."]],"qs":[{"t":"mc","q":"Milyen korú gyermekekre vonatkozik a korai fejlesztés?","o":["0-5 évesek","0-18 évesek","3-10 évesek","6-12 évesek"],"a":0,"e":"0-5 éves eltérő fejlődésű gyermekek."},{"t":"mc","q":"Miért kiemelt az első néhány év?","o":["Az emberi fejlődés üteme ekkor a leggyorsabb","Ekkor a legolcsóbb a terápia","Ekkor kötelező az iskola","Ekkor nincs szükség családra"],"a":0,"e":"Különösen az átlagostól eltérő fejlődésűeknél."},{"t":"tf","q":"A korai fejlesztésben a szülő partner, ő dönt, milyen segítséget igényel.","a":true,"e":"Az első alapelv."},{"t":"mc","q":"Mi a fejlesztés központja?","o":["Az anya-gyermek kapcsolat","A gyógyszeres kezelés","Az óvoda","A szakértői bizottság"],"a":0,"e":"Egyénre szabott, kis lépésekben haladó program."},{"t":"mc","q":"Melyik NEM a korai fejlesztés célja?","o":["A szülők helyettesítése a nevelésben","A család támogatása","A társadalmi beilleszkedés segítése","A társadalmi terhek csökkentése"],"a":0,"e":"Négy cél van, a szülő helyettesítése nem tartozik közéjük."},{"t":"fill","q":"A fejlesztést minden esetben ___ vizsgálat előzi meg.","a":["komplex"],"e":"Szakértői bizottság kötelező vizsgálata."},{"t":"tf","q":"A szülőt a gyermek fejlettségéről a hiányosságokra helyezve a hangsúlyt kell tájékoztatni.","a":false,"e":"A pozitívumokra kell helyezni a hangsúlyt."}]},{"id":"u24l2","title":"Prevenció a korai fejlesztésben","theory":[["Primer prevenció","Egészséges gyermek – <b>alapszűrés</b>: lakossági felvilágosítás, sorozatos fejlődési, táplálkozási, fizikai szűrés, információ és vizsgálatra utalás, nyomon követés."],["Szekunder prevenció","Veszélyeztetett és az alapszűrésben felismert gyerekek – <b>irányított szűrés</b> a gyanús területekre: szülő oktatása, szolgáltatások koordinálása, nyomon követés (fizikai állapot, szájhigiéné, mentálhigiéné, táplálkozás, fejlődés)."],["Tercier prevenció","Egészségkárosodásra/fejlődési zavarra <b>gyanús</b> gyermekek – <b>funkcionális diagnosztika</b> (fejlődési vizsgálat); <b>egészségkárosodott</b> vagy fejlődési zavart mutató gyermekek – <b>speciális diagnosztika</b> (irányított kivizsgálás). Mindkettőnél: szülő oktatása, szolgáltatások koordinálása, nyomon követés."]],"qs":[{"t":"match","q":"Párosítsd a prevenciós szintet a célcsoporttal!","pairs":[["Primer","Egészséges gyermek"],["Szekunder","Veszélyeztetett gyermek"],["Tercier","Gyanús vagy károsodott gyermek"]],"e":"A prevenció három szintje."},{"t":"mc","q":"Melyik szinthez tartozik az alapszűrés?","o":["Primer","Szekunder","Tercier","Egyik sem"],"a":0,"e":"Egészséges gyermek – alapszűrés."},{"t":"mc","q":"Mit jelent az irányított szűrés?","o":["A gyanús területekre koncentrált szűrés","Minden gyermek általános szűrése","Gyógyszeres kezelés","Szakértői bizottsági döntés"],"a":0,"e":"Szekunder prevenció."},{"t":"tf","q":"A speciális diagnosztika az egészségkárosodott vagy fejlődési zavart mutató gyermekek irányított kivizsgálása.","a":true,"e":"Tercier prevenció."},{"t":"fill","q":"Az egészségkárosodásra gyanús gyermekeknél ___ diagnosztika (fejlődési vizsgálat) történik.","a":["funkcionális"],"e":"Funkcionális diagnosztika."},{"t":"mc","q":"Melyik elem szerepel MINDEN prevenciós szinten?","o":["Nyomon követés","Szakértői bizottság","Gyógyszeres kezelés","Intézeti elhelyezés"],"a":0,"e":"Mindhárom szinten szerepel a nyomon követés."}]},{"id":"u24l3","title":"Fejlődésvizsgálat: Denver II, Brunet-Lézine","theory":[["Szemléletváltozás","Az elmúlt 20 évben a gyermekrehabilitációs központban: időpontos rendelés, hatoldalas anamnézislap, <b>team vizsgálatok</b> és esetmegbeszélések (pszichológus, gyógypedagógus), korai diagnosztikai és szűrőmódszerek (Denver, Bayley, fejlődésterápiai mérföldkő skála), „Szivárvány” korai fejlesztő központ, zeneterápiás csoportok, szülőszervezet, szülőcsoport."],["Denver II.","Életkor: <b>1 hónapos kortól 6 éves korig</b>. Négy területet vizsgál: nagymotoros, finommotoros, önkiszolgálás, beszédkészség. <b>125 tétel</b>; jelzése: átlagos / gyanús / megkésett fejlődés. Következmény: a fejlődési problémákat 2 éves kor előtt diagnosztizálták; a fizikális elváltozással nem járó beszéd-, viselkedés-, kognitív zavarok szűrés nélkül felderítetlenek maradtak volna."],["Brunet-Lézine","Szűrőteszt <b>0-60 hónapos</b> korig, 4 területen: nagymozgás, finommozgás, személyes-szociális fejlődés, kommunikáció. <b>Nem diagnosztikai eszköz</b>; jelzi a lemaradást, nyomon követhető vele az elmaradás mértéke, gyakrabban elvégezhető, mint a fejlődéspszichológiai vizsgálat."]],"qs":[{"t":"mc","q":"Hány tételt alkalmaz a Denver II teszt?","o":["125","60","200","45"],"a":0,"e":"125 tétel."},{"t":"match","q":"Párosítsd a tesztet az életkori tartománnyal!","pairs":[["Denver II","1 hónaptól 6 évig"],["Brunet-Lézine","0-60 hónap"]],"e":"Életkori határok."},{"t":"mc","q":"Milyen jelzést ad a Denver II?","o":["Átlagos / gyanús / megkésett fejlődés","Intelligenciahányados","Diagnózis a BNO szerint","Személyiségprofil"],"a":0,"e":"Szűrőteszt."},{"t":"tf","q":"A Brunet-Lézine skála diagnosztizálásra való eszköz.","a":false,"e":"Csak jelzést ad a lemaradásról."},{"t":"mc","q":"Melyik terület NEM szerepel a Brunet-Lézine skálán?","o":["Önkiszolgálás","Nagymozgás","Finommozgás","Kommunikáció"],"a":0,"e":"Az önkiszolgálás a Denver területei közé tartozik; Brunet-Lézine: nagymozgás, finommozgás, személyes-szociális, kommunikáció."},{"t":"fill","q":"Az átfogó gyermekrehabilitációs központban létrejött korai fejlesztő központ neve: ___.","a":["Szivárvány","szivarvany"],"e":"„Szivárvány” korai fejlesztő központ."},{"t":"mc","q":"Mi a Denver II egyik konzekvenciája?","o":["A fejlődési problémákat már 2 éves kor előtt diagnosztizálták","Csak 6 éves kor után használható","Fizikális elváltozás nélkül nem működik","Kizárja a team vizsgálatot"],"a":0,"e":"A fizikális elváltozással nem járó zavarok is felderíthetők."}]}],"color":"#ff9600"},{"id":"u25","title":"Kutatás az egészségpszichológiában","desc":"Stratégiák, módszerek, kísérlet, korreláció","lessons":[{"id":"u25l1","title":"A kutatás folyamata és a kérdés","theory":[["Folyamat","Kérdésfelvetés; tájékozódás, szakirodalom-gyűjtés; tervezés (elővizsgálat); adatgyűjtés; adatfeldolgozás és elemzés; nyilvánossá tétel. Jó téma: motiváló, szakmailag elismert, új, jól tanulmányozható, megfelel a felkészültségünknek."],["Kutatási kérdés","<b>Mi?</b> kérdés – leíró és prediktív (nem experimentális, korrelatív kutatás). <b>Miért?</b> kérdés – oksági viszonyok (kísérleti vizsgálatok). A kérdésnél: téma leszűkítése, elegendő információ, elméleti megalapozottság, hozzáférhető módszer, idő, energia, eszköz."],["Hipotézis és operacionalizálás","<b>Hipotézis</b>: állítás formájában megfogalmazott feltevés, amely megnevezi a változókat és a köztük feltételezett összefüggés tartalmát és irányát. Jó hipotézis: vizsgálható, megalapozott, nem triviális, pontos, egy problémára fókuszál. <b>Operacionalizálás</b>: a jelenségek mérhetővé tétele (meghatározza a módszert is); fontos a <b>validitás</b>. <b>Konceptualizáció</b>: elméleti megközelítés és definíció kiválasztása."]],"qs":[{"t":"mc","q":"Melyik kérdéstípusra ad választ a kísérleti vizsgálat?","o":["Miért? (oksági)","Mi? (leíró)","Mennyi? (költség)","Ki? (mintavétel)"],"a":0,"e":"A leíró/prediktív kérdésre nem experimentális, korrelatív kutatás felel."},{"t":"mc","q":"Mi a hipotézis?","o":["Állítás formájú feltevés a változók közti összefüggésről","Az adatgyűjtés módszere","A minta nagysága","A kutatás eredménye"],"a":0,"e":"Megnevezi a változókat és az összefüggés tartalmát és irányát."},{"t":"fill","q":"A jelenségek mérhetővé tétele az ___.","a":["operacionalizálás","operacionalizalas"],"e":"Operacionalizálás."},{"t":"tf","q":"Jó hipotézis vizsgálható, megalapozott és nem triviális.","a":true,"e":"Valamint pontos és egy problémára fókuszál."},{"t":"mc","q":"Melyik a kutatási folyamat helyes sorrendje?","o":["Kérdés, szakirodalom, tervezés, adatgyűjtés, elemzés, közlés","Adatgyűjtés, kérdés, elemzés","Tervezés, közlés, adatgyűjtés","Elemzés, kérdés, tervezés"],"a":0,"e":"Hat lépés."},{"t":"match","q":"Párosítsd a kérdést a válaszadó kutatással!","pairs":[["Mi történik?","Leíró/korrelatív kutatás"],["Miért történik?","Kísérleti vizsgálat"]],"e":"Leírás vs. magyarázat."}]},{"id":"u25l2","title":"Kvantitatív és kvalitatív stratégia","theory":[["Kvantitatív","Előre rögzített, behatárolt változók; cél a változók <b>kontrollja</b>; hipotézis; általában <b>deduktív</b>; a mérés központi; nagy elemszám (általánosíthatóság); aszimmetrikus kutató–alany viszony; kötött, személytelen publikáció. Módszerek: kísérlet, tesztek, kérdőívek."],["Kvalitatív","Nyitott kérdéssel indul, természetes körülmények között; kevésbé specifikus hipotézis; <b>induktív</b>; kvalitatív adatok; részletező, többnézőpontú leírás; kisebb minta, hosszabb vizsgálat; kevésbé formális viszony; személyesebb publikáció. Módszerek: esettanulmány, mélyinterjú, résztvevő megfigyelés, fókuszcsoport."],["Mikor melyiket?","Kvalitatív: nehezen kvantifikálható tárgy, fontos a kontextus, egyedi jellemzők megragadása, feltáratlan terület, a kutató beállítottsága. A kettő nem választható szét élesen; közös: szisztematikusan gyűjtött adatok módszeres kritikai feldolgozása. Stratégiák: kvantitatív (kísérleti, korrelációs), kvalitatív."]],"qs":[{"t":"match","q":"Párosítsd a stratégiát a jellemzővel!","pairs":[["Kvantitatív","Deduktív, nagy elemszám"],["Kvalitatív","Induktív, kis minta, hosszabb vizsgálat"]],"e":"Fő különbségek."},{"t":"mc","q":"Mikor érdemes kvalitatív stratégiát választani?","o":["Ha a tárgy nehezen kvantifikálható és a kontextus fontos","Ha nagy mintán kell általánosítani","Ha okságot kell bizonyítani kísérlettel","Ha pontos statisztika kell"],"a":0,"e":"Feltáratlan területen is."},{"t":"tf","q":"A kvantitatív kutatás publikációja kötött és személytelen.","a":true,"e":"A kvalitatívé személyesebb hangvételű."},{"t":"mc","q":"Melyik módszer kvalitatív?","o":["Mélyinterjú","Kísérlet","Kérdőív","Skála"],"a":0,"e":"Esettanulmány, mélyinterjú, résztvevő megfigyelés."},{"t":"fill","q":"A kvantitatív stratégia általában ___ (kiindulása hipotézis).","a":["deduktív","deduktiv"],"e":"A kvalitatív induktív."},{"t":"mc","q":"Melyik kutatási stratégia célja a változók kontroll alatt tartása?","o":["Kvantitatív","Kvalitatív","Mindkettő egyformán","Egyik sem"],"a":0,"e":"Nemkívánatos hatások kiszűrése."}]},{"id":"u25l3","title":"Kvalitatív módszerek: fókuszcsoport, interjú","theory":[["Fókuszcsoport","Csoportos beszélgetés, mely kihasználja a csoportfolyamatokat, a tagok egymás közötti kommunikációját; 5-7 vagy 8-12 fő + <b>moderátor</b>; sorozatban. Lépések: cél; célcsoport és hely; moderátor; interjúvázlat; toborzás (legalább 10 nappal előtte); levezetés; elemzés; beszámoló."],["Fókuszcsoport előnyei, hátrányai","Előny: véleménycsere, spontán összefüggések, könnyen érthető eredmények, olcsóbb, mint a mélyinterjú, gyors. Hátrány: csoportfolyamatok, nem kvantitatív, nem reprezentatív, torzítások, időigényes leírás, moderátor befolyása."],["Interjútípusok","<b>Strukturált</b>, <b>félig strukturált</b>, <b>mélyinterjú</b>. Félig strukturált: nyitott kérdések, a legkevésbé érzékeny kérdéssel kezdünk, nincs jó/rossz válasz. Készségek: hallgatás, empátia, ítéletmentesség. Kvale kérdéstípusai: bevezető, direkt, indirekt, követő-mélyítő, pontosító, irányító, sugalmazó. Fontos a beleegyező nyilatkozat."],["Tartalomelemzés, megfigyelés, esettanulmány","<b>Tartalomelemzés</b>: szókategóriák előfordulása; Gottschalk és Gleser (1969); független kódolók, kódkönyv. <b>Természetes megfigyelés</b>: rejtett/nyílt, résztvevő/nem résztvevő, strukturált/strukturálatlan. <b>Esettanulmány</b>: leíró-feltáró, hipotézistesztelő, programértékelő."]],"qs":[{"t":"mc","q":"Mi a fókuszcsoport vezetője?","o":["Moderátor","Kontrollcsoport","Kódoló","Interjúalany"],"a":0,"e":"A moderátor saját véleményét elrejti."},{"t":"mc","q":"Legalább mennyivel a fókuszcsoport előtt kell toborozni?","o":["10 nappal","1 nappal","3 nappal","1 hónappal"],"a":0,"e":"Legalább 10 nappal előtte."},{"t":"mc","q":"Melyik a fókuszcsoport hátránya?","o":["Nem reprezentatív","Drága","Lassú","Nem lehet bárkivel"],"a":0,"e":"Csoportfolyamatok, torzítások, moderátor befolyása."},{"t":"match","q":"Párosítsd az interjútípust a jellemzővel!","pairs":[["Strukturált","Hasznos olvasási nehézségnél"],["Félig strukturált","Saját vélemény, nem kategóriák"],["Kvale-féle követő","Mélyítő kérdés"]],"e":"Az interjúk jellemzői."},{"t":"tf","q":"A félig strukturált interjú a legkevésbé érzékeny kérdéssel kezdődik.","a":true,"e":"A nem direkt kérdések jobbak."},{"t":"fill","q":"A szövegek szókategóriáit vizsgáló kvalitatív módszer a ___elemzés.","a":["tartalom","tartalomelemzés"],"e":"Tartalomelemzés (Gottschalk és Gleser)."},{"t":"mc","q":"Melyik NEM esettanulmány-típus?","o":["Kísérleti","Leíró-feltáró","Hipotézistesztelő","Programértékelő"],"a":0,"e":"Három típus."}]},{"id":"u25l4","title":"Kísérlet és kontrollcsoportok","theory":[["Változók","<b>Független</b> változó (manipulált), <b>függő</b> változó (mért), <b>alanyi</b> változó. A független változó típusai: környezeti manipuláció, instrukció általi manipuláció, invazív beavatkozás. <b>Kontroll</b>: kontrollcsoport, kontrollfeltétel. A kísérlet ok-okozati összefüggést vizsgál."],["Csoportekvivalencia","Random csoportba sorolás, vagy illesztett csoportbasorolás (gyakorisági eloszláson alapuló, párosításon alapuló illesztés). Mintaválasztási problémák: bevonási/kizárási feltételek, előítéletek, <b>drop-out</b>."],["Kontrollcsoport-típusok (Pintér, 1993)","Saját kontroll; kezelés nélküli csoport; várólistás betegek; minimális terápiás kontroll; placebo-terápiás kontroll; másféle kezelés mint kontroll."],["Efficacy és effectiveness","<b>Efficacy</b> (hatásosság): ideális, kontrollált körülmények között hatékony-e a terápia (RCT). <b>Effectiveness</b> (hatékonyság): mindennapi klinikai körülmények között működik-e. <b>Cost-effectiveness</b>: költség és hatékonysági mutatók alapján."]],"qs":[{"t":"match","q":"Párosítsd a fogalmat a jelentéssel!","pairs":[["Független változó","Manipulált tényező"],["Függő változó","Mért kimenet"],["Kontrollcsoport","Összehasonlítási alap"]],"e":"Kísérleti alapfogalmak."},{"t":"mc","q":"Melyik a független változó típusa?","o":["Instrukció általi manipuláció","Drop-out","Várólistás kontroll","Kohorsz"],"a":0,"e":"Környezeti, instrukciós, invazív."},{"t":"mc","q":"Mi az efficacy?","o":["Hatásosság ideális, kontrollált körülmények között","Hatékonyság a mindennapi klinikumban","A költséghatékonyság","A terápia megítélése"],"a":0,"e":"RCT-k keresik rá a választ."},{"t":"tf","q":"Az effectiveness azt vizsgálja, működik-e a terápia mindennapi körülmények között.","a":true,"e":"Hatékonyság."},{"t":"mc","q":"Melyik NEM kontrollcsoport-típus Pintér szerint?","o":["Kohorszcsoport","Várólistás betegek","Placebo-terápiás kontroll","Saját kontroll"],"a":0,"e":"A kohorsz kutatási típus, nem kontrollcsoport-típus."},{"t":"fill","q":"A mintából kiesők (a vizsgálatot abbahagyók) jelenségét ___-nak nevezzük.","a":["drop-out","dropout","drop out"],"e":"Drop-out."},{"t":"mc","q":"Mire szolgál a random csoportba sorolás?","o":["Csoportekvivalencia biztosítására","A minta csökkentésére","Az interjú rögzítésére","Kvalitatív kódolásra"],"a":0,"e":"Csoportekvivalencia."}]},{"id":"u25l5","title":"Érvényesség, RCT, korrelációs stratégia","theory":[["A belső érvényesség veszélyforrásai","Elvárásjellemző (el nem várás hangsúlyozása, cél leplezése); kísérletvezetői elfogultság (<b>kettős vak</b> kísérlet, automatizálás); sorozathatás (ellensúlyozás); idői hatás (várakozás, külső esemény, érési hatás – spontán remisszió, drop-out)."],["RCT","<b>Randomizált kontrollált kezelés.</b> Előny: statisztikai csoportösszehasonlítás. Hátrány: nagyon drága, a randomizálás etikai problémái, kérdéses általánosíthatóság; kötelező a tájékoztatott beleegyezés."],["Korrelációs stratégia","Nincs manipuláció, az <b>együttjárást</b> vizsgálja (Galton, 1884). Alanyi változókon nyugvó (ex post facto) vizsgálatok. Keresztmetszeti vs. hosszmetszeti; retrospektív vs. prospektív.<br><b>Kohorsz</b>: előre tervezett, ok→betegség; olcsóbb, kevesebb etikai gond, mint RCT; okságra nem következtethetünk.<br><b>Eset-kontroll</b>: utólagos, ok←betegség; ritka betegségeknél szinte az egyetlen mód; torzításra hajlamos, a kontroll kiválasztása nehéz."],["Eszközök, kérdezői torzítások","Tesztek (képesség-, teljesítmény-, személyiségtesztek), kérdőívek, attitűdskálák, beavatkozásmentes vizsgálatok. Érvényességet veszélyeztet a kérdező, a válaszadó (motiváció, kognitív problémák, válaszbeállítódás), külső körülmények. Megoldások: rapport, tréning, szupervízió, kontrollkérdések, hazugságskála, projektív kérdezés."]],"qs":[{"t":"mc","q":"Mit biztosít a kettős vak kísérlet?","o":["A kísérletvezetői elfogultság és elvárás csökkentését","A nagy mintát","A kvalitatív elemzést","A ritka betegségek vizsgálatát"],"a":0,"e":"Ez a belső érvényesség veszélyforrásainak kezelése."},{"t":"match","q":"Párosítsd a vizsgálati típust a jellemzővel!","pairs":[["RCT","Randomizálás, drága"],["Kohorsz","Előre tervezett, ok→betegség"],["Eset-kontroll","Utólagos, ritka betegségekhez"]],"e":"Típusok."},{"t":"tf","q":"A kohorszkutatásból okságra is következtethetünk.","a":false,"e":"Csak a kapcsolat fennállására."},{"t":"mc","q":"Mi az eset-kontroll vizsgálat fő előnye?","o":["Ritka betegségeknél kb. az egyetlen mód","Nincs torzítás","Megmutatja az okságot","Kettős vak"],"a":0,"e":"Egyszerű, olcsó, gyors."},{"t":"fill","q":"A korrelációs stratégia kezdete ___ nevéhez fűződik (1884).","a":["Galton"],"e":"Galton, 1884."},{"t":"mc","q":"Melyik az RCT hátránya?","o":["Etikai problémák a randomizálásnál","Nincs kontrollcsoport","Nem statisztikai","Nincs tájékoztatott beleegyezés"],"a":0,"e":"Drága, kérdéses az általánosíthatóság."},{"t":"mc","q":"Mi a spontán remisszió a belső érvényesség szempontjából?","o":["Érési hatás (idői hatás)","Kísérletvezetői elfogultság","Sorozathatás","Elvárásjellemző"],"a":0,"e":"Idői hatás részeként."}]}],"color":"#ff4b4b"},{"id":"u26","title":"Pszichoszomatika","desc":"Pszichoanalitikus modellek, Alexander","lessons":[{"id":"u26l1","title":"Lelki-testi egység, Freud","theory":[["Normális pszichoszomatikus összefüggés","Az érzelmi állapotot mindig testi leképeződés kíséri: szívfrekvencia- és légzésszám-emelkedés, izzadás, remegés, szimpatikus tónusfokozódás, az amygdala aktivitása. Fordítva a test ellazulása, az aktív sport kellemes érzelmi állapotot idéz elő (szomatopszichés összefüggés)."],["Pszichoszomatikus zavar, rendszerelmélet","Példa: tartós intrapszichés feszültség gyakran a gasztrointesztinális traktus érintettségével jár (hasmenés, székrekedés, gasztritisz). A pszichés és cerebrális folyamatok kapcsolatát a rendszerelmélet fogja meg a legjobban: komplex jelenségeket a szaktudományi ismeretek integrálásával lehet leírni."],["Freud: három instancia","<b>Én</b>: szabályozó, serkentő és gátló, a realitáselv szerint működik. <b>Felettes én</b> (énideál, lelkiismeret): a morált és a külvilág elvárásait képviseli. <b>Tudattalan</b>: ösztönös késztetések, vágyak; az örömelv vezérli. Ez elméleti modell, nem köthető anatómiai struktúrához."],["Regresszió és konverzió","Patológiánál regresszió történik: verbalizáció (intellektualizálódás) helyett szomatizáció (averbális kifejezés). A legfontosabb átalakulás a testi tünetben megjelenő <b>konverzió</b>: a libidó tudattalanul szomatikus beidegzésű energiává alakul, elsősorban a mozgatórendszert érintve."]],"qs":[{"t":"mc","q":"Melyik a Freud-féle három instancia helyes felsorolása?","o":["Én, Felettes én, Tudattalan","Én, Felettes én, Ösztön-én","Tudatos, Tudatelőtti, Tudattalan","Én, Ideál-én, Szuperego-én"],"a":0,"e":"Az Én, a Felettes én és a Tudattalan alkotja a hierarchikus rendszert."},{"t":"tf","q":"A tudattalant a realitáselv vezérli.","a":false,"e":"A realitáselv az Én működési elve; a tudattalant az örömelv vezérli."},{"t":"mc","q":"Mit jelent a szomatizáció a notesz szerint?","o":["Verbalizáció helyett averbális, testi kifejezés","Az intellektualizálódás fokozódása","A felettes én megerősödése","A testi tünet tudatos eljátszása"],"a":0,"e":"Regresszióban az intellektualizálódás/verbalizáció helyett szomatizáció lép fel."},{"t":"fill","q":"A legfontosabb átalakulás a testi tünetben megjelenő ___.","a":["konverzió"],"e":"A libidó szomatikus energiává alakul."},{"t":"match","q":"Párosítsd az instanciát a jellemzőjével!","pairs":[["Én","realitáselv"],["Tudattalan","örömelv"],["Felettes én","lelkiismeret, morál"]],"e":"Freud instanciái."},{"t":"mc","q":"Melyik a normális szomatopszichés összefüggés példája?","o":["Sport utáni izomellazulás kellemes érzelmi állapota","Tartós feszültség okozta gasztritisz","Konverziós bénulás","Szimbolikus testi tünet"],"a":0,"e":"A test ellazulása, az izmok fokozott vérátáramlása kellemes érzelmi állapotot idéz elő."},{"t":"tf","q":"A rendszerelmélet szerint komplex jelenségek a szaktudományi ismeretek integrálásával írhatók le.","a":true,"e":"Ezért a rendszerelmélet fogja meg legjobban a pszichés-cerebrális összefüggést."}]},{"id":"u26l2","title":"Konverzió és szerzők a pszichoanalízisben","theory":[["Konverziós modell","Neurózisban az Én instanciák között konfliktus alakul ki, de az egyén a külvilággal a kapcsolatot teljesen megtartja. A konfliktus sikertelen elhárítása esetén a felesleges energia a mozgató apparátusra tevődik át. Később a vegetatív-autonóm szerveket is feltételezték."],["Abraham, Groddeck, Ferenczi","<b>Abraham</b>: a konverziós mechanizmus prégenitális szakra is épülhet. <b>Groddeck</b>: a konverziót sokféle szervbetegségre alkalmazza; a vegetatív szervek zavarát szimbolikus közlésként értelmezi (regresszív konverzió). <b>Ferenczi</b> a konverziós hisztéria és a szervneurózisok közti határ elmosódottságára figyelt fel (autoplasztikus fogalom)."],["Betegségelőny","Hisztériában a tünet átmenetileg enyhíti a feszültséget: <b>elsődleges betegségelőny</b>. Pszichoszomatikus betegségben ez nem áll fenn, a beteg a saját testét károsítja a levezetés helyett. <b>Stokvis</b>: a valódi neurózisban nincs autodestrukció, a testi tünet szimbolikus funkciójú; másodlagos betegségelőny (szociális odafordulás) lehetséges, elsődleges nem."],["Fenichel, Deutsch","<b>Fenichel</b> (40-es évek): a pszichoszomatikus betegségek prégenitális konverziós neurózisok, a valódi neurózisok az ödipális/genitális szakban elszenvedett trauma miatti regressziók. <b>Deutsch</b>: Adler „szervbeszéd” mechanizmusát hangsúlyozta; a konverzióban a szimbolizálás a legfontosabb alakító tényező. <b>Grinker</b> már az 50-es években a stressz szerepére mutatott rá."]],"qs":[{"t":"mc","q":"Ki mutatott rá, hogy a konverziós mechanizmus prégenitális szakra is épülhet?","o":["Abraham","Fenichel","Stokvis","Weisman"],"a":0,"e":"Abraham indíttatására alkalmazta Groddeck a konverziót többféle szervbetegségre."},{"t":"mc","q":"Mi jellemzi a konverziót neurózisban?","o":["A felesleges energia a mozgató apparátusra tevődik át","Az énhatárok teljes feloldódása","A külvilággal való kapcsolat megszakadása","Az örömelv megszűnése"],"a":0,"e":"Az egyén közben megtartja a külvilág kontaktusait."},{"t":"tf","q":"Pszichoszomatikus betegségben fennáll az elsődleges betegségelőny.","a":false,"e":"Hisztériában van elsődleges előny; pszichoszomatikus betegségben a beteg a saját testét károsítja."},{"t":"match","q":"Párosítsd a szerzőt az állításával!","pairs":[["Groddeck","vegetatív szervzavar = szimbolikus közlés"],["Stokvis","neurózisban nincs autodestrukció"],["Fenichel","pszichoszomatikus = prégenitális konverziós neurózis"],["Grinker","a stressz kiváltó szerepe (50-es évek)"]],"e":"Szerzők és tételeik."},{"t":"fill","q":"Hisztériában a tünet átmenetileg enyhíti a feszültséget, ez az ___ betegségelőny.","a":["elsődleges","elsodleges"],"e":"Másodlagos előny a szociális odafordulás."},{"t":"mc","q":"Deutsch szerint a konverzióban mi a legfontosabb alakító tényező?","o":["A szimbolizálás","A regresszió","A projekció","Az elfojtás"],"a":0,"e":"Deutsch Adler szervbeszéd-mechanizmusát hangsúlyozta."},{"t":"tf","q":"Ferenczi szerint éles határ van a konverziós hisztéria és a szervneurózisok között.","a":false,"e":"Ferenczi a határok elmosódottságára figyelt fel."}]},{"id":"u26l3","title":"Erikson, Schur, francia iskola, alexitímia","theory":[["Eriksoni funkcionális fejlődés","Erikson (és Schultz) átvette a „szervbeszéd” feltevést. Szervi módozatok: <b>receptív bekebelező</b> (passzív befogadás, biztonság), <b>aktív bekebelező</b> (birtoklás, harapás: agresszió), <b>érintés</b> (valahová tartozás, függés), <b>retenciós</b> (visszatartás, birtoklás), <b>kiválasztó</b> (odaadás, alávetettség vagy tiltakozás), <b>genitális penetráló / befogadó</b>."],["Schur: deszomatizáció és reszomatizáció","Korai életszakaszban az affektusokat diffúz testi jelenségek kísérik; később megtanuljuk szétválasztani őket. <b>Deszomatizáció</b>: tudatossággal párosuló fejlődés, a magasabb pszichés funkciók átveszik az alacsonyabbak helyét. <b>Reszomatizáció</b>: regresszió, az én funkciók nem tudják fenntartani a szintet, a tehermentesítés ismét szervi kifejeződést keres; ez tudattalan."],["Hartmann és a francia iskola","Hartmann: a pszichoszomatikust a fantáziálás szabadságának defektje jellemzi, a tudatos-tudattalan konfliktusok hiányával. Francia iskola (Marty, David, Fain, de M’Uzan): specifikus személyiségstruktúra, preverbális kommunikáció, a fantáziálás hiánya, konkrétumokhoz tapadás, gyenge én funkciók vagy rigid énstruktúra."],["Alexitímia (Nemiah)","Az alexitímiás nem tudja érzelmeit kimutatni és verbalizálni, nem tud szabadon asszociálni, érzéseit a testében nem lokalizálja. Gondolkodása automatikus, mechanikus, érzelmi laposság jellemzi, mozgása darabos (pinokkió-szindróma). Nemiah szerint az anya csődöt mond a gyermek autoerotikus aktivitásában, így sérül a fantáziálás."]],"qs":[{"t":"match","q":"Párosítsd az eriksoni módozatot az élménnyel!","pairs":[["Receptív bekebelező","passzív befogadás, biztonság"],["Retenciós","visszatartás, birtoklás"],["Kiválasztó","odaadás, alávetettség vagy tiltakozás"],["Érintés","valahová tartozás, függés"]],"e":"Eriksoni funkcionális modell."},{"t":"mc","q":"Mit jelent a reszomatizáció?","o":["Regresszió: a tehermentesítés ismét szervi kifejeződést keres","A tudatosság fokozódása","A testi tünetek szimbolikus feldolgozása","Az érzelmek verbalizálása"],"a":0,"e":"A reszomatizáció tudattalan, ellentétben a deszomatizációval."},{"t":"tf","q":"A deszomatizáció tudatossággal párosuló fejlődési folyamat.","a":true,"e":"A magasabb pszichés funkciók átveszik az alacsonyabbak helyét."},{"t":"mc","q":"Melyik jellemző az alexitímiára?","o":["Az érzések verbalizálásának és testi lokalizálásának nehézsége","Túlzott fantáziálás","Gazdag szimbolikus gondolkodás","Szabad asszociáció képessége"],"a":0,"e":"Nemiah leírása szerint az érzéseket nem tudják verbalizálni."},{"t":"fill","q":"Az alexitímiás beteg darabos mozgását ___-szindrómának nevezik.","a":["pinokkió","pinokkio","Pinokkió"],"e":"Merev magatartás, darabos mozgás."},{"t":"tf","q":"Hartmann szerint a pszichoszomatikust a fantáziálás szabadságának defektje jellemzi.","a":true,"e":"A tudatos-tudattalan konfliktusok hiányával összekapcsolva."},{"t":"mc","q":"Melyik a francia iskola képviselője?","o":["Marty","Alexander","Cremerius","Menninger"],"a":0,"e":"Marty, David, Fain, de M’Uzan tartoznak ide."},{"t":"mc","q":"Az aktív bekebelező viselkedés késői kiegészítése, amely agresszív tartalmat hordoz:","o":["harapás","simogatás","kiválasztás","ölelés"],"a":0,"e":"A táplálékfelvétel birtoklás/önfenntartás élménye kiegészül a harapással."}]},{"id":"u26l4","title":"Alexander és az archaikus én","theory":[["Alexander: specifikus konfliktus","Szervsérülékenység részben öröklött alkati, részben környezeti. A pszichés hatások három csoportja: <b>akaratlagos viselkedés</b>, <b>expresszív innerváció</b> (nevetés, sírás), <b>vegetatív reakciók emóciókban</b>. A hipertóniás/fekélybeteg szerv-tünete nem szimbolikus, hanem a feszültség fiziológiai kísérője. A fekélybeteg elfojtja a szeretet/gondoskodás utáni vágyát (orális függőség)."],["Multifaktoriális keletkezés","Alexander: pszichoszomatikus betegség akkor jön létre, ha magas fokú organikus sérülékenység társul emocionális sérülékenységgel. Alapok: 1. a pszichés megterhelés túl erős vagy túl hosszú, 2. emocionális rendellenesség (neurotikus fejlődés), 3. a vegetatív válasz kóros irányba halad. Kísérlet: a szomatikus betegség ismerete nélkül 51%-os találati arány."],["Kritikák","<b>Nemiah</b>: a neurofiziológiai hipotézisek hasznosabbak. <b>Maher</b>: a tárgyveszteség erős általános stresszt jelent, de nem szabja meg a szervi specifitást. <b>Weisman</b>: elveti a betegségspecifikus konfliktust; aktív és passzív törekvések közti konfliktusok. Az 50-es évek viselkedéslélektana: a tünet maga a betegség, mögötte nincs rejtett mechanizmus. <b>Boor</b>: a pszichoszomatika a trójai faló, amely a pszichoanalízist becsempészte az orvostudományba."],["Amon: archaikus én betegség","A korai anya-gyermek viszony zavara („alapzavar”) az énfunkciók zavarát okozza. Gyenge énhatárok, „énlyuk”; alap-konfliktus a <b>szimbiózis komplexum</b>. A pszichoszomatikus tünet virtuálisan befedi a lyukat: a lelki egyensúly helyreáll, de a testi integritás veszélyben. Az anya ambivalens, kettős üzenetet közvetít. <b>Mitscherlich</b> kétfázisú elfojtása: az első fázis neurotikus tünet, a második a testre tevődik át."]],"qs":[{"t":"mc","q":"Alexander szerint mikor jön létre pszichoszomatikus betegség?","o":["Magas organikus és emocionális sérülékenység együtt","Csak tudattalan konfliktus esetén","Kizárólag genetikai ok miatt","Csak gyermekkori trauma miatt"],"a":0,"e":"Multifaktoriális: organikus + emocionális sérülékenység."},{"t":"tf","q":"Alexander szerint a fekély szimbolikus tünet.","a":false,"e":"A tünet nem szimbolikus tehermentesítés, hanem a feszültség fiziológiai kísérője."},{"t":"fill","q":"Amon az alap-konfliktushelyzetet ___ komplexumnak nevezte.","a":["szimbiózis","szimbiozis"],"e":"A korai szimbiózisból való kilépés akadályozott."},{"t":"match","q":"Párosítsd a szerzőt a kritikával / tézissel!","pairs":[["Weisman","aktív-passzív törekvések konfliktusa"],["Maher","nincs szervi specifitás"],["Mitscherlich","kétfázisú elfojtás"],["Amon","énlyuk"]],"e":"Kritikák és újabb modellek."},{"t":"mc","q":"Melyik NEM tartozik Alexander szerint a multifaktoriális betegségkeletkezés alapjai közé?","o":["Szimbiózis komplexum","Túl erős vagy hosszú pszichés megterhelés","Neurotikus személyiségfejlődés","Kóros irányú vegetatív válasz"],"a":0,"e":"A szimbiózis komplexum Amon fogalma."},{"t":"tf","q":"Boor szerint a pszichoszomatika a pszichoanalízis „trójai falova” az orvostudományban.","a":true,"e":"Becsempészte a pszichoanalízist az orvostudományba."},{"t":"mc","q":"Mit jelent az „énlyuk” Amon szerint?","o":["Az én képtelen beépíteni bizonyos tapasztalatokat, ez énhiány","A felettes én hiánya","A tudattalan teljes elfojtása","Az érzelmek túlzott kifejezése"],"a":0,"e":"A gyenge énhatárok miatt az én idegenként éli meg és leválasztja a tapasztalatokat."}]}],"color":"#2b70c9"},{"id":"u27","title":"Pszichofarmakológia","desc":"Transzmitterek, gyógyszercsoportok","lessons":[{"id":"u27l1","title":"Szinapszis és neurotranszmitterek","theory":[["Ingerületátvitel","Típusai: gap junction (réskapcsolat) és kémiai szinapszis. Hírvivők: hormonok, neurotranszmitterek, lokális (parakrin) anyagok. Neuronkapcsolódás: axoszomatikus, axodendritikus, axoaxonális. <b>Depolarizáció</b> (Na+ beáramlás) = serkentés; <b>hiperpolarizáció</b> (Cl- túlsúly a posztszinaptikus membránon) = gátlás. A Na-K pumpa (3 Na+ ki, 2 K+ be, ATP-vel) segíti a repolarizációt."],["Receptorok","Működés szerint: exitátor (depolarizáció), inhibitor (hiperpolarizáció). Hely szerint: pre- és posztszinaptikus. Autoreceptor: a saját sejt transzmitterére; heteroreceptor: idegenére. Receptor gátlása = antagonizmus, serkentése = agonizmus. A preszinaptikus receptor negatív feedbackkel működik: nagy koncentrációnál leállítja a felszabadulást."],["Mi számít neurotranszmitternek?","Kritériumok: a preszinaptikus sejtben szintetizálódik; elegendő mennyiségben válaszkiváltó; külső bejuttatása is választ vált ki; speciális lebontási mechanizmus van (visszaszívódás = reuptake, vagy lebontás, pl. MAO A/B a sejtben). A kotranszmitter/neuromodulátor nagyobb molekulájú, lassabban hat, tartósabb a hatása (pl. endorfinok)."],["Diszregulációs hipotézis","A kórképeket a transzmitterek koncentrációjának és a receptorok érzékenységének változásával magyarázzák (down- vs. up-reguláció). Az antidepresszívum csökkenti az érzékenységet (deszenzitizál), az antipszichotikum növeli (hiperszenzitizál). Összefüggések: skizofrénia ~ dopaminerg, depresszió ~ szerotoninerg, szorongás ~ GABA-erg, demencia ~ kolinerg."]],"qs":[{"t":"mc","q":"Mi okozza a posztszinaptikus gátlást?","o":["Hiperpolarizáció (Cl- túlsúly)","Depolarizáció","Na+ beáramlás","K+ pumpálása befelé"],"a":0,"e":"A Cl- vándorlása hiperpolarizál."},{"t":"match","q":"Párosítsd a fogalmat a jelentésével!","pairs":[["Agonizmus","receptor serkentése"],["Antagonizmus","receptor gátlása"],["Autoreceptor","saját sejt transzmitterére"],["Heteroreceptor","idegen transzmitterre"]],"e":"Receptortípusok."},{"t":"tf","q":"A Na-K pumpa három Na+ iont pumpál ki és két K+ iont vesz fel, energiaigénnyel (ATP).","a":true,"e":"Aktív transzport, segíti a repolarizációt."},{"t":"fill","q":"A transzmitter visszaszívódását angolul ___ néven ismerjük.","a":["reuptake"],"e":"A lebontás másik módja az enzimes bontás."},{"t":"mc","q":"Melyik társítás szerepel a jegyzetben?","o":["Szorongás ~ GABA-erg","Depresszió ~ GABA-erg","Demencia ~ dopaminerg","Skizofrénia ~ kolinerg"],"a":0,"e":"Skizofrénia ~ dopaminerg, depresszió ~ szerotoninerg, szorongás ~ GABA-erg, demencia ~ kolinerg."},{"t":"tf","q":"Az antipszichotikum a receptorok érzékenységét csökkenti.","a":false,"e":"Az antidepresszívum csökkenti, az antipszichotikum növeli az érzékenységet."},{"t":"mc","q":"A kotranszmitter jellemzője:","o":["Lassabban hat, tartósabb posztszinaptikus hatású","Gyorsabban szintetizálódik","Kisebb molekulájú","Csak serkentő"],"a":0,"e":"Nagyobb molekulasúly, lassabb szintézis és hatás."}]},{"id":"u27l2","title":"Acetilkolin, monoaminok, GABA","theory":[["Acetilkolin","Kognitív funkciók; hippokampusz. Alulműködése Alzheimer-kórban: minél kevesebb, annál súlyosabb az emlékezetvesztés. Az ideg-izom szinapszisban is acetilkolin működik. Receptorai: nikotin- és muszkarin-receptorok. Bontója az acetilkolin-észteráz; elosztóközpont a nucleus basalis Meynerti. Acetilkolin-bontást gátló szerek Alzheimerben, Parkinsonban."],["Katekolaminok","Szintézis: tirozin → L-Dopa → dopamin → noradrenalin → adrenalin. Bomlástermék: dopamin: HVA, noradrenalin: MHPG. <b>Noradrenalin</b>: stresszválasz, jutalmazás, motiváció, REM; a szimpatikus idegrendszer alapvető hormonja; szintézis a locus coeruleusban. Receptorok: alfa (α1, α2), béta (β1, β2)."],["Dopamin","Három pályarendszer: <b>nigrostriális</b> (hiánya: Parkinson), <b>mezokortikális-mezolimbikus</b> (pszichés állapot, affektus, kogníció), <b>tuberoinfundibuláris</b> (D2; prolaktin gátlása, blokádja: tejcsorgás). Receptorok D1-D5; a D3 gátló autoreceptor csak a limbikus rendszerben."],["Szerotonin, GABA, opiátok","<b>Szerotonin</b>: raphe-magok; bomlástermék 5-HIAA; a tobozmirigyben belőle melatonin (cirkadián ritmus); étkezés, testhő, alvás. <b>GABA</b>: gátló transzmitter, előanyaga (glutamát) serkentő; epilepszia, szorongás; GABA-A gyors, hiperpolarizál; GABA-B lassú. <b>Opiátok/endorfinok</b>: neuromodulátorok (μ, κ, δ receptorok), fájdalomcsillapítás, eufória."]],"qs":[{"t":"mc","q":"Melyik pályarendszer károsodása okoz Parkinson-kórt?","o":["Nigrostriális","Mezolimbikus","Tuberoinfundibuláris","Mezokortikális"],"a":0,"e":"Dopaminhiány a nigrostriális pályán."},{"t":"fill","q":"A dopamin bomlásterméke a ___.","a":["HVA","hva"],"e":"A noradrenaliné az MHPG."},{"t":"mc","q":"Mi a következménye a tuberoinfundibuláris D2-blokádnak?","o":["Tejcsorgás (prolaktin)","Parkinson-kór","Epilepszia","Alvászavar"],"a":0,"e":"A dopamin gátolja a prolaktint; blokádja tejcsorgást okoz."},{"t":"match","q":"Párosítsd a transzmittert a bomlástermékkel / jellemzővel!","pairs":[["Szerotonin","5-HIAA"],["Noradrenalin","MHPG"],["Dopamin","HVA"],["Acetilkolin","acetilkolin-észteráz bontja"]],"e":"Bomlástermékek."},{"t":"tf","q":"A GABA előanyaga, a glutamát gátló hatású.","a":false,"e":"A glutamát serkentő, a GABA gátló."},{"t":"mc","q":"Hol szintetizálódik a noradrenalin?","o":["Locus coeruleus","Raphe-magok","Tobozmirigy","Hipofízis"],"a":0,"e":"A locus coeruleus felel a szintéziséért."},{"t":"tf","q":"A szerotoninból melatonin szintetizálódik a tobozmirigyben.","a":true,"e":"A cirkadián ritmus hormonja."},{"t":"mc","q":"Alzheimer-kórban melyik rendszer alulműködik?","o":["Kolinerg","Szerotoninerg","Noradrenerg","GABA-erg"],"a":0,"e":"Az előagyi acetilkolin-termelő sejtek alulműködése."}]},{"id":"u27l3","title":"Antipszichotikumok","theory":[["Hatásmechanizmus, csoportok","Első szer: 1952 (chlorpromazin). A skizofrénia pozitív tüneteit kezelik; D2-gátlás a mezolimbikus és mezokortikális rendszerben. <b>Klasszikus (első generációs)</b>: hatásuk arányos a D2-affinitással; extrapiramidális és hormonális mellékhatások; kis, közepes, nagy potenciálúak (nagy potenciál: legvalószínűbb extrapiramidális mellékhatás). <b>Atípusos (második generációs)</b>: szelektívebb, szerotoninerg gátlás is, a negatív tüneteket is befolyásolja, kedvezőbb mellékhatásprofil."],["Terápiás hatás, mellékhatások","A terápiás hatás ~3 hét múlva jelenik meg, a mellékhatás 2-3 nap múlva. Extrapiramidális: akut disztónia (ferdenyak), akatízia, parkinsonizmus, tardív diszkinézia (csámcsogás, csettintés). Neuroleptikus malignus szindróma: láz, rigiditás, tudatzavar, vegetatív zavar. Adrenerg gátlás: ortosztatikus hipotenzió; antikolinerg: szájszárazság, obstipáció, vizeletretenció. Endokrin: tejfolyás, menstruációszavar, szexuális diszfunkció. Atípusosoknál: súlygyarapodás, inzulinháztartás-eltérés."],["Egyes szerek (jegyzet szerint)","<b>Haloperidol</b>: D2-blokád, akut pszichózis, delírium. <b>Tiaprid</b>: D2-antagonista; agresszió, Tourette; kifejezett Parkinsonban nem. <b>Clozapin (Leponex)</b>: fehérvérsejtszám csökkenés, nyálcsorgás, lassulás. <b>Risperidon</b>: hízás, tejcsorgás. <b>Quetiapin</b>: szedáció, vérnyomáscsökkenés. <b>Olanzapin</b>: nincs extrapiramidális mellékhatás, antikolinerg. <b>Aripiprazol</b>: 5-HT1A részleges agonista, első shub. <b>Ziprasidon</b>: kardiális mellékhatás. A farmakoterápiát atípusos szerrel indítják (kivéve klozapin), monoterápiára törekedve."],["Indikáció, ellenjavallat","Indikáció: skizofrénia, paranoid, szkizoaffektív pszichózis, mániás/depressziós pszichózis, szimptómás pszichózis, heveny izgalmi állapot, agitált demens, alkoholizmus. Ellenjavallat: szorongás, szomatoform zavar, nem pszichotikus depresszió, alvászavar, személyiségzavar (kivéve pszichotikus dekompenzáció). Kombinálható antiepileptikummal (carbamazepin, valproát, lamotrigin), antidepresszánssal."]],"qs":[{"t":"mc","q":"Melyik receptor gátlása a terápiásan legfontosabb?","o":["Mezolimbikus és mezokortikális D2","Nigrostriális D1","Tuberoinfundibuláris D3","GABA-A"],"a":0,"e":"A mezolimbikus és mezokortikális D2-gátlás."},{"t":"tf","q":"A terápiás hatás 2-3 nap után jelentkezik, a mellékhatás ~3 hét után.","a":false,"e":"Fordítva: a terápiás hatás késik (~3 hét), a mellékhatás 2-3 nap múlva megjelenik."},{"t":"match","q":"Párosítsd a mellékhatást a szerrel / jelenséggel!","pairs":[["Fehérvérsejtszám-csökkenés","clozapin"],["Tejcsorgás","risperidon"],["Kardiális mellékhatás","ziprasidon"],["Csámcsogás","tardív diszkinézia"]],"e":"Jellemző mellékhatások."},{"t":"mc","q":"Melyik az akut extrapiramidális mellékhatás?","o":["Akut disztónia (ferdenyak)","Tardív diszkinézia","Hízás","Tejcsorgás"],"a":0,"e":"Az akut disztónia preszinaptikus blokád következménye (jegyzet)."},{"t":"fill","q":"Az antipszichotikumok közül az első 1952-ben a ___ volt.","a":["chlorpromazin","klórpromazin","hibernal"],"e":"Hibernal néven is szerepel a jegyzetben."},{"t":"mc","q":"Melyik tartozik az atípusos szerekre jellemző előnyök közé?","o":["Szerotoninerg gátlás, a negatív tünetekre is hat","Nagyobb extrapiramidális kockázat","Csak a pozitív tünetekre hat","Nincs szerotoninerg hatás"],"a":0,"e":"Atípusosak: szerotoninerg gátlás is."},{"t":"tf","q":"Személyiségzavarban az antipszichotikum általában ellenjavallt, kivéve pszichotikus dekompenzációt.","a":true,"e":"Jegyzet szerint."},{"t":"mc","q":"Neuroleptikus malignus szindróma jele:","o":["Láz, rigiditás, tudatzavar","Tejfolyás","Hízás","Szájszárazság"],"a":0,"e":"Láz, rigiditás, tudatzavar, vegetatív zavar."}]},{"id":"u27l4","title":"Antidepresszánsok","theory":[["Csoportok","<b>Triciklusosok</b>: reuptake-gátlók és receptorblokkolók, sok mellékhatás, kardiotoxikusak (Melipramin, Anafranil: kényszer; Teperin: szedatív). <b>SSRI</b>: citalopram, escitalopram (Cipralex), fluoxetin, fluvoxamin, paroxetin, sertralin. <b>SNRI</b>: reboxetin (figyelemzavar, energiátlanság), duloxetin, venlafaxin. <b>SNDRI</b>: bupropion. Receptorblokkolók: mianserin, mirtazapin. Coaxil (tianeptin): szerotonin-felvételt fokoz. Valdoxal: melatonin 1-2 receptorra hat, májenzim-emelkedést okozhat."],["MAO-gátlók és mechanizmus","MAO-gátlók: irreverzibilis (nialamid, fenelzin) és reverzibilis MAO-A gátló (moclobemid); atípusos depresszióban hatásosak. Az SSRI-k MAO-gátlóval együtt nem adhatók. A reuptake gátlása növeli a szinaptikus rés monoamin-tartalmát. Depresszióban a szerotonin (és noradrenalin) aktivitás csökken a limbikus rendszerben, a posztszinaptikus béta-receptor érzékenység nő; az antidepresszívumok ezt állítják vissza."],["SSRI mellékhatások","Émelygés, hányinger, puffadás, hasmenés, remegés, zsibbadás; kb. 30%-ban szexuális diszfunkció (súlynövekedés, impotencia, anorgazmia). Nincs cardio- és hepatotoxikus hatásuk, rövid felezési idő. Szorongásos zavarokban (fóbia, pánik, GAD, OCD, PTSD) a kezelést SSRI-vel javasolt kezdeni. Terhesség és szoptatás a klasszikus triciklusosoknál kontraindikált."]],"qs":[{"t":"mc","q":"Melyik az SNDRI?","o":["Bupropion","Venlafaxin","Fluoxetin","Moclobemid"],"a":0,"e":"Szelektív noradrenalin- és dopamin-reuptake gátló."},{"t":"match","q":"Párosítsd a csoportot a szerrel!","pairs":[["SSRI","sertralin"],["SNRI","reboxetin"],["Reverzibilis MAO-A gátló","moclobemid"],["Triciklusos","Melipramin"]],"e":"Antidepresszáns-csoportok."},{"t":"tf","q":"SSRI-t MAO-gátlóval együtt adni szabad.","a":false,"e":"Együtt nem adhatók."},{"t":"mc","q":"Melyik mellékhatás jellemző az SSRI-kre?","o":["Szexuális diszfunkció","Kardiotoxicitás","Hepatotoxicitás","Fehérvérsejt-csökkenés"],"a":0,"e":"Kb. 30%-ban szexuális diszfunkció."},{"t":"fill","q":"A reboxetin olyan depresszióban javasolt, ahol ___ és energiátlanság dominál.","a":["figyelemzavar"],"e":"Szelektív noradrenalin reuptake-gátló."},{"t":"tf","q":"A triciklusos antidepresszánsok sok mellékhatásúak és kardiotoxikusak.","a":true,"e":"A jegyzet szerint kerülendők depresszióban."},{"t":"mc","q":"Mire hat a Valdoxal?","o":["Melatonin 1 és 2 receptor","Szerotonin reuptake","MAO-A","GABA-A"],"a":0,"e":"Máj-enzimemelkedést okozhat."}]},{"id":"u27l5","title":"Szorongásoldók, altatók, lítium","theory":[["Benzodiazepinek","A GABA-A receptorhoz kötődve fokozzák annak affinitását a GABA iránt. Hatások: anxiolitikus, szedatív-hipnotikus, amnesztikus, antikonvulzív, izomrelaxáns. Nagypotenciálúak: alprazolam (Xanax), clonazepam (Rivotril), lorazepam. Kispotenciálúak: diazepam (Seduxen), chlordiazepoxid, medazepam, clobazam. Régebbi: barbiturátok (ma már nincsenek)."],["Hátrányok","Szedáció, kognitív romlás, függőség; rontja a memóriát és koncentrációt, passzív elkerülést segít, nem a megoldást. Visszacsapásos tünet: fejfájás, szorongás, alvászavar, remegés, izzadás. Ellenjavallat: más addikció, izomgyengeség, alvási apnoe, terhesség, szoptatás. Nem addiktívak: SSRI, Coaxil. Buspiron (Anxiron): 5-HT1A serkentő."],["Altatók","Eunoctin: átaltató; Gerodorm, Dormicum: elaltató. „Ideális” altatók (nincs hozzászokás): Leudormin, Imovane (gyorsan ürül, ~6 óra átalvás, időskorban is jó), Stilnox/Andante (nem izomlazító, nem görcsgátló), Circadian. Másodlagos alvászavar valaminek a következménye (pl. stressz)."],["Lítium","Mániás pszichózisban az első jó szer: lítium-karbonát; fázismegelőző hatású, antimániás és antidepresszáns. Serkenti a szerotonin szintézist és reuptake-et, csökkenti a noradrenalin felszabadulást, növeli a GABA-gátlást. Mellékhatás: antidiuretikus hormon blokkolása (sok vizelet, kiszáradás), pajzsmirigy növekedése; túladagolása veszélyes. Kombinálható atípusos antipszichotikummal, carbamazepinnel, valproáttal, lamotriginnel."]],"qs":[{"t":"mc","q":"Hogyan hatnak a benzodiazepinek?","o":["A GABA-A receptor GABA iránti affinitását fokozzák","Gátolják a MAO-t","Blokkolják a D2 receptort","Növelik a noradrenalin felszabadulást"],"a":0,"e":"GABA-A-hoz kötődve."},{"t":"tf","q":"Alvási apnoe esetén a benzodiazepinek ellenjavaltak.","a":true,"e":"Terhesség, szoptatás, más addikció mellett."},{"t":"match","q":"Párosítsd a szert a besorolással!","pairs":[["Alprazolam","nagypotenciálú benzodiazepin"],["Diazepam","kispotenciálú benzodiazepin"],["Buspiron","5-HT1A serkentő"],["Lítium","mániás pszichózis első szere"]],"e":"Szerek."},{"t":"mc","q":"Melyik lítium-mellékhatás szerepel a jegyzetben?","o":["Az antidiuretikus hormon blokkolása","Fehérvérsejt-szám csökkenés","Tejcsorgás","Akatízia"],"a":0,"e":"Sok vizelet, kiszáradás; pajzsmirigy növekedése."},{"t":"fill","q":"A benzodiazepinek antikonvulzív, anxiolitikus, szedatív, amnesztikus és ___ hatásúak.","a":["izomrelaxáns","izomlazító"],"e":"A jegyzet szerinti legfontosabb klinikai hatások."},{"t":"mc","q":"Melyik altató nem izomlazító és nem görcsgátló?","o":["Stilnox/Andante","Seduxen","Eunoctin","Xanax"],"a":0,"e":"Hiperpolarizál; „ideális” altató."},{"t":"tf","q":"A másodlagos alvászavar valaminek a következménye, pl. stressznek.","a":true,"e":"Az elsődlegestől különbözik."}]}],"color":"#00cd9c"},{"id":"u28","title":"Humanisztikus irányzat","desc":"Rogers, Maslow, Frankl, Gestalt","lessons":[{"id":"u28l1","title":"Rogers: személyközpontú szemlélet","theory":[["Alapgondolat","A humanisztikus pszichológia a „harmadik erő” (USA, 40-es évek). Rogers szerint nem a módszer, hanem a segítő személy a legfontosabb. A „beteg” helyett „kliens” kifejezést használja, egyenrangú társak. Nondirektív: a terapeuta nem irányít, nem tanácsol. A kliens problémái hamis önképéből adódnak."],["Terapeuta-változók (rogersi triász)","<b>Empátia</b> (benneérzés): az érzelmi élmény megértése és visszatükrözése. <b>Kongruencia</b>: őszinte, hiteles viselkedés; verbális és nonverbális közlés egyezik a belső állapottal. <b>Feltétel nélküli elfogadás</b>: pozitív érzelmi odafordulás, nondirektivitás, feltétel nélküliség. A kliens legfontosabb dimenziója az <b>önfeltárás</b>."],["Önkép, teljesen működő személy","Önkép: az önmagunkról alkotott ismeretek összessége; formái: aktuális és ideális. Kis távolságuk húzóerő a fejlődéshez; túl nagy távolság: negatív önkép, neurózis. Inkongruencia: az öntapasztalat nem esik egybe az önképpel (lelki szenvedés, tünetek). <b>Teljesen működő személy</b>: nyitott a tapasztalatra, feltétel nélküli önbecsülés, nincsenek introjektumok. Alapja az önaktualizáló tendencia."]],"qs":[{"t":"mc","q":"Melyik NEM tartozik a rogersi triászhoz?","o":["Interpretáció","Empátia","Kongruencia","Feltétel nélküli elfogadás"],"a":0,"e":"A triász: empátia, kongruencia, feltétel nélküli elfogadás."},{"t":"tf","q":"Rogers a „páciens” kifejezést részesíti előnyben.","a":false,"e":"Kliensről beszél, az egyenrangúság miatt."},{"t":"fill","q":"Az önmagunkról alkotott ismeretek összessége az ___.","a":["önkép","onkep"],"e":"Aktuális és ideális formája van."},{"t":"mc","q":"Mi az inkongruencia?","o":["Az öntapasztalat nem esik egybe az önképpel","Az empátia hiánya a terapeutánál","Az ideális és aktuális én egybeesése","A feltétel nélküli elfogadás"],"a":0,"e":"Lelki szenvedés, pszichés vagy pszichoszomatikus tünetek kiindulópontja."},{"t":"tf","q":"Túl nagy távolság az önkép és az énideál között feszültséget és negatív önképet okoz.","a":true,"e":"Optimális a kisfokú távolság."},{"t":"match","q":"Párosítsd!","pairs":[["Empátia","benneérzés, visszatükrözés"],["Kongruencia","hitelesség"],["Önfeltárás","a kliens legfontosabb dimenziója"]],"e":"Rogers fogalmai."},{"t":"mc","q":"Mi az aktualizáló tendencia?","o":["A növekedésre irányuló, alapvetően pozitív mozgatóerő","A tudattalan ösztönkésztetés","A külső jutalmazás hatása","A szorongás elhárítása"],"a":0,"e":"Formái: formatív és önaktualizáció."}]},{"id":"u28l2","title":"Maslow: a lét pszichológiája","theory":[["Hiány- és növekedési motívumok","Maslow szerint az ember alapvetően jó (Freud: rossz). Az emberi motívumok hierarchikusak (prepotencia). <b>Hiánymotívumok (D)</b>: homályos lencsén át látjuk a világot, a környezettől függünk. <b>Növekedési motívumok (B)</b>: ha minden hiány kielégült; megjelenik az önmegvalósítás (metamotiváció)."],["Önmegvalósító emberek","Hatékonyabb valóságészlelés, önelfogadás és mások elfogadása, spontaneitás, problémaközpontúság, autonómia, gyermeki kreativitás, kevés de mély kapcsolat, gyakoribb csúcsélmények, demokratikus jellemszerkezet. Tökéletlenségeik is vannak: makacsok, szórakozottak, jóhiszeműségük miatt becsapják őket. Az önmegvalósítás gyakoriság kérdése, nem igen-nem."],["Csúcsélmények, B-értékek","A csúcsélmény a B-gondolkodás misztikus élménye; mindig jó élmény. Maslow értékobjektivista: B-értékek a valóságban vannak (egészlegesség, tökéletesség, igazságosság, elevenség, szépség, játékosság, igazság…). Szeretet: D-szeretet (kielégíthető, szorongással) vs. B-szeretet (cél, nem eszköz, sosem elégül ki, segíti a másik önmegvalósítását)."]],"qs":[{"t":"match","q":"Párosítsd!","pairs":[["D-motiváció","hiánymotiváció"],["B-motiváció","növekedési motiváció"],["Metamotiváció","önmegvalósítás"],["B-szeretet","a másik önmegvalósítását segíti"]],"e":"Maslow fogalmai."},{"t":"tf","q":"Maslow szerint az emberek alapvetően rosszak.","a":false,"e":"Alapvetően jók; ez Freuddal ellentétes."},{"t":"mc","q":"Mi jellemző a hiánymotivált emberre?","o":["A környezetétől függ, a világot homályos lencsén át látja","Gyakori csúcsélmények","Problémaközpontú","Metamotiváció"],"a":0,"e":"A hiányokat csak a környezet elégítheti ki."},{"t":"fill","q":"A növekedési motiváció angol jelölése: ___-motiváció.","a":["B"],"e":"B mint being (lét); D mint deficit."},{"t":"mc","q":"Az önmegvalósítás Maslow szerint:","o":["Gyakoriság kérdése, nem igen-nem","Mindenkinél egyformán teljes","Csak művészeknél létezik","Csak a gyerekeknél van meg"],"a":0,"e":"Az önmegvalósítás pillanatai a csúcsélmények."},{"t":"tf","q":"A B-szeretet kielégíthető és szorongással jár.","a":false,"e":"Ez a D-szeretet; a B-szeretet sosem elégül ki."},{"t":"mc","q":"Maslow értékfelfogása:","o":["Értékobjektivizmus","Értékrelativizmus","Nihilizmus","Kulturális relativizmus"],"a":0,"e":"Az értékek a valóságban vannak."}]},{"id":"u28l3","title":"Frankl és a Gestalt","theory":[["Frankl: logoterápia","A harmadik bécsi irány (Freud, Adler után). Fő tézis: az elsődleges motiváció az <b>élet értelmének keresése</b>. Három pillér: szabad akarat, értelemkeresés, az élet értelme (minden helyzetben specifikus, objektív realitás). Az egzisztencia-analízis a filozófiai-tudományos alap. Technikák: paradox szándék, szókratészi párbeszéd (és reflexió). A logosz = értelem."],["Gestalt: alapelvek","Az egész több a részek összegénél. Wertheimer (1912, tachisztoszkóp, látszólagos mozgás), Köhler, Lewin (mezőelmélet). Törvények: figura-háttér, folytonosság, közelség, hasonlóság, zártság."],["Perls: Gestalt-terápia","Az életet a homeosztázis irányítja. Az uralkodó szükséglet az előtérben álló alak; kielégítés után az alak bezáródik. Neurotikus konfliktus: a személy nem tud a szükségletek hierarchiája szerint dönteni. Négy határzavar: <b>introjekció</b> (kritikátlan bekebelezés), <b>projekció</b>, <b>konfluencia</b> (összemosódás), <b>retroflexió</b> (visszahajlítás). Cél: integráció."]],"qs":[{"t":"mc","q":"Mi Frankl szerint az ember elsődleges motivációja?","o":["Az élet értelmének keresése","A hatalomra törekvés","Az ösztönkielégítés","A biztonság"],"a":0,"e":"A logoterápia alaptétele."},{"t":"match","q":"Párosítsd a határzavart a leírásával!","pairs":[["Introjekció","kritikátlan bekebelezés"],["Projekció","a felelősség áthárítása a környezetre"],["Konfluencia","nincs határ önmagam és a környezet között"],["Retroflexió","magammal teszem, amit másokkal akarnék"]],"e":"Perls négy határzavara."},{"t":"tf","q":"A Gestalt-pszichológia szerint az egész a részek egyszerű összege.","a":false,"e":"Az egész több a részek összegénél."},{"t":"fill","q":"A látszólagos mozgás tachisztoszkópos kísérletét ___ végezte 1912-ben.","a":["Wertheimer","wertheimer"],"e":"A Gestalt megalakulása."},{"t":"mc","q":"Melyik a logoterápia egyik technikája?","o":["Paradox szándék","Szabad asszociáció","Tükrözés","Dezszenzitizáció"],"a":0,"e":"Paradox szándék, szókratészi párbeszéd."},{"t":"mc","q":"Melyik NEM Gestalt észlelési törvény?","o":["Kondicionálás","Zártság","Közelség","Hasonlóság"],"a":0,"e":"Figura-háttér, folytonosság, közelség, hasonlóság, zártság."},{"t":"tf","q":"Perls szerint a neurotikus személy nem tud a szükségletek hierarchiájának megfelelően dönteni.","a":true,"e":"A terápia ezt a rangsorolást tanítja."}]}],"color":"#e5a000"},{"id":"u29","title":"Pozitív pszich. és szalutogenezis","desc":"Seligman, Antonovsky","lessons":[{"id":"u29l1","title":"Pozitív pszichológia (Seligman)","theory":[["Pillérek és fókusz","Három pillér: pozitív érzelmek, pozitív magatartások (erősségek, erények), pozitív intézmények (demokrácia, sajtószabadság). A mentális betegségek gyógyítása mellett az erősségek azonosítása és erősítése a cél. Az optimizmus: a nehézségeket ideiglenesnek, kontrollálhatónak, helyzetspecifikusnak tartja. Autentikus boldogság: a legalapvetőbb erősségek azonosításából, fejlesztéséből és használatából."],["Erények és erősségek","6 erény → 24 erősség: bölcsesség és tudás, bátorság, szeretet és emberség, igazság és méltányosság, mértékletesség, spiritualitás és transzcendencia. Az erősség 3 kritériuma: szinte minden kultúra értékeli; saját jogán becsült, nem eszköz; alakítható, fejleszthető."],["Boldogsági képlet","<b>B = I + K + E</b>: tartós boldogságszint = irányultság (biológiailag meghatározott, a személyiség kb. 50%-a genetika) + külső körülmények + ellenőrzés. Hedonisztikus mókuskerék: a jó dolgokhoz hozzászokunk. A gazdagság és boldogság korrelációja alacsony; a házasság és a társas élet erősen kapcsolódik. Magyarázó stílus 3 összetevője: állandóság, kiterjedtség, megszemélyesítés."]],"qs":[{"t":"mc","q":"Hány erényt és erősséget különít el Seligman?","o":["6 erényt és 24 erősséget","3 erényt és 12 erősséget","5 erényt és 20 erősséget","10 erényt és 30 erősséget"],"a":0,"e":"6 erény, 24 erősség."},{"t":"fill","q":"A boldogsági képlet: B = I + K + ___.","a":["E"],"e":"Irányultság + külső körülmények + ellenőrzés."},{"t":"match","q":"Párosítsd a magyarázó stílus összetevőit!","pairs":[["Állandóság","tartós vagy átmeneti esemény"],["Kiterjedtség","univerzális vagy specifikus hiedelem"],["Megszemélyesítés","belső vagy külső kontroll"]],"e":"A magyarázó stílus 3 összetevője."},{"t":"tf","q":"A pozitív pszichológia hedonizmus, a boldog pillanatok halmozása.","a":false,"e":"A pozitív és negatív pillanatok különbségét és az erősségeket vizsgálja."},{"t":"mc","q":"Mi a hedonisztikus mókuskerék?","o":["A jó dolgokhoz való hozzászokás, nő az elvárás","A boldogság genetikai meghatározottsága","A negatív érzelmek halmozódása","A társas élet hiánya"],"a":0,"e":"Magától értetődőnek vesszük a jót."},{"t":"mc","q":"Melyik NEM az erősség kritériuma?","o":["Csak a saját kultúrában értékes","Szinte minden kultúrában értékes","Saját jogán becsült","Fejleszthető"],"a":0,"e":"Közel minden kultúrában értékes."},{"t":"tf","q":"A házasság erőteljes kapcsolatban áll a boldogsággal.","a":true,"e":"A fizikai vonzerő és a gazdagság viszont alig."}]},{"id":"u29l2","title":"Antonovsky: szalutogenezis","theory":[["Szalutogenezis vs. patogenezis","A patogenezis a betegség eredetét kérdezi, a szalutogenezis azt, ami az egészséghez járul hozzá. Antonovsky (amerikai-izraeli orvosszociológus) az egészséget folyamatnak tekinti: egyik póluson a patogenezis, a másikon a szalutogenezis (egészség–betegség kontinuum). Még a haldokló betegben is vannak egészséges aspektusok. Kiinduló megfigyelés: koncentrációs tábort túlélt menopauzás nők körében magasabb volt az egészségesek aránya a kontrollcsoportnál."],["Koherencia-érzés","Diszpozicionális, globális irányultság, nem állapot. 3 összetevő: <b>érthetőség</b> (információfeldolgozási mintázat, kognitív), <b>kezelhetőség</b> (az erőforrások és mások segítségének érzékelése; instrumentális bizalom), <b>értelemteliség</b> (emocionális; megéri erőfeszítést tenni; enélkül nincs valódi koherencia). A koherencia a megküzdési módnál magasabb szintű: szabályozza, melyiket alkalmazzuk. Gyermek- és serdülőkorban alakul ki, a 30-as évek elejére teljes."],["Salutogenetikus orientáció","Kritériumai: koherencia, kapcsolódás, építő kommunikáció; orientáció az egészségre (attraktív célok, életminőség), nem a deficitekre hanem a tartalékokra; a szubjektivitás értékelése; dinamikus, regulációra törekvő; megszünteti a dichotómiát. Káoszelmélet: betegség = káosz, egészség = rend; a koherencia az egészség, az entrópia a betegség/halál felé billent. A betegség olyan, mint a piros lámpa: jelzi, hogy eltávolodtunk a koherenciától. WHO: az egészség testi-lelki-szociális jólét."]],"qs":[{"t":"mc","q":"Hány összetevője van a koherencia-érzésnek?","o":["3","2","4","5"],"a":0,"e":"Érthetőség, kezelhetőség, értelemteliség."},{"t":"match","q":"Párosítsd az összetevőt a jellemzővel!","pairs":[["Érthetőség","információfeldolgozási mintázat"],["Kezelhetőség","erőforrások, mások segítsége"],["Értelemteliség","emocionális; megéri az erőfeszítést"]],"e":"A koherencia három összetevője."},{"t":"tf","q":"Antonovsky szerint az egészség és betegség dichotóm, kizárják egymást.","a":false,"e":"Kontinuum két pólusa; a dichotómiát felszámolja."},{"t":"mc","q":"Mely összetevő nélkül nincs valódi koherencia-érzés?","o":["Értelemteliség","Érthetőség","Kezelhetőség","Spiritualitás"],"a":0,"e":"Az emocionális összetevő nélkül."},{"t":"fill","q":"Antonovsky szerint a betegség olyan, mint a piros ___.","a":["lámpa","közlekedési lámpa","lampa"],"e":"Jelzi, hogy eltávolodtunk a koherenciától."},{"t":"tf","q":"A koherencia-érzés a 30-as évek elejére teljesen kifejlődik.","a":true,"e":"Utána viszonylag stabil."},{"t":"mc","q":"A salutogenetikus orientáció fókusza:","o":["Tartalékok és attraktív célok","Rizikófaktorok feltárása","Diagnosztikai besorolás","Deficitek hangsúlyozása"],"a":0,"e":"Nem a deficiteket, hanem a szunnyadó potenciálokat nevezi meg."}]},{"id":"u29l3","title":"Attraktor, rezonancia, rendszerek","theory":[["Attraktor és konzisztens reguláció","Antonovsky az ideális állapotot <b>attraktornak</b> nevezi; az egész élet az attraktorok körül forog, a legfontosabb a koherencia. Minél erősebb a szükséglet (pl. szomjúság), annál attraktívabb a kielégítés gondolata. A konzisztens reguláció tudattalanul megy végbe. Az agyban közelítő rendszer (a jutalmazó rendszerrel összefügg; a salutogenetikus orientáció aktiválja) és kerülő rendszer (félelemközpont; az entrópia aktiválja) működik."],["Rendszerek, rezonancia","Az ember egység, mely egy nagyobb egység része (pl. gyermek születése megváltoztatja a család szerkezetét). Minden rendszerre jellemző a koherencia; ha szétesik, szétesik a rendszer. Kommunikáció nélkül nincs koherencia. A rezonancia a kommunikáció, megértés, kooperáció alapja: minimális energiával visz át információt. A betegség/tünet információt ad arról, mit kell még megtanulni. Koherenciaszintek: születés, kilépés a családból fiatal felnőttként, átlépés a halálba."]],"qs":[{"t":"mc","q":"Mit nevez Antonovsky attraktornak?","o":["Az ideális állapotot, amely felé törekszünk","A betegség kiváltó okát","A stresszforrást","A megküzdési módot"],"a":0,"e":"A legfontosabb attraktor a koherencia."},{"t":"tf","q":"Antonovsky szerint kommunikáció nélkül is lehet koherencia.","a":false,"e":"Kommunikáció nélkül nincs koherencia."},{"t":"fill","q":"A rendszerek közti információátvitel alapja a ___.","a":["rezonancia"],"e":"Minimális energiabefektetéssel visz át információt."},{"t":"mc","q":"Melyik rendszer aktiválódik az entrópia hatására?","o":["Kerülő rendszer (félelemközpont)","Közelítő rendszer","Jutalmazó rendszer","Motoros rendszer"],"a":0,"e":"A közelítő rendszert a salutogenetikus orientáció aktiválja."},{"t":"match","q":"Párosítsd!","pairs":[["Káosz","betegség"],["Rend","egészség"],["Entrópia","betegség, halál felé billent"],["Koherencia","egészség felé billent"]],"e":"Káoszelmélet."},{"t":"tf","q":"A tünet információt adhat arról, mit kell még megtanulnia az érintett rendszernek.","a":true,"e":"Összhang önmagunkkal, másokkal, kultúrával, természettel."},{"t":"mc","q":"Melyik NEM koherenciaszint-átlépés a jegyzet szerint?","o":["Iskolakezdés","Kilépés az anyaméhből","Kilépés a családból","Átlépés a halálba"],"a":0,"e":"Anyaméh, család, halál."}]}],"color":"#a560e8"},{"id":"u30","title":"Tranzakcióanalízis, TP","desc":"Berne, Bagdy transzperszonális","lessons":[{"id":"u30l1","title":"Tranzakcióanalízis (Berne): énállapotok","theory":[["Alapok","Az ember nem tud nem kommunikálni. Berne tranzakcióanalízise egyszerre pszichoterápiás módszer, személyiségelmélet és a társas tevékenységek elmélete. Éhségek: inger-, elismerés-, struktúraéhség. A kielégülés egysége a <b>simogatás</b>; a tranzakció a simogatások cseréje. Az intimitás lenne a tökéletes válasz, de a társadalom kerüli."],["Énállapotok","Szülői (exteropszichikus: a szülőkre hasonló), Felnőtt (neopszichikus: a valóság tárgyilagos értékelése), Gyermeki (archeopszichikus: korai gyermekkori maradvány). A Gyermeki alkalmazkodó, természetes vagy lázadó lehet. A Gyermeki a személyiség legértékesebb része (intuíció, alkotókészség, öröm). A Felnőtt szabályoz és közvetít a másik kettő között."],["Strukturális patológia","<b>Kontamináció</b>: egyik énállapot szennyez egy másikat (pl. szülői előítéletesség). <b>Kizárás</b>: Szülői kizárás: nincs lelkiismeret (antiszociális); Gyermeki kizárás: rideg, merev, munkafüggő; Felnőtt kizárás: elveszti a valósággal a kapcsolatot."]],"qs":[{"t":"mc","q":"Melyik énállapot a neopszichikus?","o":["Felnőtt","Szülői","Gyermeki","Archaikus"],"a":0,"e":"A Felnőtt a valóság tárgyilagos értékelése."},{"t":"match","q":"Párosítsd az énállapotot a tudományos nevével!","pairs":[["Szülői","exteropszichikus"],["Felnőtt","neopszichikus"],["Gyermeki","archeopszichikus"]],"e":"Berne énállapotai."},{"t":"fill","q":"A tranzakció a ___ cseréje.","a":["simogatások","simogatásoké","simogatas"],"e":"Társas érintkezés egysége."},{"t":"tf","q":"A Gyermeki énállapot a személyiség legértékesebb része.","a":true,"e":"Intuíció, alkotókészség, spontán hajtóerők, öröm."},{"t":"mc","q":"A Gyermeki énállapot formái:","o":["Alkalmazkodó, természetes, lázadó","Aktív, passzív","Kontrolláló, gondoskodó","Spontán, reaktív"],"a":0,"e":"Három megnyilvánulási forma."},{"t":"mc","q":"Mi a Szülői kizárás következménye?","o":["Nincs lelkiismeret, bűntudat (antiszociális)","Rideg, merev személyiség","Valóságkapcsolat elvesztése","Szorongás"],"a":0,"e":"A Gyermeki kizárás a rideg, munkafüggő személyiség."},{"t":"tf","q":"A kontamináció azt jelenti, hogy az egyik énállapot egy másikat szennyez.","a":true,"e":"Pl. szülői előítélet."}]},{"id":"u30l2","title":"Tranzakciók és játszmák","theory":[["Tranzakciótípusok","<b>Kiegészítő</b>: a megcélzott énállapot válaszol, a kommunikáció zavartalan. <b>Keresztezett</b>: a kommunikáció megszakad (pl. két felnőtt beszélget, de a Szülői válaszol a Gyermekinek). <b>Rejtett</b>: társadalmi és pszichológiai szint; szöget bezáró (kereskedő–háziasszony) és dupla fenekű (flört)."],["Játszma","Kiegészítő, rejtett tranzakciók sorozata, előrelátható kimenetel felé; felszínen hihető, rejtett indítékú, nyereséggel. Tisztességtelen, öntudatlan. Tézis: a játszma általános leírása; antitézis: visszautasítása. Példa: „ha te nem lennél” játszma. Nevelés során sajátítjuk el. Fokozatok: elsőfokú (társadalmilag elfogadott), másodfokú (eltitkolt, zárt ajtók mögött), harmadfokú (életre szóló)."]],"qs":[{"t":"match","q":"Párosítsd a tranzakciót a leírással!","pairs":[["Kiegészítő","a megcélzott énállapot válaszol"],["Keresztezett","megszakad a kommunikáció"],["Rejtett","társadalmi és pszichológiai szint"]],"e":"Tranzakciótípusok."},{"t":"tf","q":"Keresztezett tranzakcióban a kommunikáció zavartalan.","a":false,"e":"Megszakad, amíg valaki át nem vált kiegészítőre."},{"t":"mc","q":"A flört melyik tranzakció példája?","o":["Dupla fenekű (rejtett)","Kiegészítő","Keresztezett","Egyszerű"],"a":0,"e":"Társadalmi szinten kötözködés, pszichológiai szinten más a tartalom."},{"t":"fill","q":"A játszma harmadfokú változatát az egész ___ játsszuk.","a":["életre","életen át","élet"],"e":"Életre szólóan."},{"t":"mc","q":"A játszma ismertetőjegye:","o":["Rejtett jelleg és nyereség","Nyílt őszinteség","Spontaneitás","Intimitás"],"a":0,"e":"Az intimitás pótléka."},{"t":"tf","q":"A játszmák tudatosak és tisztességesek.","a":false,"e":"Tisztességtelenek, öntudatlanok."}]},{"id":"u30l3","title":"Transzperszonális irány (Bagdy)","theory":[["A 4. erő","Irányzatok: 1. pszichoanalízis, 2. behaviorizmus, 3. humanisztikus, 4. transzperszonális. A transzperszonális (TP) a tudatfelettivel foglalkozik; a test-lélek felosztást a szellemmel egészíti ki, az önaktualizáció (Maslow) énközpontúságát öntranszcendáló irányba mozdítja. Nem vállal közösséget a redukcionista tanításokkal."],["Emberkép és spiritualitás","Az ember spirituális, intuitív, altruista, értelemkereső. Spiritualitása: hit, de nem vallás; hit abban, hogy a világ egy és mindannyian része vagyunk. 5 fő spirituális kérdés (pl. Ki vagyok én? Miért vagyok itt? Hogyan tehetném a világot egészségesebbé?). Fejlődés: spirituális krízisek, csúcsélmények mentén. Jung: szinkronicitás."]],"qs":[{"t":"mc","q":"Melyik a transzperszonális irányzat sorszáma?","o":["4. erő","3. erő","2. erő","1. erő"],"a":0,"e":"Pszichoanalízis, behaviorizmus, humanisztikus, majd TP."},{"t":"tf","q":"A transzperszonális irány azonos a vallással.","a":false,"e":"Hit, de nem vallás."},{"t":"fill","q":"A TP a test és lélek mellett a ___ dimenziót is figyelembe veszi.","a":["szellem","szellemi"],"e":"Test–lélek–szellem."},{"t":"mc","q":"Mit mozdít az öntranszcendáló irányba a TP?","o":["Maslow önaktualizációját","Freud ösztönelméletét","Skinner kondicionálását","Rogers triászát"],"a":0,"e":"Az énközpontúság fölé emeli."},{"t":"tf","q":"Jung szinkronicitás-fogalmát a TP idézi mint ok-okozati kapcsolaton túli jelenséget.","a":true,"e":"Tér-idői és oksági összefüggéseken túl létező jelenségek."},{"t":"mc","q":"Hány fő spirituális kérdést fogalmaz meg Bagdy?","o":["5","3","7","10"],"a":0,"e":"Öt fő kérdés."}]}],"color":"#ff86d0"}];
